declare
  d constant jsonb := $content${"units":[{"id":"a1-u01","language_code":"en","level":"A1","position":1,"title_es":"Saludos y presentaciones","title_en":"Greetings and introductions","description_es":"Saludar, despedirte, ser amable y presentarte.","emoji":"👋","objective_es":"Puedes saludar según el momento del día, presentarte, preguntar cómo está alguien y responder con cortesía.","grammar":{"title":"My name is… / I am…","explanation":"Para decir tu nombre usas my name is o I am (I'm). Para devolver un saludo agregas too: nice to meet you too.","examples":[{"target":"My name is Tom.","base":"Mi nombre es Tom."},{"target":"I'm fine, thank you.","base":"Estoy bien, gracias."}]},"review_status":"draft"},{"id":"a1-u02","language_code":"en","level":"A1","position":2,"title_es":"Pronombres y verbo to be","title_en":"Pronouns and the verb to be","description_es":"Yo, tú, él, ella… y cómo decir quién eres y cómo estás.","emoji":"🧍","objective_es":"Puedes usar los pronombres y el verbo to be para decir quién eres, cómo estás y hablar de otras personas.","grammar":{"title":"To be: am, is, are","explanation":"To be es «ser» y «estar» a la vez. I am; you, we y they are; he, she e it is. Para negar se agrega not y para preguntar el verbo va primero.","examples":[{"target":"I'm a student.","base":"Soy estudiante."},{"target":"She is not tired.","base":"Ella no está cansada."},{"target":"Are you happy?","base":"¿Estás feliz?"}]},"review_status":"draft"},{"id":"a1-u03","language_code":"en","level":"A1","position":3,"title_es":"Números, edades y países","title_en":"Numbers, ages and countries","description_es":"Contar hasta veinte, decir tu edad y de dónde eres.","emoji":"🌍","objective_es":"Puedes contar hasta veinte, decir tu edad y de dónde eres.","grammar":{"title":"La edad con to be","explanation":"En inglés la edad va con to be, no con have: I am ten (years old). El origen también: I am from Argentina.","examples":[{"target":"How old are you?","base":"¿Cuántos años tienes?"},{"target":"I'm twenty years old.","base":"Tengo veinte años."},{"target":"Where are you from?","base":"¿De dónde eres?"}]},"review_status":"draft"},{"id":"a1-u04","language_code":"en","level":"A1","position":4,"title_es":"Familia y personas","title_en":"Family and people","description_es":"Presentar a tu familia y hablar de otras personas.","emoji":"👨‍👩‍👧","objective_es":"Puedes presentar a tu familia, decir de quién es algo con his, her, our y their, y cuántos familiares tienes.","grammar":{"title":"His / her y have / has","explanation":"His es «su» de él y her, «su» de ella: depende de quién es dueño. Tener es have, pero con he, she e it es has.","examples":[{"target":"Her brother is ten.","base":"Su hermano (de ella) tiene diez años."},{"target":"I have two sisters.","base":"Tengo dos hermanas."},{"target":"He has a baby.","base":"Él tiene un bebé."}]},"review_status":"draft"},{"id":"a1-u07","language_code":"en","level":"A1","position":7,"title_es":"Comida y bebidas","title_en":"Food and drinks","description_es":"Pedir comida, decir qué quieres y hablar de las comidas del día.","emoji":"🍎","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a1-u08","language_code":"en","level":"A1","position":8,"title_es":"Rutinas y presente simple","title_en":"Routines and present simple","description_es":"Contar qué haces todos los días, preguntar y negar en presente.","emoji":"⏰","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a1-u11","language_code":"en","level":"A1","position":11,"title_es":"Gustos y preferencias","title_en":"Likes and preferences","description_es":"Decir qué te gusta, qué no, qué sabes hacer y cuál es tu favorito.","emoji":"❤️","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a2-u06","language_code":"en","level":"A2","position":6,"title_es":"Ropa y compras","title_en":"Clothes and shopping","description_es":"La ropa, las tallas, los precios y cómo pagar.","emoji":"👕","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a2-u10","language_code":"en","level":"A2","position":10,"title_es":"Trabajo y obligaciones","title_en":"Work and obligations","description_es":"Profesiones, la oficina y lo que tienes que hacer: have to y must.","emoji":"💼","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"it-a1-u01","language_code":"it","level":"A1","position":1,"title_es":"Saludos y presentaciones","title_en":"Saluti e presentazioni","description_es":"Saludar según la hora, despedirte, ser amable y presentarte.","emoji":"👋","objective_es":"Puedes saludar según el momento del día, presentarte, preguntar cómo está alguien y responder con cortesía.","grammar":{"title":"Mi chiamo… (me llamo)","explanation":"Para decir tu nombre se usa chiamarsi, igual que «llamarse»: mi chiamo Ana. Para preguntar el nombre a alguien de confianza: come ti chiami?","examples":[{"target":"Mi chiamo Marco.","base":"Me llamo Marco."},{"target":"Come ti chiami?","base":"¿Cómo te llamas?"}]},"review_status":"draft"},{"id":"it-a1-u02","language_code":"it","level":"A1","position":2,"title_es":"¿Quién eres y de dónde eres?","title_en":"Chi sei e di dove sei?","description_es":"El verbo essere, decir de dónde eres y hablar de otras personas.","emoji":"🌍","objective_es":"Puedes decir quién eres y de dónde eres, preguntarle lo mismo a otra persona y hablar de alguien con lui y lei.","grammar":{"title":"Essere (ser) y la concordancia -o / -a","explanation":"Io sono, tu sei, lui/lei è. Las nacionalidades cambian como en español: italiano / italiana. Para negar, non va antes del verbo: non sono.","examples":[{"target":"Io sono argentina.","base":"Yo soy argentina."},{"target":"Lui è italiano.","base":"Él es italiano."},{"target":"Non sono spagnolo.","base":"No soy español."}]},"review_status":"draft"},{"id":"it-a1-u03","language_code":"it","level":"A1","position":3,"title_es":"Números y edad","title_en":"Numeri ed età","description_es":"Contar hasta veinte y decir cuántos años tienes.","emoji":"🔢","objective_es":"Puedes contar hasta veinte, preguntar la edad y decir cuántos años tienes.","grammar":{"title":"Avere … anni","explanation":"Como en español, la edad se dice con avere (tener): ho venti anni. Ho se escribe con h, pero la h no suena.","examples":[{"target":"Quanti anni hai?","base":"¿Cuántos años tienes?"},{"target":"Ho diciotto anni.","base":"Tengo dieciocho años."}]},"review_status":"draft"},{"id":"it-a1-u04","language_code":"it","level":"A1","position":4,"title_es":"La familia","title_en":"La famiglia","description_es":"Nombrar a tu familia, decir cuántos hermanos tienes y cómo se llaman.","emoji":"👨‍👩‍👧","objective_es":"Puedes presentar a tu familia, decir cuántos hermanos tienes y cómo se llaman tus familiares.","grammar":{"title":"Mio, mia y el artículo","explanation":"Mio va con palabras masculinas y mia con femeninas. Con un familiar en singular no se pone artículo (mia madre), pero sí en plural (i miei genitori) y con la mayoría de las demás palabras (il mio amico).","examples":[{"target":"Mia madre si chiama Laura.","base":"Mi mamá se llama Laura."},{"target":"Mio fratello ha dieci anni.","base":"Mi hermano tiene diez años."},{"target":"I miei genitori sono di Roma.","base":"Mis padres son de Roma."}]},"review_status":"draft"},{"id":"it-a1-u05","language_code":"it","level":"A1","position":5,"title_es":"Objetos y colores","title_en":"Oggetti e colori","description_es":"Nombrar objetos con su artículo, en singular y en plural, y decir de qué color son.","emoji":"🎒","objective_es":"Puedes preguntar qué es algo, nombrar objetos con el artículo correcto (il, lo, la, l’, i, gli, le) y decir de qué color son.","grammar":{"title":"Los artículos il, lo, la, l’ y sus plurales","explanation":"Il va con la mayoría de los masculinos y lo con los que empiezan con s + consonante o z. La va con los femeninos. Ante vocal, il / lo / la se vuelven l’. En plural: il → i, lo y l’ (masculino) → gli, la y l’ (femenino) → le.","examples":[{"target":"il libro → i libri","base":"el libro → los libros"},{"target":"lo zaino → gli zaini","base":"la mochila → las mochilas"},{"target":"la penna → le penne","base":"el bolígrafo → los bolígrafos"},{"target":"l'orologio → gli orologi","base":"el reloj → los relojes"}]},"review_status":"draft"},{"id":"it-a1-u06","language_code":"it","level":"A1","position":6,"title_es":"La casa","title_en":"La casa","description_es":"Las partes de la casa, los muebles, decir qué hay y dónde está cada cosa.","emoji":"🏠","objective_es":"Puedes describir tu casa con c'è y ci sono y decir dónde está algo con in, nel / nella y sul / sulla.","grammar":{"title":"C'è / ci sono y las preposiciones articuladas","explanation":"C'è es «hay» con una cosa y ci sono con varias. In y su se juntan con el artículo: in + il = nel, in + la = nella, su + il = sul, su + la = sulla. Con las habitaciones de la casa se usa in sin artículo: in cucina.","examples":[{"target":"In camera c'è un letto.","base":"En la habitación hay una cama."},{"target":"Ci sono due sedie.","base":"Hay dos sillas."},{"target":"Il libro è sul tavolo.","base":"El libro está sobre la mesa."}]},"review_status":"draft"},{"id":"it-a1-u07","language_code":"it","level":"A1","position":7,"title_es":"En el bar","title_en":"Al bar","description_es":"Pedir algo para tomar y comer en un bar italiano, con o sin azúcar, y pedir la cuenta.","emoji":"☕","objective_es":"Puedes pedir en un bar con vorrei, prendo o per me, decir con o sin qué lo quieres y pedir la cuenta.","grammar":{"title":"Pedir con vorrei, prendo y per me","explanation":"Vorrei («quisiera») es la forma amable de pedir. Prendo («tomo», «me pido») es igual de común entre amigos o en la barra. Per me… («para mí…») sirve para pedir sin verbo.","examples":[{"target":"Vorrei un cappuccino, per favore.","base":"Quisiera un capuchino, por favor."},{"target":"Io prendo un caffè.","base":"Yo me pido un café."},{"target":"Per me un gelato.","base":"Para mí un helado."}]},"review_status":"draft"},{"id":"it-a1-u08","language_code":"it","level":"A1","position":8,"title_es":"La rutina","title_en":"La routine","description_es":"Contar tu día: despertarte, desayunar, trabajar o estudiar, con verbos en -are, -ere e -ire.","emoji":"🌅","objective_es":"Puedes contar qué haces en un día normal con verbos en presente (parlo, leggo, dormo) y con mi sveglio / mi alzo.","grammar":{"title":"Presente: -are, -ere, -ire y verbos reflexivos","explanation":"Con io casi todos los verbos terminan en -o: parlo, leggo, dormo. Con tu terminan en -i: parli, leggi, dormi. Con lui / lei, en -a (los de -are) o en -e (los de -ere e -ire): parla, legge, dorme. Los reflexivos llevan mi delante, como en español: mi sveglio, mi alzo.","examples":[{"target":"Io parlo italiano.","base":"Yo hablo italiano."},{"target":"Tu parli spagnolo?","base":"¿Tú hablas español?"},{"target":"La mattina mi sveglio alle sette.","base":"A la mañana me despierto a las siete."}]},"review_status":"draft"},{"id":"it-a1-u09","language_code":"it","level":"A1","position":9,"title_es":"Horas y días","title_en":"Ore e giorni","description_es":"Decir y preguntar la hora, a qué hora haces algo y los días de la semana.","emoji":"🕗","objective_es":"Puedes preguntar y decir la hora (che ore sono? sono le otto), decir a qué hora haces algo (alle nove) y nombrar los días.","grammar":{"title":"Sono le… / è l’una / alle…","explanation":"Para la hora se usa sono le + número (sono le otto), salvo la una: è l'una. Para decir a qué hora pasa algo: alle + número (alle nove) y all'una. Media es e mezza y cuarto es e un quarto.","examples":[{"target":"Che ore sono? Sono le otto.","base":"¿Qué hora es? Son las ocho."},{"target":"È l'una e mezza.","base":"Es la una y media."},{"target":"Lavoro alle nove.","base":"Trabajo a las nueve."}]},"review_status":"draft"},{"id":"it-a1-u10","language_code":"it","level":"A1","position":10,"title_es":"La ciudad","title_en":"La città","description_es":"Lugares de la ciudad, preguntar dónde está algo, ir a un lugar y dar direcciones.","emoji":"🏙️","objective_es":"Puedes preguntar dov'è…?, decir adónde vas con vado a / vado in y entender a destra, a sinistra, sempre dritto, vicino y lontano.","grammar":{"title":"Andare: vado a… / vado in…","explanation":"Andare («ir») es irregular: vado, vai, va. Con ciudades y con casa se usa a: vado a Roma, vado a casa. Con muchos lugares de la ciudad se usa in sin artículo: vado in banca, vado in piazza, vado in centro.","examples":[{"target":"Vado a Roma.","base":"Voy a Roma."},{"target":"Vado in banca.","base":"Voy al banco."},{"target":"Scusi, dov'è la stazione?","base":"Disculpe, ¿dónde está la estación?"}]},"review_status":"draft"},{"id":"it-a1-u11","language_code":"it","level":"A1","position":11,"title_es":"Gustos","title_en":"Mi piace","description_es":"Decir lo que te gusta y lo que no, preguntar gustos y decir lo que quieres y puedes hacer.","emoji":"❤️","objective_es":"Puedes decir mi piace / mi piacciono / non mi piace, preguntar ti piace?, responder anch'io o neanch'io y usar voglio y posso con un verbo.","grammar":{"title":"Mi piace / mi piacciono · voglio, posso + infinitivo","explanation":"Como en español, lo que gusta es el sujeto: mi piace con una cosa o un verbo (mi piace il calcio, mi piace cucinare) y mi piacciono con varias cosas (mi piacciono i gatti). Volere («querer») y potere («poder») van con el verbo en infinitivo: voglio viaggiare, posso pagare?","examples":[{"target":"Mi piace il calcio.","base":"Me gusta el fútbol."},{"target":"Mi piacciono i gatti.","base":"Me gustan los gatos."},{"target":"Voglio viaggiare in Italia.","base":"Quiero viajar a Italia."}]},"review_status":"draft"},{"id":"it-a1-u12","language_code":"it","level":"A1","position":12,"title_es":"Preguntas y precios","title_en":"Domande","description_es":"Preguntar quién, qué, cuándo, por qué, cómo y cuál, y preguntar cuánto cuesta algo en un negocio.","emoji":"❓","objective_es":"Puedes hacer preguntas con chi, cosa, quando, perché, come y quale, preguntar quanto costa? / quanto costano? y decir si algo es caro o economico.","grammar":{"title":"Palabras para preguntar · quanto costa / quanto costano","explanation":"La palabra de pregunta va al principio: chi? (¿quién?), cosa? (¿qué?), quando? (¿cuándo?), perché? (¿por qué?), come? (¿cómo?), quale? (¿cuál?). Perché sirve también para responder: «porque». Para el precio: quanto costa? con una cosa y quanto costano? con varias.","examples":[{"target":"Quando parti? — Domani.","base":"¿Cuándo te vas? — Mañana."},{"target":"Perché studi italiano? — Perché voglio viaggiare.","base":"¿Por qué estudias italiano? — Porque quiero viajar."},{"target":"Quanto costa il biglietto?","base":"¿Cuánto cuesta el boleto?"}]},"review_status":"draft"},{"id":"pt-a1-u01","language_code":"pt","level":"A1","position":1,"title_es":"Saludos y presentaciones","title_en":"Cumprimentos e apresentações","description_es":"Saludar, despedirte, agradecer y presentarte en portugués de Brasil.","emoji":"👋","objective_es":"Puedes saludar según el momento del día, presentarte, preguntar cómo está alguien y responder con cortesía.","grammar":{"title":"Obrigado / obrigada","explanation":"Para agradecer, la palabra concuerda con quien habla: un hombre dice obrigado y una mujer, obrigada.","examples":[{"target":"Obrigado, Ana! (lo dice Pedro)","base":"¡Gracias, Ana!"},{"target":"Obrigada, Pedro! (lo dice Ana)","base":"¡Gracias, Pedro!"}]},"review_status":"draft"},{"id":"pt-a1-u02","language_code":"pt","level":"A1","position":2,"title_es":"¿Quién eres y de dónde eres?","title_en":"Quem é você e de onde você é?","description_es":"El verbo ser, decir de dónde eres y hablar de otras personas.","emoji":"🌍","objective_es":"Puedes decir quién eres y de dónde eres, preguntarle lo mismo a otra persona y hablar de alguien con ele y ela.","grammar":{"title":"Ser con eu, você, ele y ela","explanation":"Eu sou (yo soy) y, para você, ele y ela, la misma forma: é. En Brasil você es el «tú» de todos los días y va con el verbo como ele: você é.","examples":[{"target":"Eu sou argentina.","base":"Yo soy argentina."},{"target":"Você é brasileiro?","base":"¿Tú eres brasileño?"},{"target":"Ela é professora.","base":"Ella es profesora."}]},"review_status":"draft"},{"id":"pt-a1-u03","language_code":"pt","level":"A1","position":3,"title_es":"Números y edad","title_en":"Números e idade","description_es":"Contar hasta veinte y decir cuántos años tienes.","emoji":"🔢","objective_es":"Puedes contar hasta veinte, preguntar la edad y decir cuántos años tienes.","grammar":{"title":"Ter … anos","explanation":"La edad se dice con ter (tener): eu tenho vinte anos. Con você, ele y ela: tem. Um y dois cambian con palabras femeninas: uma, duas.","examples":[{"target":"Quantos anos você tem?","base":"¿Cuántos años tienes?"},{"target":"Eu tenho dezoito anos.","base":"Tengo dieciocho años."},{"target":"Tenho duas irmãs.","base":"Tengo dos hermanas."}]},"review_status":"draft"},{"id":"pt-a1-u04","language_code":"pt","level":"A1","position":4,"title_es":"La familia","title_en":"A família","description_es":"Nombrar a tu familia, decir cuántos hermanos tienes y cómo se llaman.","emoji":"👨‍👩‍👧","objective_es":"Puedes presentar a tu familia, decir cuántos hermanos tienes y cómo se llaman tus familiares.","grammar":{"title":"Meu / minha","explanation":"Meu va con palabras masculinas y minha con femeninas: meu pai, minha mãe. En Brasil suele ir con artículo: o meu irmão, a minha irmã (las dos formas son correctas).","examples":[{"target":"Minha mãe se chama Laura.","base":"Mi mamá se llama Laura."},{"target":"Meu irmão tem dez anos.","base":"Mi hermano tiene diez años."}]},"review_status":"draft"},{"id":"pt-a1-u05","language_code":"pt","level":"A1","position":5,"title_es":"Objetos y colores","title_en":"Objetos e cores","description_es":"Nombrar objetos con su artículo, decir de qué color son y de quién son.","emoji":"🎒","objective_es":"Puedes preguntar qué es algo, nombrar objetos con o / a / um / uma, decir de qué color son y de quién son con do / da.","grammar":{"title":"Artículos y de + artículo","explanation":"El artículo es o (masculino), a (femenino), os y as en plural; um y uma son «un» y «una». De se junta con el artículo: de + o = do, de + a = da. En Brasil los nombres de persona suelen llevar artículo: o livro do João.","examples":[{"target":"o livro → os livros","base":"el libro → los libros"},{"target":"a caneta → as canetas","base":"el bolígrafo → los bolígrafos"},{"target":"A chave é da Ana.","base":"La llave es de Ana."}]},"review_status":"draft"},{"id":"pt-a1-u06","language_code":"pt","level":"A1","position":6,"title_es":"La casa","title_en":"A casa","description_es":"Las partes de la casa, los muebles, decir qué hay y dónde está cada cosa.","emoji":"🏠","objective_es":"Puedes describir tu casa con tem / há y decir dónde está algo con no / na, em cima de y embaixo de.","grammar":{"title":"Tem / há y em + artículo","explanation":"Para decir «hay», en Brasil se usa casi siempre tem; há es más formal. Em («en») se junta con el artículo: em + o = no, em + a = na. Para ubicar algo: está + no / na / em cima de / embaixo de.","examples":[{"target":"Na sala tem um sofá.","base":"En la sala hay un sillón."},{"target":"O livro está no quarto.","base":"El libro está en el dormitorio."},{"target":"A chave está em cima da mesa.","base":"La llave está encima de la mesa."}]},"review_status":"draft"},{"id":"pt-a1-u07","language_code":"pt","level":"A1","position":7,"title_es":"La comida","title_en":"A comida","description_es":"El desayuno, pedir con quero y queria, con o sin algo, y pedir la cuenta.","emoji":"🍞","objective_es":"Puedes nombrar lo que comes en el desayuno, pedir con quero o queria (más amable), decir con o sin qué y pedir la cuenta.","grammar":{"title":"Quero y queria","explanation":"Quero es «quiero». Para pedir con amabilidad, en Brasil se usa queria (literalmente «quería»): eu queria um café, por favor. Para mim… («para mí…») sirve para pedir sin verbo.","examples":[{"target":"Quero um suco.","base":"Quiero un jugo."},{"target":"Eu queria um pão de queijo, por favor.","base":"Quisiera un pan de queso, por favor."},{"target":"Para mim, um café com leite.","base":"Para mí, un café con leche."}]},"review_status":"draft"},{"id":"pt-a1-u08","language_code":"pt","level":"A1","position":8,"title_es":"La rutina","title_en":"A rotina","description_es":"Contar tu día: despertarte, trabajar o estudiar, almorzar y cenar, con verbos en -ar, -er e -ir.","emoji":"🌅","objective_es":"Puedes contar qué haces en un día normal con verbos en presente (falo, escrevo, durmo) y decir dónde vives con moro em.","grammar":{"title":"Presente: -ar, -er, -ir","explanation":"Con eu casi todos los verbos terminan en -o: falo, escrevo, durmo. Con você, ele y ela, en -a (los de -ar) o en -e (los de -er e -ir): fala, escreve, dorme. En Brasil «tú» casi no se usa: se dice você con el verbo como ele.","examples":[{"target":"Eu falo português.","base":"Yo hablo portugués."},{"target":"Você fala espanhol?","base":"¿Tú hablas español?"},{"target":"Eu moro em São Paulo.","base":"Vivo en San Pablo."}]},"review_status":"draft"},{"id":"pt-a1-u09","language_code":"pt","level":"A1","position":9,"title_es":"Horas y días","title_en":"Horas e dias","description_es":"Decir y preguntar la hora, a qué hora haces algo y los días de la semana (segunda-feira…).","emoji":"🕗","objective_es":"Puedes preguntar y decir la hora (que horas são? são oito horas), decir a qué hora haces algo (às nove) y nombrar los días de la semana.","grammar":{"title":"São… horas / é uma hora / às…","explanation":"Para la hora se usa são + número + horas (são oito horas), salvo la una: é uma hora. Para decir a qué hora pasa algo: às + número (às nove). Los días de lunes a viernes se cuentan: segunda-feira (lunes), terça-feira (martes)…","examples":[{"target":"Que horas são? São oito horas.","base":"¿Qué hora es? Son las ocho."},{"target":"É uma e meia.","base":"Es la una y media."},{"target":"Trabalho às nove.","base":"Trabajo a las nueve."}]},"review_status":"draft"},{"id":"pt-a1-u10","language_code":"pt","level":"A1","position":10,"title_es":"La ciudad","title_en":"A cidade","description_es":"Lugares de la ciudad, preguntar dónde queda algo, decir adónde vas y dar direcciones.","emoji":"🏙️","objective_es":"Puedes preguntar onde fica…?, decir adónde vas con vou para… y entender à direita, à esquerda, reto, perto y longe.","grammar":{"title":"Onde fica…? / vou para…","explanation":"Para preguntar dónde queda un lugar se usa onde fica…? (ficar = quedar). Ir es irregular: eu vou, você vai. Adónde vas va con para + artículo: vou para a escola, vou para o centro. En la charla para a se dice pra.","examples":[{"target":"Com licença, onde fica a estação?","base":"Permiso, ¿dónde queda la estación?"},{"target":"Eu vou para a padaria.","base":"Voy a la panadería."},{"target":"A loja fica à direita.","base":"La tienda queda a la derecha."}]},"review_status":"draft"},{"id":"pt-a1-u11","language_code":"pt","level":"A1","position":11,"title_es":"Gustos","title_en":"Eu gosto de…","description_es":"Decir lo que te gusta con gostar de, preguntar gustos, decir lo que puedes hacer y dos falsos amigos.","emoji":"❤️","objective_es":"Puedes decir eu gosto de… / não gosto de…, preguntar você gosta de…?, responder eu também / eu também não y usar posso y pode con un verbo.","grammar":{"title":"Gostar de (≠ gustar) · poder + infinitivo","explanation":"En portugués la persona es el sujeto: eu gosto de futebol («me gusta el fútbol»), literalmente «yo gusto de». Siempre lleva de, que se junta con el artículo: gosto do Brasil (de + o), gosto da praia (de + a). Poder va con el verbo en infinitivo: posso pagar?","examples":[{"target":"Eu gosto de futebol.","base":"Me gusta el fútbol."},{"target":"Eu gosto da praia.","base":"Me gusta la playa."},{"target":"Você pode jogar amanhã?","base":"¿Puedes jugar mañana?"}]},"review_status":"draft"},{"id":"pt-a1-u12","language_code":"pt","level":"A1","position":12,"title_es":"Preguntas y precios","title_en":"Perguntas","description_es":"Preguntar qué, quién, cuándo, por qué y cuál, preguntar cuánto cuesta algo y el falso amigo apelido.","emoji":"❓","objective_es":"Puedes preguntar con o que, quem, quando, por que y qual, responder con porque, preguntar quanto custa? / quanto custam? y decir si algo es caro o barato.","grammar":{"title":"Palabras para preguntar · por que / porque","explanation":"La palabra de pregunta va al principio: o que? (¿qué?), quem? (¿quién?), quando? (¿cuándo?), qual? (¿cuál?). Para «¿por qué?» se escribe por que, separado; para responder, porque, junto. El precio: quanto custa? con una cosa y quanto custam? con varias.","examples":[{"target":"O que você faz? — Eu estudo.","base":"¿Qué haces? — Estudio."},{"target":"Por que você estuda português? — Porque eu gosto.","base":"¿Por qué estudias portugués? — Porque me gusta."},{"target":"Quanto custa a camiseta?","base":"¿Cuánto cuesta la camiseta?"}]},"review_status":"draft"},{"id":"zh-a1-u01","language_code":"zh","level":"A1","position":1,"title_es":"Tonos y saludos","title_en":"你好！Tones and greetings","description_es":"Los cuatro tonos, saludar, agradecer, disculparte y decir tu nombre.","emoji":"👋","objective_es":"Puedes distinguir los cuatro tonos, saludar, agradecer, disculparte, decir tu nombre y responder que estás bien.","grammar":{"title":"Los tonos","explanation":"Cada sílaba tiene un tono que cambia el significado: 1.º alto y parejo (mā), 2.º sube (má), 3.º baja y sube (mǎ), 4.º baja (mà). Sin marca, el tono es neutro y corto.","examples":[{"target":"妈 mā","base":"mamá"},{"target":"马 mǎ","base":"caballo"},{"target":"骂 mà","base":"regañar"}]},"review_status":"draft"},{"id":"zh-a1-u02","language_code":"zh","level":"A1","position":2,"title_es":"¿Quién eres y de dónde eres?","title_en":"你是哪国人？","description_es":"Ser con 是, negar con 不, preguntar con 吗 y decir tu nacionalidad.","emoji":"🌍","objective_es":"Puedes decir qué eres y de dónde eres, negar, hacer preguntas de sí o no y hablar de alguien con 他 y 她.","grammar":{"title":"是, 不 y 吗","explanation":"是 (shì) une dos sustantivos: 我是学生 «yo soy estudiante». Para negar, 不 antes del verbo: 我不是老师. Para preguntar sí o no, 吗 al final: 你是学生吗？ El verbo no cambia nunca.","examples":[{"target":"我是学生。","base":"Soy estudiante."},{"target":"我不是老师。","base":"No soy profesor/a."},{"target":"你是中国人吗？","base":"¿Eres chino/a?"}]},"review_status":"draft"},{"id":"zh-a1-u03","language_code":"zh","level":"A1","position":3,"title_es":"Números y edad","title_en":"数字和年龄","description_es":"Contar hasta veinte, preguntar la edad y decir cuántos años tienes.","emoji":"🔢","objective_es":"Puedes contar hasta veinte, armar números con 十, preguntar la edad y decir cuántos años tienes.","grammar":{"title":"Números con 十 y la edad con 岁","explanation":"Los números se arman como una cuenta: 十八 = 10 + 8, 二十 = 2 × 10. La edad no lleva verbo: 我二十岁 «yo veinte años». Para contar cosas, «dos» es 两: 两岁.","examples":[{"target":"我二十岁。","base":"Tengo veinte años."},{"target":"你几岁？","base":"¿Cuántos años tienes? (a un chico)"},{"target":"你多大？","base":"¿Qué edad tienes? (a un joven o adulto)"}]},"review_status":"draft"},{"id":"zh-a1-u04","language_code":"zh","level":"A1","position":4,"title_es":"La familia","title_en":"我的家","description_es":"Nombrar a tu familia, decir cuántos hermanos tienes y de quién es algo.","emoji":"👨‍👩‍👧","objective_es":"Puedes nombrar a tu familia, decir cuántos hermanos tienes (o que no tienes) y marcar de quién es algo con 的.","grammar":{"title":"有 / 没有 y el clasificador 个","explanation":"有 es «tener» y se niega con 没: 没有 (nunca 不有). Para contar personas, entre el número y la palabra va un clasificador: 两个哥哥. 个 es el más común.","examples":[{"target":"我有两个哥哥。","base":"Tengo dos hermanos mayores."},{"target":"我没有妹妹。","base":"No tengo hermanas menores."}]},"review_status":"draft"},{"id":"zh-a1-u05","language_code":"zh","level":"A1","position":5,"title_es":"Objetos","title_en":"这是什么？","description_es":"Preguntar qué es algo con 这 y 那, contar cosas con 本, 个 y 杯, y decir de quién es.","emoji":"🎒","objective_es":"Puedes preguntar qué es algo con 这 / 那 y 什么, contar cosas con el clasificador correcto (本, 个, 杯) y preguntar de quién es con 谁的.","grammar":{"title":"这 / 那 y los clasificadores","explanation":"这 (zhè) es «esto / este» y 那 (nà) «eso / ese». Entre un número (o 这 / 那) y la cosa va un clasificador: 本 para libros, 杯 para bebidas y 个 para casi todo lo demás. 一 cambia de tono: yì běn, yì bēi, pero yí ge.","examples":[{"target":"这是什么？","base":"¿Qué es esto?"},{"target":"我有三本书。","base":"Tengo tres libros."},{"target":"一杯水","base":"un vaso de agua","note":"yì bēi"}]},"review_status":"draft"},{"id":"zh-a1-u06","language_code":"zh","level":"A1","position":6,"title_es":"La casa","title_en":"你在哪儿？","description_es":"Decir dónde está algo o alguien con 在, preguntar con 哪儿 y ubicar con 里, 上 y 下.","emoji":"🏠","objective_es":"Puedes decir y preguntar dónde está algo o alguien con 在 y 哪儿, ubicarlo con 里, 上 y 下, y decir qué hay en un lugar con 有.","grammar":{"title":"在 + lugar + 里 / 上 / 下","explanation":"在 (zài) es «estar en»: cosa + 在 + lugar. Para precisar, la palabra de posición va DESPUÉS del lugar: 在包里 «en el bolso», 在桌子上 «sobre la mesa». Para «hay» se invierte el orden: lugar + 有 + cosa.","examples":[{"target":"我在家。","base":"Estoy en casa."},{"target":"手机在桌子上。","base":"El celular está sobre la mesa."},{"target":"桌子上有一本书。","base":"Sobre la mesa hay un libro."}]},"review_status":"draft"},{"id":"zh-a1-u07","language_code":"zh","level":"A1","position":7,"title_es":"Comer y beber","title_en":"吃饭","description_es":"Comer y beber con 吃 y 喝, pedir con 要, decir qué tienes ganas de comer con 想.","emoji":"🍜","objective_es":"Puedes decir qué comes y tomas, pedir con 要 (y rechazar con 不要), decir qué tienes ganas de comer con 想 y que algo está rico.","grammar":{"title":"要 y 想 + verbo","explanation":"要 (yào) es «querer» para pedir algo concreto: 我要一杯茶. 想 (xiǎng) + verbo es «tener ganas de»: 我想吃饺子. Los dos se niegan con 不 (不要, 不想). El verbo no cambia nunca.","examples":[{"target":"我要一杯咖啡。","base":"Quiero un café."},{"target":"我想吃面条。","base":"Tengo ganas de comer fideos."},{"target":"我不要牛奶。","base":"No quiero leche.","note":"bú yào"}]},"review_status":"draft"},{"id":"zh-a1-u08","language_code":"zh","level":"A1","position":8,"title_es":"Todos los días","title_en":"每天","description_es":"Contar tu rutina: levantarte, desayunar, trabajar o estudiar, con la palabra de tiempo antes del verbo.","emoji":"🌅","objective_es":"Puedes contar qué haces en un día normal (起床, 工作, 学习, 睡觉) y cuándo (每天, 早上, 晚上), con el tiempo antes del verbo.","grammar":{"title":"Tiempo antes del verbo","explanation":"En chino la palabra de tiempo va antes del verbo, nunca al final: 我每天学习中文 («yo todos los días estudio chino»). También puede ir al principio de la oración: 早上我喝咖啡. El verbo no cambia nunca.","examples":[{"target":"我每天学习中文。","base":"Estudio chino todos los días."},{"target":"早上我喝咖啡。","base":"Por la mañana tomo café."},{"target":"我晚上看电视。","base":"Por la noche miro la tele."}]},"review_status":"draft"},{"id":"zh-a1-u09","language_code":"zh","level":"A1","position":9,"title_es":"La hora y los días","title_en":"时间","description_es":"Preguntar y decir la hora con 几点, los días con 星期 y la fecha con 月 y 号.","emoji":"🕗","objective_es":"Puedes preguntar y decir la hora (现在几点？八点半), decir a qué hora haces algo, nombrar los días con 星期 y decir la fecha.","grammar":{"title":"几点, 星期几 y 几月几号","explanation":"La hora es número + 点: 八点 (las ocho), 八点半 (ocho y media), 八点十分 (ocho y diez). Las dos son 两点, no 二点. Los días son 星期 + número: 星期一 es lunes; el domingo es 星期天. Para preguntar se pone 几 donde va el número: 几点？星期几？几月几号？","examples":[{"target":"现在几点？现在八点半。","base":"¿Qué hora es? Son las ocho y media."},{"target":"今天星期几？今天星期一。","base":"¿Qué día es hoy? Hoy es lunes."},{"target":"今天五月三号。","base":"Hoy es 3 de mayo."}]},"review_status":"draft"},{"id":"zh-a1-u10","language_code":"zh","level":"A1","position":10,"title_es":"Ir a lugares","title_en":"去","description_es":"Decir adónde vas con 去, lugares de la ciudad, cómo vas (坐地铁, 走路) y si queda cerca o lejos.","emoji":"🚇","objective_es":"Puedes decir adónde vas (我去商店), cómo vas (我坐地铁去学校), preguntar 怎么去？ y decir si un lugar queda cerca (近) o lejos (远).","grammar":{"title":"去 + lugar y 坐 + vehículo + 去","explanation":"去 (qù) es «ir» y va directo con el lugar, sin preposición: 我去学校. El medio de transporte va antes: 坐 (zuò, «tomar, ir sentado en») + vehículo + 去 + lugar: 我坐地铁去学校. Para preguntar cómo: 你怎么去？","examples":[{"target":"你去哪儿？我去商店。","base":"¿Adónde vas? Voy a la tienda."},{"target":"我坐地铁去学校。","base":"Voy a la escuela en metro."},{"target":"医院远吗？不远，很近。","base":"¿El hospital queda lejos? No, queda muy cerca."}]},"review_status":"draft"},{"id":"zh-a1-u11","language_code":"zh","level":"A1","position":11,"title_es":"Gustos y habilidades","title_en":"喜欢","description_es":"Decir lo que te gusta con 喜欢, lo que sabes hacer con 会, lo que puedes con 能 y cómo estás con 很 + adjetivo.","emoji":"❤️","objective_es":"Puedes decir 我喜欢… / 我不喜欢…, contar lo que sabes hacer (我会游泳), decir si puedes (我今天不能去) y describir con 很 + adjetivo (我很忙).","grammar":{"title":"喜欢 + cosa o verbo · 会 y 能 · 很 + adjetivo","explanation":"喜欢 (xǐhuan) es «gustar» y funciona como un verbo común: 我喜欢猫 («me gustan los gatos», literalmente «yo gusto gatos»); también va con otro verbo: 我喜欢看电影. 会 (huì) es «saber hacer algo aprendido» (我会游泳) y 能 (néng) es «poder» en ese momento (我今天不能去). Los adjetivos van con 很 y sin 是: 我很忙.","examples":[{"target":"我喜欢听音乐。","base":"Me gusta escuchar música."},{"target":"你会说中文吗？","base":"¿Sabes hablar chino?"},{"target":"今天我很累。","base":"Hoy estoy muy cansado/a."}]},"review_status":"draft"},{"id":"zh-a1-u12","language_code":"zh","level":"A1","position":12,"title_es":"De compras","title_en":"多少钱","description_es":"Preguntar cuánto cuesta algo (多少钱), entender precios en 块, opinar con 太…了 y 怎么样 y preguntar «¿y…?» con 呢.","emoji":"🛍️","objective_es":"Puedes preguntar 多少钱？, entender precios (二十块), decir 太贵了！, preguntar 怎么样？, usar 呢 para «¿y…?» y distinguir 买 (comprar) de 卖 (vender).","grammar":{"title":"多少钱 · 太 + adjetivo + 了 · 呢","explanation":"Para el precio: cosa + 多少钱？ (这个多少钱？). En la charla la moneda se dice 块 (kuài): 十块. Con ropa van clasificadores: 一件衣服 (una prenda), 一双鞋 (un par de zapatos). Para «demasiado»: 太 + adjetivo + 了 (太贵了！). 呢 al final pregunta «¿y…?»: 你呢？, 我的手机呢？","examples":[{"target":"这件衣服多少钱？","base":"¿Cuánto cuesta esta prenda?"},{"target":"九十块？太贵了！","base":"¿Noventa yuanes? ¡Es carísimo!","note":"jiǔshí kuài"},{"target":"这双鞋怎么样？","base":"¿Qué tal estos zapatos?"}]},"review_status":"draft"},{"id":"a1-u13","language_code":"en","level":"A1","position":13,"title_es":"Letras y datos personales","title_en":"Letters and personal details","description_es":"El alfabeto, deletrear y dar datos personales en un formulario.","emoji":"🔤","objective_es":"Puedes deletrear un nombre y entender un formulario con datos personales.","grammar":null,"review_status":"draft"},{"id":"a1-u14","language_code":"en","level":"A1","position":14,"title_es":"Precios y compras","title_en":"Prices and shopping","description_es":"Los números hasta el 100, los precios y cómo pedir en una tienda.","emoji":"🛍️","objective_es":"Puedes entender precios y lo que se pide en una tienda.","grammar":null,"review_status":"draft"},{"id":"a2-u13","language_code":"en","level":"A2","position":13,"title_es":"Comer afuera","title_en":"Eating out","description_es":"El menú, some y any, much y many, pedir en un restaurante y pagar la cuenta.","emoji":"🍽️","objective_es":"Puedes leer un menú, pedir la comida con cortesía y pedir la cuenta.","grammar":{"title":"Some, any, much y many","explanation":"Some va en afirmativas y any en negativas y preguntas. Many va con lo que se cuenta (many eggs) y much con lo que no (much water); a lot of sirve para los dos.","examples":[{"target":"There is some milk.","base":"Hay algo de leche."},{"target":"We don't have any bread.","base":"No tenemos nada de pan."},{"target":"There aren't many people here.","base":"No hay mucha gente aquí."}]},"review_status":"draft"},{"id":"a2-u14","language_code":"en","level":"A2","position":14,"title_es":"Tiempo libre e invitaciones","title_en":"Free time and invitations","description_es":"Pasatiempos, invitar, proponer planes, aceptar o rechazar y quedar para verse.","emoji":"🎟️","objective_es":"Puedes hablar de tus pasatiempos, invitar a alguien y aceptar o rechazar un plan.","grammar":{"title":"Invitar y proponer","explanation":"Would you like to + verbo invita (¿te gustaría…?). Let's + verbo y How about + sustantivo o verbo con -ing proponen un plan. Se acepta con I'd love to y se rechaza con Sorry, I can't.","examples":[{"target":"Would you like to go to the cinema?","base":"¿Te gustaría ir al cine?"},{"target":"Let's go out tonight!","base":"¡Salgamos esta noche!"},{"target":"Sorry, I can't. Maybe another time.","base":"Perdón, no puedo. Quizás otro día."}]},"review_status":"draft"},{"id":"a2-u15","language_code":"en","level":"A2","position":15,"title_es":"Cómo es","title_en":"Describing people and places","description_es":"El aspecto y el carácter de una persona, tu barrio y cómo comparar personas y lugares.","emoji":"🧑‍🦱","objective_es":"Puedes describir a una persona y un lugar, y compararlos.","grammar":{"title":"Look like y be like","explanation":"What does she look like? pregunta por el aspecto; What is she like?, por el carácter. El aspecto se describe con be (She is tall) y con have (She has curly hair).","examples":[{"target":"What does she look like?","base":"¿Cómo es (físicamente)?"},{"target":"She has long blond hair.","base":"Tiene el pelo largo y rubio."},{"target":"What's he like? He's friendly.","base":"¿Cómo es (de carácter)? Es simpático."}]},"review_status":"draft"},{"id":"a2-u16","language_code":"en","level":"A2","position":16,"title_es":"Mensajes, correos y llamadas","title_en":"Messages, emails and calls","description_es":"Mensajes y correos, pedir algo con Could you…?, hablar por teléfono y reservar un hotel.","emoji":"✉️","objective_es":"Puedes escribir y entender mensajes y correos cortos, hablar por teléfono y reservar un hotel.","grammar":{"title":"Correos y pedidos","explanation":"Un correo empieza con Dear + nombre y termina con Best wishes. Para pedir algo con cortesía se usa Could you + verbo…? (¿podrías…?).","examples":[{"target":"Dear Ana,","base":"Querida Ana:"},{"target":"Could you send me the photos, please?","base":"¿Podrías mandarme las fotos, por favor?"},{"target":"Best wishes, Leo","base":"Saludos, Leo"}]},"review_status":"draft"},{"id":"a2-u17","language_code":"en","level":"A2","position":17,"title_es":"Contar una historia","title_en":"Telling a story","description_es":"Lo que estaba pasando (was/were + -ing), when y while, accidentes y el orden de un relato.","emoji":"📖","objective_es":"Puedes contar una historia corta del pasado: qué estaba pasando, qué pasó de repente y cómo terminó.","grammar":{"title":"Past continuous","explanation":"Was/were + verbo con -ing cuenta lo que estaba pasando en un momento del pasado. La acción corta que la interrumpe va en past simple: I was cooking when the phone rang.","examples":[{"target":"I was reading at nine.","base":"A las nueve estaba leyendo."},{"target":"I was sleeping when the phone rang.","base":"Estaba durmiendo cuando sonó el teléfono."},{"target":"While we were walking, we heard a noise.","base":"Mientras caminábamos, oímos un ruido."}]},"review_status":"draft"},{"id":"b1-u01","language_code":"en","level":"B1","position":1,"title_es":"Experiencias de vida","title_en":"Life experiences","description_es":"Contar experiencias con el present perfect y decir cuándo pasaron con el past simple; logros y recuerdos.","emoji":"🌍","objective_es":"Puedes contar experiencias de tu vida, decir si alguna vez hiciste algo y explicar cuándo y cómo pasó.","grammar":{"title":"Present perfect y past simple","explanation":"El present perfect (have/has + participio) cuenta una experiencia sin decir cuándo: I have climbed a mountain. Si dices cuándo (last year, in 2020, two years ago), usas el past simple: I climbed it last year.","examples":[{"target":"I have been to Brazil.","base":"Estuve en Brasil (alguna vez)."},{"target":"I went there last year.","base":"Fui el año pasado."},{"target":"Have you ever won a prize?","base":"¿Alguna vez ganaste un premio?"}]},"review_status":"draft"},{"id":"b1-u02","language_code":"en","level":"B1","position":2,"title_es":"Hábitos y aficiones","title_en":"Habits and hobbies","description_es":"Desde cuándo haces algo (for, since), lo que vienes haciendo (have been + -ing) y lo que te gusta, empiezas o dejas de hacer.","emoji":"🎸","objective_es":"Puedes contar desde cuándo haces algo, qué vienes haciendo últimamente y qué hábitos empezaste o dejaste.","grammar":{"title":"Present perfect continuous","explanation":"Have/has been + verbo con -ing cuenta algo que empezó en el pasado y sigue hasta ahora: I have been learning English for two years. For va con un período (for two years) y since con el comienzo (since 2020).","examples":[{"target":"I've been playing the guitar for three years.","base":"Toco la guitarra desde hace tres años."},{"target":"She has been working here since March.","base":"Trabaja aquí desde marzo."},{"target":"How long have you been learning English?","base":"¿Hace cuánto que aprendes inglés?"}]},"review_status":"draft"},{"id":"b1-u03","language_code":"en","level":"B1","position":3,"title_es":"Anécdotas","title_en":"Anecdotes","description_es":"Contar anécdotas: lo que estaba pasando, lo que ya había pasado (had + participio) y el orden de los hechos.","emoji":"🗯️","objective_es":"Puedes contar una anécdota en orden, explicar qué ya había pasado y reaccionar a lo que te cuentan.","grammar":{"title":"Past perfect","explanation":"Had + participio cuenta algo que pasó ANTES de otro momento del pasado: When I got to the station, the train had left (el tren se fue antes de que yo llegara). Es igual para todas las personas: I had, she had, they had.","examples":[{"target":"When I arrived, the train had left.","base":"Cuando llegué, el tren ya se había ido."},{"target":"I realized I had forgotten my keys.","base":"Me di cuenta de que me había olvidado las llaves."},{"target":"By the time we got there, the movie had started.","base":"Para cuando llegamos, la película había empezado."}]},"review_status":"draft"},{"id":"b1-u04","language_code":"en","level":"B1","position":4,"title_es":"Planes y objetivos","title_en":"Plans and goals","description_es":"Hablar del futuro: lo que vas a hacer, lo que ya arreglaste, lo que decides en el momento y lo que puede pasar; metas y proyectos.","emoji":"🎯","objective_es":"Puedes contar tus planes y objetivos, decir qué ya arreglaste y qué podría pasar, y hablar de proyectos a largo plazo.","grammar":{"title":"Formas de futuro","explanation":"Going to: una intención (I am going to save money). Present continuous: algo ya arreglado, con día y hora (I am meeting Ana on Friday). Will: una decisión en el momento o una predicción (I will help you). Might: algo posible (I might go).","examples":[{"target":"I'm meeting my sister on Saturday.","base":"El sábado me encuentro con mi hermana."},{"target":"It's cold. I'll close the window.","base":"Hace frío. Cierro la ventana."},{"target":"I might go to the concert.","base":"Puede que vaya al recital."}]},"review_status":"draft"},{"id":"b1-u05","language_code":"en","level":"B1","position":5,"title_es":"Trabajo y estudios","title_en":"Work and studies","description_es":"Obligaciones y permisos (have to, must, allowed to), exámenes y materias, avisos de trabajo, el CV y una entrevista.","emoji":"💼","objective_es":"Puedes hablar de obligaciones y normas en el trabajo o el estudio, entender un aviso de trabajo y responder en una entrevista.","grammar":{"title":"Obligación y permiso","explanation":"Have to y must: obligación (must, sobre todo en normas escritas). Don't have to: no hace falta (no es obligatorio). Mustn't y not allowed to: está prohibido. Allowed to: tienes permiso.","examples":[{"target":"I have to wear a uniform at work.","base":"Tengo que usar uniforme en el trabajo."},{"target":"You don't have to come. It's not necessary.","base":"No hace falta que vengas. No es necesario."},{"target":"We are not allowed to use our phones in class.","base":"No nos dejan usar el teléfono en clase."}]},"review_status":"draft"},{"id":"b1-u06","language_code":"en","level":"B1","position":6,"title_es":"Viajes y cultura","title_en":"Travel and culture","description_es":"El primer condicional (if, unless), problemas de viaje, recorrer una ciudad, dinero y propinas y las costumbres de otros países.","emoji":"🧳","objective_es":"Puedes resolver problemas de viaje, decir qué vas a hacer si pasa algo y explicar costumbres de un lugar.","grammar":{"title":"Primer condicional","explanation":"If + presente, will + verbo: una condición posible y su resultado. If it rains, we will stay at the hotel. Unless es «a menos que» (= if not): We will miss the bus unless we take a taxi.","examples":[{"target":"If it rains, we will visit the museum.","base":"Si llueve, vamos a visitar el museo."},{"target":"If you wait ten minutes, the room will be ready.","base":"Si espera diez minutos, la habitación va a estar lista."},{"target":"We'll be late unless we take a taxi.","base":"Vamos a llegar tarde a menos que tomemos un taxi."}]},"review_status":"draft"},{"id":"b1-u07","language_code":"en","level":"B1","position":7,"title_es":"Salud y bienestar","title_en":"Health and well-being","description_es":"Síntomas y la farmacia, consejos (should, ought to, had better), hábitos saludables, comparaciones y el estrés.","emoji":"🧘","objective_es":"Puedes explicar síntomas, dar y pedir consejos de salud y comparar hábitos.","grammar":{"title":"Consejos y comparaciones","explanation":"Should y ought to dan consejos (ought to es más formal). Had better ('d better) es un consejo fuerte, casi una advertencia: You'd better see a doctor. Para comparar: as … as (tan … como), not as … as (no tan … como), much / a bit + comparativo (mucho / un poco más).","examples":[{"target":"You'd better see a doctor.","base":"Más vale que vayas al médico."},{"target":"Walking is not as hard as running.","base":"Caminar no es tan duro como correr."},{"target":"I feel much better today.","base":"Hoy me siento mucho mejor."}]},"review_status":"draft"},{"id":"b1-u08","language_code":"en","level":"B1","position":8,"title_es":"Tecnología y comunicación","title_en":"Technology and communication","description_es":"Explicar qué es algo o quién es alguien (who, which, that, where), aparatos, internet, redes sociales y videollamadas.","emoji":"📱","objective_es":"Puedes explicar para qué sirve un aparato o una app, resolver problemas simples de tecnología y contar cómo te comunicas.","grammar":{"title":"Oraciones de relativo","explanation":"Who se refiere a personas (the woman who lives next door); which y that, a cosas (an app which/that helps you); where, a lugares (the cafe where we met). Así explicas qué es algo sin empezar otra oración.","examples":[{"target":"She is the teacher who helped me.","base":"Es la profesora que me ayudó."},{"target":"This is an app that helps you learn words.","base":"Es una app que te ayuda a aprender palabras."},{"target":"That is the cafe where we met.","base":"Ese es el café donde nos conocimos."}]},"review_status":"draft"},{"id":"b1-u09","language_code":"en","level":"B1","position":9,"title_es":"Medioambiente y sociedad","title_en":"The environment and society","description_es":"El planeta y la contaminación, la voz pasiva (is made, was built), reciclar, ahorrar energía y proyectos de la comunidad.","emoji":"🌱","objective_es":"Puedes hablar de problemas del medioambiente, explicar cómo se hace algo con la voz pasiva y proponer soluciones simples.","grammar":{"title":"Voz pasiva","explanation":"La pasiva pone el foco en lo que recibe la acción: be + participio. Presente: Paper is recycled. Pasado: The bridge was built in 1890. Si importa quién lo hizo, va con by: It was designed by a famous engineer.","examples":[{"target":"Plastic bottles are recycled here.","base":"Aquí se reciclan las botellas de plástico."},{"target":"This house was built in 1950.","base":"Esta casa fue construida en 1950."},{"target":"The park was cleaned by volunteers.","base":"El parque fue limpiado por voluntarios."}]},"review_status":"draft"},{"id":"b1-u10","language_code":"en","level":"B1","position":10,"title_es":"Noticias y medios","title_en":"News and media","description_es":"Titulares y artículos, contar lo que alguien dijo o preguntó (estilo indirecto), sucesos y noticias falsas.","emoji":"📰","objective_es":"Puedes entender titulares y noticias breves, contar lo que otra persona dijo o preguntó y distinguir una fuente confiable.","grammar":{"title":"Estilo indirecto","explanation":"Para contar lo que alguien dijo: said (that) + oración, o told + persona + (that). El verbo suele ir un tiempo atrás: «I am tired» → She said she was tired; «I will call» → He said he would call; «I can help» → She said she could help. Preguntas: asked if… / asked where…","examples":[{"target":"She said that she was tired.","base":"Dijo que estaba cansada."},{"target":"He told me that he would call.","base":"Me dijo que iba a llamar."},{"target":"They asked if we were ready.","base":"Preguntaron si estábamos listos."}]},"review_status":"draft"},{"id":"b1-u11","language_code":"en","level":"B1","position":11,"title_es":"Opiniones y relaciones","title_en":"Opinions and relationships","description_es":"Dar tu opinión, acordar y discrepar, ventajas y desventajas, imaginar con el segundo condicional, relaciones y deseos.","emoji":"💬","objective_es":"Puedes dar y defender tu opinión, aconsejar a alguien con if I were you, hablar de tus relaciones y expresar deseos.","grammar":{"title":"Segundo condicional","explanation":"If + past simple, would + verbo: una situación imaginaria o poco probable. If I had more time, I would travel more (no tengo tiempo). Con be se usa were para todos: If I were you, I would talk to her (yo que tú…).","examples":[{"target":"If I had more time, I would travel more.","base":"Si tuviera más tiempo, viajaría más."},{"target":"If I were you, I would talk to her.","base":"Yo que tú, hablaría con ella."},{"target":"I wish I had more free time.","base":"Ojalá tuviera más tiempo libre."}]},"review_status":"draft"},{"id":"b1-u12","language_code":"en","level":"B1","position":12,"title_es":"Problemas y soluciones","title_en":"Problems and solutions","description_es":"Deducir qué pasa (must be, can't be), cosas que se rompen, reclamos, causas y contrastes (because of, although, however) y soluciones.","emoji":"🛠️","objective_es":"Puedes explicar un problema, sacar conclusiones, hacer un reclamo formal y proponer una solución.","grammar":{"title":"Deducción y conectores","explanation":"Must be: estás casi seguro de que es así; can't be: estás casi seguro de que no; might be: es posible. Conectores: because of + sustantivo (causa), therefore (consecuencia), although + oración y however al empezar otra oración (contraste).","examples":[{"target":"They can't be mine. They must be Tom's.","base":"No pueden ser mías. Deben ser de Tom."},{"target":"Because of the storm, the trains are canceled.","base":"Por la tormenta, los trenes están cancelados."},{"target":"Although it was expensive, it broke after a week.","base":"Aunque era caro, se rompió a la semana."}]},"review_status":"draft"},{"id":"b2-u01","language_code":"en","level":"B2","position":1,"title_es":"Decir las cosas con matices","title_en":"Saying things with nuance","description_es":"Malentendidos, tono e indirectas; remember, stop o try con -ing o infinitivo; ser directo sin ser brusco.","emoji":"🗣️","objective_es":"Puedes aclarar un malentendido, entender una indirecta y decir algo difícil con tacto.","grammar":{"title":"Verbos con -ing o infinitivo","explanation":"Algunos verbos cambian de sentido según lo que sigue. Remember / forget + -ing: algo que ya pasó (I remember meeting her). Remember / forget + to: algo que tienes que hacer (Remember to call him). Stop + -ing: dejar de hacer; stop + to: parar para hacer otra cosa. Try + -ing: probar algo; try + to: intentar. Regret + -ing: lamentar algo que hiciste. Mean to: tener la intención.","examples":[{"target":"I remember meeting her, but I forgot to ask her name.","base":"Me acuerdo de haberla conocido, pero me olvidé de preguntarle el nombre."},{"target":"We stopped to talk. Then we stopped talking.","base":"Paramos para hablar. Después dejamos de hablar."},{"target":"I didn't mean to sound rude.","base":"No fue mi intención sonar maleducado."}]},"review_status":"draft"},{"id":"b2-u02","language_code":"en","level":"B2","position":2,"title_es":"Trabajo, liderazgo y negociación","title_en":"Work, leadership and negotiation","description_es":"Negociar y ceder, poner condiciones (as long as, provided that, otherwise, in case), liderar un equipo y decir que no con cortesía.","emoji":"🤝","objective_es":"Puedes negociar un acuerdo con condiciones, repartir tareas en un equipo y rechazar una propuesta con cortesía.","grammar":{"title":"Condiciones: as long as, provided that, otherwise, in case","explanation":"As long as y provided that ponen una condición (siempre que, siempre y cuando) y van con presente aunque hablen del futuro. Otherwise (si no, de lo contrario) dice qué pasa si la condición no se cumple. In case (por si) habla de una precaución: haces algo antes por si pasa otra cosa. Unless (a menos que) ya lo conoces del B1.","examples":[{"target":"I could offer three percent, as long as you sign a two-year contract.","base":"Podría ofrecer un tres por ciento, siempre que firmen un contrato de dos años."},{"target":"Send me the terms in writing, in case anything changes.","base":"Mándame las condiciones por escrito, por si algo cambia."},{"target":"Hurry up. Otherwise, we will miss the train.","base":"Apúrate. Si no, vamos a perder el tren."}]},"review_status":"draft"},{"id":"b2-u03","language_code":"en","level":"B2","position":3,"title_es":"Sociedad, cultura y actualidad","title_en":"Society, culture and current affairs","description_es":"Cambios en la sociedad, generaciones y costumbres, cifras y encuestas, y la voz pasiva avanzada: has been done, is being done, it is said that…","emoji":"🏙️","objective_es":"Puedes hablar de cambios sociales, entender una noticia con cifras y contar lo que se dice o se espera con la voz pasiva.","grammar":{"title":"Voz pasiva avanzada","explanation":"La pasiva pone el foco en lo que pasa, no en quién lo hace. Present perfect: has been + participio (The roof has been repaired). Continuo: is / are being + participio (New homes are being built). Con modales: should / can / will be + participio. Impersonal, para lo que piensa o dice la gente: It is said that… / It is believed that…, o Something is expected to / is believed to + verbo.","examples":[{"target":"Two thousand new homes are being built near the river.","base":"Se están construyendo dos mil viviendas nuevas cerca del río."},{"target":"The roof has already been repaired.","base":"El techo ya fue reparado."},{"target":"It is said that living alone makes people lonely.","base":"Se dice que vivir solo hace que la gente se sienta sola."}]},"review_status":"draft"},{"id":"b2-u04","language_code":"en","level":"B2","position":4,"title_es":"Ciencia, tecnología e innovación","title_en":"Science, technology and innovation","description_es":"Investigación y descubrimientos, inventos, inteligencia artificial y privacidad, y oraciones de relativo con comas, whose y which.","emoji":"🔬","objective_es":"Puedes contar un descubrimiento, opinar sobre la tecnología y dar información extra con oraciones de relativo.","grammar":{"title":"Oraciones de relativo avanzadas","explanation":"Las explicativas van entre comas y agregan información extra; no se usa that: Our filter, which costs five dollars, uses sunlight. Whose indica posesión (cuyo): a scientist whose team… Which puede retomar toda la oración anterior: One experiment failed, which was frustrating. En un registro más formal, la preposición va antes: for whom, in which. Most of which / many of whom: la mayoría de los cuales.","examples":[{"target":"Our filter, which costs less than five dollars, uses only sunlight.","base":"Nuestro filtro, que cuesta menos de cinco dólares, usa sólo la luz del sol."},{"target":"Marie Curie, whose discoveries changed medicine, won two Nobel Prizes.","base":"Marie Curie, cuyos descubrimientos cambiaron la medicina, ganó dos premios Nobel."},{"target":"One of our experiments failed, which was very frustrating.","base":"Uno de nuestros experimentos falló, lo cual fue muy frustrante."}]},"review_status":"draft"},{"id":"b2-u05","language_code":"en","level":"B2","position":5,"title_es":"Economía, consumo y finanzas","title_en":"Money, shopping and everyday finance","description_es":"Ahorros, préstamos y deudas, gastar menos, marcas y precios, have something done y comparaciones como twice as… as o nowhere near as… as.","emoji":"💳","objective_es":"Puedes hablar de tu economía, comparar precios con matices y explicar que mandas a hacer o arreglar algo.","grammar":{"title":"Have something done y comparación avanzada","explanation":"Have / get + objeto + participio: otra persona hace algo por ti (I had my screen replaced = me cambiaron la pantalla; no la cambiaste tú). Para comparar con matices: by far + superlativo (by far the best), twice / three times as … as (el doble de…), nowhere near as … as (ni de cerca tan… como) y the …-er, the …-er (cuanto más…, más…).","examples":[{"target":"I'd like to have the screen replaced.","base":"Quisiera que me cambiaran la pantalla."},{"target":"That's twice as much as I paid last time!","base":"¡Es el doble de lo que pagué la última vez!"},{"target":"It was by far the best decision I made last year.","base":"Fue por lejos la mejor decisión que tomé el año pasado."}]},"review_status":"draft"},{"id":"b2-u06","language_code":"en","level":"B2","position":6,"title_es":"Psicología y relaciones","title_en":"Psychology and relationships","description_es":"Deducir lo que pasó y lamentar lo que hiciste (must have, should have), peleas y reconciliaciones, estados de ánimo y empatía.","emoji":"🫂","objective_es":"Puedes deducir qué le pasó a alguien, lamentar lo que hiciste, resolver una pelea y hablar de emociones.","grammar":{"title":"Modales perfectos","explanation":"Modal + have + participio habla del pasado. Para deducir: must have (seguro que sí), might / could have (es posible) y can’t have (seguro que no): She must have lost her phone. Para lamentar o criticar: should have / shouldn’t have (debería / no debería haber) y could have (podría haber, pero no lo hizo).","examples":[{"target":"She must have lost her phone again.","base":"Seguro que perdió el teléfono otra vez."},{"target":"She can't have lost it. She posted a photo this morning.","base":"No puede haberlo perdido. Subió una foto esta mañana."},{"target":"I should have thought before I spoke.","base":"Debería haber pensado antes de hablar."}]},"review_status":"draft"},{"id":"b2-u07","language_code":"en","level":"B2","position":7,"title_es":"Medioambiente y problemas globales","title_en":"The environment and global issues","description_es":"El calentamiento global, sequías e inundaciones, energía renovable, pobreza y especies en peligro, y el contraste con despite, even though y whereas.","emoji":"🌍","objective_es":"Puedes hablar de problemas ambientales y globales, sus causas y consecuencias, y matizar con despite, even though y whereas.","grammar":{"title":"Concesivas y contraste","explanation":"Despite / in spite of + sustantivo o -ing (a pesar de): Despite the storms, the rivers are low. Even though + oración (aunque, a pesar de que), más fuerte que although: Even though they saved water, they lost their crops. Even if + oración (aun si, incluso si): una condición que no cambia el resultado. Whereas (mientras que) compara dos hechos opuestos.","examples":[{"target":"Despite the storms last week, the rivers are still very low.","base":"A pesar de las tormentas de la semana pasada, los ríos siguen muy bajos."},{"target":"Even if everyone stopped flying, it would be a tiny difference.","base":"Aun si todos dejaran de volar, sería una diferencia mínima."},{"target":"A family can save a few tons, whereas a factory can produce millions.","base":"Una familia puede ahorrar unas toneladas, mientras que una fábrica puede producir millones."}]},"review_status":"draft"},{"id":"b2-u08","language_code":"en","level":"B2","position":8,"title_es":"Medios y desinformación","title_en":"Media and misinformation","description_es":"Rumores y publicaciones virales, fuentes confiables y sesgadas, y estilo indirecto con claim, deny, admit, warn, accuse y refuse.","emoji":"📰","objective_es":"Puedes reconocer información engañosa, contar con precisión lo que dijo alguien y opinar sobre las fuentes.","grammar":{"title":"Verbos de reporte","explanation":"Para contar lo que alguien dijo con más precisión que say o tell, cada verbo tiene su forma: claim that / claim to (afirmar), suggest + -ing o suggest that (sugerir), warn someone (not) to (advertir), insist that / insist on + -ing (insistir), accuse someone of + -ing (acusar), deny / admit + -ing (negar / admitir) y refuse to (negarse a). Los tiempos retroceden como en el B1: is → was, has → had.","examples":[{"target":"She warned people not to believe everything they read online.","base":"Advirtió a la gente que no creyera todo lo que lee en internet."},{"target":"He denied using public money.","base":"Negó haber usado dinero público."},{"target":"They accused him of lying.","base":"Lo acusaron de mentir."}]},"review_status":"draft"},{"id":"b2-u09","language_code":"en","level":"B2","position":9,"title_es":"Educación y desarrollo personal","title_en":"Education and personal growth","description_es":"Mirar atrás con el tercer condicional y if only, la forma de pensar y la motivación, estudiar con método y salir de la zona de confort.","emoji":"🎓","objective_es":"Puedes hablar de tu educación, lamentar decisiones del pasado e imaginar otros resultados, y contar cómo aprendes mejor.","grammar":{"title":"Tercer condicional y wish / if only","explanation":"El tercer condicional imagina un pasado distinto: If + past perfect, would have + participio (If I had studied, I would have passed = si hubiera estudiado, habría aprobado). Negativo: If I hadn’t left, I wouldn’t have started my business. Para lamentar algo del pasado: I wish / If only + past perfect (If only I had asked for help = ojalá hubiera pedido ayuda).","examples":[{"target":"If I had listened to my teacher, I would have studied science.","base":"Si le hubiera hecho caso a mi profesora, habría estudiado ciencias."},{"target":"If I hadn't left, I wouldn't have started my business.","base":"Si no me hubiera ido, no habría empezado mi negocio."},{"target":"If only I had asked for help.","base":"Ojalá hubiera pedido ayuda."}]},"review_status":"draft"},{"id":"b2-u10","language_code":"en","level":"B2","position":10,"title_es":"Argumentación y debate","title_en":"Argument and debate","description_es":"Sumar argumentos, reconocer y rebatir, defender una postura y concluir, con conectores y oraciones como What matters is… o The reason why… is…","emoji":"⚖️","objective_es":"Puedes defender una opinión con argumentos, reconocer la postura contraria, rebatirla y sacar una conclusión.","grammar":{"title":"Oraciones escindidas y conectores","explanation":"Para enfatizar una parte de la oración, la «partes» en dos: What matters is the result (lo que importa es…), What worries me is… (lo que me preocupa es…), The reason why… is that… (la razón por la que… es que…), It is… that… (It is the cost of ignorance that should worry us). Conectores formales: moreover y furthermore suman; as a result da la consecuencia; admittedly reconoce un punto contrario y nevertheless lo rebate; on the contrary dice que es todo lo opuesto.","examples":[{"target":"What worries me is the customers.","base":"Lo que me preocupa son los clientes."},{"target":"The reason why they did it is that people work better when they are rested.","base":"La razón por la que lo hicieron es que la gente trabaja mejor descansada."},{"target":"Admittedly, it is expensive. Nevertheless, it is worth it.","base":"Es cierto que es caro. Aun así, vale la pena."}]},"review_status":"draft"},{"id":"b2-u11","language_code":"en","level":"B2","position":11,"title_es":"Historias, libros y expresiones","title_en":"Stories, books and idioms","description_es":"Hablar de novelas y personajes, contar una historia con participios e inversión (Never had I…, Hardly had… when…) y expresiones idiomáticas frecuentes.","emoji":"📚","objective_es":"Puedes comentar un libro, contar una historia con recursos narrativos y entender expresiones idiomáticas frecuentes.","grammar":{"title":"Participios e inversión narrativa","explanation":"Las oraciones con participio resumen una acción del mismo sujeto: Walking home, I saw… (mientras caminaba); Having missed the train, she walked (como había perdido el tren). En los relatos, algunas expresiones negativas al principio invierten el sujeto y el auxiliar para dar dramatismo: Never had she felt so alone; Hardly had she stopped when…; No sooner had we arrived than…; Little did she know that…","examples":[{"target":"Having missed the last train, Elena set off on foot.","base":"Como había perdido el último tren, Elena salió a pie."},{"target":"Never had she felt so alone.","base":"Nunca se había sentido tan sola."},{"target":"Little did she know that this night would change her life.","base":"Poco se imaginaba que esa noche le cambiaría la vida."}]},"review_status":"draft"},{"id":"b2-u12","language_code":"en","level":"B2","position":12,"title_es":"Decisiones y conflictos","title_en":"Decisions and conflicts","description_es":"Pesar una decisión, condicionales mixtos, resolver conflictos y defender una postura, e inversión enfática (Not only…, Under no circumstances…).","emoji":"🧭","objective_es":"Puedes pesar una decisión difícil, imaginar cómo sería tu presente con otras elecciones, mediar en un conflicto y expresarte con énfasis formal.","grammar":{"title":"Condicionales mixtos e inversión enfática","explanation":"Los condicionales mixtos combinan tiempos: un pasado distinto con un resultado en el presente (If I had taken the job, I would be living in Berlin now) o un presente distinto con un resultado en el pasado (If I were braver, I would have said yes). En un registro formal, algunas expresiones al principio invierten auxiliar y sujeto para dar énfasis: Not only is it free, but…; Under no circumstances will we…; Only then can we…; Should you need help (= If you need help).","examples":[{"target":"If you had taken the job, you'd be speaking German by now.","base":"Si hubieras aceptado el trabajo, ya estarías hablando alemán."},{"target":"If I were braver, I would have said yes.","base":"Si fuera más valiente, habría dicho que sí."},{"target":"Not only is the service free, but it is also confidential.","base":"El servicio no sólo es gratuito, sino que también es confidencial."}]},"review_status":"draft"},{"id":"pt-a1-u13","language_code":"pt","level":"A1","position":13,"title_es":"Profesiones y trabajo","title_en":"Profissões","description_es":"Nós, eles, elas, vocês y a gente; ser y los verbos en -ar en plural; nosso y nossa; profesiones y lugares de trabajo.","emoji":"💼","objective_es":"Puedes decir a qué te dedicas tú y otras personas, hablar en plural (nós trabalhamos, eles trabalham) y usar a gente como en Brasil.","grammar":{"title":"Pronombres plurales · ser y -ar en plural","explanation":"Nós (nosotros), eles / elas (ellos, ellas) y vocês (ustedes). Ser: nós somos, eles são, vocês são. Los verbos en -ar: nós trabalhamos, eles trabalham. En el habla de Brasil se dice mucho a gente («nosotros») con el verbo como ele: a gente trabalha. La profesión va sin artículo: ela é médica.","examples":[{"target":"Nós somos estudantes.","base":"Somos estudiantes."},{"target":"Eles trabalham em um restaurante.","base":"Ellos trabajan en un restaurante."},{"target":"A gente trabalha em casa.","base":"Trabajamos en casa."}]},"review_status":"draft"},{"id":"pt-a1-u14","language_code":"pt","level":"A1","position":14,"title_es":"¿Cómo estás? Estados y descripciones","title_en":"Como você está?","description_es":"Estar para cómo estás ahora, estar com fome / sede, ser para describir, la concordancia de los adjetivos y el falso amigo chato.","emoji":"😊","objective_es":"Puedes decir cómo estás (estou cansado, estou com fome), describir personas y cosas con ser y elegir entre ser y estar.","grammar":{"title":"Ser y estar · estar com · concordancia","explanation":"Ser describe cómo es algo o alguien: ele é alto, a casa é grande. Estar dice cómo está ahora: estou cansado, ela está triste. «Tener hambre / sed» se dice estar com: estou com fome, estou com sede. Los adjetivos concuerdan: cansado, cansada, cansados, cansadas.","examples":[{"target":"Ele é alto e simpático.","base":"Él es alto y simpático."},{"target":"Hoje eu estou cansada.","base":"Hoy estoy cansada."},{"target":"Você está com fome?","base":"¿Tienes hambre?"}]},"review_status":"draft"},{"id":"pt-a1-u15","language_code":"pt","level":"A1","position":15,"title_es":"Fechas, meses y clima","title_en":"Datas e tempo","description_es":"Los meses, la fecha y el cumpleaños, em + mes y el clima con faz calor, faz frio y chove.","emoji":"📅","objective_es":"Puedes decir la fecha y cuándo es tu cumpleaños, nombrar los meses y las estaciones y contar qué tiempo hace.","grammar":{"title":"La fecha · em + mes · fazer para el clima","explanation":"La fecha: dia + número + de + mes (dia cinco de maio). Con meses va em: em março; con un día, no dia: no dia dez. El clima se dice con fazer: faz calor, faz frio; «llueve» es chove. Los meses van con minúscula.","examples":[{"target":"Hoje é dia dez de maio.","base":"Hoy es 10 de mayo."},{"target":"O meu aniversário é em março.","base":"Mi cumpleaños es en marzo."},{"target":"No inverno faz frio.","base":"En invierno hace frío."}]},"review_status":"draft"},{"id":"pt-a1-u16","language_code":"pt","level":"A1","position":16,"title_es":"Transporte y tiempo libre","title_en":"Transporte e lazer","description_es":"Ir de ônibus, de carro o a pé; las contracciones ao, à, pelo y pela; fazer e ir en plural para proponer planes.","emoji":"🚲","objective_es":"Puedes decir cómo vas a un lugar, por dónde pasa el autobús, qué haces en tu tiempo libre y proponer un plan con vamos…?","grammar":{"title":"Ir de + transporte · ao, à, pelo, pela · fazer","explanation":"El transporte va con de (no con «en»): vou de ônibus, de carro, de metrô; caminando es a pé. A + o = ao y a + a = à: vou ao cinema, vou à praia. Por + o = pelo y por + a = pela: passo pela praça. Fazer: eu faço, você / ele faz, nós fazemos. Ir: nós vamos, eles vão.","examples":[{"target":"Eu vou para a escola de ônibus.","base":"Voy a la escuela en autobús."},{"target":"Vamos ao cinema?","base":"¿Vamos al cine?"},{"target":"O ônibus passa pela praça.","base":"El autobús pasa por la plaza."}]},"review_status":"draft"},{"id":"pt-a2-u01","language_code":"pt","level":"A2","position":1,"title_es":"¿Qué hiciste el fin de semana?","title_en":"O fim de semana","description_es":"El pretérito perfeito de los verbos regulares (falei, comi, saí), ontem, a semana passada, já y ainda não.","emoji":"🗓️","objective_es":"Puedes contar qué hiciste ayer o el fin de semana, preguntarle a otro qué hizo y decir lo que ya hiciste y lo que todavía no.","grammar":{"title":"Pretérito perfeito regular","explanation":"Para acciones terminadas. -ar: eu falei, você / ele falou, nós falamos, eles falaram. -er: eu comi, ele comeu, nós comemos, eles comeram. -ir: eu saí, ele saiu, nós saímos, eles saíram. Ojo: con -ar, nós falamos es igual en presente y en pasado. Já es «ya» y ainda não, «todavía no».","examples":[{"target":"Ontem eu trabalhei até tarde.","base":"Ayer trabajé hasta tarde."},{"target":"Você já comeu?","base":"¿Ya comiste?"},{"target":"No sábado eles saíram.","base":"El sábado ellos salieron."}]},"review_status":"draft"},{"id":"pt-a2-u02","language_code":"pt","level":"A2","position":2,"title_es":"Viajes","title_en":"Viagens","description_es":"El perfeito irregular (fui, foi, fiz, fez, tive, estive), conhecer un lugar, el aeropuerto y el falso amigo mala.","emoji":"✈️","objective_es":"Puedes contar un viaje (adónde fuiste, qué hiciste, qué conociste), entender un aviso del aeropuerto y explicar un problema de viaje.","grammar":{"title":"Perfeito irregular: fui, fiz, tive, estive","explanation":"Ser e ir tienen el mismo pasado: eu fui, você / ele foi, nós fomos, eles foram (fui a Salvador; foi ótimo). Fazer: fiz, fez. Ter: tive, teve. Estar: estive, esteve. Conhecer es «conocer», también un lugar: conheci o Rio.","examples":[{"target":"Eu fui para Salvador nas férias.","base":"Fui a Salvador en las vacaciones."},{"target":"A viagem foi ótima.","base":"El viaje fue buenísimo."},{"target":"Ontem eu tive um problema no aeroporto.","base":"Ayer tuve un problema en el aeropuerto."}]},"review_status":"draft"},{"id":"pt-a2-u03","language_code":"pt","level":"A2","position":3,"title_es":"Restaurantes y hospedaje","title_en":"Restaurante e hospedagem","description_es":"Pedir con cortesía (gostaria de, poderia), la carta, pagar y dejar propina, reservar una posada y el falso amigo sobremesa.","emoji":"🍽️","objective_es":"Puedes pedir en un restaurante con cortesía, entender una carta, pagar y reservar una habitación preguntando qué incluye.","grammar":{"title":"Pedidos corteses: gostaria de, poderia","explanation":"Para pedir con cortesía: eu gostaria de + verbo o + cosa (gostaria de um café) y poderia…? («¿podría…?»): poderia me trazer a conta? En el habla también va pode me trazer…? y o queria… (que ya conoces). Gostaria de + o = gostaria do.","examples":[{"target":"Eu gostaria do prato do dia.","base":"Quisiera el plato del día."},{"target":"Poderia me trazer o cardápio?","base":"¿Me podría traer la carta?"},{"target":"Eu gostaria de reservar um quarto.","base":"Me gustaría reservar una habitación."}]},"review_status":"draft"},{"id":"pt-a2-u04","language_code":"pt","level":"A2","position":4,"title_es":"Cuando era chico","title_en":"Infância","description_es":"El pretérito imperfeito (era, tinha, morava, brincava, ia), costumava, el barrio, los vecinos y el falso amigo brincar.","emoji":"🧸","objective_es":"Puedes contar cómo era tu vida de niño, qué hacías siempre y cómo eran las personas y los lugares de antes.","grammar":{"title":"Pretérito imperfeito","explanation":"Para costumbres y descripciones del pasado («hacía», «era»). -ar: eu / ele morava, nós morávamos, eles moravam. -er / -ir: comia, saía. Irregulares: ser → era; ter → tinha; ir → ia. Costumava + verbo es «solía»: costumava ir a pé.","examples":[{"target":"Quando eu era criança, morava no interior.","base":"Cuando era chico, vivía en el interior."},{"target":"A gente brincava na rua.","base":"Jugábamos en la calle."},{"target":"Todo domingo a gente ia à casa dos avós.","base":"Todos los domingos íbamos a la casa de los abuelos."}]},"review_status":"draft"},{"id":"pt-a2-u05","language_code":"pt","level":"A2","position":5,"title_es":"¿Qué pasó? Contar un hecho","title_en":"O que aconteceu?","description_es":"Imperfeito para la escena y perfeito para lo que pasó, estava + gerundio, los conectores del relato y el falso amigo perceber.","emoji":"💬","objective_es":"Puedes contar algo que te pasó: describir la escena, decir qué pasó de repente y ordenar el relato con primeiro, então y no final.","grammar":{"title":"Imperfeito y perfeito · estava + gerundio","explanation":"En un relato, el imperfeito pinta la escena (estava chovendo, eu estava no ônibus) y el perfeito cuenta lo que pasó (eu caí, perdi o celular). Estar + gerundio en pasado: eu estava andando («estaba caminando»); en Brasil el gerundio termina en -ndo, como en español.","examples":[{"target":"Eu estava andando quando vi o acidente.","base":"Estaba caminando cuando vi el accidente."},{"target":"Estava chovendo e eu caí na rua.","base":"Estaba lloviendo y me caí en la calle."},{"target":"De repente, o ônibus parou.","base":"De repente, el autobús frenó."}]},"review_status":"draft"},{"id":"pt-a2-u06","language_code":"pt","level":"A2","position":6,"title_es":"Planes e invitaciones","title_en":"Planos e convites","description_es":"El futuro próximo (vou + verbo), invitar, aceptar y rechazar como en Brasil (topa?, bora!, que pena, combinado) y el churrasco.","emoji":"🎉","objective_es":"Puedes contar tus planes, invitar a alguien, aceptar o rechazar una invitación con cortesía y arreglar día y hora.","grammar":{"title":"Futuro próximo: ir + infinitivo","explanation":"Para planes se usa ir + infinitivo, sin «a» en el medio: eu vou viajar, você vai sair?, nós vamos jantar, eles vão chegar tarde. Es la forma normal del futuro en el portugués hablado de Brasil.","examples":[{"target":"No sábado eu vou fazer um churrasco.","base":"El sábado voy a hacer un asado."},{"target":"Vocês vão sair hoje?","base":"¿Ustedes van a salir hoy?"},{"target":"A gente vai jantar fora.","base":"Vamos a cenar afuera."}]},"review_status":"draft"},{"id":"pt-a2-u07","language_code":"pt","level":"A2","position":7,"title_es":"Trabajo y estudios","title_en":"Trabalho e estudos","description_es":"El futuro do presente en lo formal (será, terá), la facultad, la pasantía, la entrevista y los falsos amigos vaga, pretender y prova.","emoji":"🎓","objective_es":"Puedes hablar de tu trabajo y tus estudios, entender un aviso de trabajo y un correo formal, y contar qué tienes pensado hacer.","grammar":{"title":"Futuro do presente (formal)","explanation":"Infinitivo + -ei, -á, -emos, -ão: trabalharei, trabalhará, trabalharemos, trabalharão. Ser → será; ter → terá. En el habla de Brasil se prefiere vou + verbo; el futuro simple aparece en avisos, correos y noticias: a reunião será às dez.","examples":[{"target":"A reunião será às dez.","base":"La reunión será a las diez."},{"target":"A entrevista terá duração de uma hora.","base":"La entrevista durará una hora."},{"target":"Eu pretendo fazer um estágio.","base":"Tengo pensado hacer una pasantía."}]},"review_status":"draft"},{"id":"pt-a2-u08","language_code":"pt","level":"A2","position":8,"title_es":"Salud y bienestar","title_en":"Saúde","description_es":"Estar com dor de…, el cuerpo, los síntomas, la farmacia, pedir una cita y el imperativo para indicaciones y consejos.","emoji":"🩺","objective_es":"Puedes decir qué te duele y qué síntomas tienes, pedir una cita, entender indicaciones de un remedio y dar consejos de salud.","grammar":{"title":"Imperativo · estar com dor de","explanation":"«Me duele la cabeza» se dice estou com dor de cabeça. Para indicaciones y consejos se usa el imperativo (con você): -ar → -e (tome, descanse, evite); -er / -ir → -a (beba, coma, abra). Negativo: não tome. Entre amigos también se oye toma, bebe.","examples":[{"target":"Estou com dor de cabeça.","base":"Me duele la cabeza."},{"target":"Tome este remédio e beba muita água.","base":"Toma este remedio y toma mucha agua."},{"target":"Não coma muito hoje.","base":"No comas mucho hoy."}]},"review_status":"draft"},{"id":"pt-a2-u09","language_code":"pt","level":"A2","position":9,"title_es":"Compras y servicios","title_en":"Compras","description_es":"Comparar (mais… do que, tão… quanto, melhor, pior), el superlativo, probarse y cambiar ropa, los descuentos y los falsos amigos calça y tênis.","emoji":"🛍️","objective_es":"Puedes comparar productos y precios, elegir el mejor, probarte ropa, pedir otra talla y cambiar algo que compraste.","grammar":{"title":"Comparativos y superlativos","explanation":"Mais + adjetivo + (do) que: a calça azul é mais barata (do) que a preta. Menos… (do) que. Igualdad: tão… quanto (tão boa quanto). Irregulares: bom → melhor, ruim → pior, grande → maior, pequeno → menor. Superlativo: o / a mais…: o mais barato da loja.","examples":[{"target":"Esta calça é mais barata do que aquela.","base":"Este pantalón es más barato que aquel."},{"target":"A câmera é tão boa quanto a do outro.","base":"La cámara es tan buena como la del otro."},{"target":"É o melhor celular do ano.","base":"Es el mejor celular del año."}]},"review_status":"draft"},{"id":"pt-a2-u10","language_code":"pt","level":"A2","position":10,"title_es":"Tecnología y comunicación","title_en":"Tecnologia","description_es":"Los pronombres de objeto como en Brasil (te ligo, me manda), el celular, las apps, las contraseñas y los falsos amigos ligar, apagar, desligar y tela.","emoji":"📱","objective_es":"Puedes llamar y mandar mensajes, resolver problemas simples con el celular o la computadora y usar los pronombres te, me, o / a.","grammar":{"title":"Pronombres de objeto en Brasil","explanation":"En Brasil me, te y nos van antes del verbo: te ligo, me manda, vou te mandar. Para «lo / la» lo formal es o / a (eu o conheço) y en el habla se dice ele / ela después del verbo (eu vi ele ontem). Ligar para alguien es «llamarlo».","examples":[{"target":"Te ligo em dez minutos.","base":"Te llamo en diez minutos."},{"target":"Me manda uma mensagem?","base":"¿Me mandas un mensaje?"},{"target":"Eu vi ele ontem.","base":"Lo vi ayer."}]},"review_status":"draft"},{"id":"pt-a2-u11","language_code":"pt","level":"A2","position":11,"title_es":"Rutina y cuidados","title_en":"Rotina e cuidados","description_es":"Los verbos reflexivos (me levanto, me deito, me sinto), tomar banho, la frecuencia, la duración con há / faz y desde, y el falso amigo academia.","emoji":"⏰","objective_es":"Puedes contar tu rutina con verbos reflexivos, decir con qué frecuencia haces algo y desde hace cuánto tiempo.","grammar":{"title":"Reflexivos · frecuencia y duración","explanation":"En Brasil el pronombre reflexivo va antes del verbo: eu me levanto, você / ele se levanta, nós nos levantamos, eles se levantam. No son reflexivos tomar banho (bañarse) ni acordar (despertarse). Duración: há / faz + tiempo («hace»): moro aqui há dois anos; faz dois anos que moro aqui. Desde es igual.","examples":[{"target":"Eu me levanto às seis.","base":"Me levanto a las seis."},{"target":"Às vezes eu vou à academia.","base":"A veces voy al gimnasio."},{"target":"Moro em Recife há dois anos.","base":"Vivo en Recife hace dos años."}]},"review_status":"draft"},{"id":"pt-a2-u12","language_code":"pt","level":"A2","position":12,"title_es":"Opiniones y problemas","title_en":"Opiniões e problemas","description_es":"Dar una opinión, acordar y discrepar, condicionales sencillos (se…), y resolver problemas de todos los días: algo se rompió, no funciona o se cortó internet.","emoji":"💡","objective_es":"Puedes dar y pedir opiniones, decir si estás de acuerdo, plantear condiciones simples y explicar un problema para que te lo resuelvan.","grammar":{"title":"Opinar · condicionales sencillos","explanation":"Opinar: acho que + verbo (acho que é melhor), na minha opinião. Acordar: concordo; discrepar: discordo. Condición posible: se + presente y el resultado en presente o con vou + verbo (se você tem tempo, a gente vai). Expresiones fijas muy usadas: se der («si se puede»), se você quiser («si quieres»).","examples":[{"target":"Acho que morar no centro é melhor.","base":"Creo que vivir en el centro es mejor."},{"target":"Se você tem tempo, a gente pode almoçar.","base":"Si tienes tiempo, podemos almorzar."},{"target":"O meu celular quebrou e não funciona.","base":"Se me rompió el celular y no funciona."}]},"review_status":"draft"},{"id":"it-a1-u13","language_code":"it","level":"A1","position":13,"title_es":"Profesiones y trabajo","title_en":"Lavoro","description_es":"Noi, voi y loro; essere y los verbos en -are en plural; nostro y nostra; profesiones y lugares de trabajo.","emoji":"💼","objective_es":"Puedes decir de qué trabajas tú y otras personas, hablar en plural (noi lavoriamo, loro lavorano) y presentar a tu grupo.","grammar":{"title":"Pronombres plurales · essere y -are en plural","explanation":"Noi (nosotros), voi (ustedes) y loro (ellos, ellas). Essere: noi siamo, voi siete, loro sono. Ojo: siete no es el número 7 (sette), es «ustedes son». Los verbos en -are: noi lavoriamo, voi lavorate, loro lavorano (el acento va en la-vó-ra-no). La profesión va sin artículo con essere (sono medico) y con artículo con fare (faccio il medico).","examples":[{"target":"Noi siamo studenti.","base":"Somos estudiantes."},{"target":"Loro lavorano in un ristorante.","base":"Ellos trabajan en un restaurante."},{"target":"Faccio il cuoco.","base":"Soy cocinero."}]},"review_status":"draft"},{"id":"it-a1-u14","language_code":"it","level":"A1","position":14,"title_es":"¿Cómo eres? ¿Cómo estás?","title_en":"Come sei?","description_es":"Describir a una persona, decir cómo estás (sono stanco, sto male) y hablar de hambre, sed, frío y calor.","emoji":"🙂","objective_es":"Puedes describir cómo es una persona, decir cómo estás y si tienes hambre, sed, frío o calor, sin confundir essere, stare y avere.","grammar":{"title":"Essere, stare y avere · concordancia de los adjetivos","explanation":"En italiano los estados van con essere: sono stanco (estoy cansado), è malata (está enferma). Stare se usa sobre todo para la salud y el saludo: sto bene, sto male. Hambre, sed, frío y calor van con avere, como en español: ho fame, ho caldo. Los rasgos físicos van con avere y artículo: ha i capelli neri. El adjetivo concuerda: alto, alta, alti, alte; giovane, giovani.","examples":[{"target":"Sono molto stanco.","base":"Estoy muy cansado."},{"target":"Ho freddo e sto male.","base":"Tengo frío y me siento mal."},{"target":"Elena è alta e ha i capelli neri.","base":"Elena es alta y tiene el pelo negro."}]},"review_status":"draft"},{"id":"it-a1-u15","language_code":"it","level":"A1","position":15,"title_es":"Fechas, meses y clima","title_en":"Date e tempo","description_es":"Contar hasta cien, decir la fecha y tu cumpleaños, preguntar qué tiempo hace y hablar de las estaciones.","emoji":"📅","objective_es":"Puedes decir la fecha y cuándo es tu cumpleaños, contar hasta cien y decir qué tiempo hace (fa caldo, piove, nevica) en cada estación.","grammar":{"title":"La fecha · fare con el clima","explanation":"La fecha va con il + número + mes, y los meses en minúscula: il 5 maggio. El día 1 se dice con el ordinal: il primo maggio. «En mayo» es a maggio o in maggio. Para el clima se usa fare: fa caldo, fa freddo; y también piove, nevica, c’è il sole. Ojo: fa caldo es «hace calor» (caldo no es el caldo). L’estate (el verano) es femenino.","examples":[{"target":"Il mio compleanno è il primo maggio.","base":"Mi cumpleaños es el 1 de mayo."},{"target":"Che tempo fa? — Piove e fa freddo.","base":"¿Qué tiempo hace? — Llueve y hace frío."},{"target":"D'estate fa caldo.","base":"En verano hace calor."}]},"review_status":"draft"},{"id":"it-a1-u16","language_code":"it","level":"A1","position":16,"title_es":"Transporte, tiempo libre y ayer","title_en":"Trasporti e tempo libero","description_es":"Decir cómo vas a los lugares, adónde vas el fin de semana (al mare, alla stazione) y contar algo que hiciste ayer.","emoji":"🚆","objective_es":"Puedes decir cómo vas a un lugar (in treno, a piedi), adónde van tú y otros (andiamo al mare, vanno in montagna) y contar en pocas palabras qué hiciste ayer (ho mangiato, sono andato).","grammar":{"title":"In treno · al / alla · un primer passato prossimo","explanation":"El transporte va con in y sin artículo: in treno, in autobus, in macchina; pero a piedi. «Tomar» el autobús es prendere: prendo l’autobus. A + il = al, a + la = alla: vado al cinema, alla stazione; pero in montagna. Andare: vado, vai, va, andiamo, andate, vanno. Para contar lo que hiciste: avere + participio (ho mangiato, ho visto); con andare se usa essere y el participio concuerda: sono andato / sono andata.","examples":[{"target":"Andiamo a Roma in treno.","base":"Vamos a Roma en tren."},{"target":"Sabato vado al mare.","base":"El sábado voy al mar."},{"target":"Ieri sono andata al cinema.","base":"Ayer fui al cine."}]},"review_status":"draft"},{"id":"it-a2-u01","language_code":"it","level":"A2","position":1,"title_es":"¿Qué hiciste el fin de semana?","title_en":"Il fine settimana","description_es":"Contar lo que hiciste con el passato prossimo: participios regulares e irregulares, già, non… ancora y las expresiones del pasado.","emoji":"🗓️","objective_es":"Puedes contar qué hiciste el fin de semana o ayer (ho dormito, abbiamo preso il treno), decir lo que ya hiciste y lo que todavía no, y entender el relato de otra persona.","grammar":{"title":"Passato prossimo con avere","explanation":"Para contar algo terminado: avere en presente + participio. Los regulares: -are → -ato (parlato), -ere → -uto (bevuto), -ire → -ito (dormito). Irregulares frecuentes: fatto, letto, scritto, preso, visto. Con avere el participio no cambia: Sara ha letto, loro hanno letto. Donde en español solemos decir «comí», en italiano se dice ho mangiato. Già y ancora van entre avere y el participio: ho già mangiato, non ho ancora mangiato.","examples":[{"target":"Sabato ho dormito fino alle dieci.","base":"El sábado dormí hasta las diez."},{"target":"Abbiamo preso il treno per Como.","base":"Tomamos el tren a Como."},{"target":"Non ho ancora mangiato.","base":"Todavía no comí."}]},"review_status":"draft"},{"id":"it-a2-u02","language_code":"it","level":"A2","position":2,"title_es":"Viajes","title_en":"Viaggi","description_es":"Contar un viaje con el passato prossimo con essere (sono partito, siamo arrivati), entender el aeropuerto y decir hace cuánto pasó algo.","emoji":"✈️","objective_es":"Puedes contar un viaje (cuándo saliste y llegaste, dónde estuviste y cuánto te quedaste), entender anuncios del aeropuerto y decir hace cuánto pasó algo (due anni fa).","grammar":{"title":"Passato prossimo con essere","explanation":"Los verbos de movimiento y de cambio de lugar forman el passato prossimo con essere: andare, partire, arrivare, tornare, uscire, salire, scendere, rimanere. Con essere el participio concuerda como un adjetivo: sono arrivato (él), sono arrivata (ella), siamo arrivati, siamo arrivate. Essere y stare comparten participio: sono stato = «estuve» o «fui». Ojo: salire es «subir» y uscire es «salir». Fa después del tiempo es «hace»: due anni fa.","examples":[{"target":"Sono partita da Buenos Aires alle dieci.","base":"Salí de Buenos Aires a las diez."},{"target":"Siamo stati al mare tutti i giorni.","base":"Estuvimos en el mar todos los días."},{"target":"Sono salito sul treno due ore fa.","base":"Subí al tren hace dos horas."}]},"review_status":"draft"},{"id":"it-a2-u03","language_code":"it","level":"A2","position":3,"title_es":"Restaurantes y hotel","title_en":"Ristorante e albergo","description_es":"Reservar una mesa o una habitación, pedir con cortesía (mi porta…?, potrei…?), entender el menú italiano y pagar la cuenta.","emoji":"🍝","objective_es":"Puedes reservar una habitación o una mesa, pedir en un restaurante con cortesía tratando de usted (Lei), entender el orden del menú y la cuenta (il coperto, la mancia) y pagar.","grammar":{"title":"Pedidos corteses con Lei · potrei, mi porta…?","explanation":"En el restaurante y en el hotel se trata de Lei (usted), con el verbo en tercera persona: mi porta il conto? (¿me trae la cuenta?), desidera? (¿qué desea?). Para pedir con cortesía: vorrei, potrei avere…? (¿podría tener…?), posso avere…? El menú italiano va en orden: primo (pasta o risotto), secondo (carne o pescado), contorno (la guarnición, aparte) y dolce. En la cuenta suele estar il coperto; la mancia (propina) no es obligatoria.","examples":[{"target":"Vorrei prenotare una camera doppia.","base":"Quisiera reservar una habitación doble."},{"target":"Mi porta il conto, per favore?","base":"¿Me trae la cuenta, por favor?"},{"target":"Potrei avere un’acqua?","base":"¿Podría tomar un agua?"}]},"review_status":"draft"},{"id":"it-a2-u04","language_code":"it","level":"A2","position":4,"title_es":"Cuando era chico","title_en":"Da piccolo","description_es":"Contar cómo era tu vida de chico con el imperfetto: dónde vivías, qué hacías, qué había y qué te gustaba.","emoji":"🧸","objective_es":"Puedes contar cómo eras de chico o chica, dónde vivías, qué hacías por lo general y qué había en tu barrio o tu pueblo, y entender los recuerdos de otra persona.","grammar":{"title":"Imperfetto: hábitos y descripciones","explanation":"El imperfetto describe cómo eran las cosas y lo que hacías siempre, como nuestro pretérito imperfecto. Regulares: -are → -avo (abitavo), -ere → -evo, -ire → -ivo; con noi, -avamo / -evamo (andavamo). Essere es irregular: ero, eri, era, eravamo, eravate, erano. Avere es regular (avevo) y fare usa la raíz fac- (facevo). C’era / c’erano = «había». Ojo: giocare a calcio, sin artículo (no «al calcio»).","examples":[{"target":"Da piccolo abitavo in un paese.","base":"De chico vivía en un pueblo."},{"target":"Di solito giocavo a calcio con mio fratello.","base":"Por lo general jugaba al fútbol con mi hermano."},{"target":"Non c'era l'autobus.","base":"No había autobús."}]},"review_status":"draft"},{"id":"it-a2-u05","language_code":"it","level":"A2","position":5,"title_es":"¿Qué pasó? Contar un hecho","title_en":"Cos'è successo?","description_es":"Contar algo que te pasó: la escena con el imperfetto (pioveva, stavo leggendo) y el hecho con el passato prossimo (all’improvviso è caduto…).","emoji":"💬","objective_es":"Puedes contar algo que te pasó (perdiste algo, te robaron, te caíste): describir la escena, decir qué estabas haciendo, qué pasó de repente y cómo terminó.","grammar":{"title":"Imperfetto y passato prossimo · stavo + gerundio","explanation":"En un relato, el imperfetto pinta la escena (pioveva, c’era tanta gente) y lo que estaba pasando; el passato prossimo cuenta el hecho que pasó (sono caduto). Para «estaba haciendo»: stare en imperfetto + gerundio (-are → -ando, -ere / -ire → -endo): stavo leggendo. Mentre (mientras) va con imperfetto; all’improvviso (de repente) con el hecho. Conectores: poi, allora, quindi (así que), per fortuna (por suerte).","examples":[{"target":"Mentre stavo leggendo, è arrivato Marco.","base":"Mientras estaba leyendo, llegó Marco."},{"target":"Pioveva e all'improvviso sono caduto.","base":"Llovía y de repente me caí."},{"target":"Per fortuna ho trovato le chiavi.","base":"Por suerte encontré las llaves."}]},"review_status":"draft"},{"id":"it-a2-u06","language_code":"it","level":"A2","position":6,"title_es":"Planes e invitaciones","title_en":"Inviti e programmi","description_es":"Invitar, aceptar y rechazar con amabilidad, ponerse de acuerdo para salir y contar planes con el futuro (andrò, farò, sarà).","emoji":"🥂","objective_es":"Puedes invitar a alguien (ti va di…?, che ne dici di…?), aceptar o rechazar con amabilidad, arreglar día y hora, y contar tus planes con el futuro.","grammar":{"title":"Invitar y responder · futuro semplice","explanation":"Para invitar: ti va di + infinitivo? (¿tienes ganas de…?) o che ne dici di…? (¿qué te parece…?). Aceptar: volentieri!, d’accordo. Rechazar: mi dispiace, non posso: devo lavorare. El futuro: -are / -ere → -erò, -ire → -irò; irregulares frecuentes: andrò, farò, sarò / sarà, verrò. Para planes cercanos alcanza el presente: domani vado al mare. Tra due giorni es «dentro de dos días». Ojo: magari es «¡ojalá!» o «quizás».","examples":[{"target":"Ti va di venire alla festa?","base":"¿Tienes ganas de venir a la fiesta?"},{"target":"Mi dispiace, non posso: devo lavorare.","base":"Lo siento, no puedo: tengo que trabajar."},{"target":"L’estate prossima andrò in Puglia.","base":"El verano que viene voy a ir a Puglia."}]},"review_status":"draft"},{"id":"it-a2-u07","language_code":"it","level":"A2","position":7,"title_es":"Trabajo y estudios","title_en":"Lavoro e studio","description_es":"Contar qué haces actualmente y desde cuándo, entender un aviso y una entrevista de trabajo, y hablar de la universidad.","emoji":"🎓","objective_es":"Puedes decir qué estás haciendo ahora y desde hace cuánto (lavoro qui da due anni), hablar de tu trabajo o tus estudios, entender un aviso y una entrevista, y decir lo que tienes que hacer.","grammar":{"title":"Stare + gerundio · presente + da · dovere y potere","explanation":"Sto studiando es «estoy estudiando»: stare en presente + gerundio. Para algo que empezó en el pasado y sigue: presente + da + tiempo: lavoro qui da due anni (trabajo aquí desde hace dos años). No confundir con fa: sono arrivato due anni fa (llegué hace dos años). Dovere (tener que): devo, devi, deve, dobbiamo, dovete, devono. Potere: posso, puoi, può, possiamo, potete, possono. Ojo: il colloquio es la entrevista de trabajo.","examples":[{"target":"Sto studiando per un esame.","base":"Estoy estudiando para un examen."},{"target":"Lavoro in un negozio da due anni.","base":"Trabajo en una tienda desde hace dos años."},{"target":"Dobbiamo finire oggi.","base":"Tenemos que terminar hoy."}]},"review_status":"draft"},{"id":"it-a2-u08","language_code":"it","level":"A2","position":8,"title_es":"Salud y bienestar","title_en":"Salute e benessere","description_es":"Decir qué te duele y qué síntomas tienes, entender al médico y al farmacéutico, y dar consejos con el imperativo.","emoji":"🩺","objective_es":"Puedes decir qué te duele y cómo te sientes, entender las indicaciones del médico y de la farmacia, y dar consejos de salud con el imperativo (riposati, prenda…).","grammar":{"title":"Mi fa male · ho mal di · imperativo con tu y con Lei","explanation":"Para el dolor: mi fa male + la parte del cuerpo (mi fa male la schiena) o ho mal di + parte, sin artículo (ho mal di testa, di gola). Imperativo con tu: -are → -a (mangia), -ere / -ire → -i (prendi, bevi, dormi); en negativo, non + infinitivo (non mangiare!). Con Lei (usted) se invierte: -are → -i (mangi), -ere / -ire → -a (prenda, beva). Con un reflexivo, el pronombre va pegado: riposati! Al médico se va con da: vado dal medico.","examples":[{"target":"Mi fa male la schiena.","base":"Me duele la espalda."},{"target":"Riposati e non uscire stasera!","base":"¡Descansa y no salgas esta noche!"},{"target":"Prenda questo sciroppo, signora.","base":"Tome este jarabe, señora."}]},"review_status":"draft"},{"id":"it-a2-u09","language_code":"it","level":"A2","position":9,"title_es":"Compras y servicios","title_en":"Negozi e servizi","description_es":"Comparar productos y precios, elegir el mejor, comprar ropa (tallas, probador, descuentos) y hacer las compras en el mercado.","emoji":"🛍️","objective_es":"Puedes comparar (più caro di, meno caro), decir cuál es el mejor o el peor, comprar ropa preguntando la talla y el descuento, y pedir cantidades en el mercado (un etto, ne vorrei tre).","grammar":{"title":"Comparativos y superlativos · ne","explanation":"Para comparar: più / meno + adjetivo + di (Roma è più grande di Firenze). Mejor y peor como adjetivo: migliore, peggiore (il migliore del mercato). El superlativo: il più caro del negozio, o con -issimo (bellissimo, carissimo). Ne reemplaza una cantidad de algo que ya se nombró: Quante mele vuole? — Ne prendo tre. En el mercado se pide por chilo y por etto (100 gramos). Ojo: i saldi son las liquidaciones.","examples":[{"target":"Il mercato è meno caro del supermercato.","base":"El mercado es menos caro que el súper."},{"target":"È il ristorante migliore della città.","base":"Es el mejor restaurante de la ciudad."},{"target":"Quante mele vuole? — Ne prendo tre.","base":"¿Cuántas manzanas quiere? — Llevo tres."}]},"review_status":"draft"},{"id":"it-a2-u10","language_code":"it","level":"A2","position":10,"title_es":"Tecnología y comunicación","title_en":"Tecnologia e comunicazione","description_es":"Hablar del celular, los mensajes y las llamadas, y usar los pronombres: ti chiamo, lo vedo, gli scrivo, le telefono.","emoji":"📱","objective_es":"Puedes hablar del celular y la compu, mandar y responder mensajes, arreglar una llamada y usar los pronombres para no repetir a quién (ti chiamo, la vedo, gli scrivo).","grammar":{"title":"Pronombres de objeto directo e indirecto","explanation":"Los pronombres van antes del verbo conjugado: ti chiamo (te llamo), lo vedo (lo veo), la chiamo (la llamo). Directos: mi, ti, lo, la, ci, vi, li, le. Indirectos («a quién»): mi, ti, gli (a él), le (a ella; Le = a usted), ci, vi, gli (a ellos). Ojo con el español: gli scrivo es «le escribo» a un hombre y le telefono, «le hablo por teléfono» a una mujer. Chiamare va con directo (la chiamo) y telefonare con indirecto (le telefono).","examples":[{"target":"Ti chiamo stasera.","base":"Te llamo esta noche."},{"target":"Vedi Marco? — Sì, lo vedo domani.","base":"¿Ves a Marco? — Sí, lo veo mañana."},{"target":"Gli scrivo un messaggio.","base":"Le escribo un mensaje (a él)."}]},"review_status":"draft"},{"id":"it-a2-u11","language_code":"it","level":"A2","position":11,"title_es":"Rutina y relaciones","title_en":"Routine e relazioni","description_es":"Contar tu rutina con los reflexivos en presente y en pasado, decir con qué frecuencia haces algo y hablar de pareja y familia.","emoji":"💞","objective_es":"Puedes contar tu rutina y la de otros (si alza, ci alziamo), lo que hiciste esta mañana (mi sono alzata tardi), cada cuánto haces algo y cómo se conocieron dos personas.","grammar":{"title":"Reflexivos y recíprocos · ci de lugar · frecuencia","explanation":"Los reflexivos llevan mi, ti, si, ci, vi, si antes del verbo: mi alzo, ti alzi, si alza, ci alziamo. En pasado van con essere y el participio concuerda: mi sono alzato / alzata, ci siamo alzati. Con ci / si también se dice lo que hacen dos personas entre sí: ci siamo conosciuti (nos conocimos), si sono sposati (se casaron), ci sentiamo (hablamos). Ci reemplaza un lugar: Vai in palestra? — Sì, ci vado. Frecuencia: sempre, spesso (seguido), qualche volta (a veces), non… mai (nunca).","examples":[{"target":"Mio padre si alza alle sei.","base":"Mi papá se levanta a las seis."},{"target":"Stamattina mi sono alzata tardi.","base":"Esta mañana me levanté tarde."},{"target":"Vai in palestra? — Sì, ci vado spesso.","base":"¿Vas al gimnasio? — Sí, voy seguido."}]},"review_status":"draft"},{"id":"it-a2-u12","language_code":"it","level":"A2","position":12,"title_es":"Opiniones, problemas y soluciones","title_en":"Opinioni e problemi","description_es":"Dar tu opinión y estar o no de acuerdo, expresar deseos y dar consejos con el condicional, y resolver un problema en una tienda.","emoji":"💡","objective_es":"Puedes dar tu opinión (secondo me…), decir si estás de acuerdo, expresar deseos y consejos (mi piacerebbe, dovresti) y resolver un problema con algo que compraste (non funziona, vorrei il rimborso).","grammar":{"title":"Opiniones · condizionale presente · conectores","explanation":"Para opinar: secondo me (para mí), penso di sì / di no (creo que sí / que no), sono d’accordo / non sono d’accordo. El condizionale suaviza: deseos (mi piacerebbe, preferirei, vorrei), consejos (dovresti riposare) y propuestas (sarebbe meglio…). Se forma con -erei / -irei (preferirei); irregulares frecuentes: vorrei, potrei, dovrei / dovresti, sarei / sarebbe. Conectores: invece (en cambio), comunque (de todos modos), purtroppo (lamentablemente). Ojo: con una cosa rota el participio concuerda: si è rotto il telefono, si è rotta la lavatrice.","examples":[{"target":"Secondo me è una bella idea.","base":"Para mí es una buena idea."},{"target":"Dovresti parlare con il capo.","base":"Deberías hablar con el jefe."},{"target":"Il cellulare non funziona: vorrei il rimborso.","base":"El celular no anda: quisiera el reembolso."}]},"review_status":"draft"},{"id":"zh-a1-u13","language_code":"zh","level":"A1","position":13,"title_es":"Trabajo, estudios e idiomas","title_en":"工作 Work and languages","description_es":"El plural con 们, 都, las profesiones, dónde trabajas y qué idiomas hablas.","emoji":"💼","objective_es":"Puedes hablar de varias personas, decir de qué trabajas y dónde, y contar qué idiomas hablas.","grammar":{"title":"们 · 都 · 在 + lugar + verbo","explanation":"Con 们 los pronombres pasan a plural: 我们, 你们, 他们. 都 (todos) va antes del verbo. El lugar va con 在 antes del verbo: 我在医院工作 («yo en el hospital trabajo»). Las profesiones no cambian en femenino.","examples":[{"target":"我们都是学生。","base":"Todos somos estudiantes."},{"target":"我在公司工作。","base":"Trabajo en una empresa."},{"target":"我会说一点儿英语。","base":"Hablo un poco de inglés."}]},"review_status":"draft"},{"id":"zh-a1-u14","language_code":"zh","level":"A1","position":14,"title_es":"Descripciones, colores y comparaciones","title_en":"颜色 Colors and descriptions","description_es":"Colores, cosas nuevas y viejas, cómo es una persona, 比 y 跟…一样.","emoji":"🎨","objective_es":"Puedes describir cosas y personas (colores, tamaño, estatura, pelo), quejarte con 有点儿 y comparar con 比 y 跟…一样.","grammar":{"title":"Adjetivo + 的 · 有点儿 · 比 · 跟…一样","explanation":"Con 的 un color o un adjetivo funciona como sustantivo: 红色的 (el rojo, uno rojo). 有点儿 + adjetivo es «medio…» con queja: 有点儿贵. Para comparar: A 比 B + adjetivo, sin 很 (我比你高). Para decir que son iguales: A 跟 B 一样 (+ adjetivo).","examples":[{"target":"我要红色的。","base":"Quiero el rojo."},{"target":"我比我哥哥高。","base":"Soy más alto que mi hermano."},{"target":"我跟你一样高。","base":"Soy tan alto como tú."}]},"review_status":"draft"},{"id":"zh-a1-u15","language_code":"zh","level":"A1","position":15,"title_es":"Fechas, cumpleaños y clima","title_en":"天气 Dates and weather","description_es":"El año y la fecha, cumpleaños, el clima, las estaciones y 了 de cambio.","emoji":"🌦️","objective_es":"Puedes decir fechas completas y tu cumpleaños, saludar en un cumpleaños, hablar del clima y de las estaciones.","grammar":{"title":"La fecha · 了 de cambio","explanation":"La fecha va de lo grande a lo chico: año, mes, día (十月五号). El año se lee cifra por cifra. 了 al final de la oración marca un cambio de situación: 下雨了 (se puso a llover), 我二十岁了 (ya tengo veinte).","examples":[{"target":"今天是十月五号。","base":"Hoy es 5 de octubre."},{"target":"下雨了！","base":"¡Se puso a llover!"},{"target":"北京的冬天很冷。","base":"El invierno en Pekín es muy frío."}]},"review_status":"draft"},{"id":"zh-a1-u16","language_code":"zh","level":"A1","position":16,"title_es":"Direcciones, planes y lo que hice","title_en":"方向 Directions and plans","description_es":"Ubicar lugares, dar indicaciones, pedir permiso, proponer planes y contar lo que hiciste.","emoji":"🧭","objective_es":"Puedes decir dónde está un lugar y cómo llegar, pedir permiso, proponer un plan y contar lo que hiciste (o no) ayer.","grammar":{"title":"Lugar + 旁边 · 往 · 可以 · 吧 · 了 y 没","explanation":"Para ubicar: cosa + 在 + lugar + 旁边 / 左边 / 前面. Para indicar: 一直走, 往左走. 可以 pide o da permiso. 吧 al final propone: 我们走吧. 了 después del verbo cuenta una acción terminada (我买了…) y 没 la niega, sin 了 (我没去).","examples":[{"target":"银行在公园旁边。","base":"El banco está al lado del parque."},{"target":"我们一起去吧！","base":"¡Vamos juntos!"},{"target":"我昨天没去银行。","base":"Ayer no fui al banco."}]},"review_status":"draft"},{"id":"zh-a2-u01","language_code":"zh","level":"A2","position":1,"title_es":"¿Qué hiciste el fin de semana?","title_en":"周末 The weekend","description_es":"Contar el fin de semana con 了, decir qué ya hiciste y qué todavía no.","emoji":"🏔️","objective_es":"Puedes contar qué hiciste el fin de semana, qué ya hiciste (已经…了) y qué todavía no (还没…呢).","grammar":{"title":"了 · 已经…了 · 还没…呢","explanation":"Verbo + 了 cuenta algo terminado; con un número, 了 va pegado al verbo (看了两个电影). 已经…了 es «ya». «Todavía no» es 还没 + verbo, con 呢 opcional al final y nunca con 了. 刚才 es «hace un rato».","examples":[{"target":"上个星期我看了两个电影。","base":"La semana pasada vi dos películas."},{"target":"我已经吃饭了。","base":"Ya comí."},{"target":"我还没写作业呢。","base":"Todavía no hice la tarea."}]},"review_status":"draft"},{"id":"zh-a2-u02","language_code":"zh","level":"A2","position":2,"title_es":"Viajes y experiencias","title_en":"旅游 Travel","description_es":"Contar experiencias con 过, cuántas veces, de dónde a dónde y cómo viajaste.","emoji":"🧳","objective_es":"Puedes contar lugares donde estuviste (过) y cuántas veces, decir de dónde a dónde y cuánto tardaste, y preguntar cómo y cuándo llegó alguien (是…的).","grammar":{"title":"过 · 次 · 从…到… · 是…的","explanation":"Verbo + 过 cuenta una experiencia (alguna vez) y se niega con 没: 没去过. Cuántas veces: 去过两次. De A a B: 从 A 到 B. Para algo que ya pasó, 是 + cómo / cuándo / con quién + verbo + 的: 我是坐飞机来的.","examples":[{"target":"我去过长城两次。","base":"Fui dos veces a la Gran Muralla."},{"target":"从北京到上海坐火车五个小时。","base":"De Pekín a Shanghái son cinco horas en tren."},{"target":"我是坐飞机来的。","base":"Vine en avión."}]},"review_status":"draft"},{"id":"zh-a2-u03","language_code":"zh","level":"A2","position":3,"title_es":"Restaurante y hotel","title_en":"饭馆 Restaurants and hotels","description_es":"Leer un menú, pedir, decir cómo es la comida, pedir la cuenta y llegar a un hotel.","emoji":"🍜","objective_es":"Puedes leer un menú sencillo, pedir con 来 y 请, decir si algo es picante o dulce, pedir la cuenta y hacer el check-in en un hotel.","grammar":{"title":"请 · 给 + persona · 来 + cantidad · verbo repetido","explanation":"请 + verbo es «por favor»: 请给我菜单. 给 es «dar» y, antes de una persona, «a / para»: 给我一双筷子. En un restaurante, 来 + cantidad es pedir: 来一碗米饭. El verbo repetido suaviza: 尝尝 (prueba un poco).","examples":[{"target":"请给我菜单。","base":"El menú, por favor."},{"target":"来两碗米饭。","base":"Dos platos de arroz, por favor."},{"target":"你尝尝！","base":"¡Prueba un poco!"}]},"review_status":"draft"},{"id":"zh-a2-u04","language_code":"zh","level":"A2","position":4,"title_es":"¿Qué estás haciendo?","title_en":"打电话 On the phone","description_es":"Acciones en curso con 在 y 正在, llamadas, esperar y encontrarse en un lugar.","emoji":"📞","objective_es":"Puedes decir qué estás haciendo ahora, atender y hacer una llamada, pedir que te esperen y decir dónde estás.","grammar":{"title":"在 / 正在 + verbo (+ 呢) · 给 + persona + 打电话","explanation":"Una acción en curso se dice con 在 o 正在 antes del verbo, muchas veces con 呢 al final: 我在做饭呢. Se niega con 没在. Para llamar a alguien: 给 + persona + 打电话. Al atender se dice 喂 (wéi).","examples":[{"target":"你在做什么呢？——我在跑步。","base":"¿Qué estás haciendo? — Estoy corriendo."},{"target":"她正在洗澡呢。","base":"Se está bañando."},{"target":"我晚上给你打电话。","base":"Por la noche te llamo."}]},"review_status":"draft"},{"id":"zh-a2-u05","language_code":"zh","level":"A2","position":5,"title_es":"Salud y bienestar","title_en":"身体 Health","description_es":"Decir qué te duele, contar que te enfermaste, ir al médico y dar consejos.","emoji":"🩺","objective_es":"Puedes decir qué te duele y cómo te sientes, avisar que estás enfermo, entender al médico y dar consejos con 应该 y 别.","grammar":{"title":"Parte del cuerpo + 疼 · 应该 · 别 · 多 + verbo","explanation":"Lo que duele va antes de 疼: 我头疼. 感冒了 / 生病了 cuentan un cambio (me resfrié, me enfermé). 应该 + verbo es un consejo (deberías); 别 + verbo pide que no se haga algo; 多 + verbo es «haz más…»: 多喝水.","examples":[{"target":"我头疼，嗓子也疼。","base":"Me duele la cabeza y también la garganta."},{"target":"你应该多休息。","base":"Deberías descansar más."},{"target":"别吃辣的！","base":"¡No comas picante!"}]},"review_status":"draft"},{"id":"zh-a2-u06","language_code":"zh","level":"A2","position":6,"title_es":"Invitaciones y planes","title_en":"邀请 Invitations","description_es":"Preguntar si alguien puede, contar planes, invitar, aceptar o rechazar y recibir visitas.","emoji":"🎉","objective_es":"Puedes preguntar si alguien tiene tiempo, contar tus planes, invitar, aceptar o rechazar con amabilidad y recibir a alguien en tu casa.","grammar":{"title":"A-不-A · 打算 · 还是 · 进来 / 出去","explanation":"Se pregunta repitiendo el verbo con 不 (去不去, 想不想) o con 没 si es 有 (有没有空), sin 吗. 打算 + verbo es un plan. 还是 es «o» en preguntas. Después de un verbo de movimiento, 来 indica hacia quien habla y 去, hacia afuera: 进来, 出去, 回来, 上来.","examples":[{"target":"你有没有空？","base":"¿Tienes tiempo?"},{"target":"你喝茶还是喝咖啡？","base":"¿Tomas té o café?"},{"target":"欢迎，欢迎！请进来！","base":"¡Bienvenido! ¡Pasa!"}]},"review_status":"draft"},{"id":"zh-a2-u07","language_code":"zh","level":"A2","position":7,"title_es":"Trabajo y estudios","title_en":"工作和学习 Work and study","description_es":"Horarios de trabajo, reuniones, exámenes, resultados de una acción y cómo se hace algo.","emoji":"💼","objective_es":"Puedes hablar de tu horario y tus compañeros, de exámenes y estudios, decir si terminaste o entendiste algo y contar cuánto tiempo estudiaste o trabajaste.","grammar":{"title":"Complementos de resultado · 得 de grado · duración con 了","explanation":"Un verbo o adjetivo después del verbo dice el resultado: 做完 (terminar), 听懂 (entender lo que se oye), 写错 (escribir mal), 准备好 (dejar listo); se niegan con 没 (没听懂). Cómo se hace algo: verbo + 得 + adjetivo (说得很好). Cuánto duró: verbo + 了 + tiempo (学了两年).","examples":[{"target":"我做完作业了。","base":"Terminé la tarea."},{"target":"你中文说得很好！","base":"¡Hablas muy bien chino!"},{"target":"我学了两年中文。","base":"Estudié chino dos años."}]},"review_status":"draft"},{"id":"zh-a2-u08","language_code":"zh","level":"A2","position":8,"title_es":"Compras y comparaciones","title_en":"买东西 Shopping","description_es":"Probarse ropa, cambiar y elegir, comparar con 更, 最 y 没有…那么, descuentos y pagos.","emoji":"🛍️","objective_es":"Puedes probarte ropa y decir si te queda bien, cambiar algo, comparar precios y productos, entender un descuento y decir cómo pagas.","grammar":{"title":"比…一点儿 / 多了 · 更 · 最 · 没有…那么","explanation":"Con 比 se dice cuánto: 比…一点儿 (un poco más), 比…多了 (mucho más). 更 es «aún más» y 最, «el más», ambos antes del adjetivo. A 没有 B 那么 + adjetivo es «A no es tan… como B». 打八折 no es 80 % de descuento: pagas el 80 %.","examples":[{"target":"这个比那个贵多了。","base":"Este es mucho más caro que aquel."},{"target":"红色的最便宜。","base":"El rojo es el más barato."},{"target":"这件没有那件那么贵。","base":"Esta no es tan cara como aquella."}]},"review_status":"draft"},{"id":"zh-a2-u09","language_code":"zh","level":"A2","position":9,"title_es":"Tecnología y comunicación","title_en":"手机和电脑 Technology","description_es":"Mensajes, fotos y videos, internet y contraseñas, cargar el celular y el primer 把.","emoji":"📱","objective_es":"Puedes mandar mensajes, fotos y correos, pedir la contraseña del wifi, decir con qué haces algo (用) y usar 把 para decir qué haces con una cosa.","grammar":{"title":"发给 + persona · 用 + cosa + verbo · 把","explanation":"Quien recibe va después del verbo con 给 (发给你) o antes con 给 (给你发). 用 + cosa + verbo dice con qué: 我用手机上网. Con 把 la cosa va antes del verbo cuando haces algo con ella: 把照片发给我. Después del verbo siempre va algo más (给我, 了…).","examples":[{"target":"我一会儿发给你。","base":"Te lo mando en un rato."},{"target":"我用手机拍照片。","base":"Saco fotos con el celular."},{"target":"请把手机给我。","base":"Dame el celular, por favor."}]},"review_status":"draft"},{"id":"zh-a2-u10","language_code":"zh","level":"A2","position":10,"title_es":"Rutinas, cambios y relaciones","title_en":"变化 Changes","description_es":"Antes y ahora, cosas que cambian, la pareja y los vecinos, «cuando…» y «mientras…».","emoji":"🔄","objective_es":"Puedes contar cómo eran las cosas antes y cómo son ahora, decir qué cambia cada vez más, hablar de parejas, hijos y vecinos, y contar qué hacías de chico.","grammar":{"title":"以前…现在…了 · 越来越 · …的时候 · 一边…一边","explanation":"以前 (antes) contrasta con 现在; 了 al final marca el cambio y 不…了 es «ya no». 越来越 + adjetivo es «cada vez más». …的时候 es «cuando…» y va al principio. 一边 A 一边 B es hacer dos cosas a la vez.","examples":[{"target":"以前我不喝咖啡，现在喝了。","base":"Antes no tomaba café; ahora sí."},{"target":"天气越来越冷了。","base":"Hace cada vez más frío."},{"target":"她一边听音乐一边做饭。","base":"Cocina mientras escucha música."}]},"review_status":"draft"},{"id":"zh-a2-u11","language_code":"zh","level":"A2","position":11,"title_es":"Cultura y costumbres chinas","title_en":"节日 Festivals and customs","description_es":"El Año Nuevo chino, la Fiesta de Medio Otoño, regalos y tradiciones, por qué y en qué orden.","emoji":"🧧","objective_es":"Puedes contar cómo se festeja el Año Nuevo chino y la Fiesta de Medio Otoño, preguntar y explicar por qué, decir en qué orden se hacen las cosas y hablar de regalos.","grammar":{"title":"为什么 · 因为…所以… · 先…再… · adjetivos repetidos","explanation":"为什么 pregunta «¿por qué?» y se responde con 因为 (porque); 所以 es «por eso», y los dos se pueden usar juntos. 先 A 再 B es «primero A y después B». Algunos adjetivos se repiten para sonar más vivos: 甜甜的 (dulcecito).","examples":[{"target":"因为下雨了，所以我不去。","base":"Como llueve, no voy."},{"target":"我们先吃饭，再看电视。","base":"Primero comemos y después miramos la tele."},{"target":"月饼甜甜的，很好吃。","base":"Los pasteles de luna son dulcecitos y muy ricos."}]},"review_status":"draft"},{"id":"zh-a2-u12","language_code":"zh","level":"A2","position":12,"title_es":"Opiniones, problemas y soluciones","title_en":"问题和办法 Problems and solutions","description_es":"Dar tu opinión, contar un problema (se rompió, lo perdí, me lo robaron) y buscar una solución.","emoji":"🛠️","objective_es":"Puedes dar tu opinión y decir si estás de acuerdo, contar qué te pasó (丢了, 坏了, 被偷了), proponer una solución y hablar de condiciones con 如果…就….","grammar":{"title":"觉得 · 但是 · 被 · 如果…就…","explanation":"觉得 da una opinión (我觉得…) y 但是 es «pero». Con 被 algo sufre la acción, casi siempre algo malo: 我的手机被偷了. 如果…就… es «si…, (entonces)…»: 如果下雨，我就不去; 就 va antes del verbo. 怎么了？ es «¿qué pasó?» y 怎么办？, «¿qué hago?».","examples":[{"target":"我觉得这个很好，但是有点儿贵。","base":"Me parece muy bueno, pero es medio caro."},{"target":"我的手机被偷了！","base":"¡Me robaron el celular!"},{"target":"如果下雨，我就不去。","base":"Si llueve, no voy."}]},"review_status":"draft"},{"id":"fr-a1-u01","language_code":"fr","level":"A1","position":1,"title_es":"Saludos y presentaciones","title_en":"Bonjour!","description_es":"Saludar y despedirse, tu y vous, ça va, je m'appelle. Consonantes finales mudas y elisión.","emoji":"👋","objective_es":"Puedes saludar y despedirte según la hora y la persona, preguntar cómo está alguien, presentarte y decir tu nombre.","grammar":{"title":"Tu y vous · je m'appelle","explanation":"Con amigos, familia y chicos se usa tu (salut, s'il te plaît, et toi?); con desconocidos, en un negocio o con una persona mayor, vous (bonjour, s'il vous plaît, et vous?), junto con madame o monsieur. Para presentarse: je m'appelle + nombre. Delante de vocal, me se vuelve m' (elisión): je m'appelle, nunca «je me appelle». Muchas consonantes finales no suenan: en salut y en s'il vous plaît, la t final no se pronuncia.","examples":[{"target":"Bonjour, madame.","base":"Buenos días, señora."},{"target":"Salut! Je m'appelle Lucas.","base":"¡Hola! Me llamo Lucas."},{"target":"Ça va? — Ça va bien, merci.","base":"¿Cómo va? — Bien, gracias."}]},"review_status":"draft"},{"id":"fr-a1-u02","language_code":"fr","level":"A1","position":2,"title_es":"Soy argentino: être y nacionalidades","title_en":"Je suis argentin","description_es":"Être en singular y vous êtes, nacionalidades con género, je suis de, j'habite à, je parle y ne… pas. Liaison vous‿êtes y consonante final del femenino.","emoji":"🌎","objective_es":"Puedes decir quién eres, tu nacionalidad, de dónde eres, dónde vives y qué idiomas hablas, y preguntárselo a otra persona.","grammar":{"title":"Être · nacionalidades · ne… pas","explanation":"El verbo être (ser) en singular: je suis, tu es, il est, elle est, y vous êtes para usted. Las nacionalidades concuerdan con la persona: il est argentin, elle est argentine; en el femenino la consonante final sí suena (argentine, française, étudiante). Con una profesión no va artículo: je suis étudiant. Para el origen: je suis de + ciudad; para dónde vives: j'habite à + ciudad. La negación rodea al verbo: je ne suis pas, je ne parle pas; delante de vocal, ne se vuelve n': il n'est pas. Los idiomas y las nacionalidades se escriben en minúscula.","examples":[{"target":"Je suis argentine.","base":"Soy argentina."},{"target":"Vous êtes d'où?","base":"¿De dónde es usted?"},{"target":"Je ne parle pas italien.","base":"No hablo italiano."}]},"review_status":"draft"},{"id":"fr-a1-u03","language_code":"fr","level":"A1","position":3,"title_es":"Números y edad","title_en":"Les nombres","description_es":"Números del 1 al 12 y el 20, avoir en singular y la edad con avoir (j'ai vingt ans). Six y dix, deux y douze, liaison deux‿ans.","emoji":"🔢","objective_es":"Puedes contar del uno al doce y el veinte, decir cuántos años tienes y preguntar la edad de otra persona.","grammar":{"title":"Avoir y la edad","explanation":"La edad se dice con avoir (tener), no con être: j'ai vingt ans, nunca «je suis vingt». Avoir en singular: j'ai (je se vuelve j' delante de vocal), tu as, il a, elle a. Ans es la forma plural de an (año): un an, deux ans. Para preguntar: quel âge as-tu? (con inversión y guion) o, más coloquial, tu as quel âge? Ojo con la liaison: deux‿ans, trois‿ans, six‿ans y dix‿ans se unen con un sonido z; huit ans y vingt ans hacen sonar la t; neuf ans se dice con un sonido v.","examples":[{"target":"J'ai vingt ans.","base":"Tengo veinte años."},{"target":"Quel âge as-tu? — J'ai douze ans.","base":"¿Cuántos años tienes? — Tengo doce."},{"target":"Il a six ans.","base":"Tiene seis años."}]},"review_status":"draft"},{"id":"fr-a1-u04","language_code":"fr","level":"A1","position":4,"title_es":"La familia","title_en":"La famille","description_es":"La familia, los posesivos (mon / ma / mes, ton / ta / tes, son / sa / ses), il s'appelle y j'ai un frère. Falso amigo: les parents. Le fils y la fille.","emoji":"👨‍👩‍👧","objective_es":"Puedes presentar a tu familia, decir cómo se llaman y cuántos años tienen, y preguntar por la familia de otra persona.","grammar":{"title":"Los posesivos","explanation":"El posesivo concuerda con la cosa o la persona poseída, no con quien la posee: mon père, ma mère, mes parents (mi, mis); ton / ta / tes (tu, tus); son / sa / ses (su, sus). Por eso son père es «su papá» tanto de Hugo como de Léa, y sa mère es «su mamá» aunque hable de un hombre. Delante de vocal se usa mon, ton, son aunque la palabra sea femenina: mon amie, nunca «ma amie». Para presentar: c'est mon frère, voici ma famille. Ojo con el falso amigo: les parents son los padres (no los parientes).","examples":[{"target":"C'est mon père.","base":"Es mi papá."},{"target":"Voici ma sœur et mes parents.","base":"Esta es mi hermana y estos son mis padres."},{"target":"Sa mère s'appelle Anne.","base":"Su mamá se llama Anne."}]},"review_status":"draft"},{"id":"fr-a1-u05","language_code":"fr","level":"A1","position":5,"title_es":"Objetos y colores","title_en":"Les objets et les couleurs","description_es":"Objetos de todos los días con c'est / ce sont, un / une / des y le / la / les; los colores y la concordancia (vert / verte). La s del plural no suena.","emoji":"🎨","objective_es":"Puedes nombrar objetos, preguntar qué es algo, decir de qué color es y describirlo con chico o grande.","grammar":{"title":"Artículos · c'est / ce sont · el color después del sustantivo","explanation":"Cada sustantivo tiene género: un / le con masculinos, une / la con femeninos, l' delante de vocal y des / les en plural. A veces el género no coincide con el español: la couleur (el color), le stylo (el bolígrafo). Para nombrar algo: c'est + un / une (singular) y ce sont + des (plural); se pregunta qu'est-ce que c'est? El color va después del sustantivo y concuerda: un sac vert, une chaise verte, des chaises vertes. Petit y grand van antes: un petit livre, une grande table. La s del plural no suena: livre y livres se dicen igual, la diferencia se oye en le / les.","examples":[{"target":"Qu'est-ce que c'est? — C'est un stylo.","base":"¿Qué es esto? — Es un bolígrafo."},{"target":"Ce sont des clés.","base":"Son llaves."},{"target":"C'est une petite table blanche.","base":"Es una mesa chica y blanca."}]},"review_status":"draft"},{"id":"fr-a1-u06","language_code":"fr","level":"A1","position":6,"title_es":"La casa","title_en":"Chez moi","description_es":"Las partes de la casa, il y a / il n'y a pas de, où est…? y las preposiciones de lugar (dans, sur, sous, à côté de, devant, derrière). Sur y sous no suenan igual.","emoji":"🏠","objective_es":"Puedes describir tu casa o tu apartamento, decir qué hay y qué no hay, y preguntar y decir dónde está algo.","grammar":{"title":"Il y a / il n'y a pas de · où est…? · preposiciones de lugar","explanation":"Il y a (hay) sirve para singular y plural: il y a une chambre, il y a deux chambres. En la negación, un / une / des pasan a de: il n'y a pas de fenêtre (nunca «pas une fenêtre»). Para ubicar algo: où est…? (o où sont…? en plural) y la respuesta con il / elle est + dans, sur, sous, devant, derrière o à côté de. De + le se contrae en du: à côté du lit; con la y l' no cambia: à côté de la porte.","examples":[{"target":"Il y a deux chambres et un salon.","base":"Hay dos dormitorios y una sala."},{"target":"Il n'y a pas de fenêtre.","base":"No hay ventana."},{"target":"Où est le chat? — Il est sous le lit.","base":"¿Dónde está el gato? — Está debajo de la cama."}]},"review_status":"draft"},{"id":"fr-a1-u07","language_code":"fr","level":"A1","position":7,"title_es":"Comer y beber","title_en":"Manger et boire","description_es":"Comida y bebida, je voudrais y je prends en el café, los partitivos (du pain, de la viande, de l'eau, des légumes), pas de y las cantidades (beaucoup de, un peu de). Vocales nasales.","emoji":"🥐","objective_es":"Puedes pedir algo de comer y de tomar en un café, decir qué comes y qué no, y hablar de cantidades.","grammar":{"title":"Los partitivos · pas de · beaucoup de, un peu de","explanation":"Para algo que no se cuenta, el francés usa el partitivo, que en español no se dice: du (masculino), de la (femenino), de l' (delante de vocal) y des (plural). Je mange du pain (como pan), je bois de l'eau (tomo agua), je mange des légumes. En la negación y después de una cantidad queda sólo de (d' delante de vocal): je ne bois pas de café, beaucoup de fromage, un peu de lait, une bouteille d'eau. Para pedir con cortesía: je voudrais (quisiera) + un / une: je voudrais un café, s'il vous plaît.","examples":[{"target":"Je mange du pain et de la viande.","base":"Como pan y carne."},{"target":"Je ne bois pas de café.","base":"No tomo café."},{"target":"Un peu de lait, s'il vous plaît.","base":"Un poco de leche, por favor."}]},"review_status":"draft"},{"id":"fr-a1-u08","language_code":"fr","level":"A1","position":8,"title_es":"Mi día","title_en":"Ma journée","description_es":"Rutina y momentos del día; verbos en -er en presente, nous / ils / on; je me lève, je me couche; d'abord, ensuite; toujours, souvent. -e, -es, -ent mudas y liaison ils‿écoutent.","emoji":"⏰","objective_es":"Puedes contar tu rutina: a qué momento del día haces cada cosa, en qué orden y con qué frecuencia, y lo que hacen otras personas.","grammar":{"title":"Verbos en -er en presente","explanation":"Los verbos en -er (travailler, regarder, écouter) cambian la terminación: je travaille, tu travailles, il / elle / on travaille, nous travaillons, vous travaillez, ils / elles travaillent. Las terminaciones -e, -es y -ent no se pronuncian: travaille, travailles y travaillent suenan igual; sólo nous (-ons) y vous (-ez) suenan distinto. On (nosotros, informal) va con el verbo como il: on travaille. Delante de vocal hay liaison con sonido z: nous‿écoutons, ils‿écoutent. Los pronominales llevan me / te / se: je me lève, tu te lèves, il se lève.","examples":[{"target":"Je travaille le matin.","base":"Trabajo por la mañana."},{"target":"Nous travaillons à Lyon.","base":"Trabajamos en Lyon."},{"target":"Ils écoutent la radio le soir.","base":"Ellos escuchan la radio por la noche."}]},"review_status":"draft"},{"id":"fr-a1-u09","language_code":"fr","level":"A1","position":9,"title_es":"La hora y los días","title_en":"Quelle heure est-il?","description_es":"La hora con il est… heures, et quart, et demie, moins le quart, midi y minuit; à quelle heure?; los días sin artículo (lundi) y con artículo para lo habitual (le lundi); aujourd'hui, demain, quand. Liaison deux‿heures, neuf heures.","emoji":"🕐","objective_es":"Puedes decir y preguntar la hora, decir a qué hora haces algo y hablar de los días de la semana, de hoy y de mañana.","grammar":{"title":"Il est… heures · lundi / le lundi","explanation":"La hora se dice con il est + número + heures (une heure, en singular): il est trois heures. Después se agrega et quart (y cuarto), et demie (y media) o moins le quart (menos cuarto). A las doce: midi (mediodía) o minuit (medianoche), sin heures; con ellos se escribe et demi, sin e. Para decir a qué hora: à + hora (à sept heures). Los días van en minúscula y sin artículo cuando es un día concreto (lundi, je travaille: este lunes); con le es una costumbre (le lundi, je travaille: todos los lunes). Delante de heures hay liaison: deux‿heures y trois‿heures con sonido z; en neuf heures, la f suena como v.","examples":[{"target":"Il est huit heures et quart.","base":"Son las ocho y cuarto."},{"target":"Je me lève à sept heures et demie.","base":"Me levanto a las siete y media."},{"target":"Le dimanche, je ne travaille pas.","base":"Los domingos no trabajo."}]},"review_status":"draft"},{"id":"fr-a1-u10","language_code":"fr","level":"A1","position":10,"title_es":"La ciudad y las direcciones","title_en":"En ville","description_es":"Aller en presente; à + le = au, à + les = aux (au cinéma, à la gare); lugares de la ciudad; près de, loin; indicaciones con tournez, allez, prenez. Ils vont / ils sont y liaison nous‿allons. Género distinto: la banque.","emoji":"🏙️","objective_es":"Puedes decir adónde vas, nombrar los lugares de la ciudad, decir si quedan cerca o lejos y pedir y dar indicaciones simples.","grammar":{"title":"Aller + à · au, à la, aux","explanation":"Aller es irregular: je vais, tu vas, il / elle va, nous allons, vous allez, ils / elles vont. Para decir adónde se usa à, que se contrae con le y les: à + le = au (au cinéma), à + les = aux (aux Galeries Lafayette); con la y l' no cambia (à la gare). Lo mismo con de: de + le = du (près du musée). Para dar indicaciones a alguien que tratas de vous, el imperativo es el mismo verbo sin el pronombre: tournez, allez, prenez. Liaison: nous‿allons y vous‿allez se unen con sonido z.","examples":[{"target":"Je vais au cinéma.","base":"Voy al cine."},{"target":"Nous allons à la gare.","base":"Vamos a la estación."},{"target":"Tournez à gauche.","base":"Doble a la izquierda."}]},"review_status":"draft"},{"id":"fr-a1-u11","language_code":"fr","level":"A1","position":11,"title_es":"Gustos y tiempo libre","title_en":"J'aime…","description_es":"Aimer, adorer, détester y préférer + le / la o + infinitivo; faire du sport; jouer au foot y jouer de la guitare; avec; pas du tout. Terminaciones mudas y liaison ils‿aiment.","emoji":"❤️","objective_es":"Puedes decir qué te gusta, qué te encanta, qué odias y qué prefieres hacer en tu tiempo libre, y preguntárselo a otra persona.","grammar":{"title":"Aimer + le / la · faire du · jouer au / jouer de la","explanation":"Con aimer, adorer, détester y préférer va el artículo definido, como en español: j'aime le foot, je déteste la musique (nunca «j'aime du foot»). También van con un infinitivo, sin preposición: j'aime lire, je préfère danser. Para negar: je n'aime pas, y para reforzar, pas du tout. Faire va con du / de la: je fais du sport. Jouer cambia de preposición: jouer au foot (deportes: à + le = au) y jouer de la guitare o du piano (instrumentos: de + le = du). En español es «jugar» y «tocar»; en francés, siempre jouer.","examples":[{"target":"J'aime le foot, mais je préfère la musique.","base":"Me gusta el fútbol, pero prefiero la música."},{"target":"Je fais du sport avec Léa.","base":"Hago deporte con Léa."},{"target":"Il joue de la guitare.","base":"Él toca la guitarra."}]},"review_status":"draft"},{"id":"fr-a1-u12","language_code":"fr","level":"A1","position":12,"title_es":"Preguntas, compras y precios","title_en":"Questions et achats","description_es":"Tres maneras de preguntar (entonación, est-ce que, inversión); qui, qu'est-ce que, comment, pourquoi / parce que, combien, quel / quelle; números hasta 100 y precios en euros. Falso amigo: le magasin.","emoji":"🛍️","objective_es":"Puedes hacer preguntas de distintas maneras, preguntar y entender precios hasta 100 euros y pedir lo que buscas en una tienda.","grammar":{"title":"Tres maneras de preguntar · quel / quelle · los números","explanation":"Una pregunta de sí o no se hace de tres maneras: con la entonación (tu parles français?, lo más común al hablar), con est-ce que delante (est-ce que tu parles français?, neutro) o con inversión del verbo y el pronombre unidos por un guion (parles-tu français?, más formal y escrito). Para pedir información: qui (quién), qu'est-ce que (qué), comment (cómo), pourquoi (por qué, y se responde parce que), combien (cuánto; combien de + sustantivo, sin artículo). Quel concuerda con el sustantivo: quel sac, quelle couleur, y suenan igual. Los números siguen una lógica propia: 70 es soixante-dix (60 + 10), 80 es quatre-vingts (4 × 20) y 90, quatre-vingt-dix.","examples":[{"target":"Est-ce que tu parles français?","base":"¿Hablas francés?"},{"target":"Pourquoi tu aimes Paris? — Parce que c'est une grande ville.","base":"¿Por qué te gusta París? — Porque es una ciudad grande."},{"target":"C'est combien? — Quarante euros.","base":"¿Cuánto cuesta? — Cuarenta euros."}]},"review_status":"draft"},{"id":"fr-a1-u13","language_code":"fr","level":"A1","position":13,"title_es":"Trabajo y estudios","title_en":"Le travail","description_es":"Profesiones con género, la profesión sin artículo con être, être y avoir en plural (ils‿ont / ils sont), je commence y je finis. Falso amigo: le bureau.","emoji":"💼","objective_es":"Puedes preguntar y decir a qué se dedica alguien, dónde trabaja y a qué hora empieza y termina, y hablar de tu familia en plural.","grammar":{"title":"Je suis médecin · nous sommes, ils ont · je finis","explanation":"Con être, la profesión va sin artículo: elle est médecin, je suis professeur (nunca «je suis un professeur»); con c'est, en cambio, sí: c'est un médecin. Muchas profesiones tienen femenino: serveur → serveuse, vendeur → vendeuse, infirmier → infirmière, boulanger → boulangère. Être y avoir en plural: nous sommes, vous êtes, ils sont; nous avons, vous avez, ils ont. Ojo con la liaison: en ils ont la s se une a la vocal con un sonido z; en ils sont se oye una s. Finir es un verbo en -ir: je finis, tu finis, il finit (suenan igual).","examples":[{"target":"Elle est médecin.","base":"Ella es médica."},{"target":"Nous sommes professeurs et nous avons deux enfants.","base":"Somos profesores y tenemos dos hijos."},{"target":"Je commence à neuf heures et je finis à cinq heures.","base":"Empiezo a las nueve y termino a las cinco."}]},"review_status":"draft"},{"id":"fr-a1-u14","language_code":"fr","level":"A1","position":14,"title_es":"Cómo es: describir personas","title_en":"Comment est-il?","description_es":"Describir el físico y el carácter de alguien: comment est-il?, avoir les cheveux / les yeux, très y assez. Femeninos irregulares y posición del adjetivo. Falsos amigos: gentil y drôle.","emoji":"🧑","objective_es":"Puedes preguntar cómo es una persona y describir su físico (altura, pelo, ojos) y su carácter, con muy y bastante.","grammar":{"title":"El adjetivo: concordancia y lugar","explanation":"El adjetivo concuerda con la persona: en femenino suele sumar una e (blond → blonde, court → courte) y en plural una s. Algunos femeninos son irregulares: beau → belle, vieux → vieille, gentil → gentille, sportif → sportive, sérieux → sérieuse. La mayoría va después del sustantivo (un chat noir, une fille sportive), pero beau, jeune, vieux, petit y grand van antes: un beau garçon, une jeune femme. Para el pelo y los ojos se usa avoir + les: elle a les cheveux longs, il a les yeux bleus (yeux es el plural irregular de œil). Para preguntar se invierte el verbo: comment est-il? / comment est-elle?","examples":[{"target":"Comment est-elle? — Elle est jeune et très belle.","base":"¿Cómo es? — Es joven y muy linda."},{"target":"Il a les cheveux courts et les yeux bleus.","base":"Tiene el pelo corto y los ojos azules."},{"target":"C'est un vieux chien noir.","base":"Es un perro negro viejo."}]},"review_status":"draft"},{"id":"fr-a1-u15","language_code":"fr","level":"A1","position":15,"title_es":"Meses, fechas y cumpleaños","title_en":"Les dates","description_es":"Los meses (en minúscula, en + mes), la fecha (le 14 juillet, pero le premier mai), le mois, l'année y l'anniversaire (cumpleaños). El 14 de julio y la Fête de la musique.","emoji":"📅","objective_es":"Puedes decir los meses, preguntar y decir la fecha, y hablar de cumpleaños y fechas importantes.","grammar":{"title":"La fecha: le + número + mes","explanation":"Los meses se escriben con minúscula y son masculinos. «En mayo» es en mai. La fecha se dice le + número + mes, sin «de»: le 14 juillet (el 14 de julio). Sólo el día 1 cambia: le premier mai (el primero de mayo). Para preguntar la fecha: quelle est la date? Se responde nous sommes le 3 mars o c'est le 3 mars. Falso amigo: l'anniversaire es el cumpleaños.","examples":[{"target":"Nous sommes le premier avril.","base":"Hoy es primero de abril."},{"target":"C'est le 14 juillet.","base":"Es 14 de julio."},{"target":"Mon anniversaire, c'est en mai.","base":"Mi cumpleaños es en mayo."}]},"review_status":"draft"},{"id":"fr-a1-u16","language_code":"fr","level":"A1","position":16,"title_es":"El clima y las estaciones","title_en":"La météo","description_es":"Quel temps fait-il? Il fait beau / mauvais / froid / chaud, il pleut, il neige, il y a du soleil / du vent; las estaciones (en été, pero au printemps); la mer, la montagne, la plage. Los hemisferios.","emoji":"☀️","objective_es":"Puedes preguntar y decir qué tiempo hace, hablar de las estaciones y contar si prefieres el mar o la montaña.","grammar":{"title":"Il fait + adjetivo · en / au + estación","explanation":"Para el clima, el francés usa il fait + adjetivo: il fait beau (hace buen tiempo), il fait mauvais, il fait froid, il fait chaud; nunca «il est froid». La lluvia y la nieve tienen verbo propio: il pleut, il neige. Con el sol y el viento se usa il y a du: il y a du soleil, il y a du vent. Para preguntar: quel temps fait-il? Las estaciones son masculinas y se dicen con en (en été, en automne, en hiver), salvo au printemps. Ojo: la mer (el mar) es femenino.","examples":[{"target":"Quel temps fait-il? — Il fait beau.","base":"¿Qué tiempo hace? — Hace buen tiempo."},{"target":"Il pleut et il y a du vent.","base":"Llueve y hay viento."},{"target":"Au printemps, il fait beau, mais en hiver, il fait froid.","base":"En primavera hace buen tiempo, pero en invierno hace frío."}]},"review_status":"draft"},{"id":"fr-a1-u17","language_code":"fr","level":"A1","position":17,"title_es":"Transporte y planes","title_en":"Transports et projets","description_es":"Medios de transporte (en bus, en train, pero à pied y à vélo), prendre en presente y el futuro próximo con aller + infinitivo. Ce soir, ce week-end, la semaine prochaine. Liaison en‿avion; il prend / ils prennent.","emoji":"🚆","objective_es":"Puedes decir cómo vas a un lugar, comprar un pasaje y contar qué vas a hacer esta noche, el fin de semana o en las vacaciones.","grammar":{"title":"Prendre · aller + infinitivo","explanation":"Prendre es irregular: je prends, tu prends, il prend (suenan igual: la s y la d finales no se pronuncian), nous prenons, vous prenez, ils prennent (aquí suena la doble n). Con los transportes con motor se usa en (en bus, en train, en voiture, en avion, en métro), pero à pied y à vélo. Para los planes cercanos, el futuro próximo: aller en presente + infinitivo (je vais partir, tu vas rester, on va visiter). En la negación, ne… pas rodea a aller: je ne vais pas partir.","examples":[{"target":"Nous prenons le métro.","base":"Tomamos el metro."},{"target":"Ce week-end, on va visiter Paris.","base":"Este fin de semana vamos a visitar París."},{"target":"Je ne vais pas partir ce soir.","base":"No me voy a ir esta noche."}]},"review_status":"draft"},{"id":"fr-a2-u01","language_code":"fr","level":"A2","position":1,"title_es":"¿Qué hiciste el fin de semana?","title_en":"Le week-end dernier","description_es":"Passé composé con avoir: participios en -é, -i, -u e irregulares (fait, pris); je n'ai pas mangé; déjà y pas encore; faire les courses y faire le ménage. Je parle / j'ai parlé, j'ai bu / j'ai vu.","emoji":"🗓️","objective_es":"Puedes contar qué hiciste ayer o el fin de semana pasado, decir lo que no hiciste y preguntar si alguien ya hizo algo.","grammar":{"title":"El passé composé con avoir","explanation":"Para contar una acción terminada se usa avoir en presente + participio: j'ai mangé, tu as fini, il a lu, nous avons vu, vous avez fait, ils ont pris. Los verbos en -er hacen el participio en -é (parler → parlé), los en -ir en -i (finir → fini, dormir → dormi); boire, lire y voir dan bu, lu, vu; faire da fait y prendre, pris. En la negación, ne… pas rodea al auxiliar: je n'ai pas mangé. Déjà va entre el auxiliar y el participio: j'ai déjà fini. Ojo con la pronunciación: je parle termina en l, j'ai parlé termina en é.","examples":[{"target":"Hier, j'ai mangé avec mes parents.","base":"Ayer comí con mis padres."},{"target":"Je n'ai pas encore fini.","base":"Todavía no terminé."},{"target":"Nous avons pris le train.","base":"Tomamos el tren."}]},"review_status":"draft"},{"id":"fr-a2-u02","language_code":"fr","level":"A2","position":2,"title_es":"Viajes","title_en":"Voyages","description_es":"Passé composé con être (aller, partir, arriver, rester, rentrer, venir, tomber) y la concordancia; il y a + tiempo = hace; el aeropuerto, el hotel, la maleta; en retard / à l'heure. Cultura: el TGV y la SNCF.","emoji":"✈️","objective_es":"Puedes contar un viaje: adónde fuiste, cuándo llegaste y volviste, cuánto te quedaste y si el vuelo o el tren llegó a tiempo.","grammar":{"title":"El passé composé con être","explanation":"Un grupo de verbos, casi todos de movimiento, forma el passé composé con être en lugar de avoir: aller (allé), partir (parti), arriver (arrivé), rester (resté), rentrer (rentré), venir (venu), tomber (tombé). Con être, el participio concuerda con el sujeto como un adjetivo: elle est partie, nous sommes arrivés, elles sont venues (la e y la s que se agregan no suenan). Los demás verbos siguen con avoir: j'ai pris le train, nous avons visité Rome. Il y a + tiempo significa «hace»: je suis parti il y a deux ans.","examples":[{"target":"Elle est partie à six heures.","base":"Ella se fue a las seis."},{"target":"Nous sommes arrivés en retard.","base":"Llegamos tarde."},{"target":"Il y a deux ans, je suis allé à Rome.","base":"Hace dos años fui a Roma."}]},"review_status":"draft"},{"id":"fr-a2-u03","language_code":"fr","level":"A2","position":3,"title_es":"Restaurante y hotel","title_en":"Au restaurant et à l'hôtel","description_es":"Reservar y pedir con cortesía: j'aimerais, je pourrais, pourriez-vous…? La carte y le menu, l'entrée, la cuenta y el service compris.","emoji":"🍽️","objective_es":"Puedes reservar una mesa o una habitación, pedir cosas en el hotel, elegir de la carta, pedir la carne a tu gusto y pagar la cuenta con cortesía.","grammar":{"title":"El condicional de cortesía: j'aimerais, je pourrais, pourriez-vous…?","explanation":"Para pedir con amabilidad, el francés usa el condicional, como el español «me gustaría» o «¿podría…?». Ya conoces je voudrais (quisiera). Ahora sumas j'aimerais (me gustaría), je pourrais (yo podría) y pourriez-vous…? (¿podría usted…?), que van con un sustantivo o con un verbo en infinitivo: j'aimerais réserver, pourriez-vous me donner…? En el hotel y en el restaurante se usa siempre vous. Las terminaciones -ais y -ez se escriben distinto, pero la s y la z finales no suenan.","examples":[{"target":"J'aimerais réserver une table pour ce soir.","base":"Me gustaría reservar una mesa para esta noche."},{"target":"Je pourrais avoir l'addition?","base":"¿Me podría traer la cuenta?"},{"target":"Pourriez-vous me donner la clé?","base":"¿Podría darme la llave?"}]},"review_status":"draft"},{"id":"fr-a2-u04","language_code":"fr","level":"A2","position":4,"title_es":"Cuando era chico","title_en":"Quand j'étais petit","description_es":"El imparfait para describir el pasado y lo habitual: j'étais, j'avais, j'habitais, je jouais, il y avait, c'était; d'habitude, avant, chaque.","emoji":"🧸","objective_es":"Puedes contar cómo era tu infancia: dónde vivías, cómo eras, qué había y qué hacías normalmente, y compararlo con tu vida de ahora.","grammar":{"title":"El imparfait: j'étais, j'avais, j'habitais","explanation":"El imparfait es el pasado para describir y para contar lo habitual, como el imperfecto español (era, tenía, vivía, jugaba). Se forma con la raíz de nous en presente (nous habitons → habit-) y las terminaciones -ais, -ais, -ait, -ions, -iez, -aient: j'habitais, il habitait, nous habitions. Être es irregular: j'étais, c'était. Avoir: j'avais, il y avait (había). La edad va con avoir: quand j'avais dix ans, nunca «j'étais dix ans». Las terminaciones -ais, -ait y -aient suenan igual: la s, la t y el -ent finales no se pronuncian.","examples":[{"target":"Quand j'étais petit, j'habitais à la campagne.","base":"Cuando era chico, vivía en el campo."},{"target":"D'habitude, je jouais avec mon frère.","base":"Normalmente jugaba con mi hermano."},{"target":"Il y avait un grand jardin.","base":"Había un jardín grande."}]},"review_status":"draft"},{"id":"fr-a2-u05","language_code":"fr","level":"A2","position":5,"title_es":"¿Qué pasó? Contar un hecho","title_en":"Qu'est-ce qui s'est passé?","description_es":"Contar un hecho: imparfait para la escena (il pleuvait, j'étais en train de…) y passé composé para lo que pasó (soudain, tout à coup, alors).","emoji":"📰","objective_es":"Puedes preguntar qué pasó y contar un hecho (un robo, una pérdida, un accidente): cómo era la escena, qué pasó de repente, qué hiciste y cómo terminó.","grammar":{"title":"Imparfait y passé composé: la escena y el hecho","explanation":"Para contar algo que pasó se combinan los dos pasados, como en español «llovía cuando vi…». El imparfait pinta la escena, lo que estaba pasando: il pleuvait, j'étais en train de lire (estaba leyendo: être en train de + infinitivo), pendant que je dormais (mientras dormía). El passé composé cuenta el hecho puntual, a menudo con soudain o tout à coup (de repente): j'ai vu un accident, quelqu'un a volé mon sac. Alors (entonces) introduce la consecuencia, y heureusement / malheureusement, tu comentario. Ojo: je regardais y j'ai regardé suenan distinto (e abierta al final frente a j'ai delante).","examples":[{"target":"Il pleuvait. Soudain, j'ai vu un accident.","base":"Llovía. De repente, vi un accidente."},{"target":"J'étais en train de lire quand quelqu'un est arrivé.","base":"Estaba leyendo cuando llegó alguien."},{"target":"J'ai eu peur, alors j'ai appelé la police.","base":"Tuve miedo, entonces llamé a la policía."}]},"review_status":"draft"},{"id":"fr-a2-u06","language_code":"fr","level":"A2","position":6,"title_es":"Invitaciones y planes","title_en":"Invitations et projets","description_es":"Invitar, aceptar y rechazar (ça te dit de…?, avec plaisir, d'accord, désolé, je ne peux pas); el futur simple (j'irai, je ferai, je serai, je viendrai, il y aura, ce sera); dans + tiempo; prochain; le rendez-vous. Cultura: el apéro.","emoji":"🎉","objective_es":"Puedes invitar a alguien, aceptar o rechazar con cortesía, proponer otro día y contar tus planes en futuro.","grammar":{"title":"Ça te dit de…? · el futur simple","explanation":"Para invitar a un amigo: ça te dit de + infinitivo (ça te dit d'aller…? delante de vocal). Para hablar del futuro hay dos formas: el futuro próximo (je vais partir, on va visiter), más inmediato y muy oral, y el futur simple, para planes y predicciones. Los irregulares más usados son j'irai (aller), je ferai (faire), je serai (être), je viendrai (venir), il y aura (il y a) y ce sera (c'est). Todos terminan en -ai en la persona je, que suena como una é cerrada. Dans + tiempo dice cuándo pasa algo a partir de ahora: dans deux jours, dentro de dos días.","examples":[{"target":"Samedi, j'irai à la plage.","base":"El sábado voy a ir a la playa."},{"target":"Je vais partir maintenant.","base":"Ya me voy."},{"target":"Il y aura de la musique et ce sera sympa.","base":"Va a haber música y va a estar buenísimo."}]},"review_status":"draft"},{"id":"fr-a2-u07","language_code":"fr","level":"A2","position":7,"title_es":"Trabajo y estudios","title_en":"Travail et études","description_es":"Devoir, pouvoir, vouloir + infinitivo e il faut; depuis + presente frente a il y a y pendant; d'abord, ensuite, enfin, parce que; la entrevista, la pasantía, el CV. Falsos amigos: le stage, réussir un examen.","emoji":"🎓","objective_es":"Puedes decir lo que tienes que hacer, lo que puedes y lo que quieres, contar desde cuándo trabajas o estudias y hablar de una entrevista, una pasantía o un examen.","grammar":{"title":"Devoir, pouvoir, vouloir + infinitivo · depuis","explanation":"Je dois (tengo que), je peux (puedo) y je veux (quiero) van seguidos de un infinitivo: je dois travailler, je peux venir. Con tu, las formas son iguales: tu dois, tu peux, tu veux. Il faut + infinitivo es la obligación general (hay que): il faut envoyer un CV; il faut + sustantivo, lo que hace falta: il faut un diplôme. Para algo que empezó y sigue, el francés usa el presente con depuis: je travaille ici depuis deux ans (trabajo aquí desde hace dos años). Para algo terminado, passé composé con il y a (hace) o pendant (durante).","examples":[{"target":"Je dois travailler samedi.","base":"Tengo que trabajar el sábado."},{"target":"Il faut envoyer ton CV.","base":"Hay que mandar tu currículum."},{"target":"Je travaille ici depuis deux ans.","base":"Trabajo aquí desde hace dos años."}]},"review_status":"draft"},{"id":"fr-a2-u08","language_code":"fr","level":"A2","position":8,"title_es":"Salud y bienestar","title_en":"La santé","description_es":"Avoir mal à con contracción (à la tête, au dos, aux dents); je me sens bien / mal; en la consulta y en la farmacia (vous avez mal où?, depuis quand?); el imperativo con vous (reposez-vous, buvez de l'eau). Géneros distintos: le dos, la dent.","emoji":"🩺","objective_es":"Puedes decir qué te duele y cómo te sientes, explicarle al médico desde cuándo estás mal y entender y dar consejos de salud.","grammar":{"title":"Avoir mal à · el imperativo con vous","explanation":"Para decir qué te duele: avoir mal à + parte del cuerpo con artículo, y à se contrae con le y les: à + le = au (j'ai mal au dos), à + les = aux (j'ai mal aux dents); con la no cambia (à la tête, à la gorge). Ojo con los géneros: le dos (la espalda) es masculino y la dent (el diente), femenino. Para aconsejar con vous se usa el imperativo, que es la forma de vous sin el pronombre: prenez, buvez; en negativo, ne mangez pas trop. Con un verbo pronominal, el pronombre va después, con guion: reposez-vous.","examples":[{"target":"J'ai mal au dos.","base":"Me duele la espalda."},{"target":"Elle a mal aux dents.","base":"A ella le duelen los dientes."},{"target":"Reposez-vous et buvez de l'eau.","base":"Descanse y tome agua."}]},"review_status":"draft"},{"id":"fr-a2-u09","language_code":"fr","level":"A2","position":9,"title_es":"Compras y servicios","title_en":"Les achats","description_es":"La ropa, el talle y el número; comparar con plus, moins, aussi… que, meilleur y le plus; el pronombre en con cantidades; pagar. Falsos amigos: la robe, les soldes.","emoji":"👗","objective_es":"Puedes comprar ropa y zapatos: pedir tu talle y tu número, probarte algo, comparar precios y calidad, decir cuántos te llevas y pagar.","grammar":{"title":"Comparar · meilleur · el pronombre en","explanation":"Para comparar: plus / moins / aussi + adjetivo + que (en francés siempre que, también con aussi: nunca «comme»). El adjetivo concuerda: la robe est plus chère que la veste. Bon tiene una forma propia: meilleur (meilleure en femenino), nunca «plus bon». El superlativo lleva artículo: la veste la plus chère du magasin, la meilleure boulangerie de la ville. Para no repetir el sustantivo con una cantidad se usa en, delante del verbo: des chemises? J'en prends deux.","examples":[{"target":"La veste est plus chère que la chemise.","base":"La chaqueta es más cara que la camisa."},{"target":"C'est la meilleure boulangerie de la ville.","base":"Es la mejor panadería de la ciudad."},{"target":"Des chemises? J'en prends deux.","base":"¿Camisas? Me llevo dos."}]},"review_status":"draft"},{"id":"fr-a2-u10","language_code":"fr","level":"A2","position":10,"title_es":"Tecnología y comunicación","title_en":"La technologie","description_es":"La computadora, el celular y las apps; envoyer, recevoir, appeler; los pronombres le, la, l', les y lui, leur antes del verbo. Falso amigo: marcher (funcionar).","emoji":"💻","objective_es":"Puedes hablar de tu computadora y tu celular, decir que algo no funciona, mandar y recibir mensajes y mails, y decir a quién llamas, ves, escribes o hablas sin repetir su nombre.","grammar":{"title":"Pronombres le, la, l', les · lui, leur","explanation":"Para no repetir una persona o una cosa, el francés usa pronombres que van siempre delante del verbo. Objeto directo (verbos sin à, como appeler o voir): le, la (l' delante de vocal) y les: Paul? Je l'appelle. Objeto indirecto (verbos con à, como parler à, écrire à, envoyer à, téléphoner à): lui (a él o a ella) y leur (a ellos o a ellas, sin s): ma sœur? Je lui écris. En la negación el pronombre queda pegado al verbo: je ne l'appelle pas. Con un infinitivo va delante del infinitivo, nunca al final como en español: je vais l'appeler (voy a llamarlo).","examples":[{"target":"Paul? Je l'appelle ce soir.","base":"¿Paul? Lo llamo esta noche."},{"target":"Mes parents? Je les vois le dimanche.","base":"¿Mis padres? Los veo los domingos."},{"target":"Ma sœur? Je lui écris un mail.","base":"¿Mi hermana? Le escribo un mail."}]},"review_status":"draft"},{"id":"fr-a2-u11","language_code":"fr","level":"A2","position":11,"title_es":"Relaciones y vida cotidiana","title_en":"Les relations","description_es":"Pronominales en passé composé (je me suis levée, on s'est rencontrés), recíprocos, el pronombre y (j'y vais), qui / que y la negación ampliada (ne… jamais, plus, rien, personne).","emoji":"🤝","objective_es":"Puedes contar tu rutina y lo que hiciste con verbos pronominales, hablar de tus relaciones (cómo se conocieron, si se llevan bien), usar y para un lugar, unir frases con qui y que y negar con ne… jamais, ne… plus, ne… rien y ne… personne.","grammar":{"title":"Pronominales con être · y · qui / que · ne… jamais","explanation":"Los verbos pronominales (se lever, se réveiller, se marier, se disputer) forman el passé composé con être, y el participio concuerda con el sujeto: je me suis levé, una mujer escribe je me suis levée y en plural ils se sont mariés (suena igual). Con on = nosotros se suele concordar en plural: on s'est rencontrés. El pronombre y reemplaza un lugar ya nombrado y va antes del verbo: Tu vas à Lyon? — Oui, j'y vais. Qui es el sujeto del verbo que sigue (le copain qui habite à Nice) y que, el objeto (le film que j'ai vu). Como ne… pas, las negaciones ne… jamais (nunca), ne… plus (ya no), ne… rien (nada) y ne… personne (nadie) rodean al verbo: je ne bois jamais de café.","examples":[{"target":"Hier, je me suis levée tard.","base":"Ayer me levanté tarde."},{"target":"Tu vas à Lyon? — Oui, j'y vais demain.","base":"¿Vas a Lyon? — Sí, voy mañana."},{"target":"C'est le copain qui habite à Nice.","base":"Es el amigo que vive en Niza."}]},"review_status":"draft"},{"id":"fr-a2-u12","language_code":"fr","level":"A2","position":12,"title_es":"Opiniones, problemas y soluciones","title_en":"Opinions et problèmes","description_es":"Dar la opinión (à mon avis, je pense que, je suis d'accord), aconsejar con el condicional (tu devrais, on pourrait), si + presente → futuro, reclamar (ça ne marche pas) y discurso indirecto (il dit que). Donc, pourtant, enfin.","emoji":"💬","objective_es":"Puedes dar tu opinión y decir si estás de acuerdo, aconsejar y proponer soluciones, hablar de lo que vas a hacer según el clima, reclamar en un negocio cuando algo no funciona y contar lo que te dijo otra persona.","grammar":{"title":"Condicional para aconsejar · si + presente · il dit que","explanation":"Para aconsejar o proponer se usa el condicional: tu devrais + infinitivo (deberías), on pourrait + infinitivo (podríamos), j'aimerais (me gustaría); la terminación -ais / -ait suena como la è de mère. Para una hipótesis sobre el futuro: si + presente y después futuro: S'il pleut, on restera à la maison (nunca futuro después de si). Si se elide sólo delante de il / ils: s'il, pero si elle. Para contar lo que dijo otro: il dit que + presente; en pasado, elle m'a dit que y el presente pasa a imperfecto: «C'est fermé» → Elle m'a dit que c'était fermé. Ojo: tener razón es avoir raison: tu as raison.","examples":[{"target":"Tu es fatigué? Tu devrais dormir.","base":"¿Estás cansado? Deberías dormir."},{"target":"S'il pleut, on restera à la maison.","base":"Si llueve, nos vamos a quedar en casa."},{"target":"Elle m'a dit que c'était fermé.","base":"Me dijo que estaba cerrado."}]},"review_status":"draft"},{"id":"fr-a2-u13","language_code":"fr","level":"A2","position":13,"title_es":"Moi, toi y el imperativo","title_en":"Moi, toi et l'impératif","description_es":"Los pronombres tónicos (moi, toi, eux…), después de avec, pour, sans y chez, y para responder (c'est moi, moi aussi, moi non plus). El imperativo con tu y nous (regarde, prends, allons-y) y con pronombres (dépêche-toi, aide-moi).","emoji":"👉","objective_es":"Puedes remarcar de quién hablas (moi, je…; lui, il…), usar los pronombres después de una preposición (avec moi, chez toi, sans eux), estar de acuerdo con moi aussi y moi non plus, y dar indicaciones o consejos a un amigo con el imperativo de tu y de nous, en afirmativo y en negativo (regarde, allons-y, n'oublie pas, dépêche-toi).","grammar":{"title":"Pronombres tónicos · imperativo con tu y nous","explanation":"Los pronombres tónicos son moi, toi, lui, elle, nous, vous, eux y elles. No reemplazan al sujeto (je, tu, il, ils…), lo acompañan: moi, je préfère le thé. Se usan después de una preposición (avec moi, pour toi, sans eux, chez moi = en mi casa), solos para responder (c'est moi, moi aussi, moi non plus) y después de c'est. El imperativo es el presente sin el sujeto: tu prends → prends, nous allons → allons. En los verbos en -er (y en aller) la s de tu se cae: tu regardes → regarde, tu vas → va, salvo delante de y: vas-y. Être, avoir y savoir son irregulares: sois, aie, sache. En afirmativo el pronombre va después, con guion, y me o te pasan a moi o toi: dépêche-toi, aide-moi. En negativo vuelve adelante: ne te dépêche pas.","examples":[{"target":"Moi, je préfère le cinéma. Et toi?","base":"Yo prefiero el cine. ¿Y tú?"},{"target":"Tu viens chez moi samedi?","base":"¿Vienes a mi casa el sábado?"},{"target":"Dépêche-toi, on est en retard! — Ne t'inquiète pas.","base":"¡Apúrate, llegamos tarde! — No te preocupes."}]},"review_status":"draft"}],"lessons":[{"id":"a1-u01-l01","unit_id":"a1-u01","position":1,"title_es":"Hola y adiós","objective_es":"Saludar y despedirte; decir sí y no.","intro":{"explanation":"Hello y hi son «hola»; hi es más informal. Para despedirte: goodbye o, más informal, bye.","examples":[{"target":"Hello, Ana!","base":"¡Hola, Ana!"},{"target":"Bye, Mom!","base":"¡Chao, mamá!"},{"target":"No, thank you.","base":"No, gracias."}]},"takeaways":["Saludas con hello o hi.","Te despides con goodbye o bye.","Dices yes y no."]},{"id":"a1-u01-l02","unit_id":"a1-u01","position":2,"title_es":"Momentos del día","objective_es":"Saludar según la hora del día.","intro":{"explanation":"Good morning es para la mañana, good afternoon para la tarde y good evening para saludar a la noche. Good night es sólo para despedirte o irte a dormir.","examples":[{"target":"Good morning, everyone!","base":"¡Buenos días a todos!"},{"target":"Good evening! Welcome.","base":"¡Buenas noches! Bienvenidos."},{"target":"Good night! See you tomorrow.","base":"¡Buenas noches! Hasta mañana."}]},"takeaways":["Saludas con good morning, good afternoon o good evening según la hora.","Usas good night sólo para despedirte."]},{"id":"a1-u01-rev1","unit_id":"a1-u01","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Hola y adiós» y «Momentos del día».","intro":null,"takeaways":[]},{"id":"a1-u01-l03","unit_id":"a1-u01","position":4,"title_es":"Cortesía","objective_es":"Pedir por favor, agradecer y disculparte.","intro":{"explanation":"Please es «por favor» y thank you, «gracias»; se responde you're welcome. Sorry es para pedir perdón y excuse me, para llamar la atención de alguien.","examples":[{"target":"Water, please.","base":"Agua, por favor."},{"target":"Thank you! — You're welcome.","base":"¡Gracias! — De nada."},{"target":"Excuse me, please.","base":"Disculpe, por favor."}]},"takeaways":["Pides algo con please y agradeces con thank you.","Respondes you're welcome.","Te disculpas con sorry o excuse me."]},{"id":"a1-u01-l04","unit_id":"a1-u01","position":5,"title_es":"Presentarte","objective_es":"Decir tu nombre y saludar a alguien nuevo.","intro":{"explanation":"Para presentarte: my name is + tu nombre. Al conocer a alguien se dice nice to meet you, y se responde nice to meet you too.","examples":[{"target":"My name is Tom.","base":"Mi nombre es Tom."},{"target":"Nice to meet you.","base":"Encantado de conocerte."},{"target":"Nice to meet you too.","base":"Igualmente."}]},"takeaways":["Te presentas con my name is + tu nombre.","Respondes nice to meet you too."]},{"id":"a1-u01-l05","unit_id":"a1-u01","position":7,"title_es":"¿Cómo estás?","objective_es":"Preguntar y responder cómo está alguien.","intro":{"explanation":"How are you? es «¿cómo estás?». Se responde I'm fine o I'm good, y se devuelve la pregunta con and you?","examples":[{"target":"How are you?","base":"¿Cómo estás?"},{"target":"I'm fine, thank you. And you?","base":"Estoy bien, gracias. ¿Y tú?"}]},"takeaways":["Preguntas how are you? y respondes I'm fine.","Devuelves la pregunta con and you?"]},{"id":"a1-u02-l01","unit_id":"a1-u02","position":1,"title_es":"Yo, tú, él, ella","objective_es":"Usar los pronombres I, you, he y she.","intro":{"explanation":"I es «yo» y siempre va con mayúscula. You sirve para tú, vos y usted. He es «él» y she, «ella».","examples":[{"target":"I am Ana.","base":"Yo soy Ana."},{"target":"She is my friend.","base":"Ella es mi amiga."}]},"takeaways":["Usas I, you, he y she.","Escribes I siempre con mayúscula."]},{"id":"a1-u02-l02","unit_id":"a1-u02","position":2,"title_es":"Nosotros, ellos y cosas","objective_es":"Usar we, they e it.","intro":{"explanation":"We es «nosotros» y they, «ellos» o «ellas». Para una cosa o un animal se usa it, que en español no se dice.","examples":[{"target":"We are friends.","base":"Somos amigos."},{"target":"It is a cat.","base":"Es un gato."}]},"takeaways":["Usas we y they para varias personas.","Usas it para cosas y animales."]},{"id":"a1-u02-rev1","unit_id":"a1-u02","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Yo, tú, él, ella» y «Nosotros, ellos y cosas».","intro":null,"takeaways":[]},{"id":"a1-u02-l03","unit_id":"a1-u02","position":4,"title_es":"I am, you are","objective_es":"Decir cómo estás con am y are.","intro":{"explanation":"Con I va am (I am) y con you, are (you are). Al hablar se contraen: I’m, you’re. To be sirve tanto para «ser» como para «estar».","examples":[{"target":"I am happy.","base":"Estoy feliz."},{"target":"You're tired.","base":"Estás cansado."}]},"takeaways":["Usas I am y you are.","Sabes que to be es «ser» y «estar»."]},{"id":"a1-u02-l04","unit_id":"a1-u02","position":5,"title_es":"He is, she is","objective_es":"Hablar de otras personas con is.","intro":{"explanation":"Con he, she e it el verbo es is: he is, she is, it is. Al hablar se contrae: he’s, she’s.","examples":[{"target":"He is a teacher.","base":"Él es profesor."},{"target":"She's my friend.","base":"Ella es mi amiga."}]},"takeaways":["Usas is con he, she e it.","Presentas a otra persona con he is o she is."]},{"id":"a1-u02-l05","unit_id":"a1-u02","position":7,"title_es":"Negar y preguntar","objective_es":"Formar oraciones negativas y preguntas con to be.","intro":{"explanation":"Para negar, not va después de to be: I am not, she is not (isn’t). Para preguntar, el verbo va primero: Are you tired?","examples":[{"target":"I'm not tired.","base":"No estoy cansado."},{"target":"Is she a student?","base":"¿Ella es estudiante?"}]},"takeaways":["Niegas con not después de am, is o are.","Preguntas poniendo el verbo primero: Are you…?"]},{"id":"a1-u03-l01","unit_id":"a1-u03","position":1,"title_es":"Del 1 al 5","objective_es":"Contar del uno al cinco.","intro":{"explanation":"One, two, three, four, five. Three empieza con th: la lengua va entre los dientes.","examples":[{"target":"One, two, three.","base":"Uno, dos, tres."},{"target":"Two coffees, please.","base":"Dos cafés, por favor."}]},"takeaways":["Cuentas del uno al cinco.","Pronuncias three con la lengua entre los dientes."]},{"id":"a1-u03-l02","unit_id":"a1-u03","position":2,"title_es":"Del 6 al 10","objective_es":"Contar del seis al diez.","intro":{"explanation":"Six, seven, eight, nine, ten. Eight se escribe con gh, pero suena «éit».","examples":[{"target":"Seven days.","base":"Siete días."},{"target":"Ten dollars.","base":"Diez dólares."}]},"takeaways":["Cuentas del seis al diez.","Escribes eight con gh."]},{"id":"a1-u03-l03","unit_id":"a1-u03","position":4,"title_es":"Hasta veinte","objective_es":"Usar números más grandes: 11, 12, 15 y 20.","intro":{"explanation":"Eleven y twelve son especiales. Del 13 al 19 terminan en -teen: fifteen. Twenty es veinte. Ojo: fifteen (15) y fifty (50) suenan parecido.","examples":[{"target":"I have twelve friends.","base":"Tengo doce amigos."},{"target":"Fifteen dollars.","base":"Quince dólares."}]},"takeaways":["Dices 11, 12, 15 y 20.","Reconoces la terminación -teen."]},{"id":"a1-u03-l04","unit_id":"a1-u03","position":5,"title_es":"¿Cuántos años tienes?","objective_es":"Preguntar y decir la edad.","intro":{"explanation":"Para la edad se usa to be, no have: I am ten (years old). Se pregunta How old are you? Decir «I have ten years» es un error típico.","examples":[{"target":"How old are you?","base":"¿Cuántos años tienes?"},{"target":"I'm twelve years old.","base":"Tengo doce años."}]},"takeaways":["Preguntas la edad con How old are you?","Respondes con I am + edad, sin have."]},{"id":"a1-u03-rev2","unit_id":"a1-u03","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Hasta veinte» y «¿Cuántos años tienes?».","intro":null,"takeaways":[]},{"id":"a1-u03-l05","unit_id":"a1-u03","position":7,"title_es":"¿De dónde eres?","objective_es":"Decir de qué país eres.","intro":{"explanation":"Where are you from? es «¿de dónde eres?». Se responde I am from + país. Los países van con mayúscula y algunos con the: the United States.","examples":[{"target":"Where are you from?","base":"¿De dónde eres?"},{"target":"I'm from Mexico.","base":"Soy de México."},{"target":"She is from the United States.","base":"Ella es de Estados Unidos."}]},"takeaways":["Preguntas el origen con Where are you from?","Respondes con I am from + país."]},{"id":"a1-u04-l01","unit_id":"a1-u04","position":1,"title_es":"Mi familia","objective_es":"Nombrar a la familia cercana.","intro":{"explanation":"Mother y father son madre y padre; parents, los dos. Ojo: parents no son los parientes, son tus padres.","examples":[{"target":"My family is small.","base":"Mi familia es chica."},{"target":"My parents are from Spain.","base":"Mis padres son de España."}]},"takeaways":["Nombras a tu madre, tu padre y tus padres.","Sabes que parents son tus padres."]},{"id":"a1-u04-l02","unit_id":"a1-u04","position":2,"title_es":"Hermanos y abuelos","objective_es":"Hablar de hermanos, abuelos y bebés.","intro":{"explanation":"Brother y sister son hermano y hermana. Grandmother y grandfather, los abuelos.","examples":[{"target":"I have a brother.","base":"Tengo un hermano."},{"target":"My grandmother is happy.","base":"Mi abuela está feliz."}]},"takeaways":["Nombras a tus hermanos y abuelos.","Dices cómo está un familiar con is."]},{"id":"a1-u04-l03","unit_id":"a1-u04","position":4,"title_es":"Personas","objective_es":"Hombre, mujer, chico, chica y preguntar quién es alguien.","intro":{"explanation":"Man y woman son hombre y mujer; boy y girl, chico y chica. Para preguntar quién es alguien: Who is he?","examples":[{"target":"Who is she?","base":"¿Quién es ella?"},{"target":"He is a boy.","base":"Él es un chico."}]},"takeaways":["Nombras a las personas: man, woman, boy, girl.","Preguntas quién es alguien con Who is…?"]},{"id":"a1-u04-l04","unit_id":"a1-u04","position":5,"title_es":"Su, nuestro y su de ellos","objective_es":"Usar his, her, our y their.","intro":{"explanation":"En inglés «su» cambia según el dueño: his (de él), her (de ella), their (de ellos). Our es «nuestro» o «nuestra».","examples":[{"target":"His name is Tom.","base":"Su nombre (de él) es Tom."},{"target":"Our mother is a teacher.","base":"Nuestra madre es profesora."}]},"takeaways":["Eliges his o her según quién es el dueño.","Usas our y their."]},{"id":"a1-u04-l05","unit_id":"a1-u04","position":7,"title_es":"Tengo dos hermanas","objective_es":"Usar have y has para hablar de tu familia.","intro":{"explanation":"Tener es have con I, you, we y they, y has con he, she e it: I have, she has.","examples":[{"target":"I have two sisters.","base":"Tengo dos hermanas."},{"target":"She has a brother.","base":"Ella tiene un hermano."}]},"takeaways":["Usas have y has según la persona.","Dices cuántos familiares tienes."]},{"id":"a1-u06-l01","unit_id":"a1-u06","position":1,"title_es":"Mi casa","objective_es":"Casa, apartamento, puerta, ventana y jardín.","intro":null,"takeaways":[]},{"id":"a1-u07-l03","unit_id":"a1-u07","position":4,"title_es":"Comer y beber","objective_es":"Decir qué comes y qué tomas.","intro":null,"takeaways":[]},{"id":"a1-u07-l04","unit_id":"a1-u07","position":5,"title_es":"Quiero un café","objective_es":"Pedir lo que quieres con want y please.","intro":null,"takeaways":[]},{"id":"a1-u07-l05","unit_id":"a1-u07","position":7,"title_es":"Comidas del día","objective_es":"Desayuno, almuerzo, cena y decir si tienes hambre o sed.","intro":null,"takeaways":[]},{"id":"a1-u08-l05","unit_id":"a1-u08","position":7,"title_es":"¿Trabajas? Siempre, normalmente, nunca","objective_es":"Preguntar con do/does y decir con qué frecuencia.","intro":null,"takeaways":[]},{"id":"a1-u10-l03","unit_id":"a1-u10","position":4,"title_es":"Viajar por la ciudad","objective_es":"Estación, hotel y autobús.","intro":null,"takeaways":[]},{"id":"a1-u10-l05","unit_id":"a1-u10","position":7,"title_es":"Dobla a la izquierda","objective_es":"Dar indicaciones: left, right, turn y straight on.","intro":null,"takeaways":[]},{"id":"a1-u11-l04","unit_id":"a1-u11","position":5,"title_es":"Sé nadar","objective_es":"Decir lo que sabes o puedes hacer con can.","intro":null,"takeaways":[]},{"id":"a2-u04-l02","unit_id":"a2-u04","position":2,"title_es":"En el aeropuerto","objective_es":"Pasaporte, maleta y vuelo.","intro":null,"takeaways":[]},{"id":"a2-u06-l02","unit_id":"a2-u06","position":2,"title_es":"¿Qué tienes puesto?","objective_es":"Wear: usar ropa siempre o tenerla puesta ahora.","intro":null,"takeaways":[]},{"id":"a2-u06-rev1","unit_id":"a2-u06","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «La ropa» y «¿Qué tienes puesto?».","intro":null,"takeaways":[]},{"id":"a2-u06-l03","unit_id":"a2-u06","position":4,"title_es":"En el negocio","objective_es":"Pedir una talla y probarte ropa.","intro":null,"takeaways":[]},{"id":"a2-u11-l02","unit_id":"a2-u11","position":2,"title_es":"Frío y calor","objective_es":"La temperatura y cómo te sientes.","intro":null,"takeaways":[]},{"id":"it-a1-u01-l01","unit_id":"it-a1-u01","position":1,"title_es":"Ciao y arrivederci","objective_es":"Saludar y despedirte; decir sí y no.","intro":{"explanation":"Ciao sirve para saludar y para despedirte entre amigos. Con alguien que no conoces, para despedirte usa arrivederci.","examples":[{"target":"Ciao, Marco!","base":"¡Hola, Marco!"},{"target":"Arrivederci, signora!","base":"¡Adiós, señora!"},{"target":"Ciao, a presto!","base":"¡Chao, hasta pronto!"}]},"takeaways":["Saludas y te despides con ciao.","Te despides con arrivederci de alguien que no conoces.","Dices sì (con tilde) y no."]},{"id":"it-a1-u01-l02","unit_id":"it-a1-u01","position":2,"title_es":"Buongiorno y buonasera","objective_es":"Saludar según el momento del día.","intro":{"explanation":"Buongiorno se dice a la mañana y hasta media tarde. Desde la tarde se saluda con buonasera. Buonanotte es sólo para despedirte a la noche o antes de dormir.","examples":[{"target":"Buongiorno, professore!","base":"¡Buenos días, profesor!"},{"target":"Buonasera, signora Rossi.","base":"Buenas tardes, señora Rossi."},{"target":"Buonanotte, mamma!","base":"¡Buenas noches, mamá!","note":"al irte a dormir"}]},"takeaways":["Saludas con buongiorno a la mañana y con buonasera desde la tarde.","Usas buonanotte sólo para despedirte a la noche."]},{"id":"it-a1-u01-l03","unit_id":"it-a1-u01","position":4,"title_es":"Per favore y grazie","objective_es":"Pedir por favor, agradecer y disculparte.","intro":{"explanation":"Grazie es gracias y prego, de nada. Scusa sirve para pedir perdón o llamar la atención de alguien de confianza.","examples":[{"target":"Un caffè, per favore.","base":"Un café, por favor."},{"target":"Grazie! — Prego.","base":"¡Gracias! — De nada."},{"target":"Scusa, Marta!","base":"¡Perdón, Marta!"}]},"takeaways":["Pides algo con per favore.","Agradeces con grazie y respondes prego.","Te disculpas con scusa."]},{"id":"it-a1-u01-l04","unit_id":"it-a1-u01","position":5,"title_es":"Mi chiamo…","objective_es":"Decir tu nombre y preguntar el de otra persona.","intro":{"explanation":"Mi chiamo + nombre es «me llamo». Para preguntar: come ti chiami? Al conocer a alguien se responde piacere.","examples":[{"target":"Mi chiamo Giulia.","base":"Me llamo Giulia."},{"target":"Ciao! Come ti chiami?","base":"¡Hola! ¿Cómo te llamas?"},{"target":"Piacere!","base":"¡Mucho gusto!"}]},"takeaways":["Te presentas con mi chiamo + tu nombre.","Preguntas el nombre con come ti chiami?","Al conocer a alguien dices piacere."]},{"id":"it-a1-u01-l05","unit_id":"it-a1-u01","position":7,"title_es":"Come stai?","objective_es":"Preguntar y responder cómo está alguien.","intro":{"explanation":"Come stai? es «¿cómo estás?» entre personas de confianza. Se responde bene (bien) o molto bene (muy bien), y se devuelve la pregunta con e tu?","examples":[{"target":"Ciao, Anna! Come stai?","base":"¡Hola, Anna! ¿Cómo estás?"},{"target":"Bene, grazie. E tu?","base":"Bien, gracias. ¿Y tú?"},{"target":"Anch’io sto bene.","base":"Yo también estoy bien."}]},"takeaways":["Preguntas come stai? y respondes bene o molto bene.","Devuelves la pregunta con e tu?","Dices «también» con anche."]},{"id":"it-a1-u02-l01","unit_id":"it-a1-u02","position":1,"title_es":"Io sono…","objective_es":"Decir quién eres con sono.","intro":{"explanation":"Sono es «soy». En italiano el pronombre io casi siempre se omite, igual que en español: sono Marco. Studente es para un varón y studentessa, para una mujer.","examples":[{"target":"Sono Marco.","base":"Soy Marco."},{"target":"Sono una studentessa.","base":"Soy estudiante.","note":"lo dice una mujer"}]},"takeaways":["Dices quién eres con sono.","Usas studente o studentessa según quién habla."]},{"id":"it-a1-u02-l02","unit_id":"it-a1-u02","position":2,"title_es":"Tu sei, lui è","objective_es":"Hablar de ti y de otras personas con sei y è.","intro":{"explanation":"Tu sei es «tú eres» y lui è / lei è, «él es / ella es». Ojo: è con tilde es «es»; sin tilde, e significa «y».","examples":[{"target":"Tu sei Luca?","base":"¿Tú eres Luca?"},{"target":"Lui è Paolo.","base":"Él es Paolo."},{"target":"Lei è la mia amica.","base":"Ella es mi amiga."}]},"takeaways":["Usas sei con tu y è con lui o lei.","Distingues è (es) de e (y)."]},{"id":"it-a1-u02-l03","unit_id":"it-a1-u02","position":4,"title_es":"Non sono…","objective_es":"Negar y preguntar con essere.","intro":{"explanation":"Para negar, non va antes del verbo: non sono, non è. Una pregunta de sí o no es la misma oración con entonación de pregunta: Sei italiano?","examples":[{"target":"Sei italiano? — No, non sono italiano.","base":"¿Eres italiano? — No, no soy italiano."},{"target":"Lui non è un amico.","base":"Él no es un amigo."}]},"takeaways":["Niegas con non antes del verbo.","Preguntas con la misma oración y entonación de pregunta."]},{"id":"it-a1-u02-l04","unit_id":"it-a1-u02","position":5,"title_es":"Nacionalidades","objective_es":"Decir tu nacionalidad con la terminación correcta.","intro":{"explanation":"Muchas nacionalidades terminan en -o para un varón y en -a para una mujer: italiano / italiana, argentino / argentina. Español es spagnolo y mexicano, messicano.","examples":[{"target":"Sono argentina.","base":"Soy argentina."},{"target":"Pablo è spagnolo.","base":"Pablo es español."},{"target":"Carlos è messicano.","base":"Carlos es mexicano."}]},"takeaways":["Dices tu nacionalidad con sono + nacionalidad.","Cambias -o por -a si hablas de una mujer."]},{"id":"it-a1-u02-l05","unit_id":"it-a1-u02","position":7,"title_es":"Di dove sei?","objective_es":"Preguntar y decir de dónde eres.","intro":{"explanation":"Di dove sei? es «¿de dónde eres?». Se responde sono di + ciudad: sono di Roma, sono di Buenos Aires.","examples":[{"target":"Di dove sei?","base":"¿De dónde eres?"},{"target":"Sono di Buenos Aires.","base":"Soy de Buenos Aires."},{"target":"Anche lei è di Roma.","base":"Ella también es de Roma."}]},"takeaways":["Preguntas de dónde es alguien con di dove sei?","Respondes con sono di + ciudad."]},{"id":"it-a1-u02-final","unit_id":"it-a1-u02","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Quién eres y de dónde eres?».","intro":null,"takeaways":[]},{"id":"it-a1-u03-l01","unit_id":"it-a1-u03","position":1,"title_es":"Da uno a cinque","objective_es":"Contar del uno al cinco.","intro":{"explanation":"Los primeros números se parecen al español, pero se pronuncian distinto: due (dos), tre (tres), quattro con doble t y cinque, que suena «chínkue».","examples":[{"target":"Uno, due, tre.","base":"Uno, dos, tres."},{"target":"Due caffè, per favore.","base":"Dos cafés, por favor."}]},"takeaways":["Cuentas del uno al cinco.","Pides dos o tres cosas con un número."]},{"id":"it-a1-u03-l02","unit_id":"it-a1-u03","position":2,"title_es":"Da sei a dieci","objective_es":"Contar del seis al diez.","intro":{"explanation":"Sei (seis) es igual a sei (eres) de la unidad anterior: el contexto los distingue. Sette, otto y dieci llevan doble consonante o «ci», que suena «chi».","examples":[{"target":"Sei, sette, otto.","base":"Seis, siete, ocho."},{"target":"Dieci euro.","base":"Diez euros."}]},"takeaways":["Cuentas del seis al diez.","Sabes que sei puede ser «seis» o «eres»."]},{"id":"it-a1-u03-l03","unit_id":"it-a1-u03","position":4,"title_es":"Fino a venti","objective_es":"Usar números más grandes: 15, 18 y 20.","intro":{"explanation":"Quindici es quince y venti, veinte. Diciotto (dieciocho) se arma como «diez-ocho». Son los números que más vas a usar para la edad.","examples":[{"target":"Ho quindici anni.","base":"Tengo quince años."},{"target":"Lei ha diciotto anni.","base":"Ella tiene dieciocho años."}]},"takeaways":["Dices 15, 18 y 20.","Reconoces los números de oído."]},{"id":"it-a1-u03-l04","unit_id":"it-a1-u03","position":5,"title_es":"Quanti anni hai?","objective_es":"Preguntar y decir la edad.","intro":{"explanation":"La edad se dice con avere (tener): ho (tengo), hai (tienes), ha (tiene) + número + anni. La h de ho, hai y ha no se pronuncia.","examples":[{"target":"Quanti anni hai?","base":"¿Cuántos años tienes?"},{"target":"Ho venti anni.","base":"Tengo veinte años."},{"target":"Marco ha dieci anni.","base":"Marco tiene diez años."}]},"takeaways":["Preguntas la edad con quanti anni hai?","Respondes con ho + número + anni."]},{"id":"it-a1-u03-l05","unit_id":"it-a1-u03","position":7,"title_es":"Presentarte completo","objective_es":"Decir tu nombre, de dónde eres y cuántos años tienes.","intro":{"explanation":"Ya puedes presentarte entero: mi chiamo + nombre, sono di + ciudad y ho + edad. Recuerda: la edad va con ho, el origen con sono.","examples":[{"target":"Mi chiamo Ana, sono di Rosario e ho vent’anni.","base":"Me llamo Ana, soy de Rosario y tengo veinte años."},{"target":"Lui è Paolo e ha otto anni.","base":"Él es Paolo y tiene ocho años."}]},"takeaways":["Te presentas con nombre, origen y edad.","Usas sono para el origen y ho para la edad."]},{"id":"it-a1-u04-l01","unit_id":"it-a1-u04","position":1,"title_es":"Madre e padre","objective_es":"Nombrar a tu familia cercana.","intro":{"explanation":"Madre y padre se escriben igual que en español. Ojo: genitori significa «padres» (mamá y papá); parenti, en cambio, son los parientes.","examples":[{"target":"La mia famiglia è piccola.","base":"Mi familia es chica."},{"target":"I miei genitori sono di Roma.","base":"Mis padres son de Roma."}]},"takeaways":["Nombras a tu madre, tu padre y tus padres.","Sabes que genitori son tus padres."]},{"id":"it-a1-u04-l02","unit_id":"it-a1-u04","position":2,"title_es":"Fratelli e sorelle","objective_es":"Hablar de tus hermanos.","intro":{"explanation":"Fratello es hermano y sorella, hermana. Con ho (tengo) dices cuántos tienes: ho un fratello, ho due sorelle. Si no tienes hermanos: sono figlio unico (o figlia unica).","examples":[{"target":"Ho un fratello e una sorella.","base":"Tengo un hermano y una hermana."},{"target":"Sono figlia unica.","base":"Soy hija única."}]},"takeaways":["Dices cuántos hermanos tienes con ho.","Dices que eres hijo único con figlio unico."]},{"id":"it-a1-u04-l03","unit_id":"it-a1-u04","position":4,"title_es":"Nonni e figli","objective_es":"Hablar de abuelos e hijos.","intro":{"explanation":"Nonno y nonna son los abuelos; figlio y figlia, los hijos. Como en italiano casi todo cambia -o / -a, puedes adivinar muchos femeninos.","examples":[{"target":"Mia nonna è di Napoli.","base":"Mi abuela es de Nápoles."},{"target":"Lei è mia figlia.","base":"Ella es mi hija."}]},"takeaways":["Nombras a tus abuelos y a tus hijos.","Cambias -o por -a para el femenino."]},{"id":"it-a1-u04-l04","unit_id":"it-a1-u04","position":5,"title_es":"Mio, mia","objective_es":"Usar mio y mia con tu familia.","intro":{"explanation":"Mio va con palabras masculinas (mio padre, mio fratello) y mia con femeninas (mia madre, mia sorella). Con un familiar en singular no se usa artículo.","examples":[{"target":"Mio fratello ha dieci anni.","base":"Mi hermano tiene diez años."},{"target":"Mia sorella è una studentessa.","base":"Mi hermana es estudiante."}]},"takeaways":["Eliges mio o mia según la palabra.","No pones artículo con un familiar en singular."]},{"id":"it-a1-u04-l05","unit_id":"it-a1-u04","position":7,"title_es":"Si chiama…","objective_es":"Decir cómo se llaman tus familiares.","intro":{"explanation":"Para decir cómo se llama otra persona: si chiama + nombre. Para preguntar: come si chiama tuo fratello?","examples":[{"target":"Mia madre si chiama Laura.","base":"Mi madre se llama Laura."},{"target":"Come si chiama tuo fratello?","base":"¿Cómo se llama tu hermano?"}]},"takeaways":["Dices cómo se llama alguien con si chiama.","Presentas a tu familia con nombre y edad."]},{"id":"it-a1-u05-l01","unit_id":"it-a1-u05","position":1,"title_es":"Che cos'è?","objective_es":"Preguntar qué es algo y nombrar objetos con il y la.","intro":{"explanation":"Para preguntar qué es algo: che cos'è? Se responde con è + la cosa: è un libro, è la penna. Il va con la mayoría de las palabras masculinas y la con las femeninas.","examples":[{"target":"Che cos'è? È un libro.","base":"¿Qué es? Es un libro."},{"target":"La chiave è qui.","base":"La llave está aquí."}]},"takeaways":["Preguntas qué es algo con che cos'è?","Usas il con masculinos y la con femeninos."]},{"id":"it-a1-u05-l02","unit_id":"it-a1-u05","position":2,"title_es":"Lo zaino, l'orologio","objective_es":"Usar lo y l'.","intro":{"explanation":"Lo va con las palabras masculinas que empiezan con s + consonante o con z: lo zaino. Delante de vocal, il y la se vuelven l': l'orologio, l'amica.","examples":[{"target":"Lo zaino è qui.","base":"La mochila está aquí."},{"target":"L'orologio di Luca.","base":"El reloj de Luca."}]},"takeaways":["Usas lo con las palabras que empiezan con z o s + consonante.","Usas l' ante vocal."]},{"id":"it-a1-u05-l03","unit_id":"it-a1-u05","position":4,"title_es":"I, gli, le","objective_es":"Nombrar objetos en plural.","intro":{"explanation":"En plural: il → i, lo y l' (masculinos) → gli, la y l' (femeninos) → le. Las palabras en -o pasan a -i, las en -a a -e y las en -e a -i: i libri, le penne, le chiavi.","examples":[{"target":"Ho i libri.","base":"Tengo los libros."},{"target":"Le chiavi sono qui.","base":"Las llaves están aquí."}]},"takeaways":["Pasas los artículos al plural: i, gli, le.","Cambias la última letra de la palabra."]},{"id":"it-a1-u05-l04","unit_id":"it-a1-u05","position":5,"title_es":"I colori","objective_es":"Nombrar los colores.","intro":{"explanation":"Los colores van después de la palabra y concuerdan como cualquier adjetivo: rosso con masculinos, rossa con femeninos. Blu no cambia nunca.","examples":[{"target":"Lo zaino è rosso.","base":"La mochila es roja.","note":"zaino es masculino"},{"target":"La penna è nera.","base":"El bolígrafo es negro."}]},"takeaways":["Nombras cinco colores.","Sabes que blu no cambia."]},{"id":"it-a1-u05-l05","unit_id":"it-a1-u05","position":7,"title_es":"Di che colore è?","objective_es":"Preguntar y decir de qué color es algo.","intro":{"explanation":"Para preguntar el color: di che colore è? Ojo con la concordancia: el color sigue a la palabra italiana, aunque en español sea de otro género (lo zaino è nero, «la mochila es negra»).","examples":[{"target":"Di che colore è lo zaino?","base":"¿De qué color es la mochila?"},{"target":"La chiave è gialla.","base":"La llave es amarilla."}]},"takeaways":["Preguntas de qué color es algo.","Haces concordar el color con la palabra."]},{"id":"it-a1-u06-l01","unit_id":"it-a1-u06","position":1,"title_es":"Le stanze","objective_es":"Nombrar las partes de la casa.","intro":{"explanation":"Para decir en qué parte de la casa estás se usa in, sin artículo: in cucina, in bagno, in camera. Ojo: sono también es «estoy» (sono in cucina), y camera es la habitación, no la cámara de fotos.","examples":[{"target":"Sono in cucina.","base":"Estoy en la cocina."},{"target":"Mia madre è in soggiorno.","base":"Mi mamá está en la sala."}]},"takeaways":["Nombras las partes de la casa.","Dices dónde estás con in + habitación."]},{"id":"it-a1-u06-l02","unit_id":"it-a1-u06","position":2,"title_es":"I mobili","objective_es":"Nombrar muebles y partes de una habitación.","intro":{"explanation":"Tavolo es la mesa; sedia, la silla; letto, la cama; divano, el sillón. Finestra (ventana) y porta (puerta) son femeninas.","examples":[{"target":"Il letto è grande.","base":"La cama es grande."},{"target":"La finestra è aperta.","base":"La ventana está abierta."}]},"takeaways":["Nombras seis muebles y partes de la casa.","Sabes que tavolo es la mesa."]},{"id":"it-a1-u06-l03","unit_id":"it-a1-u06","position":4,"title_es":"C'è, ci sono","objective_es":"Decir qué hay en una habitación.","intro":{"explanation":"C'è es «hay» con una cosa y ci sono, con varias: c'è un divano, ci sono due sedie. Para preguntar alcanza con el signo de pregunta: c'è un bagno?","examples":[{"target":"In camera c'è un letto.","base":"En la habitación hay una cama."},{"target":"In cucina ci sono quattro sedie.","base":"En la cocina hay cuatro sillas."}]},"takeaways":["Dices qué hay con c'è y ci sono.","Preguntas si hay algo: c'è…?"]},{"id":"it-a1-u06-l04","unit_id":"it-a1-u06","position":5,"title_es":"Nel, nella","objective_es":"Decir dentro de qué está algo.","intro":{"explanation":"Con un objeto concreto, in se junta con el artículo: in + il = nel, in + la = nella (y in + lo = nello). Con las habitaciones alcanza in: in cucina.","examples":[{"target":"Il telefono è nella borsa.","base":"El teléfono está en la cartera."},{"target":"Le chiavi sono nel cassetto.","base":"Las llaves están en el cajón."}]},"takeaways":["Dices dónde está algo con nel y nella.","Usas in solo con las habitaciones."]},{"id":"it-a1-u06-l05","unit_id":"it-a1-u06","position":7,"title_es":"Sul, sulla. Dove?","objective_es":"Preguntar dónde está algo y decir que está sobre otra cosa.","intro":{"explanation":"Su es «sobre» y también se junta con el artículo: su + il = sul, su + la = sulla. Para preguntar dónde está algo: dov'è…? (dove + è); con varias cosas, dove sono…?","examples":[{"target":"Il libro è sul tavolo.","base":"El libro está sobre la mesa."},{"target":"Dov'è la chiave? È sulla sedia.","base":"¿Dónde está la llave? Está sobre la silla."}]},"takeaways":["Preguntas dónde está algo con dov'è…?","Dices que algo está sobre otra cosa con sul y sulla."]},{"id":"it-a1-u07-l01","unit_id":"it-a1-u07","position":1,"title_es":"Un caffè!","objective_es":"Nombrar lo que se toma en un bar italiano.","intro":{"explanation":"En Italia un caffè es un espresso chiquito. El cappuccino lleva leche y se toma a la mañana con un cornetto. Ojo: latte es «leche»; si pides «un latte» te dan un vaso de leche.","examples":[{"target":"Un caffè, per favore.","base":"Un café, por favor."},{"target":"Un cappuccino e un cornetto.","base":"Un capuchino y un croissant."}]},"takeaways":["Nombras lo que se toma en un bar.","Sabes que latte es leche."]},{"id":"it-a1-u07-l02","unit_id":"it-a1-u07","position":2,"title_es":"Vorrei…","objective_es":"Pedir con amabilidad.","intro":{"explanation":"Vorrei es «quisiera»: la forma amable de pedir. Vorrei un panino, per favore. Acqua es femenina y empieza con vocal: un'acqua.","examples":[{"target":"Vorrei un panino, per favore.","base":"Quisiera un sándwich, por favor."},{"target":"Vorrei un succo d'arancia.","base":"Quisiera un jugo de naranja."}]},"takeaways":["Pides con vorrei.","Nombras agua, jugo y sándwich."]},{"id":"it-a1-u07-l03","unit_id":"it-a1-u07","position":4,"title_es":"Prendo… Per me…","objective_es":"Pedir con prendo y per me.","intro":{"explanation":"Prendo («tomo», «me pido») es otra forma muy común de pedir: io prendo un caffè. Per me… («para mí…») sirve para pedir sin verbo, como en español.","examples":[{"target":"Io prendo un gelato.","base":"Yo me pido un helado."},{"target":"Per me un cappuccino.","base":"Para mí un capuchino."}]},"takeaways":["Pides con prendo.","Pides con per me… sin verbo."]},{"id":"it-a1-u07-l04","unit_id":"it-a1-u07","position":5,"title_es":"Con o senza?","objective_es":"Decir con o sin qué lo quieres y si está rico.","intro":{"explanation":"Senza es «sin»; con se dice igual que en español. Para la comida, «rico» es buono: il gelato è buono. Bene es «bien» (sto bene), no se usa para la comida.","examples":[{"target":"Un caffè senza zucchero.","base":"Un café sin azúcar."},{"target":"Il gelato è molto buono!","base":"¡El helado está muy rico!"}]},"takeaways":["Pides con o senza.","Dices que algo está rico con buono."]},{"id":"it-a1-u07-l05","unit_id":"it-a1-u07","position":7,"title_es":"Il conto, per favore","objective_es":"Pedir la cuenta y entender cuando te dan algo.","intro":{"explanation":"Para pagar: il conto, per favore. Cuando te alcanzan algo te dicen ecco («aquí tiene»). En muchos bares italianos se paga primero en la caja y después se pide en la barra.","examples":[{"target":"Il conto, per favore.","base":"La cuenta, por favor."},{"target":"Ecco il suo caffè.","base":"Aquí tiene su café."}]},"takeaways":["Pides la cuenta.","Entiendes ecco cuando te dan algo."]},{"id":"it-a1-u08-l01","unit_id":"it-a1-u08","position":1,"title_es":"Mi sveglio e mi alzo","objective_es":"Contar cómo empieza tu día.","intro":{"explanation":"Despertarse y levantarse son reflexivos, como en español: mi sveglio («me despierto»), mi alzo («me levanto»). Desayunar se dice faccio colazione («hago desayuno»). La mattina es «a la mañana».","examples":[{"target":"La mattina mi sveglio presto.","base":"A la mañana me despierto temprano."},{"target":"Mi alzo e faccio colazione.","base":"Me levanto y desayuno."}]},"takeaways":["Dices que te despiertas y te levantas.","Dices que desayunas con faccio colazione."]},{"id":"it-a1-u08-l02","unit_id":"it-a1-u08","position":2,"title_es":"Parlo, leggo, dormo","objective_es":"Usar verbos en -are, -ere e -ire con io.","intro":{"explanation":"Los verbos italianos terminan en -are (parlare), -ere (leggere) o -ire (dormire). Con io, los tres terminan en -o: parlo, leggo, dormo. Igual que en español: hablo, leo, duermo.","examples":[{"target":"Parlo italiano.","base":"Hablo italiano."},{"target":"La sera leggo e poi dormo.","base":"A la noche leo y después duermo."}]},"takeaways":["Conjugas verbos en -are, -ere e -ire con io.","Dices qué haces a la noche."]},{"id":"it-a1-u08-l03","unit_id":"it-a1-u08","position":4,"title_es":"Tu parli? Lei parla","objective_es":"Conjugar con tu y con lui / lei.","intro":{"explanation":"Con tu el verbo termina en -i: parli, leggi, dormi. Con lui o lei termina en -a en los verbos de -are (parla) y en -e en los demás (legge, dorme). Como en español, el pronombre se puede omitir.","examples":[{"target":"Tu parli spagnolo?","base":"¿Tú hablas español?"},{"target":"Lei parla molto bene.","base":"Ella habla muy bien."}]},"takeaways":["Preguntas con tu parli…?","Hablas de otra persona con parla."]},{"id":"it-a1-u08-l04","unit_id":"it-a1-u08","position":5,"title_es":"Lavoro e studio","objective_es":"Decir qué haces durante el día.","intro":{"explanation":"Lavoro es «trabajo» y studio «estudio». A casa es «en casa» (y también «a casa»): lavoro a casa. Mangio es «como» y bevo «tomo, bebo».","examples":[{"target":"Lavoro a casa.","base":"Trabajo en casa."},{"target":"Studio italiano e mangio un panino.","base":"Estudio italiano y como un sándwich."}]},"takeaways":["Dices si trabajas o estudias.","Dices qué comes y qué tomas."]},{"id":"it-a1-u08-l05","unit_id":"it-a1-u08","position":7,"title_es":"Ogni giorno","objective_es":"Contar tu rutina en orden.","intro":{"explanation":"Para contar tu día: ogni giorno («todos los días»), sempre («siempre») y poi («después»). Sempre va después del verbo: faccio sempre colazione.","examples":[{"target":"Studio italiano ogni giorno.","base":"Estudio italiano todos los días."},{"target":"Faccio colazione, poi lavoro.","base":"Desayuno, después trabajo."}]},"takeaways":["Cuentas tu rutina con ogni giorno y poi.","Ubicas sempre después del verbo."]},{"id":"it-a1-u09-l01","unit_id":"it-a1-u09","position":1,"title_es":"Che ore sono?","objective_es":"Preguntar y decir la hora en punto.","intro":{"explanation":"Para preguntar la hora: che ore sono? Se responde con sono le + número, en plural como en español: sono le otto. La una es la excepción: è l'una.","examples":[{"target":"Che ore sono? Sono le otto.","base":"¿Qué hora es? Son las ocho."},{"target":"È l'una.","base":"Es la una."}]},"takeaways":["Preguntas la hora con che ore sono?","Dices la hora con sono le… y è l'una."]},{"id":"it-a1-u09-l02","unit_id":"it-a1-u09","position":2,"title_es":"E mezza, e un quarto","objective_es":"Decir la hora con minutos.","intro":{"explanation":"Como en español: y media es e mezza, y cuarto es e un quarto. Las 11 y las 12 son undici y dodici; a las 12 del día también se le dice mezzogiorno («mediodía»).","examples":[{"target":"Sono le tre e mezza.","base":"Son las tres y media."},{"target":"Sono le undici e un quarto.","base":"Son las once y cuarto."}]},"takeaways":["Dices y media y y cuarto.","Cuentas hasta las doce y dices mediodía."]},{"id":"it-a1-u09-l03","unit_id":"it-a1-u09","position":4,"title_es":"A che ora?","objective_es":"Decir a qué hora haces algo.","intro":{"explanation":"Para preguntar cuándo pasa algo: a che ora? Se responde con alle + número: alle nove («a las nueve»). Con la una: all'una. Y a mezzogiorno: «al mediodía».","examples":[{"target":"A che ora lavori?","base":"¿A qué hora trabajas?"},{"target":"Mi sveglio alle sette.","base":"Me despierto a las siete."}]},"takeaways":["Preguntas a che ora…?","Dices a qué hora haces algo con alle."]},{"id":"it-a1-u09-l04","unit_id":"it-a1-u09","position":5,"title_es":"I giorni","objective_es":"Nombrar los días de lunes a viernes.","intro":{"explanation":"Los días de lunes a viernes terminan en -dì y llevan tilde: lunedì, martedì, mercoledì, giovedì, venerdì. Se escriben con minúscula. «El lunes estudio» es simplemente lunedì studio, sin artículo.","examples":[{"target":"Oggi è lunedì.","base":"Hoy es lunes."},{"target":"Martedì studio italiano.","base":"El martes estudio italiano."}]},"takeaways":["Nombras los días de lunes a viernes.","Dices qué haces un día sin artículo."]},{"id":"it-a1-u09-l05","unit_id":"it-a1-u09","position":7,"title_es":"Oggi, domani","objective_es":"Hablar de hoy, mañana y el fin de semana.","intro":{"explanation":"Oggi es «hoy» y domani «mañana» (el día siguiente; «a la mañana» es la mattina). Sabato y domenica no llevan tilde. Con artículo indican costumbre: la domenica = «los domingos».","examples":[{"target":"Domani è sabato.","base":"Mañana es sábado."},{"target":"Il fine settimana dormo molto.","base":"El fin de semana duermo mucho."}]},"takeaways":["Distingues domani y la mattina.","Hablas del fin de semana."]},{"id":"it-a1-u10-l01","unit_id":"it-a1-u10","position":1,"title_es":"In città","objective_es":"Nombrar lugares de la ciudad.","intro":{"explanation":"Algunos lugares se parecen al español: ristorante, supermercato, stazione. Otros no: el hotel también se dice albergo, la calle es strada y el banco (de dinero) es banca.","examples":[{"target":"Il ristorante è in piazza.","base":"El restaurante está en la plaza."},{"target":"Roma è una città molto bella.","base":"Roma es una ciudad muy linda."}]},"takeaways":["Nombras lugares de la ciudad.","Sabes que el banco es banca."]},{"id":"it-a1-u10-l02","unit_id":"it-a1-u10","position":2,"title_es":"Dov'è…?","objective_es":"Preguntar dónde está un lugar.","intro":{"explanation":"Dov'è…? (dove + è) es «¿dónde está…?». A un desconocido se le habla de usted: scusi («disculpe»); a un amigo, scusa.","examples":[{"target":"Scusi, dov'è la stazione?","base":"Disculpe, ¿dónde está la estación?"},{"target":"Dov'è il supermercato?","base":"¿Dónde está el supermercado?"}]},"takeaways":["Preguntas dónde está algo con dov'è?","Le hablas de usted a un desconocido con scusi."]},{"id":"it-a1-u10-l03","unit_id":"it-a1-u10","position":4,"title_es":"Vado a… Vado in…","objective_es":"Decir adónde vas.","intro":{"explanation":"Vado es «voy» y vai «vas». Con ciudades y con casa va a: vado a Roma, vado a casa. Con lugares como banca, piazza o centro va in, sin artículo: vado in banca («voy al banco»).","examples":[{"target":"Dove vai? Vado a casa.","base":"¿Adónde vas? Voy a casa."},{"target":"Vado in banca.","base":"Voy al banco."}]},"takeaways":["Dices adónde vas con vado.","Eliges entre a (ciudades, casa) e in (lugares)."]},{"id":"it-a1-u10-l04","unit_id":"it-a1-u10","position":5,"title_es":"A destra, a sinistra","objective_es":"Entender y dar direcciones.","intro":{"explanation":"Para dar direcciones: a destra («a la derecha»), a sinistra («a la izquierda») y sempre dritto («todo derecho»). Ojo: sinistra se parece a «siniestra», que en español también quiere decir izquierda.","examples":[{"target":"La banca è a destra.","base":"El banco está a la derecha."},{"target":"Vai sempre dritto.","base":"Ve todo derecho."}]},"takeaways":["Entiendes a destra y a sinistra.","Das la indicación sempre dritto."]},{"id":"it-a1-u10-l05","unit_id":"it-a1-u10","position":7,"title_es":"Vicino o lontano?","objective_es":"Decir si un lugar está cerca o lejos.","intro":{"explanation":"Vicino es «cerca» y lontano «lejos». Se usan con è: la stazione è vicino. Para decir cerca de qué: vicino a (vicino alla stazione).","examples":[{"target":"La stazione è vicino.","base":"La estación está cerca."},{"target":"L'ospedale è lontano?","base":"¿El hospital está lejos?"}]},"takeaways":["Dices si algo está cerca o lejos.","Preguntas y entiendes indicaciones completas."]},{"id":"it-a1-u11-l01","unit_id":"it-a1-u11","position":1,"title_es":"Mi piace","objective_es":"Decir lo que te gusta y lo que no.","intro":{"explanation":"Mi piace es «me gusta»: va con una cosa (mi piace il calcio) o con un verbo (mi piace cucinare). Para negar, non va adelante: non mi piace. Con las cosas se usa el artículo, como en español.","examples":[{"target":"Mi piace il caffè.","base":"Me gusta el café."},{"target":"Non mi piace cucinare.","base":"No me gusta cocinar."}]},"takeaways":["Dices lo que te gusta con mi piace.","Dices lo que no te gusta con non mi piace."]},{"id":"it-a1-u11-l02","unit_id":"it-a1-u11","position":2,"title_es":"Mi piacciono","objective_es":"Hablar de gustos con cosas en plural.","intro":{"explanation":"Con varias cosas, piace pasa a piacciono: mi piacciono i gatti («me gustan los gatos»). El plural de cane es cani y el de gatto, gatti; el de film no cambia (i film).","examples":[{"target":"Mi piacciono i cani.","base":"Me gustan los perros."},{"target":"Non mi piacciono i film tristi.","base":"No me gustan las películas tristes."}]},"takeaways":["Usas mi piacciono con cosas en plural.","Nombras perros y gatos."]},{"id":"it-a1-u11-l03","unit_id":"it-a1-u11","position":4,"title_es":"Ti piace? Anch'io!","objective_es":"Preguntar gustos y responder.","intro":{"explanation":"Ti piace…? es «¿te gusta…?». Para estar de acuerdo: anch'io («yo también») si te gusta, neanch'io («yo tampoco») si no te gusta.","examples":[{"target":"Ti piace ballare?","base":"¿Te gusta bailar?"},{"target":"Non mi piace cantare. — Neanch'io.","base":"No me gusta cantar. — Yo tampoco."}]},"takeaways":["Preguntas gustos con ti piace?","Respondes anch'io o neanch'io."]},{"id":"it-a1-u11-l04","unit_id":"it-a1-u11","position":5,"title_es":"Voglio…","objective_es":"Decir lo que quieres hacer.","intro":{"explanation":"Voglio es «quiero» y vuoi «quieres». Van con una cosa (voglio un caffè) o con un verbo en infinitivo (voglio viaggiare). Vorrei («quisiera») es más amable para pedir en un bar.","examples":[{"target":"Voglio viaggiare in Italia.","base":"Quiero viajar a Italia."},{"target":"Vuoi giocare a calcio?","base":"¿Quieres jugar al fútbol?"}]},"takeaways":["Dices lo que quieres hacer con voglio + verbo.","Preguntas vuoi…?"]},{"id":"it-a1-u11-l05","unit_id":"it-a1-u11","position":7,"title_es":"Posso…?","objective_es":"Pedir permiso y preguntar si alguien puede.","intro":{"explanation":"Posso es «puedo» y puoi «puedes». También van con el verbo en infinitivo: posso pagare? («¿puedo pagar?»), puoi venire domani? («¿puedes venir mañana?»).","examples":[{"target":"Posso pagare?","base":"¿Puedo pagar?"},{"target":"Oggi non posso.","base":"Hoy no puedo."}]},"takeaways":["Pides permiso con posso…?","Dices que no puedes con non posso."]},{"id":"it-a1-u12-l01","unit_id":"it-a1-u12","position":1,"title_es":"Chi? Cosa?","objective_es":"Preguntar quién y qué.","intro":{"explanation":"Chi? es «¿quién?» (se lee «qui»: ch suena como k) y cosa? es «¿qué?» (también che cosa?). Cosa fai? es «¿qué haces?».","examples":[{"target":"Chi è lei? — È mia sorella.","base":"¿Quién es ella? — Es mi hermana."},{"target":"Cosa fai oggi?","base":"¿Qué haces hoy?"}]},"takeaways":["Preguntas quién con chi?","Preguntas qué con cosa?"]},{"id":"it-a1-u12-l02","unit_id":"it-a1-u12","position":2,"title_es":"Quando? Perché?","objective_es":"Preguntar cuándo y por qué, y explicar.","intro":{"explanation":"Quando? es «¿cuándo?». Perché sirve para preguntar («¿por qué?») y para responder («porque»), igual pero sin signos: Perché studi? — Perché voglio viaggiare.","examples":[{"target":"Quando vai a Roma?","base":"¿Cuándo vas a Roma?"},{"target":"Perché studi italiano? — Perché mi piace.","base":"¿Por qué estudias italiano? — Porque me gusta."}]},"takeaways":["Preguntas cuándo con quando?","Preguntas y respondes con perché."]},{"id":"it-a1-u12-l03","unit_id":"it-a1-u12","position":4,"title_es":"Come? Quale?","objective_es":"Preguntar cómo y cuál.","intro":{"explanation":"Come? es «¿cómo?» (como en come stai?). Quale? es «¿cuál?»: delante de è pierde la e, qual è? («¿cuál es?»), sin apóstrofo.","examples":[{"target":"Come vai alla stazione?","base":"¿Cómo vas a la estación?"},{"target":"Qual è il tuo numero?","base":"¿Cuál es tu número?"}]},"takeaways":["Preguntas cómo con come?","Preguntas cuál con quale? / qual è?"]},{"id":"it-a1-u12-l04","unit_id":"it-a1-u12","position":5,"title_es":"Quanto costa?","objective_es":"Preguntar precios.","intro":{"explanation":"Quanto costa? es «¿cuánto cuesta?» y quanto costano? «¿cuánto cuestan?» (varias cosas). Euro no cambia en plural: dieci euro.","examples":[{"target":"Quanto costa la maglietta? — Quindici euro.","base":"¿Cuánto cuesta la camiseta? — Quince euros."},{"target":"Quanto costano le scarpe?","base":"¿Cuánto cuestan los zapatos?"}]},"takeaways":["Preguntas el precio con quanto costa?","Usas quanto costano? con varias cosas."]},{"id":"it-a1-u12-l05","unit_id":"it-a1-u12","position":7,"title_es":"Troppo caro!","objective_es":"Opinar sobre un precio y cerrar una compra.","intro":{"explanation":"Caro es igual que en español; «barato» se dice economico. Troppo es «demasiado»: è troppo caro! Para aceptar: va bene («está bien»).","examples":[{"target":"Venti euro? È troppo caro!","base":"¿Veinte euros? ¡Es demasiado caro!"},{"target":"Cinque euro? Va bene.","base":"¿Cinco euros? Está bien."}]},"takeaways":["Dices si algo es caro o barato.","Aceptas un precio con va bene."]},{"id":"pt-a1-u01-l01","unit_id":"pt-a1-u01","position":1,"title_es":"Oi y tchau","objective_es":"Saludar y despedirte; decir sí y no.","intro":{"explanation":"En Brasil se saluda con oi y se despide con tchau, que se escribe así pero suena como «chau». Ojo con não: la «ão» se dice por la nariz.","examples":[{"target":"Oi, Lucas!","base":"¡Hola, Lucas!"},{"target":"Tchau, até logo!","base":"¡Chao, hasta luego!"},{"target":"Não, obrigada.","base":"No, gracias."}]},"takeaways":["Saludas con oi y te despides con tchau o até logo.","Dices sim y não."]},{"id":"pt-a1-u01-l02","unit_id":"pt-a1-u01","position":2,"title_es":"Bom dia y boa noite","objective_es":"Saludar según el momento del día.","intro":{"explanation":"Bom dia es para la mañana y boa tarde para la tarde. Boa noite sirve para saludar y para despedirte por la noche. Fíjate: bom con día, boa con tarde y noite.","examples":[{"target":"Bom dia, professora!","base":"¡Buenos días, profesora!"},{"target":"Boa tarde, senhor Silva.","base":"Buenas tardes, señor Silva."},{"target":"Boa noite! Até amanhã.","base":"¡Buenas noches! Hasta mañana."}]},"takeaways":["Saludas con bom dia, boa tarde y boa noite.","Boa noite sirve para saludar y para despedirte."]},{"id":"pt-a1-u01-l03","unit_id":"pt-a1-u01","position":4,"title_es":"Obrigado y desculpa","objective_es":"Agradecer, responder y disculparte.","intro":{"explanation":"Para agradecer, un hombre dice obrigado y una mujer, obrigada. Se responde de nada. Desculpa sirve para pedir perdón.","examples":[{"target":"Obrigado! — De nada.","base":"¡Gracias! — De nada."},{"target":"Obrigada, Pedro!","base":"¡Gracias, Pedro!","note":"lo dice una mujer"},{"target":"Desculpa, Júlia!","base":"¡Perdón, Júlia!"}]},"takeaways":["Agradeces con obrigado u obrigada, según quién habla.","Respondes de nada y te disculpas con desculpa."]},{"id":"pt-a1-u01-l04","unit_id":"pt-a1-u01","position":5,"title_es":"Meu nome é…","objective_es":"Decir tu nombre y preguntar el de otra persona.","intro":{"explanation":"Para presentarte dices meu nome é + tu nombre. Para preguntar: como você se chama? Al conocer a alguien se dice prazer o muito prazer.","examples":[{"target":"Meu nome é Rafael.","base":"Mi nombre es Rafael."},{"target":"Oi! Como você se chama?","base":"¡Hola! ¿Cómo te llamas?"},{"target":"Muito prazer!","base":"¡Mucho gusto!"}]},"takeaways":["Te presentas con meu nome é + tu nombre.","Preguntas el nombre con como você se chama?","Al conocer a alguien dices prazer."]},{"id":"pt-a1-u01-l05","unit_id":"pt-a1-u01","position":7,"title_es":"Tudo bem?","objective_es":"Preguntar y responder cómo está alguien.","intro":{"explanation":"Tudo bem? es la forma más común de preguntar cómo está alguien. Se responde tudo bem o tudo bom, y se devuelve con e você?","examples":[{"target":"Oi, Marina! Tudo bem?","base":"¡Hola, Marina! ¿Todo bien?"},{"target":"Tudo bem. E você?","base":"Todo bien. ¿Y tú?"},{"target":"Eu também estou bem.","base":"Yo también estoy bien."}]},"takeaways":["Preguntas tudo bem? y respondes tudo bem.","Devuelves la pregunta con e você?","Dices «también» con também."]},{"id":"pt-a1-u02-l01","unit_id":"pt-a1-u02","position":1,"title_es":"Eu sou…","objective_es":"Decir quién eres con sou.","intro":{"explanation":"Sou es «soy». En Brasil se dice mucho eu sou + nombre, y es común poner el artículo antes del nombre: eu sou o Lucas, eu sou a Ana.","examples":[{"target":"Eu sou o Lucas.","base":"Yo soy Lucas."},{"target":"Eu sou estudante.","base":"Soy estudiante."}]},"takeaways":["Dices quién eres con eu sou.","Dices a qué te dedicas: estudante, professor, professora."]},{"id":"pt-a1-u02-l02","unit_id":"pt-a1-u02","position":2,"title_es":"Você, ele, ela","objective_es":"Hablar de ti y de otras personas con é.","intro":{"explanation":"Você es «tú» y se conjuga como ele (él) y ela (ella): você é, ele é, ela é. Tu existe, pero en gran parte de Brasil se usa você.","examples":[{"target":"Você é o Pedro?","base":"¿Tú eres Pedro?"},{"target":"Ela é de São Paulo.","base":"Ella es de São Paulo."}]},"takeaways":["Usas é con você, ele y ela.","Tratas a la gente de você."]},{"id":"pt-a1-u02-l03","unit_id":"pt-a1-u02","position":4,"title_es":"Não sou…","objective_es":"Negar y preguntar con ser.","intro":{"explanation":"Para negar, não va antes del verbo: não sou, não é. En Brasil también se escucha mucho el não repetido al final: não sou não.","examples":[{"target":"Você é professor? — Não, não sou professor.","base":"¿Eres profesor? — No, no soy profesor."},{"target":"Ele não é meu amigo.","base":"Él no es mi amigo."}]},"takeaways":["Niegas con não antes del verbo.","Preguntas con la misma oración y entonación de pregunta."]},{"id":"pt-a1-u02-l04","unit_id":"pt-a1-u02","position":5,"title_es":"Nacionalidades","objective_es":"Decir tu nacionalidad con la terminación correcta.","intro":{"explanation":"Como en español, muchas nacionalidades cambian -o / -a: brasileiro / brasileira, argentino / argentina. Español es espanhol (nh suena como «ñ»).","examples":[{"target":"O Pedro é brasileiro.","base":"Pedro es brasileño."},{"target":"A Júlia é brasileira.","base":"Júlia es brasileña."},{"target":"O Pablo é espanhol.","base":"Pablo es español."}]},"takeaways":["Dices tu nacionalidad con sou + nacionalidad.","Cambias -o por -a para una mujer."]},{"id":"pt-a1-u02-l05","unit_id":"pt-a1-u02","position":7,"title_es":"De onde você é?","objective_es":"Preguntar y decir de dónde eres.","intro":{"explanation":"De onde você é? es «¿de dónde eres?». Se responde sou de + ciudad o país: sou de Rosario, sou da Argentina (de + a = da).","examples":[{"target":"De onde você é?","base":"¿De dónde eres?"},{"target":"Sou de Buenos Aires.","base":"Soy de Buenos Aires."},{"target":"Sou da Argentina.","base":"Soy de Argentina.","note":"de + a = da"}]},"takeaways":["Preguntas de dónde es alguien con de onde você é?","Respondes con sou de + ciudad."]},{"id":"pt-a1-u02-final","unit_id":"pt-a1-u02","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Quién eres y de dónde eres?».","intro":null,"takeaways":[]},{"id":"pt-a1-u03-l01","unit_id":"pt-a1-u03","position":1,"title_es":"De um a cinco","objective_es":"Contar del uno al cinco.","intro":{"explanation":"Um es «uno» (con palabras femeninas, uma) y dois es «dos» (en femenino, duas). Três lleva tilde y quatro se escribe con qu.","examples":[{"target":"Um, dois, três.","base":"Uno, dos, tres."},{"target":"Dois cafés, por favor.","base":"Dos cafés, por favor."}]},"takeaways":["Cuentas del uno al cinco.","Sabes que um y dois cambian en femenino: uma, duas."]},{"id":"pt-a1-u03-l02","unit_id":"pt-a1-u03","position":2,"title_es":"De seis a dez","objective_es":"Contar del seis al diez.","intro":{"explanation":"Sete (siete), oito (ocho), nove (nueve) y dez (diez). Seis se escribe igual que en español, pero en Brasil suena «séis».","examples":[{"target":"Seis, sete, oito.","base":"Seis, siete, ocho."},{"target":"Dez reais.","base":"Diez reales."}]},"takeaways":["Cuentas del seis al diez.","Reconoces los números de oído."]},{"id":"pt-a1-u03-l03","unit_id":"pt-a1-u03","position":4,"title_es":"Até vinte","objective_es":"Usar números más grandes: 5, 15, 18 y 20.","intro":{"explanation":"Quinze es quince y vinte, veinte. Dezoito (dieciocho) es «dez-oito» todo junto. Son los que más vas a usar para la edad.","examples":[{"target":"Tenho quinze anos.","base":"Tengo quince años."},{"target":"Ela tem dezoito anos.","base":"Ella tiene dieciocho años."}]},"takeaways":["Dices 15, 18 y 20.","Reconoces los números de oído."]},{"id":"pt-a1-u03-l04","unit_id":"pt-a1-u03","position":5,"title_es":"Quantos anos você tem?","objective_es":"Preguntar y decir la edad.","intro":{"explanation":"La edad va con ter: eu tenho (tengo) y você / ele / ela tem (tienes / tiene) + número + anos.","examples":[{"target":"Quantos anos você tem?","base":"¿Cuántos años tienes?"},{"target":"Tenho vinte anos.","base":"Tengo veinte años."},{"target":"Ele tem dez anos.","base":"Él tiene diez años."}]},"takeaways":["Preguntas la edad con quantos anos você tem?","Respondes con tenho + número + anos."]},{"id":"pt-a1-u03-l05","unit_id":"pt-a1-u03","position":7,"title_es":"Apresentação completa","objective_es":"Decir tu nombre, de dónde eres y cuántos años tienes.","intro":{"explanation":"Ya puedes presentarte entero: meu nome é + nombre, sou de + ciudad y tenho + edad. El origen va con ser y la edad con ter.","examples":[{"target":"Meu nome é Ana, sou de Rosario e tenho vinte anos.","base":"Me llamo Ana, soy de Rosario y tengo veinte años."},{"target":"Ele é o Tiago e tem oito anos.","base":"Él es Tiago y tiene ocho años."}]},"takeaways":["Te presentas con nombre, origen y edad.","Usas sou para el origen y tenho para la edad."]},{"id":"pt-a1-u04-l01","unit_id":"pt-a1-u04","position":1,"title_es":"Mãe e pai","objective_es":"Nombrar a tu familia cercana.","intro":{"explanation":"Mãe y pai son madre y padre; pais (con s) son los dos. Ojo: pais suena distinto de país (país lleva tilde y es «país»).","examples":[{"target":"Minha família é pequena.","base":"Mi familia es chica."},{"target":"Meus pais são de Recife.","base":"Mis padres son de Recife."}]},"takeaways":["Nombras a tu madre, tu padre y tus padres.","Distingues pais (padres) de país."]},{"id":"pt-a1-u04-l02","unit_id":"pt-a1-u04","position":2,"title_es":"Irmãos","objective_es":"Hablar de tus hermanos.","intro":{"explanation":"Irmão es hermano e irmã, hermana (las dos con ~). Con tenho dices cuántos tienes: tenho um irmão, tenho duas irmãs. Si no tienes: sou filho único (o filha única).","examples":[{"target":"Tenho um irmão e uma irmã.","base":"Tengo un hermano y una hermana."},{"target":"Sou filha única.","base":"Soy hija única."}]},"takeaways":["Dices cuántos hermanos tienes con tenho.","Dices que eres hijo único con filho único."]},{"id":"pt-a1-u04-l03","unit_id":"pt-a1-u04","position":4,"title_es":"Avós e filhos","objective_es":"Hablar de abuelos e hijos.","intro":{"explanation":"Avô (abuelo, «o» cerrada) y avó (abuela, «o» abierta) sólo se distinguen por la tilde y el sonido. Filho y filha son hijo e hija: lh suena parecido a «ll».","examples":[{"target":"Minha avó é de Salvador.","base":"Mi abuela es de Salvador."},{"target":"Ela é minha filha.","base":"Ella es mi hija."}]},"takeaways":["Distingues avô y avó.","Nombras a tus hijos con filho y filha."]},{"id":"pt-a1-u04-l04","unit_id":"pt-a1-u04","position":5,"title_es":"Meu, minha","objective_es":"Usar meu y minha con tu familia.","intro":{"explanation":"Meu va con palabras masculinas (meu pai, meu irmão) y minha con femeninas (minha mãe, minha irmã). En Brasil también se dice con artículo: o meu irmão.","examples":[{"target":"Meu irmão tem dez anos.","base":"Mi hermano tiene diez años."},{"target":"Minha irmã é estudante.","base":"Mi hermana es estudiante."}]},"takeaways":["Eliges meu o minha según la palabra.","Presentas a tus familiares con su edad."]},{"id":"pt-a1-u04-l05","unit_id":"pt-a1-u04","position":7,"title_es":"Ela se chama…","objective_es":"Decir cómo se llaman tus familiares.","intro":{"explanation":"Para decir cómo se llama otra persona: se chama + nombre. Para preguntar: como se chama o seu irmão?","examples":[{"target":"Minha mãe se chama Laura.","base":"Mi madre se llama Laura."},{"target":"Como se chama o seu irmão?","base":"¿Cómo se llama tu hermano?"}]},"takeaways":["Dices cómo se llama alguien con se chama.","Presentas a tu familia con nombre y edad."]},{"id":"pt-a1-u05-l01","unit_id":"pt-a1-u05","position":1,"title_es":"O que é isso?","objective_es":"Preguntar qué es algo y nombrar objetos con o y a.","intro":{"explanation":"Para preguntar qué es algo: o que é isso? En portugués el artículo es o (masculino) y a (femenino): o livro, a caneta. Se responde con é + la cosa: é um livro.","examples":[{"target":"O que é isso? É um livro.","base":"¿Qué es eso? Es un libro."},{"target":"A caneta é azul.","base":"El bolígrafo es azul."}]},"takeaways":["Preguntas qué es algo con o que é isso?","Usas o con masculinos y a con femeninos."]},{"id":"pt-a1-u05-l02","unit_id":"pt-a1-u05","position":2,"title_es":"Um, uma, os, as","objective_es":"Usar um / uma y los artículos en plural.","intro":{"explanation":"Um y uma son «un» y «una». En plural el artículo es os o as: os livros, as canetas. Ojo: borracha es la goma de borrar, y óculos (lentes) va siempre en plural: os óculos.","examples":[{"target":"Tenho uma borracha.","base":"Tengo una goma de borrar."},{"target":"Tenho dois cadernos.","base":"Tengo dos cuadernos."}]},"takeaways":["Usas um, uma, os y as.","Sabes que borracha es la goma de borrar."]},{"id":"pt-a1-u05-l03","unit_id":"pt-a1-u05","position":4,"title_es":"As cores","objective_es":"Nombrar los colores.","intro":{"explanation":"Los colores van después de la palabra y concuerdan: o livro vermelho, a caneta vermelha. Azul no cambia en singular. Para las cosas, «negro» es preto.","examples":[{"target":"O livro é vermelho.","base":"El libro es rojo."},{"target":"A caneta é preta.","base":"El bolígrafo es negro."}]},"takeaways":["Nombras cinco colores.","Usas preto para el negro de las cosas."]},{"id":"pt-a1-u05-l04","unit_id":"pt-a1-u05","position":5,"title_es":"De quem é?","objective_es":"Preguntar y decir de quién es algo.","intro":{"explanation":"De se junta con el artículo: de + o = do, de + a = da. En Brasil los nombres suelen llevar artículo, así que se dice o livro do João, a chave da Ana. Para preguntar: de quem é?","examples":[{"target":"De quem é a caneta? É da Ana.","base":"¿De quién es el bolígrafo? Es de Ana."},{"target":"O caderno é do João.","base":"El cuaderno es de João."}]},"takeaways":["Preguntas de quién es algo.","Juntas de + o = do y de + a = da."]},{"id":"pt-a1-u05-l05","unit_id":"pt-a1-u05","position":7,"title_es":"Minha caneta preta","objective_es":"Describir tus cosas con posesivo y color.","intro":{"explanation":"Junta todo: meu caderno branco, minha caneta preta. En plural el color también cambia: os óculos pretos, as chaves amarelas.","examples":[{"target":"Minha caneta é azul.","base":"Mi bolígrafo es azul."},{"target":"Os óculos do meu pai são pretos.","base":"Los lentes de mi papá son negros."}]},"takeaways":["Describes tus cosas con meu / minha y un color.","Haces concordar el color en plural."]},{"id":"pt-a1-u06-l01","unit_id":"pt-a1-u06","position":1,"title_es":"Os cômodos","objective_es":"Nombrar las partes de la casa.","intro":{"explanation":"Las partes de la casa. Quarto es el dormitorio (el número cuatro es quatro) y banheiro, el baño. Sala es la sala.","examples":[{"target":"A cozinha é grande.","base":"La cocina es grande."},{"target":"Meu quarto é pequeno.","base":"Mi dormitorio es chico."}]},"takeaways":["Nombras las partes de la casa.","Sabes que quarto es el dormitorio."]},{"id":"pt-a1-u06-l02","unit_id":"pt-a1-u06","position":2,"title_es":"Os móveis","objective_es":"Nombrar muebles y partes de una habitación.","intro":{"explanation":"Muchos muebles se parecen al español: mesa, cama, sofá (el sillón). Ojo con cadeira (silla) y janela (ventana).","examples":[{"target":"A cama é grande.","base":"La cama es grande."},{"target":"A janela é branca.","base":"La ventana es blanca."}]},"takeaways":["Nombras seis muebles y partes de la casa.","Sabes que cadeira es la silla."]},{"id":"pt-a1-u06-l03","unit_id":"pt-a1-u06","position":4,"title_es":"Tem, há","objective_es":"Decir qué hay en la casa.","intro":{"explanation":"Para decir «hay», en Brasil se usa casi siempre tem: tem um sofá na sala. Há significa lo mismo, pero es más formal o escrito. Ninguno cambia en plural: tem duas cadeiras (con femeninas, «dos» es duas).","examples":[{"target":"Na sala tem um sofá.","base":"En la sala hay un sillón."},{"target":"Há três quartos.","base":"Hay tres dormitorios."}]},"takeaways":["Dices qué hay con tem.","Reconoces há en textos más formales."]},{"id":"pt-a1-u06-l04","unit_id":"pt-a1-u06","position":5,"title_es":"No quarto, na cozinha","objective_es":"Decir en qué parte de la casa está algo o alguien.","intro":{"explanation":"Em («en») se junta con el artículo: em + o = no, em + a = na. Para decir dónde está algo o alguien se usa está: o livro está no quarto, minha mãe está na cozinha.","examples":[{"target":"Minha mãe está na cozinha.","base":"Mi mamá está en la cocina."},{"target":"O livro está no quarto.","base":"El libro está en el dormitorio."}]},"takeaways":["Dices dónde está algo con está + no / na.","Juntas em + o = no y em + a = na."]},{"id":"pt-a1-u06-l05","unit_id":"pt-a1-u06","position":7,"title_es":"Onde está?","objective_es":"Preguntar dónde está algo y ubicarlo.","intro":{"explanation":"Para preguntar dónde está algo: onde está…? Para ubicarlo: em cima de (encima de) y embaixo de (debajo de). El de también se junta con el artículo: em cima da mesa, embaixo do sofá.","examples":[{"target":"Onde está a chave? Está em cima da mesa.","base":"¿Dónde está la llave? Está encima de la mesa."},{"target":"O gato está embaixo da cama.","base":"El gato está debajo de la cama."}]},"takeaways":["Preguntas dónde está algo con onde está…?","Ubicas cosas con em cima de y embaixo de."]},{"id":"pt-a1-u07-l01","unit_id":"pt-a1-u07","position":1,"title_es":"Café da manhã","objective_es":"Nombrar lo que se come en el desayuno.","intro":{"explanation":"Café da manhã es el desayuno (literalmente «café de la mañana»). Un clásico de Brasil es el pão de queijo, un pancito de queso.","examples":[{"target":"No café da manhã, tomo café com leite.","base":"En el desayuno tomo café con leche."},{"target":"O pão de queijo é gostoso.","base":"El pan de queso es rico."}]},"takeaways":["Nombras lo que comes en el desayuno.","Sabes que café da manhã es el desayuno."]},{"id":"pt-a1-u07-l02","unit_id":"pt-a1-u07","position":2,"title_es":"Eu quero…","objective_es":"Decir qué quieres comer o tomar.","intro":{"explanation":"Quero es «quiero». Con amigos o en casa alcanza con quero; para pedir en un bar es más amable queria (lo vemos en la próxima lección).","examples":[{"target":"Quero um suco, por favor.","base":"Quiero un jugo, por favor."},{"target":"Você quer água?","base":"¿Quieres agua?"}]},"takeaways":["Dices qué quieres con quero.","Nombras jugo y agua."]},{"id":"pt-a1-u07-l03","unit_id":"pt-a1-u07","position":4,"title_es":"Eu queria…","objective_es":"Pedir con amabilidad.","intro":{"explanation":"Queria (literalmente «quería») es la forma amable de pedir en Brasil: eu queria um café, por favor. Para mim… es «para mí…».","examples":[{"target":"Eu queria um pão de queijo, por favor.","base":"Quisiera un pan de queso, por favor."},{"target":"Para mim, um suco.","base":"Para mí, un jugo."}]},"takeaways":["Pides con amabilidad con queria.","Pides sin verbo con para mim…."]},{"id":"pt-a1-u07-l04","unit_id":"pt-a1-u07","position":5,"title_es":"Com ou sem?","objective_es":"Decir con o sin qué lo quieres y si está rico.","intro":{"explanation":"Com es «con» y sem, «sin». Gostoso es «rico». Ojo con dos falsos amigos: polvo es el pulpo, y esquisito significa «raro», no «exquisito».","examples":[{"target":"Um café sem açúcar.","base":"Un café sin azúcar."},{"target":"O polvo é muito gostoso.","base":"El pulpo es muy rico."}]},"takeaways":["Pides com o sem.","Dices que algo está rico con gostoso."]},{"id":"pt-a1-u07-l05","unit_id":"pt-a1-u07","position":7,"title_es":"A conta, por favor","objective_es":"Pedir la cuenta.","intro":{"explanation":"Para pagar: a conta, por favor. Para agradecer, recuerda: obrigado si eres hombre, obrigada si eres mujer.","examples":[{"target":"A conta, por favor.","base":"La cuenta, por favor."},{"target":"Eu queria a conta, por favor.","base":"Quisiera la cuenta, por favor."}]},"takeaways":["Pides la cuenta.","Pides una comida completa con amabilidad."]},{"id":"pt-a1-u08-l01","unit_id":"pt-a1-u08","position":1,"title_es":"Acordo e tomo café","objective_es":"Contar cómo empieza tu día.","intro":{"explanation":"Acordo es «me despierto», sin pronombre reflexivo. Desayunar se dice tomar café da manhã: eu tomo café da manhã. De manhã es «por la mañana».","examples":[{"target":"Eu acordo às sete.","base":"Me despierto a las siete."},{"target":"De manhã tomo café da manhã em casa.","base":"A la mañana tomo el desayuno en casa."}]},"takeaways":["Dices que te despiertas con acordo.","Dices que desayunas con tomo café da manhã."]},{"id":"pt-a1-u08-l02","unit_id":"pt-a1-u08","position":2,"title_es":"Falo, escrevo, durmo","objective_es":"Usar verbos en -ar, -er e -ir con eu.","intro":{"explanation":"Los verbos terminan en -ar (falar), -er (escrever, ler) o -ir (dormir). Con eu terminan en -o: falo, escrevo, durmo. Ler («leer») es irregular: eu leio.","examples":[{"target":"Falo português.","base":"Hablo portugués."},{"target":"À noite eu leio e depois durmo.","base":"Por la noche leo y después duermo."}]},"takeaways":["Conjugas verbos en -ar, -er e -ir con eu.","Dices qué haces por la noche."]},{"id":"pt-a1-u08-l03","unit_id":"pt-a1-u08","position":4,"title_es":"Você fala…?","objective_es":"Conjugar con você, ele y ela.","intro":{"explanation":"Con você, ele y ela el verbo termina en -a en los verbos de -ar (fala) y en -e en los demás (escreve, dorme). En Brasil a un amigo también se le dice você.","examples":[{"target":"Você fala espanhol?","base":"¿Tú hablas español?"},{"target":"Ela fala muito bem.","base":"Ella habla muy bien."}]},"takeaways":["Preguntas con você fala…?","Hablas de otra persona con ele / ela fala."]},{"id":"pt-a1-u08-l04","unit_id":"pt-a1-u08","position":5,"title_es":"Trabalho e estudo","objective_es":"Decir qué haces durante el día y dónde vives.","intro":{"explanation":"Trabalho es «trabajo» y estudo «estudio». Para decir dónde vives se usa morar: eu moro em Buenos Aires. Almoço es «almuerzo» y janto «ceno».","examples":[{"target":"Eu moro em Buenos Aires.","base":"Vivo en Buenos Aires."},{"target":"Almoço e depois trabalho.","base":"Almuerzo y después trabajo."}]},"takeaways":["Dices si trabajas o estudias.","Dices dónde vives con moro em."]},{"id":"pt-a1-u08-l05","unit_id":"pt-a1-u08","position":7,"title_es":"Todo dia","objective_es":"Contar tu rutina en orden.","intro":{"explanation":"Todo dia es «todos los días»; sempre, «siempre»; depois, «después». Ojo con assistir: assisto TV es «miro la tele», no «asisto».","examples":[{"target":"Estudo português todo dia.","base":"Estudio portugués todos los días."},{"target":"Janto e depois assisto TV.","base":"Ceno y después miro la tele."}]},"takeaways":["Cuentas tu rutina con todo dia y depois.","Sabes que assistir TV es mirar la tele."]},{"id":"pt-a1-u09-l01","unit_id":"pt-a1-u09","position":1,"title_es":"Que horas são?","objective_es":"Preguntar y decir la hora en punto.","intro":{"explanation":"Para preguntar la hora: que horas são? Se responde con são + número + horas (são oito horas). La palabra horas se puede omitir: são oito. La una va en singular: é uma hora.","examples":[{"target":"Que horas são? São oito horas.","base":"¿Qué hora es? Son las ocho."},{"target":"É uma hora.","base":"Es la una."}]},"takeaways":["Preguntas la hora con que horas são?","Dices la hora con são… horas y é uma hora."]},{"id":"pt-a1-u09-l02","unit_id":"pt-a1-u09","position":2,"title_es":"E meia, e quinze","objective_es":"Decir la hora con minutos.","intro":{"explanation":"Y media es e meia; y cuarto se dice e quinze («y quince»). Once y doce son onze y doze; las 12 del día es meio-dia («mediodía»). Ojo: dos horas es duas horas (femenino).","examples":[{"target":"São três e meia.","base":"Son las tres y media."},{"target":"São onze e quinze.","base":"Son las once y cuarto."}]},"takeaways":["Dices y media y y cuarto.","Cuentas hasta las doce y dices mediodía."]},{"id":"pt-a1-u09-l03","unit_id":"pt-a1-u09","position":4,"title_es":"A que horas?","objective_es":"Decir a qué hora haces algo.","intro":{"explanation":"Para preguntar cuándo pasa algo: a que horas? Se responde con às + número: às nove («a las nueve»). Con la una: à uma. Y ao meio-dia: «al mediodía».","examples":[{"target":"A que horas você trabalha?","base":"¿A qué hora trabajas?"},{"target":"Eu acordo às sete.","base":"Me despierto a las siete."}]},"takeaways":["Preguntas a que horas…?","Dices a qué hora haces algo con às."]},{"id":"pt-a1-u09-l04","unit_id":"pt-a1-u09","position":5,"title_es":"Segunda, terça…","objective_es":"Nombrar los días de lunes a viernes.","intro":{"explanation":"En portugués los días de lunes a viernes se cuentan: segunda-feira (lunes), terça-feira (martes), quarta-feira, quinta-feira, sexta-feira. En la charla se dice sólo segunda, terça…","examples":[{"target":"Hoje é segunda-feira.","base":"Hoy es lunes."},{"target":"Terça-feira eu estudo.","base":"El martes estudio."}]},"takeaways":["Nombras los días de lunes a viernes.","Sabes que segunda-feira es lunes."]},{"id":"pt-a1-u09-l05","unit_id":"pt-a1-u09","position":7,"title_es":"Hoje, amanhã","objective_es":"Hablar de hoy, mañana y el fin de semana.","intro":{"explanation":"Hoje es «hoy» y amanhã «mañana» (el día siguiente; «por la mañana» es de manhã). Sábado y domingo se escriben como en español. «El fin de semana» es no fim de semana.","examples":[{"target":"Amanhã é sábado.","base":"Mañana es sábado."},{"target":"No fim de semana eu durmo muito.","base":"El fin de semana duermo mucho."}]},"takeaways":["Distingues amanhã y de manhã.","Hablas del fin de semana."]},{"id":"pt-a1-u10-l01","unit_id":"pt-a1-u10","position":1,"title_es":"Na cidade","objective_es":"Nombrar lugares de la ciudad.","intro":{"explanation":"Lugares de la ciudad: rua (calle), praça (plaza), estação (estación), loja (tienda), padaria (panadería) y escola (escuela). Ojo: en portugués la tienda es loja, no tienda.","examples":[{"target":"A padaria fica na praça.","base":"La panadería queda en la plaza."},{"target":"São Paulo é uma cidade grande.","base":"San Pablo es una ciudad grande."}]},"takeaways":["Nombras lugares de la ciudad.","Sabes que la tienda es loja."]},{"id":"pt-a1-u10-l02","unit_id":"pt-a1-u10","position":2,"title_es":"Onde fica…?","objective_es":"Preguntar dónde queda un lugar.","intro":{"explanation":"Para preguntar por un lugar se usa onde fica…? («¿dónde queda?»). Para llamar la atención de alguien con cortesía: com licença («permiso»).","examples":[{"target":"Com licença, onde fica a estação?","base":"Permiso, ¿dónde queda la estación?"},{"target":"Onde fica a escola?","base":"¿Dónde queda la escuela?"}]},"takeaways":["Preguntas dónde queda algo con onde fica?","Pides permiso con com licença."]},{"id":"pt-a1-u10-l03","unit_id":"pt-a1-u10","position":4,"title_es":"Vou para…","objective_es":"Decir adónde vas y cómo.","intro":{"explanation":"Ir: eu vou, você vai. Adónde se dice con para + artículo: vou para a escola, vou para o trabalho; a casa es vou para casa (sin artículo). En qué vas: de ônibus («en autobús»).","examples":[{"target":"Aonde você vai? Vou para casa.","base":"¿Adónde vas? Voy a casa."},{"target":"Eu vou para a escola de ônibus.","base":"Voy a la escuela en autobús."}]},"takeaways":["Dices adónde vas con vou para…","Dices que vas en autobús con de ônibus."]},{"id":"pt-a1-u10-l04","unit_id":"pt-a1-u10","position":5,"title_es":"À direita, à esquerda","objective_es":"Entender y dar direcciones.","intro":{"explanation":"Para dar direcciones: à direita («a la derecha»), à esquerda («a la izquierda») y siga reto («siga derecho»). La à lleva acento grave: es a + a.","examples":[{"target":"A loja fica à direita.","base":"La tienda queda a la derecha."},{"target":"Siga reto e depois à esquerda.","base":"Siga derecho y después a la izquierda."}]},"takeaways":["Entiendes à direita y à esquerda.","Das la indicación siga reto."]},{"id":"pt-a1-u10-l05","unit_id":"pt-a1-u10","position":7,"title_es":"Perto ou longe?","objective_es":"Decir si un lugar está cerca o lejos.","intro":{"explanation":"Perto es «cerca» y longe «lejos». Se usan con fica: a estação fica perto. Para preguntar: …fica longe?","examples":[{"target":"A estação fica perto.","base":"La estación queda cerca."},{"target":"A escola fica longe?","base":"¿La escuela queda lejos?"}]},"takeaways":["Dices si algo está cerca o lejos.","Preguntas y entiendes indicaciones completas."]},{"id":"pt-a1-u11-l01","unit_id":"pt-a1-u11","position":1,"title_es":"Eu gosto de…","objective_es":"Decir lo que te gusta y lo que no.","intro":{"explanation":"Gostar funciona al revés que «gustar»: eu gosto de futebol es «me gusta el fútbol» (literalmente «yo gusto de fútbol»). Siempre lleva de. Para negar: eu não gosto de…","examples":[{"target":"Eu gosto de futebol.","base":"Me gusta el fútbol."},{"target":"Eu não gosto de cozinhar.","base":"No me gusta cocinar."}]},"takeaways":["Dices lo que te gusta con gosto de.","Niegas con não gosto de."]},{"id":"pt-a1-u11-l02","unit_id":"pt-a1-u11","position":2,"title_es":"Gosto do…, gosto da…","objective_es":"Usar gostar de con artículo.","intro":{"explanation":"Con artículo, de se junta: de + o = do, de + a = da. Eu gosto da praia («me gusta la playa»), gosto do Brasil. Ojo con el falso amigo: cachorro es «perro» (no sólo el cachorrito).","examples":[{"target":"Eu gosto da praia.","base":"Me gusta la playa."},{"target":"Eu gosto muito do meu cachorro.","base":"Quiero mucho a mi perro."}]},"takeaways":["Juntas de con el artículo: do, da.","Sabes que cachorro es «perro»."]},{"id":"pt-a1-u11-l03","unit_id":"pt-a1-u11","position":4,"title_es":"Você gosta de…?","objective_es":"Preguntar gustos y responder.","intro":{"explanation":"Para preguntar: você gosta de…? («¿te gusta…?»). Para coincidir: eu também («yo también») o eu também não («yo tampoco»). Adoro es «me encanta».","examples":[{"target":"Você gosta de dançar? — Adoro!","base":"¿Te gusta bailar? — ¡Me encanta!"},{"target":"Não gosto de leite. — Eu também não.","base":"No me gusta la leche. — Yo tampoco."}]},"takeaways":["Preguntas você gosta de…?","Respondes eu também o eu também não."]},{"id":"pt-a1-u11-l04","unit_id":"pt-a1-u11","position":5,"title_es":"Que legal!","objective_es":"Opinar sobre algo y evitar un falso amigo.","intro":{"explanation":"Que legal! es «¡qué genial!»: en Brasil legal se usa para todo lo que está bueno. Ojo: esquisito NO es «exquisito», es «raro». Para algo rico se dice gostoso.","examples":[{"target":"Você joga futebol? Que legal!","base":"¿Juegas al fútbol? ¡Qué genial!"},{"target":"Que filme esquisito!","base":"¡Qué película rara!"}]},"takeaways":["Dices que algo está bueno con que legal!","Sabes que esquisito es «raro»."]},{"id":"pt-a1-u11-l05","unit_id":"pt-a1-u11","position":7,"title_es":"Posso…? Você pode…?","objective_es":"Pedir permiso y preguntar si alguien puede.","intro":{"explanation":"Posso es «puedo» y (você) pode «puedes». Van con el verbo en infinitivo: posso pagar? («¿puedo pagar?»), você pode jogar amanhã?","examples":[{"target":"Posso pagar?","base":"¿Puedo pagar?"},{"target":"Hoje eu não posso.","base":"Hoy no puedo."}]},"takeaways":["Pides permiso con posso…?","Preguntas você pode…?"]},{"id":"pt-a1-u12-l01","unit_id":"pt-a1-u12","position":1,"title_es":"O que? Quem?","objective_es":"Preguntar qué y quién.","intro":{"explanation":"O que? es «¿qué?» (o que você quer? «¿qué quieres?») y quem? es «¿quién?». Al final de la frase, que lleva acento: você quer o quê?","examples":[{"target":"O que você quer?","base":"¿Qué quieres?"},{"target":"Quem é ela? — É minha irmã.","base":"¿Quién es ella? — Es mi hermana."}]},"takeaways":["Preguntas qué con o que?","Preguntas quién con quem?"]},{"id":"pt-a1-u12-l02","unit_id":"pt-a1-u12","position":2,"title_es":"Quando? Por que?","objective_es":"Preguntar cuándo y por qué, y explicar.","intro":{"explanation":"Quando? es «¿cuándo?». Para preguntar «¿por qué?» se escribe separado: por que?; para responder, junto: porque. Suenan igual.","examples":[{"target":"Quando você trabalha? — Segunda-feira.","base":"¿Cuándo trabajas? — El lunes."},{"target":"Por que você estuda? — Porque eu gosto.","base":"¿Por qué estudias? — Porque me gusta."}]},"takeaways":["Preguntas cuándo con quando?","Distingues por que? (pregunta) y porque (respuesta)."]},{"id":"pt-a1-u12-l03","unit_id":"pt-a1-u12","position":4,"title_es":"Qual é o seu apelido?","objective_es":"Preguntar cuál y evitar un falso amigo.","intro":{"explanation":"Qual? es «¿cuál?»: qual é o seu nome? Ojo con el falso amigo: apelido es «apodo»; el apellido se dice sobrenome.","examples":[{"target":"Qual é o seu sobrenome? — Silva.","base":"¿Cuál es tu apellido? — Silva."},{"target":"Meu apelido é Juca.","base":"Mi apodo es Juca."}]},"takeaways":["Preguntas cuál con qual?","Sabes que apelido es «apodo» y sobrenome «apellido»."]},{"id":"pt-a1-u12-l04","unit_id":"pt-a1-u12","position":5,"title_es":"Quanto custa?","objective_es":"Preguntar precios.","intro":{"explanation":"Quanto custa? es «¿cuánto cuesta?» y quanto custam? «¿cuánto cuestan?» (varias cosas). La moneda de Brasil es el real; en plural, reais: dez reais.","examples":[{"target":"Quanto custa a camiseta? — Vinte reais.","base":"¿Cuánto cuesta la camiseta? — Veinte reales."},{"target":"Quanto custam os sapatos?","base":"¿Cuánto cuestan los zapatos?"}]},"takeaways":["Preguntas el precio con quanto custa?","Entiendes precios en reais."]},{"id":"pt-a1-u12-l05","unit_id":"pt-a1-u12","position":7,"title_es":"Caro ou barato?","objective_es":"Opinar sobre un precio y cerrar una compra.","intro":{"explanation":"Caro y barato son iguales que en español. Muito caro es «muy caro». Para aceptar un precio se dice tá bom («está bien»), la forma corta de está bom.","examples":[{"target":"Cinquenta reais? É muito caro!","base":"¿Cincuenta reales? ¡Es muy caro!"},{"target":"Cinco reais? Tá bom.","base":"¿Cinco reales? Está bien."}]},"takeaways":["Dices si algo es caro o barato.","Aceptas un precio con tá bom."]},{"id":"zh-a1-u01-l01","unit_id":"zh-a1-u01","position":1,"title_es":"你好！","objective_es":"Saludar y despedirte.","intro":{"explanation":"你好 (nǐ hǎo) es «hola». Con un profesor o alguien mayor se usa 您好 (nín hǎo), más respetuoso. Arriba de los caracteres vas a ver el pinyin, que indica cómo se pronuncian. Para escribir el pinyin puedes usar números de tono: ni3 hao3.","examples":[{"target":"你好！","base":"¡Hola!"},{"target":"老师，您好！","base":"¡Hola, profe!"},{"target":"再见！","base":"¡Adiós!"}]},"takeaways":["Saludas con 你好 y, con respeto, con 您好.","Te despides con 再见.","Escribes pinyin con números de tono (ni3 hao3)."]},{"id":"zh-a1-u01-l02","unit_id":"zh-a1-u01","position":2,"title_es":"Los cuatro tonos","objective_es":"Distinguir de oído los cuatro tonos.","intro":{"explanation":"El mismo sonido con otro tono es otra palabra. 1.º alto y parejo (ā), 2.º sube como una pregunta (á), 3.º baja y vuelve a subir (ǎ), 4.º baja seco (à). Escucha cada palabra y fíjate en la melodía.","examples":[{"target":"妈 mā · 麻 má · 马 mǎ · 骂 mà","base":"mamá · cáñamo · caballo · regañar"},{"target":"谢谢 xièxie","base":"gracias","note":"la segunda sílaba es neutra"}]},"takeaways":["Reconoces los cuatro tonos y el neutro.","Sabes que un tono distinto cambia la palabra."]},{"id":"zh-a1-u01-l03","unit_id":"zh-a1-u01","position":4,"title_es":"谢谢 y 对不起","objective_es":"Agradecer, disculparte y responder.","intro":{"explanation":"A 谢谢 (gracias) se responde 不客气 (de nada). A 对不起 (perdón) se responde 没关系 (no pasa nada).","examples":[{"target":"谢谢！——不客气。","base":"¡Gracias! — De nada."},{"target":"对不起！——没关系。","base":"¡Perdón! — No pasa nada."}]},"takeaways":["Respondes 不客气 cuando te agradecen.","Te disculpas con 对不起 y respondes 没关系."]},{"id":"zh-a1-u01-l04","unit_id":"zh-a1-u01","position":5,"title_es":"我叫…","objective_es":"Decir tu nombre y preguntar el de otra persona.","intro":{"explanation":"Para decir tu nombre: 我叫 + nombre («yo me llamo…»). Para preguntar: 你叫什么名字？, literalmente «¿tú te llamas qué nombre?». La pregunta va en el mismo lugar que la respuesta.","examples":[{"target":"我叫王明。","base":"Me llamo Wang Ming."},{"target":"你叫什么名字？","base":"¿Cómo te llamas?"}]},"takeaways":["Te presentas con 我叫 + tu nombre.","Preguntas el nombre con 你叫什么名字？"]},{"id":"zh-a1-u01-l05","unit_id":"zh-a1-u01","position":7,"title_es":"我很好","objective_es":"Decir que estás bien y devolver la pregunta.","intro":{"explanation":"Para decir que estás bien: 我很好. En chino no hace falta un verbo «estar» y antes de 好 casi siempre va 很 (muy), aunque se traduce simplemente «bien». Para devolver la pregunta: 你呢？","examples":[{"target":"我很好，你呢？","base":"Estoy bien, ¿y tú?"},{"target":"我也很好。","base":"Yo también estoy bien."}]},"takeaways":["Dices que estás bien con 我很好.","Devuelves la pregunta con 你呢？","Dices «también» con 也, antes del verbo o adjetivo."]},{"id":"zh-a1-u02-l01","unit_id":"zh-a1-u02","position":1,"title_es":"我是学生","objective_es":"Decir qué eres con 是.","intro":{"explanation":"是 (shì) es «ser» y sirve para todas las personas: 我是, 你是, 他是. Para tu nombre ya conoces 叫; 是 es para lo que eres: estudiante, profesor, de dónde.","examples":[{"target":"我是学生。","base":"Soy estudiante."},{"target":"你是老师。","base":"Tú eres profesor/a."}]},"takeaways":["Dices qué eres con 是.","Usas 叫 para el nombre y 是 para lo demás."]},{"id":"zh-a1-u02-l02","unit_id":"zh-a1-u02","position":2,"title_es":"不 y 吗","objective_es":"Negar con 不 y preguntar con 吗.","intro":{"explanation":"Para negar, 不 (bù) va antes del verbo: 我不是老师. Antes de un cuarto tono como 是 se pronuncia bú. Para una pregunta de sí o no, agregas 吗 (ma) al final, sin cambiar el orden.","examples":[{"target":"我不是老师。","base":"No soy profesor/a.","note":"bú shì"},{"target":"你是学生吗？","base":"¿Eres estudiante?"}]},"takeaways":["Niegas con 不 antes del verbo.","Preguntas sí o no con 吗 al final."]},{"id":"zh-a1-u02-l03","unit_id":"zh-a1-u02","position":4,"title_es":"他 y 她","objective_es":"Hablar de otras personas.","intro":{"explanation":"他 (él) y 她 (ella) se pronuncian igual: tā. Sólo se distinguen por escrito: 她 lleva 女, «mujer». 朋友 es amigo o amiga.","examples":[{"target":"他是我朋友。","base":"Él es mi amigo."},{"target":"她是老师。","base":"Ella es profesora."}]},"takeaways":["Hablas de alguien con 他 o 她.","Presentas a un amigo con 他是我朋友."]},{"id":"zh-a1-u02-l04","unit_id":"zh-a1-u02","position":5,"title_es":"中国人","objective_es":"Decir tu nacionalidad: país + 人.","intro":{"explanation":"La nacionalidad se arma con el país + 人 (persona): 中国人 «persona de China», 阿根廷人 «argentino/a». No cambia para varón o mujer.","examples":[{"target":"我是阿根廷人。","base":"Soy argentino/a."},{"target":"她是西班牙人。","base":"Ella es española."}]},"takeaways":["Dices tu nacionalidad con país + 人.","Sabes que no cambia para varón o mujer."]},{"id":"zh-a1-u02-l05","unit_id":"zh-a1-u02","position":7,"title_es":"你是哪国人？","objective_es":"Preguntar y decir de qué país eres.","intro":{"explanation":"哪 (nǎ) es «¿cuál?». 你是哪国人？ es «¿de qué país eres?» (literalmente «¿eres persona de qué país?»). Se responde poniendo el país donde estaba 哪国.","examples":[{"target":"你是哪国人？","base":"¿De qué país eres?"},{"target":"我是墨西哥人。","base":"Soy mexicano/a."}]},"takeaways":["Preguntas la nacionalidad con 你是哪国人？","Respondes con 我是 + país + 人."]},{"id":"zh-a1-u02-final","unit_id":"zh-a1-u02","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Quién eres y de dónde eres?».","intro":null,"takeaways":[]},{"id":"zh-a1-u03-l01","unit_id":"zh-a1-u03","position":1,"title_es":"一 a 五","objective_es":"Contar del uno al cinco.","intro":{"explanation":"一 (yī), 二 (èr), 三 (sān), 四 (sì), 五 (wǔ). Los tres primeros son una, dos y tres rayitas. Ojo con 四 (sì, baja) y 十 (shí, sube): suenan parecido.","examples":[{"target":"一，二，三。","base":"Uno, dos, tres."},{"target":"十五","base":"quince"}]},"takeaways":["Cuentas del uno al cinco.","Distingues 四 (sì) de 十 (shí) por el tono."]},{"id":"zh-a1-u03-l02","unit_id":"zh-a1-u03","position":2,"title_es":"六 a 十","objective_es":"Contar del seis al diez.","intro":{"explanation":"六 (liù), 七 (qī), 八 (bā), 九 (jiǔ), 十 (shí). 七 y 八 son primer tono, altos y parejos.","examples":[{"target":"六，七，八，九，十。","base":"Seis, siete, ocho, nueve, diez."},{"target":"十个学生","base":"diez estudiantes"}]},"takeaways":["Cuentas del seis al diez.","Reconoces los números de oído."]},{"id":"zh-a1-u03-l03","unit_id":"zh-a1-u03","position":4,"title_es":"Hasta veinte","objective_es":"Armar números con 十.","intro":{"explanation":"Del 11 al 19 se dice 十 + unidad: 十五 (15), 十八 (18). Las decenas, número + 十: 二十 (20). 十二 es 12 y 二十, 20: el orden importa.","examples":[{"target":"十五","base":"quince"},{"target":"二十","base":"veinte"}]},"takeaways":["Armas del 11 al 20 con 十.","Distingues 十二 (12) de 二十 (20)."]},{"id":"zh-a1-u03-l04","unit_id":"zh-a1-u03","position":5,"title_es":"你几岁？","objective_es":"Preguntar y decir la edad.","intro":{"explanation":"La edad se dice sin verbo: 我二十岁 «yo veinte años». A un chico se le pregunta 你几岁？ (几 es para números chicos); a un joven o adulto, 你多大？","examples":[{"target":"你多大？","base":"¿Qué edad tienes?"},{"target":"我十八岁。","base":"Tengo dieciocho años."},{"target":"你几岁？","base":"¿Cuántos años tienes?","note":"a un chico"}]},"takeaways":["Dices tu edad con número + 岁.","Preguntas 你多大？ a adultos y 你几岁？ a chicos."]},{"id":"zh-a1-u03-l05","unit_id":"zh-a1-u03","position":7,"title_es":"两 y 今年","objective_es":"Usar 两 para contar y decir tu edad este año.","intro":{"explanation":"Para contar cosas o medidas, «dos» es 两 (liǎng), no 二: 两岁 (dos años). 二 se usa al contar en voz alta y dentro de números como 十二 o 二十. 今年 es «este año».","examples":[{"target":"他两岁。","base":"Él tiene dos años."},{"target":"我今年十八岁。","base":"Tengo dieciocho años.","note":"literalmente «este año tengo»"}]},"takeaways":["Usas 两 para «dos» antes de una medida.","Dices tu edad con 今年 + número + 岁."]},{"id":"zh-a1-u04-l01","unit_id":"zh-a1-u04","position":1,"title_es":"爸爸妈妈","objective_es":"Nombrar a tu papá y tu mamá.","intro":{"explanation":"爸爸 (bàba) y 妈妈 (māma) son papá y mamá; la segunda sílaba es neutra. Con la familia cercana se dice 我妈妈 «mi mamá», sin nada en el medio. 家 es «familia» o «casa».","examples":[{"target":"我爸爸是老师。","base":"Mi papá es profesor."},{"target":"我妈妈很好。","base":"Mi mamá está bien."}]},"takeaways":["Nombras a tu papá y tu mamá.","Dices «mi mamá» con 我妈妈."]},{"id":"zh-a1-u04-l02","unit_id":"zh-a1-u04","position":2,"title_es":"哥哥、姐姐、弟弟、妹妹","objective_es":"Nombrar a tus hermanos según la edad.","intro":{"explanation":"En chino no hay una palabra para «hermano»: se dice si es mayor o menor. 哥哥 hermano mayor, 姐姐 hermana mayor, 弟弟 hermano menor, 妹妹 hermana menor.","examples":[{"target":"他是我哥哥。","base":"Él es mi hermano mayor."},{"target":"她是我妹妹。","base":"Ella es mi hermana menor."}]},"takeaways":["Nombras a tus hermanos según si son mayores o menores.","Presentas a un hermano con 他是我…."]},{"id":"zh-a1-u04-l03","unit_id":"zh-a1-u04","position":4,"title_es":"我有…","objective_es":"Decir cuántos hermanos tienes con 有 y 个.","intro":{"explanation":"有 (yǒu) es «tener». Para contar personas, entre el número y la palabra va 个: 两个哥哥 «dos hermanos mayores». «Dos» aquí es 两. Antes de 个, 一 se dice yí: 一个 (yí ge).","examples":[{"target":"我有两个哥哥。","base":"Tengo dos hermanos mayores."},{"target":"我有一个弟弟。","base":"Tengo un hermano menor.","note":"yí ge"}]},"takeaways":["Dices que tienes algo con 有.","Cuentas personas con número + 个."]},{"id":"zh-a1-u04-l04","unit_id":"zh-a1-u04","position":5,"title_es":"没有","objective_es":"Decir que no tienes algo y preguntar si alguien tiene.","intro":{"explanation":"有 se niega siempre con 没: 没有 (méiyǒu). «不有» no existe. Para preguntar: 你有姐姐吗？","examples":[{"target":"我没有妹妹。","base":"No tengo hermanas menores."},{"target":"你有姐姐吗？","base":"¿Tienes una hermana mayor?"}]},"takeaways":["Niegas 有 con 没有.","Preguntas si alguien tiene algo con 有…吗？"]},{"id":"zh-a1-u04-l05","unit_id":"zh-a1-u04","position":7,"title_es":"我的 y 我们家","objective_es":"Marcar de quién es algo con 的 y contar a tu familia.","intro":{"explanation":"的 (de) marca de quién es algo: 我的朋友 «mi amigo», 老师的家 «la casa del profesor». Con la familia cercana se suele omitir: 我妈妈. 我们家 es «nuestra familia».","examples":[{"target":"他是我的朋友。","base":"Él es mi amigo."},{"target":"我们家有四个人。","base":"En nuestra familia somos cuatro."}]},"takeaways":["Marcas de quién es algo con 的.","Dices cuántos son en tu familia con 家有 … 个人."]},{"id":"zh-a1-u05-l01","unit_id":"zh-a1-u05","position":1,"title_es":"这是什么？","objective_es":"Preguntar qué es algo con 这 y 那.","intro":{"explanation":"这 (zhè) es «esto / este» y 那 (nà) «eso / ese». Para preguntar qué es algo: 这是什么？ Se responde con la misma estructura: 这是书 «esto es un libro». Ojo: 那 (nà, cuarto tono) no es 哪 (nǎ, «¿cuál?»).","examples":[{"target":"这是什么？","base":"¿Qué es esto?"},{"target":"那是笔。","base":"Eso es un bolígrafo."}]},"takeaways":["Preguntas qué es algo con 这是什么？","Distingues 那 (nà) de 哪 (nǎ)."]},{"id":"zh-a1-u05-l02","unit_id":"zh-a1-u05","position":2,"title_es":"手机、包、电脑","objective_es":"Nombrar las cosas que llevas encima.","intro":{"explanation":"东西 (dōngxi) significa «cosa»: 那是什么东西？ «¿qué cosa es esa?». Con 的 dices de quién es: 我的手机 «mi celular».","examples":[{"target":"这是我的手机。","base":"Este es mi celular."},{"target":"那是什么东西？","base":"¿Qué cosa es esa?"}]},"takeaways":["Nombras celular, bolso y computadora.","Preguntas qué cosa es algo con 什么东西."]},{"id":"zh-a1-u05-l03","unit_id":"zh-a1-u05","position":4,"title_es":"三本书","objective_es":"Contar cosas con 本 y 个.","intro":{"explanation":"Para contar cosas, entre el número y la palabra va un clasificador. Los libros usan 本 (běn): 三本书. Para casi todo lo demás sirve 个: 一个包. Con 这 y 那 también: 这本书 «este libro».","examples":[{"target":"我有三本书。","base":"Tengo tres libros."},{"target":"这本书是中文书。","base":"Este libro es un libro en chino."}]},"takeaways":["Cuentas libros con 本.","Usas 个 para casi todo lo demás."]},{"id":"zh-a1-u05-l04","unit_id":"zh-a1-u05","position":5,"title_es":"一杯水","objective_es":"Contar bebidas con 杯.","intro":{"explanation":"杯 (bēi) es «vaso / taza» y también sirve para contar bebidas: 一杯水 «un vaso de agua». Antes de 杯 (primer tono), 一 se dice yì: yì bēi.","examples":[{"target":"我有一杯水。","base":"Tengo un vaso de agua.","note":"yì bēi"},{"target":"这是你的水吗？","base":"¿Esta es tu agua?"}]},"takeaways":["Cuentas bebidas con 杯.","Dices 一杯 como yì bēi."]},{"id":"zh-a1-u05-l05","unit_id":"zh-a1-u05","position":7,"title_es":"谁的？","objective_es":"Preguntar quién es alguien y de quién es algo.","intro":{"explanation":"谁 (shéi, también se oye shuí) es «quién». 谁的 es «de quién»: 这是谁的手机？ Se responde poniendo al dueño con 的: 是我的 «es mío».","examples":[{"target":"这是谁的书？","base":"¿De quién es este libro?"},{"target":"是我的。","base":"Es mío."}]},"takeaways":["Preguntas quién es alguien con 谁.","Preguntas de quién es algo con 谁的."]},{"id":"zh-a1-u06-l01","unit_id":"zh-a1-u06","position":1,"title_es":"你在哪儿？","objective_es":"Decir y preguntar dónde está alguien.","intro":{"explanation":"在 (zài) es «estar en» un lugar: 我在家 «estoy en casa». Para preguntar dónde: 你在哪儿？ El lugar va siempre después de 在, y 哪儿 ocupa el lugar de la respuesta.","examples":[{"target":"你在哪儿？","base":"¿Dónde estás?"},{"target":"我在家。","base":"Estoy en casa."}]},"takeaways":["Dices dónde estás con 在.","Preguntas dónde con 哪儿."]},{"id":"zh-a1-u06-l02","unit_id":"zh-a1-u06","position":2,"title_es":"这儿、那儿","objective_es":"Decir aquí y allá.","intro":{"explanation":"这儿 (zhèr) es «aquí» y 那儿 (nàr) «allá»: son 这 y 那 con 儿, la terminación típica del norte de China. 我在这儿 «estoy aquí».","examples":[{"target":"我在这儿。","base":"Estoy aquí."},{"target":"你的书在那儿。","base":"Tu libro está allá."}]},"takeaways":["Dices aquí con 这儿 y allá con 那儿.","Distingues 那儿 (nàr) de 哪儿 (nǎr)."]},{"id":"zh-a1-u06-l03","unit_id":"zh-a1-u06","position":4,"title_es":"房间、厨房","objective_es":"Nombrar partes y muebles de la casa.","intro":{"explanation":"房间 es la habitación y 厨房 la cocina. Muchas palabras de objetos terminan en 子 (zi, tono neutro): 桌子 mesa, 椅子 silla.","examples":[{"target":"妈妈在厨房。","base":"Mamá está en la cocina."},{"target":"我在房间里。","base":"Estoy en la habitación."}]},"takeaways":["Nombras habitación, cocina y muebles.","Reconoces el 子 neutro de 桌子 y 椅子."]},{"id":"zh-a1-u06-l04","unit_id":"zh-a1-u06","position":5,"title_es":"里 y 上","objective_es":"Decir que algo está dentro o encima de otra cosa.","intro":{"explanation":"里 (lǐ) es «dentro de» y 上 (shàng) «encima de». Van después del lugar: 书在包里 «el libro está en el bolso», 手机在桌子上 «el celular está sobre la mesa». Detrás del lugar suelen sonar en tono neutro (bāo li).","examples":[{"target":"书在包里。","base":"El libro está en el bolso."},{"target":"手机在桌子上。","base":"El celular está sobre la mesa."}]},"takeaways":["Ubicas cosas con 里 y 上.","Pones la posición después del lugar."]},{"id":"zh-a1-u06-l05","unit_id":"zh-a1-u06","position":7,"title_es":"下 y 有","objective_es":"Decir que algo está debajo y qué hay en un lugar.","intro":{"explanation":"下 (xià) es «debajo de»: 狗在桌子下 «el perro está debajo de la mesa». Para decir «hay» se pone primero el lugar y después 有: 桌子上有一本书 «sobre la mesa hay un libro».","examples":[{"target":"狗在桌子下。","base":"El perro está debajo de la mesa."},{"target":"厨房里有猫吗？","base":"¿Hay un gato en la cocina?"}]},"takeaways":["Ubicas cosas debajo con 下.","Dices qué hay con lugar + 有."]},{"id":"zh-a1-u07-l01","unit_id":"zh-a1-u07","position":1,"title_es":"吃和喝","objective_es":"Decir qué comes y qué tomas.","intro":{"explanation":"吃 (chī) es «comer» y 喝 (hē) «beber / tomar». El orden es como en español: 我吃米饭 «como arroz». El verbo no cambia con la persona ni con el tiempo.","examples":[{"target":"我吃米饭。","base":"Como arroz."},{"target":"你喝水吗？","base":"¿Tomas agua?"}]},"takeaways":["Dices qué comes con 吃 y qué tomas con 喝.","Preguntas con 吗 al final."]},{"id":"zh-a1-u07-l02","unit_id":"zh-a1-u07","position":2,"title_es":"茶、咖啡、牛奶","objective_es":"Nombrar bebidas.","intro":{"explanation":"Bebidas: 茶 (chá) té, 咖啡 (kāfēi) café y 牛奶 (niúnǎi) leche (literalmente «leche de vaca»). Se cuentan con 杯: 一杯茶.","examples":[{"target":"我喝茶。","base":"Tomo té."},{"target":"一杯咖啡","base":"un café (una taza)","note":"yì bēi"}]},"takeaways":["Nombras té, café y leche.","Cuentas bebidas con 杯."]},{"id":"zh-a1-u07-l03","unit_id":"zh-a1-u07","position":4,"title_es":"我要…","objective_es":"Pedir algo con 要 y rechazarlo con 不要.","intro":{"explanation":"要 (yào) es «querer» para pedir algo concreto: 我要一杯茶 «quiero un té». Es lo más común en un restaurante o una tienda. Para decir que no: 不要; como 要 es cuarto tono, 不 se dice bú.","examples":[{"target":"我要一杯咖啡。","base":"Quiero un café."},{"target":"我不要牛奶。","base":"No quiero leche.","note":"bú yào"}]},"takeaways":["Pides con 要.","Rechazas con 不要 (bú yào)."]},{"id":"zh-a1-u07-l04","unit_id":"zh-a1-u07","position":5,"title_es":"我想…","objective_es":"Decir qué tienes ganas de comer y que tienes hambre.","intro":{"explanation":"想 (xiǎng) + verbo es «tener ganas de»: 我想吃饺子 «tengo ganas de comer jiaozi». 饿 (è) es «tener hambre» y funciona como un adjetivo: va con 很 y sin 是: 我很饿.","examples":[{"target":"我很饿。","base":"Tengo hambre."},{"target":"我想吃面条。","base":"Tengo ganas de comer fideos."}]},"takeaways":["Dices qué tienes ganas de comer con 想.","Dices que tienes hambre con 我很饿."]},{"id":"zh-a1-u07-l05","unit_id":"zh-a1-u07","position":7,"title_es":"好吃！","objective_es":"Decir que algo está rico.","intro":{"explanation":"好吃 (hǎochī) es «rico» para la comida: 好 + 吃. Para la bebida se dice 好喝. Como todo adjetivo, va con 很: 饺子很好吃.","examples":[{"target":"饺子很好吃。","base":"Los jiaozi son muy ricos."},{"target":"苹果好吃吗？","base":"¿Las manzanas son ricas?"}]},"takeaways":["Dices que algo está rico con 好吃.","Usas 好喝 para las bebidas."]},{"id":"zh-a1-u08-l01","unit_id":"zh-a1-u08","position":1,"title_es":"早上","objective_es":"Contar cómo empieza tu día.","intro":{"explanation":"起床 (qǐchuáng) es «levantarse». 早饭 (zǎofàn) es «desayuno»: 吃早饭 es «desayunar». 早上 (zǎoshang) «por la mañana» va antes del verbo: 我早上起床.","examples":[{"target":"我早上起床。","base":"Me levanto por la mañana."},{"target":"早上我吃早饭。","base":"Por la mañana desayuno."}]},"takeaways":["Dices que te levantas con 起床.","Pones el tiempo antes del verbo."]},{"id":"zh-a1-u08-l02","unit_id":"zh-a1-u08","position":2,"title_es":"工作和学习","objective_es":"Decir si trabajas o estudias.","intro":{"explanation":"工作 (gōngzuò) es «trabajar» y también «trabajo». 学习 (xuéxí) es «estudiar»: 学 es el mismo de 学生 (estudiante). 在家 (zài jiā) es «en casa» y va antes del verbo: 我在家工作.","examples":[{"target":"他在家工作。","base":"Él trabaja en casa."},{"target":"我学习中文。","base":"Estudio chino."}]},"takeaways":["Dices si trabajas o estudias.","Dices dónde con 在家 antes del verbo."]},{"id":"zh-a1-u08-l03","unit_id":"zh-a1-u08","position":4,"title_es":"看和说","objective_es":"Decir qué miras, lees y hablas.","intro":{"explanation":"看 (kàn) es «mirar»: 看电视 «mirar la tele». Con un libro es «leer»: 看书. 说 (shuō) es «hablar, decir»: 说中文 «hablar chino».","examples":[{"target":"我晚上看电视。","base":"Por la noche miro la tele."},{"target":"你说中文吗？","base":"¿Hablas chino?"}]},"takeaways":["Usas 看 para mirar la tele y leer un libro.","Dices qué idioma hablas con 说."]},{"id":"zh-a1-u08-l04","unit_id":"zh-a1-u08","position":5,"title_es":"下午和晚上","objective_es":"Ubicar lo que haces en la tarde y en la noche.","intro":{"explanation":"下午 (xiàwǔ) es «por la tarde» y 晚上 (wǎnshang) «por la noche». 做饭 (zuò fàn) es «cocinar» y 睡觉 (shuìjiào) «dormir». Todos van con el tiempo adelante: 我晚上做饭.","examples":[{"target":"我下午工作。","base":"Por la tarde trabajo."},{"target":"我晚上做饭。","base":"Por la noche cocino."}]},"takeaways":["Dices qué haces por la tarde y por la noche.","Dices que cocinas y que duermes."]},{"id":"zh-a1-u08-l05","unit_id":"zh-a1-u08","position":7,"title_es":"每天","objective_es":"Contar tu rutina en orden.","intro":{"explanation":"每天 (měitiān) es «todos los días»; 常常 (chángcháng) «seguido»; 然后 (ránhòu) «después». 每天 y 常常 van antes del verbo: 我每天学习, 我常常做饭.","examples":[{"target":"我每天学习中文。","base":"Estudio chino todos los días."},{"target":"我起床，然后吃早饭。","base":"Me levanto y después desayuno."}]},"takeaways":["Cuentas tu rutina con 每天 y 然后.","Pones 常常 antes del verbo."]},{"id":"zh-a1-u09-l01","unit_id":"zh-a1-u09","position":1,"title_es":"现在几点？","objective_es":"Preguntar y decir la hora en punto.","intro":{"explanation":"现在 (xiànzài) es «ahora». Para preguntar la hora: 现在几点？ Se responde con número + 点: 现在八点. No hace falta verbo. Las dos son 两点, no 二点.","examples":[{"target":"现在几点？","base":"¿Qué hora es?"},{"target":"现在两点。","base":"Son las dos.","note":"liǎng diǎn"}]},"takeaways":["Preguntas la hora con 现在几点？","Dices la hora con número + 点 (y 两点)."]},{"id":"zh-a1-u09-l02","unit_id":"zh-a1-u09","position":2,"title_es":"半和分","objective_es":"Decir la hora con media y con minutos.","intro":{"explanation":"Y media es 半 (bàn): 三点半. Los minutos son número + 分 (fēn): 八点十分 «ocho y diez». La hora siempre va antes que los minutos.","examples":[{"target":"现在三点半。","base":"Son las tres y media."},{"target":"八点十分","base":"las ocho y diez"}]},"takeaways":["Dices y media con 半.","Dices minutos con 分."]},{"id":"zh-a1-u09-l03","unit_id":"zh-a1-u09","position":4,"title_es":"几点…？","objective_es":"Decir a qué hora haces algo.","intro":{"explanation":"Para decir a qué hora haces algo, la hora va antes del verbo, como las demás palabras de tiempo: 我七点起床 «me levanto a las siete». Para preguntar: 你几点工作？","examples":[{"target":"我七点起床。","base":"Me levanto a las siete."},{"target":"你几点工作？","base":"¿A qué hora trabajas?"}]},"takeaways":["Dices a qué hora haces algo con la hora antes del verbo.","Preguntas con 几点 + verbo."]},{"id":"zh-a1-u09-l04","unit_id":"zh-a1-u09","position":5,"title_es":"星期几？","objective_es":"Nombrar los días de la semana.","intro":{"explanation":"Los días son 星期 (xīngqī, «semana») + número: 星期一 lunes, 星期二 martes… hasta 星期六 sábado. El domingo es 星期天. Para preguntar el día: 今天星期几？ (sin verbo).","examples":[{"target":"今天星期几？","base":"¿Qué día es hoy?"},{"target":"今天星期一。","base":"Hoy es lunes."}]},"takeaways":["Nombras los días con 星期 + número.","Sabes que el domingo es 星期天."]},{"id":"zh-a1-u09-l05","unit_id":"zh-a1-u09","position":7,"title_es":"今天、明天、昨天","objective_es":"Hablar de hoy, mañana, ayer y la fecha.","intro":{"explanation":"今天 (jīntiān) hoy, 明天 (míngtiān) mañana, 昨天 (zuótiān) ayer: los tres terminan en 天 «día». La fecha va de grande a chico: mes + 月, día + 号. 五月三号 es «3 de mayo».","examples":[{"target":"明天星期六。","base":"Mañana es sábado."},{"target":"今天五月三号。","base":"Hoy es 3 de mayo."}]},"takeaways":["Distingues 今天, 明天 y 昨天.","Dices la fecha con 月 y 号."]},{"id":"zh-a1-u10-l01","unit_id":"zh-a1-u10","position":1,"title_es":"你去哪儿？","objective_es":"Decir adónde vas.","intro":{"explanation":"去 (qù) es «ir». Va directo con el lugar, sin «a»: 我去商店 «voy a la tienda». Para preguntar adónde: 你去哪儿？ (哪儿 va donde iría el lugar).","examples":[{"target":"你去哪儿？","base":"¿Adónde vas?"},{"target":"我去学校。","base":"Voy a la escuela."}]},"takeaways":["Dices adónde vas con 去 + lugar.","Preguntas adónde con 去哪儿？"]},{"id":"zh-a1-u10-l02","unit_id":"zh-a1-u10","position":2,"title_es":"医院和饭馆","objective_es":"Nombrar más lugares y decir que alguien viene.","intro":{"explanation":"医院 (yīyuàn) es «hospital» y 饭馆 (fànguǎn) «restaurante» (饭 es comida, como en 米饭). 来 (lái) es «venir»: 你来我家吗？ Las ciudades van igual: 我去北京.","examples":[{"target":"饭馆在那儿。","base":"El restaurante está allá."},{"target":"你来我家吗？","base":"¿Vienes a mi casa?"}]},"takeaways":["Nombras hospital y restaurante.","Distingues 去 (ir) y 来 (venir)."]},{"id":"zh-a1-u10-l03","unit_id":"zh-a1-u10","position":4,"title_es":"坐地铁","objective_es":"Decir en qué vas.","intro":{"explanation":"坐 (zuò) es «sentarse» y también «tomar» un transporte: 坐地铁 «tomar el metro», 坐公交车 «tomar el autobús», 坐出租车 «tomar un taxi». El transporte va antes de 去: 我坐地铁去学校.","examples":[{"target":"我坐地铁去学校。","base":"Voy a la escuela en metro."},{"target":"我坐出租车去医院。","base":"Voy al hospital en taxi."}]},"takeaways":["Nombras metro, autobús y taxi.","Dices en qué vas con 坐 + vehículo + 去."]},{"id":"zh-a1-u10-l04","unit_id":"zh-a1-u10","position":5,"title_es":"怎么去？","objective_es":"Preguntar y decir cómo vas.","intro":{"explanation":"怎么 (zěnme) es «¿cómo?» y va antes del verbo: 你怎么去？ «¿cómo vas?». Para decir que vas caminando: 走路 (zǒulù) + 去: 我走路去超市.","examples":[{"target":"你怎么去学校？","base":"¿Cómo vas a la escuela?"},{"target":"我走路去。","base":"Voy caminando."}]},"takeaways":["Preguntas cómo con 怎么 + verbo.","Dices que vas caminando con 走路去."]},{"id":"zh-a1-u10-l05","unit_id":"zh-a1-u10","position":7,"title_es":"远吗？","objective_es":"Decir si un lugar queda cerca o lejos.","intro":{"explanation":"远 (yuǎn) es «lejos» y 近 (jìn) «cerca». Como los adjetivos, van con 很 y sin 是: 医院很远 «el hospital queda (muy) lejos». Se niegan con 不: 不远.","examples":[{"target":"超市很近。","base":"El supermercado queda muy cerca."},{"target":"医院远吗？不远。","base":"¿El hospital queda lejos? No."}]},"takeaways":["Dices si algo está cerca o lejos.","Usas 很 y no 是 con 远 y 近."]},{"id":"zh-a1-u11-l01","unit_id":"zh-a1-u11","position":1,"title_es":"我喜欢…","objective_es":"Decir lo que te gusta y lo que no.","intro":{"explanation":"喜欢 (xǐhuan) es «gustar», pero se usa como un verbo común: 我喜欢猫 es «me gustan los gatos» (literalmente «yo gusto gatos»). Para negar, 不 va antes: 我不喜欢…","examples":[{"target":"我喜欢猫。","base":"Me gustan los gatos."},{"target":"我不喜欢牛奶。","base":"No me gusta la leche."}]},"takeaways":["Dices lo que te gusta con 喜欢.","Niegas con 不喜欢."]},{"id":"zh-a1-u11-l02","unit_id":"zh-a1-u11","position":2,"title_es":"唱歌和跳舞","objective_es":"Hablar de pasatiempos.","intro":{"explanation":"Muchas actividades son verbo + cosa: 唱歌 «cantar» (cantar canciones), 跳舞 «bailar», 踢足球 «jugar al fútbol» (patear la pelota). Van después de 喜欢: 我喜欢跳舞.","examples":[{"target":"我喜欢跳舞。","base":"Me gusta bailar."},{"target":"他非常喜欢踢足球。","base":"A él le encanta jugar al fútbol."}]},"takeaways":["Nombras pasatiempos.","Dices que algo te encanta con 非常喜欢."]},{"id":"zh-a1-u11-l03","unit_id":"zh-a1-u11","position":4,"title_es":"我会游泳","objective_es":"Decir lo que sabes hacer.","intro":{"explanation":"会 (huì) es «saber hacer» algo que se aprende: nadar, manejar, un idioma. Va antes del verbo: 我会游泳. Se niega con 不, que antes del cuarto tono de 会 se dice bú: 我不会开车 (wǒ bú huì kāichē).","examples":[{"target":"我会游泳。","base":"Sé nadar."},{"target":"你会说中文吗？","base":"¿Sabes hablar chino?"}]},"takeaways":["Dices lo que sabes hacer con 会.","Dices lo que no sabes con 不会."]},{"id":"zh-a1-u11-l04","unit_id":"zh-a1-u11","position":5,"title_es":"你能来吗？","objective_es":"Decir si puedes hacer algo.","intro":{"explanation":"能 (néng) es «poder»: si es posible en ese momento. 我今天不能去 «hoy no puedo ir». Compara: 我会游泳 (sé nadar) y 今天我不能游泳 (hoy no puedo nadar).","examples":[{"target":"明天你能来吗？","base":"¿Mañana puedes venir?"},{"target":"今天我不能去。","base":"Hoy no puedo ir."}]},"takeaways":["Preguntas si alguien puede con 能…吗？","Distingues 会 (saber) y 能 (poder)."]},{"id":"zh-a1-u11-l05","unit_id":"zh-a1-u11","position":7,"title_es":"我很忙","objective_es":"Decir cómo estás y describir cosas.","intro":{"explanation":"Los adjetivos van con 很 y sin 是: 我很忙 «estoy (muy) ocupado/a», 这个房间很大 «esta habitación es grande». 很 casi no suma «muy»: es lo normal. Para «muchísimo», 非常: 我非常累.","examples":[{"target":"我今天很忙。","base":"Hoy estoy ocupado/a."},{"target":"我的房间很小。","base":"Mi habitación es chica."}]},"takeaways":["Dices cómo estás con 很 + adjetivo.","Describes cosas como grandes o chicas."]},{"id":"zh-a1-u12-l01","unit_id":"zh-a1-u12","position":1,"title_es":"多少钱？","objective_es":"Preguntar y entender precios.","intro":{"explanation":"多少钱 (duōshao qián) es «¿cuánto cuesta?»: va después de la cosa, 这个多少钱？ En la charla la moneda (el yuan) se dice 块 (kuài) y va después del número: 十块, 二十块.","examples":[{"target":"这个多少钱？","base":"¿Cuánto cuesta esto?"},{"target":"二十块。","base":"Veinte yuanes."}]},"takeaways":["Preguntas el precio con 多少钱？","Entiendes precios con 块."]},{"id":"zh-a1-u12-l02","unit_id":"zh-a1-u12","position":2,"title_es":"一件衣服","objective_es":"Nombrar ropa y comprar.","intro":{"explanation":"衣服 (yīfu) es «ropa» y 鞋 (xié) «zapatos». Con números y con 这 / 那 llevan su clasificador: 一件衣服 (una prenda), 一双鞋 (un par de zapatos). 买 (mǎi) es «comprar».","examples":[{"target":"这件衣服很漂亮。","base":"Esta prenda es muy linda."},{"target":"我买这双鞋。","base":"Compro estos zapatos."}]},"takeaways":["Nombras ropa y zapatos.","Usas los clasificadores 件 y 双."]},{"id":"zh-a1-u12-l03","unit_id":"zh-a1-u12","position":4,"title_es":"太贵了！","objective_es":"Opinar sobre un precio.","intro":{"explanation":"贵 (guì) es «caro» y 便宜 (piányi) «barato»; como los adjetivos, van con 很: 这个很便宜. Para «demasiado»: 太 + adjetivo + 了: 太贵了！ 一共 (yígòng) es «en total».","examples":[{"target":"九十块？太贵了！","base":"¿Noventa yuanes? ¡Es carísimo!"},{"target":"一共五十块。","base":"En total, cincuenta yuanes."}]},"takeaways":["Dices si algo es caro o barato.","Te quejas del precio con 太贵了！"]},{"id":"zh-a1-u12-l04","unit_id":"zh-a1-u12","position":5,"title_es":"怎么样？","objective_es":"Pedir y dar una opinión.","intro":{"explanation":"怎么样 (zěnmeyàng) va al final y pregunta «¿qué tal?»: 这件衣服怎么样？ Para festejar, 太好了！ («¡buenísimo!»): 太 + 好 + 了.","examples":[{"target":"这双鞋怎么样？——很漂亮！","base":"¿Qué tal estos zapatos? — ¡Muy lindos!"},{"target":"你能来？太好了！","base":"¿Puedes venir? ¡Buenísimo!"}]},"takeaways":["Pides una opinión con 怎么样？","Festejas con 太好了！"]},{"id":"zh-a1-u12-l05","unit_id":"zh-a1-u12","position":7,"title_es":"买和卖・你呢？","objective_es":"Distinguir comprar y vender, y preguntar «¿y…?».","intro":{"explanation":"Sólo el tono separa 买 (mǎi, tercer tono) «comprar» y 卖 (mài, cuarto tono) «vender». 呢 (ne) al final pregunta «¿y…?»: 我很好，你呢？, 我的手机呢？ («¿y mi celular?», «¿dónde está?»).","examples":[{"target":"他卖苹果，我买苹果。","base":"Él vende manzanas y yo compro manzanas."},{"target":"我的手机呢？","base":"¿Y mi celular?"}]},"takeaways":["Distingues 买 y 卖 por el tono.","Preguntas «¿y…?» con 呢."]},{"id":"a1-u01-context","unit_id":"a1-u01","position":11,"title_es":"En contexto: un primer encuentro","objective_es":"Entender un saludo escrito y una presentación oral.","intro":{"explanation":"Vas a leer un mensaje y a escuchar a dos personas que se conocen. No hace falta entender cada palabra: busca quién habla, cuándo y qué quiere.","examples":[{"target":"Nice to meet you.","base":"Encantado de conocerte."},{"target":"Fine, thank you. And you?","base":"Bien, gracias. ¿Y tú?"}]},"takeaways":["Ahora puedes entender quién saluda, cuándo y qué pregunta en un mensaje corto."]},{"id":"a1-u02-context","unit_id":"a1-u02","position":11,"title_es":"En contexto: ¿quién es quién?","objective_es":"Entender una ficha sobre personas y preguntas con «to be» dirigidas a ti.","intro":{"explanation":"Vas a leer una ficha sobre dos personas y a escuchar a una profesora que te hace preguntas. Fíjate en quién es quién y en qué te preguntan a ti.","examples":[{"target":"He is not happy.","base":"Él no está contento."},{"target":"Are you a student?","base":"¿Eres estudiante?"}]},"takeaways":["Ahora puedes entender quién es quién en un texto corto y qué te preguntan con «to be»."]},{"id":"a1-u03-context","unit_id":"a1-u03","position":11,"title_es":"En contexto: tarjetas de jugadores","objective_es":"Entender datos de jugadores: número, edad y país.","intro":{"explanation":"Vas a leer las tarjetas de tres jugadores de un equipo infantil y a escuchar a un entrenador hablar con un chico nuevo. Presta atención a los números.","examples":[{"target":"I am from Mexico.","base":"Soy de México."},{"target":"He is twelve years old.","base":"Tiene doce años."}]},"takeaways":["Ahora puedes encontrar y comparar números, edades y países en un texto corto."]},{"id":"a1-u04-context","unit_id":"a1-u04","position":11,"title_es":"En contexto: la familia de Ana","objective_es":"Entender una descripción y una conversación sobre una familia.","intro":{"explanation":"Vas a leer cómo describe Ana a su familia y a escuchar una conversación sobre una foto. Fíjate en las relaciones: quién es hermano, abuela o bebé de quién.","examples":[{"target":"My sister has a baby.","base":"Mi hermana tiene un bebé."},{"target":"Who is he?","base":"¿Quién es él?"}]},"takeaways":["Ahora puedes entender quién es quién en una familia descripta en inglés."]},{"id":"a1-u05-context","unit_id":"a1-u05","position":11,"title_es":"En contexto: ¿cuál es el tuyo?","objective_es":"Entender mensajes sobre objetos: de quién son, cómo son.","intro":{"explanation":"Vas a leer un mensaje y escuchar una conversación sobre cosas que alguien encontró. Fíjate en el color, el tamaño y de quién es cada cosa.","examples":[{"target":"Is this your book?","base":"¿Este es tu libro?"},{"target":"That phone is black.","base":"Ese teléfono es negro."}]},"takeaways":["Ahora puedes entender de quién es un objeto y cómo es, en un mensaje corto."]},{"id":"a1-u06-context","unit_id":"a1-u06","position":11,"title_es":"En contexto: un apartamento en alquiler","objective_es":"Entender un aviso de alquiler y dónde está cada cosa.","intro":{"explanation":"Vas a leer un aviso de un apartamento y a escuchar a la dueña mostrarlo. Busca cuántas habitaciones hay y dónde está cada cosa.","examples":[{"target":"There are two bedrooms.","base":"Hay dos dormitorios."},{"target":"The keys are on the table.","base":"Las llaves están sobre la mesa."}]},"takeaways":["Ahora puedes entender qué tiene una casa y dónde está cada cosa."]},{"id":"a1-u07-context","unit_id":"a1-u07","position":11,"title_es":"En contexto: en el café","objective_es":"Entender un menú y un pedido en un café.","intro":{"explanation":"Vas a leer el menú de un café y a escuchar a una clienta pedir. Fíjate qué hay en cada comida del día y qué pide ella.","examples":[{"target":"I want eggs and bread, please.","base":"Quiero huevos y pan, por favor."},{"target":"Are you hungry?","base":"¿Tienes hambre?"}]},"takeaways":["Ahora puedes entender un menú sencillo y un pedido en un café."]},{"id":"a1-u08-context","unit_id":"a1-u08","position":11,"title_es":"En contexto: la semana de Tom","objective_es":"Entender un mensaje escrito y uno de voz sobre rutinas.","intro":{"explanation":"Vas a leer un mensaje de Tom sobre su rutina y a escuchar un mensaje de voz que le deja a su mamá. Fíjate qué hace siempre, qué no hace y dónde.","examples":[{"target":"I never watch TV.","base":"Nunca miro televisión."},{"target":"She doesn't work.","base":"Ella no trabaja."}]},"takeaways":["Ahora puedes entender qué hace alguien todos los días y qué no hace nunca."]},{"id":"a1-u09-context","unit_id":"a1-u09","position":11,"title_es":"En contexto: el programa del museo","objective_es":"Entender un horario y un anuncio con días y horas.","intro":{"explanation":"Vas a leer el horario de un museo y a escuchar un anuncio. Busca qué días abre, a qué hora y cuándo cierra.","examples":[{"target":"The museum opens at nine o'clock.","base":"El museo abre a las nueve."},{"target":"at half past ten","base":"a las diez y media"}]},"takeaways":["Ahora puedes encontrar días y horarios en un programa y en un anuncio."]},{"id":"a1-u10-context","unit_id":"a1-u10","position":11,"title_es":"En contexto: ¿cómo llego?","objective_es":"Entender carteles e indicaciones para llegar a un lugar.","intro":{"explanation":"Vas a leer un cartel, escuchar a alguien que pide indicaciones en la calle y seguir unas indicaciones escritas. Fíjate hacia dónde hay que ir y si queda cerca o lejos.","examples":[{"target":"Go straight on and turn left.","base":"Sigue derecho y dobla a la izquierda."},{"target":"The hotel is far.","base":"El hotel queda lejos."}]},"takeaways":["Ahora puedes entender indicaciones sencillas para llegar a un lugar."]},{"id":"a1-u11-context","unit_id":"a1-u11","position":11,"title_es":"En contexto: una publicación sobre hobbies","objective_es":"Entender una publicación y una conversación sobre gustos.","intro":{"explanation":"Vas a leer lo que cuenta Lily sobre sus pasatiempos y a escuchar a dos amigos hablar de lo que les gusta. Fíjate qué les encanta, qué odian y qué saben hacer.","examples":[{"target":"I can't play football.","base":"No sé jugar al fútbol."},{"target":"My favorite sport is swimming.","base":"Mi deporte favorito es la natación."}]},"takeaways":["Ahora puedes entender qué le gusta a alguien, qué odia y qué sabe hacer."]},{"id":"a1-u12-context","unit_id":"a1-u12","position":11,"title_es":"En contexto: una conversación completa","objective_es":"Entender una conversación en clase y las preguntas que te hacen a ti.","intro":{"explanation":"Vas a escuchar a una profesora que te habla a ti y una conversación en clase. Fíjate qué te pregunta, qué te pide y qué problema tiene cada uno.","examples":[{"target":"I don't understand.","base":"No entiendo."},{"target":"Can you speak slowly, please?","base":"¿Puedes hablar más despacio, por favor?"}]},"takeaways":["Ahora puedes entender cuándo alguien no entiende y qué pide para resolverlo."]},{"id":"a1-u13-context","unit_id":"a1-u13","position":11,"title_es":"En contexto: registro en un hotel","objective_es":"Entender una ficha de registro y las preguntas de un recepcionista.","intro":{"explanation":"Vas a leer la ficha de registro de Sofia Ruiz, una huésped inventada, y a escuchar al recepcionista del hotel. En el audio la huésped eres tú: presta atención a qué te pregunta y qué te pide.","examples":[{"target":"What is your surname?","base":"¿Cuál es tu apellido?"},{"target":"How do you spell it?","base":"¿Cómo se escribe?"}]},"takeaways":["Ahora puedes entender los datos de una ficha de hotel y lo que te pregunta un recepcionista."]},{"id":"a1-u14-context","unit_id":"a1-u14","position":11,"title_es":"En contexto: cliente y vendedor","objective_es":"Entender precios en un cartel, una compra en una tienda y un anuncio.","intro":{"explanation":"Vas a leer los precios de una tienda, a escuchar a un cliente con la vendedora y un anuncio de un supermercado. Fíjate en qué se compra y cuánto cuesta.","examples":[{"target":"How much is this bag?","base":"¿Cuánto cuesta esta bolsa?"},{"target":"I'd like a white cup, please.","base":"Quisiera una taza blanca, por favor."}]},"takeaways":["Ahora puedes entender precios, qué pide un cliente y cuánto paga."]},{"id":"a1-u13-l01","unit_id":"a1-u13","position":1,"title_es":"El alfabeto","objective_es":"Reconocer las letras del alfabeto inglés por su nombre.","intro":{"explanation":"Las letras se escriben igual que en español, pero sus nombres suenan distinto: la A se dice «éi», la E «i» y la I «ái». Las que más se confunden son la E y la I, y la G («yi») y la J («yéi»).","examples":[{"target":"A, E, I.","base":"A, E, I (se dicen «éi», «i», «ái»)."},{"target":"My name is Ana: A-N-A.","base":"Me llamo Ana: A-N-A."}]},"takeaways":["Reconoces las letras del alfabeto inglés por su nombre.","Distingues de oído la E de la I y la G de la J."]},{"id":"a1-u13-l02","unit_id":"a1-u13","position":2,"title_es":"Deletrear","objective_es":"Pedir que alguien deletree y entender un nombre deletreado.","intro":{"explanation":"Para pedir que te deletreen una palabra se pregunta How do you spell it? (¿cómo se escribe?). Se responde letra por letra, y dos letras iguales seguidas se dicen con double: Ross es R-O-double S.","examples":[{"target":"How do you spell it?","base":"¿Cómo se escribe?"},{"target":"Ross: R-O-double S.","base":"Ross: R-O-doble S."}]},"takeaways":["Preguntas cómo se escribe algo con How do you spell it?","Deletreas un nombre y usas double para las letras repetidas."]},{"id":"a1-u13-l03","unit_id":"a1-u13","position":4,"title_es":"Nacionalidades","objective_es":"Decir la nacionalidad y preguntar la de otra persona.","intro":{"explanation":"El país es Mexico; la nacionalidad, Mexican. En inglés las nacionalidades van siempre con mayúscula: I am Argentinian. Spanish y English son también los nombres de los idiomas. Para preguntarla: What is your nationality?","examples":[{"target":"I am Mexican.","base":"Soy mexicano."},{"target":"She is from Spain. She is Spanish.","base":"Es de España. Es española."},{"target":"What is your nationality?","base":"¿Cuál es tu nacionalidad?"}]},"takeaways":["Dices la nacionalidad con to be y mayúscula: I am Argentinian.","Preguntas la nacionalidad con What is your nationality?"]},{"id":"a1-u13-l04","unit_id":"a1-u13","position":5,"title_es":"Teléfono, email y dirección","objective_es":"Entender y pedir un número de teléfono, un correo y una dirección.","intro":{"explanation":"Para pedir un dato se usa What is your…?: What is your phone number? What is your email? What is your address? Los números de teléfono se dicen cifra por cifra. Los datos de esta lección son de Sofia Ruiz, una persona inventada.","examples":[{"target":"What is your phone number?","base":"¿Cuál es tu número de teléfono?"},{"target":"What is your email?","base":"¿Cuál es tu correo electrónico?"}]},"takeaways":["Pides un teléfono, un correo o una dirección con What is your…?","Reconoces un número de teléfono y un correo en un texto."]},{"id":"a1-u13-l05","unit_id":"a1-u13","position":7,"title_es":"Completar un formulario","objective_es":"Completar y leer un formulario con datos personales.","intro":{"explanation":"Un formulario (form) pide los datos campo por campo: First name es el nombre de pila; Surname, el apellido; Age, la edad, y City, la ciudad. Se completa con el dato solo, sin oración: Surname: Ruiz. Practicas con el formulario de Sofia Ruiz, una persona inventada.","examples":[{"target":"First name: Sofia. Surname: Ruiz.","base":"Nombre: Sofia. Apellido: Ruiz."},{"target":"What is your surname?","base":"¿Cuál es tu apellido?"}]},"takeaways":["Entiendes los campos de un formulario: first name, surname, age, city.","Sacas de un formulario el dato que te piden."]},{"id":"a1-u14-l01","unit_id":"a1-u14","position":1,"title_es":"Del 21 al 100","objective_es":"Contar de diez en diez hasta cien y armar los números del 21 al 99.","intro":{"explanation":"Las decenas terminan en -ty: thirty (30), forty (40), fifty (50). Forty se escribe sin u, aunque four la lleva. Del 21 al 99 se unen con guion: twenty-one, thirty-five. El 100 es one hundred.","examples":[{"target":"Thirty-five students.","base":"Treinta y cinco estudiantes."},{"target":"My grandmother is ninety.","base":"Mi abuela tiene noventa años."}]},"takeaways":["Cuentas de diez en diez hasta one hundred.","Armas los números del 21 al 99 con guion: forty-two."]},{"id":"a1-u14-l02","unit_id":"a1-u14","position":2,"title_es":"Precios y dinero","objective_es":"Decir y entender precios en dólares y centavos.","intro":{"explanation":"El símbolo va antes del número ($5), pero se dice después: five dollars. Un dólar tiene cien centavos (cents). Para decir un precio alcanza con to be: The book is twenty dollars. Algo barato es cheap y algo caro, expensive.","examples":[{"target":"The book is twenty dollars.","base":"El libro cuesta veinte dólares."},{"target":"A big bag, ten dollars? It is cheap!","base":"¿Una bolsa grande a diez dólares? ¡Es barata!"}]},"takeaways":["Dices un precio con to be: The coffee is three dollars.","Entiendes de oído precios con dólares y centavos."]},{"id":"a1-u14-l03","unit_id":"a1-u14","position":4,"title_es":"How much, how many","objective_es":"Preguntar precios y cantidades con how much y how many.","intro":{"explanation":"How much pregunta un precio: How much is the bag? How many va con cosas que se cuentan, en plural: How many apples are there? Se responde con el número: There are three apples. / It is ten dollars.","examples":[{"target":"How much is the bag?","base":"¿Cuánto cuesta la bolsa?"},{"target":"How many cups are there?","base":"¿Cuántas tazas hay?"}]},"takeaways":["Preguntas un precio con How much is…?","Preguntas una cantidad con How many + plural."]},{"id":"a1-u14-l04","unit_id":"a1-u14","position":5,"title_es":"Una taza de, una botella de","objective_es":"Pedir cantidades de comida y bebida con I’d like.","intro":{"explanation":"Para pedir una cantidad: a cup of + bebida (a cup of tea), a glass of (water), a bottle of (milk), a kilo of (apples). Para pedir con cortesía se usa I'd like (quisiera): es más amable que I want.","examples":[{"target":"I'd like a cup of tea, please.","base":"Quisiera una taza de té, por favor."},{"target":"Two bottles of water.","base":"Dos botellas de agua."}]},"takeaways":["Pides cantidades con a cup of, a glass of, a bottle of y a kilo of.","Pides con cortesía con I'd like."]},{"id":"a1-u14-l05","unit_id":"a1-u14","position":7,"title_es":"En la tienda","objective_es":"Pedir, preguntar el precio y pagar en una tienda.","intro":{"explanation":"En una tienda se pide con I'd like y se pregunta el precio con How much is it? El vendedor pregunta Anything else? (¿algo más?). Si no quieres nada más: No, that's all, thank you. Al pagar o entregar algo se dice Here you are (aquí tiene).","examples":[{"target":"Anything else?","base":"¿Algo más?"},{"target":"No, that's all. Here you are.","base":"No, eso es todo. Aquí tiene."}]},"takeaways":["Haces un pedido completo: I'd like…, How much is it?, That's all.","Entiendes lo que pregunta el vendedor y respondes con Here you are al pagar."]},{"id":"a1-u05-l06","unit_id":"a1-u05","position":12,"title_es":"Uno, dos, muchos","objective_es":"Formar plurales regulares e irregulares frecuentes.","intro":{"explanation":"Casi siempre el plural se forma con -s: one book, two books. Algunas palabras muy usadas cambian: man → men, woman → women. Children (niños) y people (personas) ya son plurales.","examples":[{"target":"one pen, three pens","base":"un bolígrafo, tres bolígrafos"},{"target":"These women are teachers.","base":"Estas mujeres son profesoras."}]},"takeaways":["Formas el plural con -s: books, keys.","Usas men, women, children y people."]},{"id":"a1-u09-l06","unit_id":"a1-u09","position":12,"title_es":"Meses y fechas","objective_es":"Decir los meses y las fechas, y preguntar cuándo es algo.","intro":{"explanation":"Los meses se escriben con mayúscula. Con el mes solo se usa in (in May); con la fecha, on (on May third). En la fecha se dice el número ordinal: first, second, third, fourth, fifth… (del 4 en adelante, casi siempre -th).","examples":[{"target":"My birthday is in May.","base":"Mi cumpleaños es en mayo."},{"target":"It is on May third.","base":"Es el 3 de mayo."}]},"takeaways":["Dices los doce meses.","Usas in con el mes y on con la fecha.","Dices una fecha con first, second, third…"]},{"id":"a1-u12-l06","unit_id":"a1-u12","position":12,"title_es":"Mensajes y postales","objective_es":"Leer y escribir mensajes muy breves, notas y postales.","intro":{"explanation":"Un mensaje o una nota va al grano: dónde estás y cuándo vuelves («Back at five»). Una postal saluda, cuenta algo y se despide («See you on Sunday! Love, Ana»).","examples":[{"target":"I am at the bank. Back at four.","base":"Estoy en el banco. Vuelvo a las cuatro."},{"target":"See you on Sunday!","base":"¡Nos vemos el domingo!"}]},"takeaways":["Entiendes notas, mensajes y postales breves.","Escribes una nota del tipo «Back at five»."]},{"id":"a2-u13-l01","unit_id":"a2-u13","position":1,"title_es":"El menú","objective_es":"Nombrar los platos de un menú.","intro":{"explanation":"En un restaurante, el menú (menu) se divide en platos: soup (sopa), salad (ensalada), meat (carne), fish (pescado) y dessert (postre). Vegetables (verduras) casi siempre va en plural.","examples":[{"target":"Can I see the menu, please?","base":"¿Puedo ver el menú, por favor?"},{"target":"I want the fish soup.","base":"Quiero la sopa de pescado."}]},"takeaways":["Nombras los platos de un menú: soup, salad, meat, fish, dessert.","Pides ver el menú con Can I see the menu, please?"]},{"id":"a2-u13-l02","unit_id":"a2-u13","position":2,"title_es":"Some y any","objective_es":"Decir qué hay y qué no hay con some y any.","intro":{"explanation":"Some (algo de, unos) va en oraciones afirmativas: There is some milk. Any va en negativas y en preguntas: There isn’t any milk. Is there any milk?","examples":[{"target":"There are some eggs.","base":"Hay unos huevos."},{"target":"We don't have any bread.","base":"No tenemos nada de pan."}]},"takeaways":["Usas some en afirmativas: There is some cheese.","Usas any en negativas y preguntas: Is there any juice?"]},{"id":"a2-u13-l03","unit_id":"a2-u13","position":4,"title_es":"Pedir la comida","objective_es":"Pedir una mesa y la comida con Could I have…?","intro":{"explanation":"Para pedir con cortesía se usa Could I have…? (¿me podría dar…?). Al llegar se pide la mesa: A table for two, please. Para decir que algo está muy rico: It’s delicious!","examples":[{"target":"A table for two, please.","base":"Una mesa para dos, por favor."},{"target":"Could I have the soup, please?","base":"¿Me podría dar la sopa, por favor?"}]},"takeaways":["Pides una mesa: A table for two, please.","Pides con cortesía: Could I have the fish, please?","Dices si la comida está delicious o es spicy."]},{"id":"a2-u13-l04","unit_id":"a2-u13","position":5,"title_es":"Mucho y muchos","objective_es":"Hablar de cantidades con much, many y a lot of.","intro":{"explanation":"Many va con lo que se cuenta (many people, many eggs) y much con lo que no se cuenta (much water, much money), sobre todo en negativas y preguntas. A lot of sirve para los dos, sobre todo en afirmativas.","examples":[{"target":"There aren't many people here.","base":"No hay mucha gente aquí."},{"target":"I drink a lot of water.","base":"Tomo mucha agua."}]},"takeaways":["Usas many con lo que se cuenta y much con lo que no.","Usas a lot of en afirmativas: a lot of vegetables."]},{"id":"a2-u13-l05","unit_id":"a2-u13","position":7,"title_es":"La cuenta, por favor","objective_es":"Leer un menú con precios, pedir la cuenta y pagar.","intro":{"explanation":"Al final se pide la cuenta (the bill): Could I have the bill, please? Se paga by card (con tarjeta) o in cash (en efectivo).","examples":[{"target":"Could I have the bill, please?","base":"¿Me podría dar la cuenta, por favor?"},{"target":"Can I pay by card?","base":"¿Puedo pagar con tarjeta?"}]},"takeaways":["Lees un menú con precios.","Pides la cuenta y preguntas cómo pagar."]},{"id":"a2-u14-l01","unit_id":"a2-u14","position":1,"title_es":"Pasatiempos","objective_es":"Contar qué haces en tu tiempo libre y con qué frecuencia.","intro":{"explanation":"Para hablar de tus pasatiempos (hobbies) usas el presente simple y expresiones de frecuencia: often (a menudo), once a week (una vez por semana), twice a week (dos veces por semana).","examples":[{"target":"My hobby is cooking.","base":"Mi pasatiempo es cocinar."},{"target":"I go to the gym once a week.","base":"Voy al gimnasio una vez por semana."}]},"takeaways":["Cuentas qué haces en tu tiempo libre.","Dices con qué frecuencia: often, once a week, twice a week."]},{"id":"a2-u14-l02","unit_id":"a2-u14","position":2,"title_es":"¿Te gustaría venir?","objective_es":"Invitar a alguien y aceptar o rechazar una invitación.","intro":{"explanation":"Para invitar: Would you like to…? (¿te gustaría…?). Para aceptar: I'd love to! (¡me encantaría!). Para rechazar con amabilidad: Sorry, I can't. Maybe another time.","examples":[{"target":"Would you like to go to the cinema?","base":"¿Te gustaría ir al cine?"},{"target":"Sorry, I can't. Maybe another time.","base":"Perdón, no puedo. Quizás otro día."}]},"takeaways":["Invitas con Would you like to…?","Aceptas con I'd love to y rechazas con Sorry, I can't."]},{"id":"a2-u14-l03","unit_id":"a2-u14","position":4,"title_es":"Proponer un plan","objective_es":"Proponer planes con Let's… y How about…?","intro":{"explanation":"Para proponer algo: Let's… (¡vamos a…!) o How about…? (¿qué tal si…?). Después de how about va un sustantivo o un verbo con -ing: How about Sunday? How about going out?","examples":[{"target":"Let's go out tonight!","base":"¡Salgamos esta noche!"},{"target":"How about Sunday?","base":"¿Qué tal el domingo?"}]},"takeaways":["Propones planes con Let's… y How about…?","Dices que hacen algo juntos: together."]},{"id":"a2-u14-l04","unit_id":"a2-u14","position":5,"title_es":"Quedar para verse","objective_es":"Acordar dónde y a qué hora encontrarse.","intro":{"explanation":"Para quedar se dice el lugar y la hora: Let's meet at the station at seven (encontrémonos en la estación a las siete). Para saber si alguien terminó de prepararse: Are you ready? (¿estás listo?).","examples":[{"target":"Let's meet at the station at seven.","base":"Encontrémonos en la estación a las siete."},{"target":"Are you ready?","base":"¿Estás listo?"}]},"takeaways":["Propones un lugar y una hora para encontrarse.","Preguntas si alguien está listo: Are you ready?"]},{"id":"a2-u14-l05","unit_id":"a2-u14","position":7,"title_es":"Responder una invitación","objective_es":"Entender una invitación escrita y responderla.","intro":{"explanation":"Una invitación dice qué es, cuándo y dónde. Para responder, agradece y acepta o rechaza dando una razón: Thank you! I’d love to go. / Sorry, I can’t. I have to work.","examples":[{"target":"Thank you! I'd love to go.","base":"¡Gracias! Me encantaría ir."},{"target":"Sorry, I can't. I have to work.","base":"Perdón, no puedo. Tengo que trabajar."}]},"takeaways":["Entiendes una invitación escrita: qué, cuándo y dónde.","Aceptas o rechazas una invitación dando una razón."]},{"id":"a2-u15-l01","unit_id":"a2-u15","position":1,"title_es":"¿Cómo es físicamente?","objective_es":"Preguntar y decir cómo es alguien físicamente.","intro":{"explanation":"Para preguntar por el aspecto de alguien: What does he look like? Se responde con be (He is tall and thin) o con have para el pelo, la barba o los lentes (She has curly hair. He has a beard).","examples":[{"target":"What does she look like?","base":"¿Cómo es (físicamente)?"},{"target":"She has long blond hair.","base":"Tiene el pelo largo y rubio."}]},"takeaways":["Preguntas por el aspecto con What does he look like?","Describes el pelo y la cara con have: She has curly hair."]},{"id":"a2-u15-l02","unit_id":"a2-u15","position":2,"title_es":"¿Cómo es de carácter?","objective_es":"Describir el carácter de una persona.","intro":{"explanation":"What is she like? pregunta por el carácter (¿cómo es como persona?), y What does she look like?, por el aspecto. El carácter se describe con be: She is kind and funny.","examples":[{"target":"What is your teacher like?","base":"¿Cómo es tu profesor?"},{"target":"She's very friendly.","base":"Es muy simpática."}]},"takeaways":["Distingues What is she like? (carácter) de What does she look like? (aspecto).","Describes el carácter: friendly, kind, funny, shy."]},{"id":"a2-u15-l03","unit_id":"a2-u15","position":4,"title_es":"Mi barrio","objective_es":"Describir un barrio y un lugar.","intro":{"explanation":"Un lugar se describe con be + adjetivo (The street is quiet) o con el adjetivo antes del sustantivo (a quiet street). Con there is y there are cuentas qué hay en tu barrio (neighborhood).","examples":[{"target":"I live in a quiet neighborhood.","base":"Vivo en un barrio tranquilo."},{"target":"The city is noisy and crowded.","base":"La ciudad es ruidosa y está llena de gente."}]},"takeaways":["Describes un lugar: quiet, noisy, crowded, modern, dirty.","Cuentas qué hay en tu barrio con there is y there are."]},{"id":"a2-u15-l04","unit_id":"a2-u15","position":5,"title_es":"Comparar personas y lugares","objective_es":"Comparar personas y lugares con los comparativos.","intro":{"explanation":"Con lo que aprendiste en «Comparar» puedes comparar personas y lugares. Los adjetivos cortos terminados en -y cambian la y por -ier: noisy → noisier, funny → funnier. Y los cortos con una vocal y una consonante la duplican: thin → thinner.","examples":[{"target":"My brother is thinner than me.","base":"Mi hermano es más flaco que yo."},{"target":"The city is noisier than my neighborhood.","base":"La ciudad es más ruidosa que mi barrio."}]},"takeaways":["Comparas personas: taller than, funnier than.","Comparas lugares: quieter than, the most crowded."]},{"id":"a2-u15-l05","unit_id":"a2-u15","position":7,"title_es":"Describir a alguien","objective_es":"Describir a una persona: aspecto y carácter.","intro":{"explanation":"Para describir a una persona, empieza por el aspecto (He is tall. He has dark hair.) y sigue por el carácter (He is friendly and funny). Une las ideas con and, but y because.","examples":[{"target":"He has dark hair and he wears glasses.","base":"Tiene el pelo oscuro y usa lentes."},{"target":"She's shy, but she's very kind.","base":"Es tímida, pero es muy amable."}]},"takeaways":["Describes a una persona: aspecto y carácter.","Unes ideas con and, but y because."]},{"id":"a2-u16-l01","unit_id":"a2-u16","position":1,"title_es":"Un mensaje a un amigo","objective_es":"Escribir y entender mensajes cortos entre amigos.","intro":{"explanation":"Un mensaje informal empieza con Hi y el nombre, y termina con See you soon! (¡hasta pronto!) o Take care! (¡cuídate!). Para agradecer: Thanks for… (gracias por…).","examples":[{"target":"Thanks for your message!","base":"¡Gracias por tu mensaje!"},{"target":"See you soon!","base":"¡Hasta pronto!"}]},"takeaways":["Escribes y entiendes mensajes cortos entre amigos.","Agradeces con Thanks for… y te despides con See you soon o Take care."]},{"id":"a2-u16-l02","unit_id":"a2-u16","position":2,"title_es":"Un correo","objective_es":"Empezar y terminar un correo, y pedir algo con Could you…?","intro":{"explanation":"Un correo empieza con Dear + nombre (Dear Leo,) y termina con Best wishes, + tu nombre. Para pedir algo con cortesía: Could you…? (¿podrías…?) + el verbo.","examples":[{"target":"Dear Leo,","base":"Querido Leo:"},{"target":"Could you send me the photos, please?","base":"¿Podrías mandarme las fotos, por favor?"}]},"takeaways":["Empiezas un correo con Dear… y lo terminas con Best wishes.","Pides algo con cortesía: Could you…?"]},{"id":"a2-u16-l03","unit_id":"a2-u16","position":4,"title_es":"Al teléfono","objective_es":"Pedir hablar con alguien y dejar un mensaje.","intro":{"explanation":"Al teléfono: Can I speak to…? (¿puedo hablar con…?). Si la persona no está, puedes dejar un mensaje (leave a message) o pedir que te devuelva la llamada (call me back). Hold on, please = un momento, por favor.","examples":[{"target":"Can I speak to Emma, please?","base":"¿Puedo hablar con Emma, por favor?"},{"target":"Hold on, please.","base":"Un momento, por favor."}]},"takeaways":["Pides hablar con alguien y dejas un mensaje.","Entiendes Hold on y pides que te llamen: call me back."]},{"id":"a2-u16-l04","unit_id":"a2-u16","position":5,"title_es":"Reservar un hotel","objective_es":"Reservar una habitación y entender las reglas del hotel.","intro":{"explanation":"Para reservar: I'd like to book a room. Una habitación para dos personas es a double room. Check in es registrarte al llegar y check out, dejar la habitación al irte.","examples":[{"target":"I'd like to book a double room.","base":"Quisiera reservar una habitación doble."},{"target":"You can check in at two.","base":"Pueden registrarse a las dos."}]},"takeaways":["Reservas una habitación de hotel.","Entiendes el check in, el check out y la recepción."]},{"id":"a2-u16-l05","unit_id":"a2-u16","position":7,"title_es":"Responder un correo","objective_es":"Entender un correo y responderlo.","intro":{"explanation":"Para responder un correo: agradece (Thanks for your email), contesta lo que te preguntan y despídete (Best wishes / See you soon). Si te piden algo, di qué vas a hacer con will: I’ll send you the photos tonight.","examples":[{"target":"Thanks for your email.","base":"Gracias por tu correo."},{"target":"I'll send you the photos tonight.","base":"Esta noche te mando las fotos."}]},"takeaways":["Respondes un correo: agradeces, contestas y te despides.","Dices qué vas a hacer con will: I’ll send…"]},{"id":"a2-u17-l01","unit_id":"a2-u17","position":1,"title_es":"Lo que estaba pasando","objective_es":"Contar qué estaba pasando en un momento del pasado.","intro":{"explanation":"El past continuous cuenta lo que estaba pasando en un momento del pasado: was/were + verbo con -ing. Con I, he, she e it va was; con you, we y they, were.","examples":[{"target":"I was reading at nine.","base":"A las nueve estaba leyendo."},{"target":"They were watching a movie.","base":"Estaban mirando una película."}]},"takeaways":["Cuentas qué estaba pasando: I was cooking, they were sleeping.","Preguntas: What were you doing at eight?"]},{"id":"a2-u17-l02","unit_id":"a2-u17","position":2,"title_es":"When y while","objective_es":"Contar una acción que interrumpe otra.","intro":{"explanation":"Cuando una acción corta interrumpe otra larga, la larga va en past continuous y la corta en past simple: I was cooking when the phone rang. While (mientras) va con la acción larga: While I was cooking, the phone rang.","examples":[{"target":"I was sleeping when the phone rang.","base":"Estaba durmiendo cuando sonó el teléfono."},{"target":"While we were walking, we heard a noise.","base":"Mientras caminábamos, oímos un ruido."}]},"takeaways":["Cuentas una acción que interrumpe otra: I was cooking when the phone rang.","Usas while con la acción larga."]},{"id":"a2-u17-l03","unit_id":"a2-u17","position":4,"title_es":"¿Qué pasó?","objective_es":"Preguntar qué pasó y contar un accidente.","intro":{"explanation":"Para preguntar qué pasó: What happened? Un accidente se cuenta con past simple y past continuous: I fell when I was running. Luckily (por suerte) cuenta lo bueno.","examples":[{"target":"What happened?","base":"¿Qué pasó?"},{"target":"He fell and broke his arm.","base":"Se cayó y se rompió el brazo."}]},"takeaways":["Preguntas What happened? y cuentas un accidente.","Dices cómo te sentiste: I was scared."]},{"id":"a2-u17-l04","unit_id":"a2-u17","position":5,"title_es":"El orden de la historia","objective_es":"Ordenar un relato: al principio, después, al día siguiente, al final.","intro":{"explanation":"Para ordenar una historia: at first (al principio), then (después), the next day (al día siguiente) e in the end (al final). Para decir que algo empezó: It began to rain (empezó a llover).","examples":[{"target":"At first, I was nervous.","base":"Al principio estaba nervioso."},{"target":"In the end, we were very happy.","base":"Al final estábamos muy contentos."}]},"takeaways":["Ordenas una historia con at first, then, the next day e in the end.","Cuentas cuándo empezó algo: It began to rain."]},{"id":"a2-u17-l05","unit_id":"a2-u17","position":7,"title_es":"Tu historia","objective_es":"Contar una historia corta con comienzo, problema y final.","intro":{"explanation":"Una historia corta tiene un comienzo (dónde estabas y qué estabas haciendo), algo que pasó de repente y un final. Usa was/were + -ing para la escena y el past simple para lo que pasó.","examples":[{"target":"I was walking home when I saw an old friend.","base":"Volvía caminando a casa cuando vi a un viejo amigo."},{"target":"In the end, we had dinner together.","base":"Al final, cenamos juntos."}]},"takeaways":["Cuentas una historia corta con comienzo, problema y final.","Combinas el past continuous y el past simple."]},{"id":"b1-u01-l01","unit_id":"b1-u01","position":1,"title_es":"¿Alguna vez…?","objective_es":"Preguntar y contar experiencias con el present perfect y participios irregulares.","intro":{"explanation":"Para hablar de experiencias sin decir cuándo pasaron: have/has + participio. Muchos participios son irregulares: go → gone, write → written, speak → spoken, take → taken, give → given.","examples":[{"target":"Have you ever spoken to a famous person?","base":"¿Alguna vez hablaste con una persona famosa?"},{"target":"I have written a story.","base":"Escribí una historia (alguna vez)."}]},"takeaways":["Preguntas por experiencias: Have you ever…?","Usas participios irregulares: written, spoken, taken, given."]},{"id":"b1-u01-l02","unit_id":"b1-u01","position":2,"title_es":"Been y gone","objective_es":"Distinguir been to (fue y volvió) de gone to (se fue y sigue allá); contar lo que llevas hecho.","intro":{"explanation":"Been to dice que alguien fue a un lugar y ya volvió: I have been to Spain. Gone to dice que se fue y todavía está allá: She has gone to the bank (no está). So far (hasta ahora) suma lo hecho hasta hoy.","examples":[{"target":"I have been to Spain twice.","base":"Estuve en España dos veces."},{"target":"Kate has gone to the bank.","base":"Kate se fue al banco (no está)."}]},"takeaways":["Diferencias been to (ya volvió) de gone to (sigue allá).","Cuentas lo que hiciste hasta ahora con so far."]},{"id":"b1-u01-l03","unit_id":"b1-u01","position":4,"title_es":"¿Y cuándo fue?","objective_es":"Pasar de la experiencia (present perfect) a los detalles (past simple).","intro":{"explanation":"Una conversación sobre experiencias suele empezar con el present perfect (Have you ever…?) y sigue con el past simple para los detalles: When did you go? Who did you go with? Con last year, ago, in 2019 o yesterday va siempre el past simple.","examples":[{"target":"Have you ever climbed a mountain? Yes, I climbed one last year.","base":"¿Escalaste alguna vez una montaña? Sí, escalé una el año pasado."},{"target":"It was the first time I saw the sea.","base":"Fue la primera vez que vi el mar."}]},"takeaways":["Pasas del present perfect al past simple para dar detalles.","Cuentas la primera vez que hiciste algo: It was the first time…"]},{"id":"b1-u01-l04","unit_id":"b1-u01","position":5,"title_es":"Logros","objective_es":"Contar logros y momentos importantes de la vida.","intro":{"explanation":"Para contar logros: I have graduated, I have won a prize. Para decir cómo te sientes: I am proud of… (estoy orgulloso de…). Win es irregular: won (pasado y participio).","examples":[{"target":"I have won a prize.","base":"Gané un premio."},{"target":"My parents are very proud of me.","base":"Mis padres están muy orgullosos de mí."}]},"takeaways":["Cuentas logros: I have graduated, I have won a prize.","Dices de qué estás orgulloso: I am proud of…"]},{"id":"b1-u01-l05","unit_id":"b1-u01","position":7,"title_es":"Un recuerdo inolvidable","objective_es":"Contar una experiencia importante: qué pasó, cuándo y cómo te sentiste.","intro":{"explanation":"Para contar un recuerdo: preséntalo con el present perfect o con una frase como My best memory is…, y cuenta los detalles en past simple. Unforgettable (inolvidable) y adventure (aventura) ayudan a describirlo.","examples":[{"target":"My best memory is the day I graduated.","base":"Mi mejor recuerdo es el día que me gradué."},{"target":"It was an unforgettable adventure.","base":"Fue una aventura inolvidable."}]},"takeaways":["Cuentas un recuerdo con detalles en past simple.","Lo describes: unforgettable, an adventure."]},{"id":"b1-u02-l01","unit_id":"b1-u02","position":1,"title_es":"For, since y how long","objective_es":"Decir desde cuándo haces algo con for, since y how long.","intro":{"explanation":"Para algo que empezó en el pasado y sigue: have/has + participio. For va con un período (for two years, for a long time) y since con el momento en que empezó (since 2020, since March). Para preguntar: How long…?","examples":[{"target":"I have lived here for two years.","base":"Vivo aquí desde hace dos años."},{"target":"She has worked here since March.","base":"Trabaja aquí desde marzo."}]},"takeaways":["Usas for con un período y since con un comienzo.","Preguntas How long have you…?"]},{"id":"b1-u02-l02","unit_id":"b1-u02","position":2,"title_es":"Lo que vienes haciendo","objective_es":"Contar lo que vienes haciendo con have been + -ing.","intro":{"explanation":"El present perfect continuous (have/has been + -ing) cuenta una actividad que empezó antes y sigue ahora, o que hiciste mucho últimamente: I have been studying a lot lately. Con I, you, we y they: have been (I've been); con he, she e it: has been.","examples":[{"target":"I've been studying a lot lately.","base":"Estuve estudiando mucho últimamente."},{"target":"How long have you been learning English?","base":"¿Hace cuánto que aprendes inglés?"}]},"takeaways":["Cuentas lo que vienes haciendo: I have been working a lot.","Preguntas How long have you been…?"]},{"id":"b1-u02-rev1","unit_id":"b1-u02","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «For, since y how long» y «Lo que vienes haciendo».","intro":null,"takeaways":[]},{"id":"b1-u02-l03","unit_id":"b1-u02","position":4,"title_es":"Lo que disfrutas","objective_es":"Hablar de gustos y habilidades con verbos + -ing, good at e interested in.","intro":{"explanation":"Después de enjoy, love, like, hate, stop y avoid, el verbo va con -ing: I enjoy cooking. También después de preposiciones: good at singing, interested in learning.","examples":[{"target":"I enjoy cooking for my friends.","base":"Disfruto cocinar para mis amigos."},{"target":"She is good at singing.","base":"Es buena cantando."}]},"takeaways":["Usas -ing después de enjoy, stop y avoid.","Dices en qué eres bueno y qué te interesa: good at, interested in."]},{"id":"b1-u02-l04","unit_id":"b1-u02","position":5,"title_es":"Empezar y dejar","objective_es":"Contar hábitos nuevos y hábitos que dejaste: take up, give up, stop, avoid, decide to.","intro":{"explanation":"Take up es empezar un pasatiempo; give up, dejar un hábito. Después de decide, want, hope y learn va to + verbo: I decided to take up yoga. Después de stop, give up y avoid va -ing: I stopped eating meat.","examples":[{"target":"I decided to take up running.","base":"Decidí empezar a correr."},{"target":"My father gave up smoking.","base":"Mi papá dejó de fumar."}]},"takeaways":["Cuentas un hábito nuevo (take up) y uno que dejaste (give up).","Eliges -ing o to: stop eating, decide to eat."]},{"id":"b1-u02-rev2","unit_id":"b1-u02","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Lo que disfrutas» y «Empezar y dejar».","intro":null,"takeaways":[]},{"id":"b1-u02-l05","unit_id":"b1-u02","position":7,"title_es":"Practicar y mejorar","objective_es":"Contar cómo aprendes algo nuevo: practicar, mejorar, seguir intentando.","intro":{"explanation":"Para hablar de un aprendizaje: practice (practicar), improve (mejorar), skill (habilidad). Keep + -ing es seguir haciendo algo: Keep practicing! Con el present perfect cuentas el resultado: My English has improved.","examples":[{"target":"My English has improved a lot.","base":"Mi inglés mejoró mucho."},{"target":"Keep practicing every day.","base":"Sigue practicando todos los días."}]},"takeaways":["Cuentas cómo practicas y cuánto mejoraste.","Animas a alguien: Keep practicing!"]},{"id":"b1-u03-l01","unit_id":"b1-u03","position":1,"title_es":"La escena","objective_es":"Armar la escena de una anécdota con el past continuous y el past simple.","intro":{"explanation":"Una anécdota suele empezar con la escena (past continuous: I was having lunch) y sigue con lo que pasó (past simple: when a man said my name). Para reaccionar: strange (raro), surprised (sorprendido), embarrassed (avergonzado).","examples":[{"target":"I was having lunch when a man said my name.","base":"Estaba almorzando cuando un hombre dijo mi nombre."},{"target":"A strange thing happened today.","base":"Hoy pasó algo raro."}]},"takeaways":["Armas la escena con was/were + -ing y cuentas lo que pasó en past simple.","Dices cómo te sentiste: surprised, embarrassed."]},{"id":"b1-u03-l02","unit_id":"b1-u03","position":2,"title_es":"Lo que ya había pasado","objective_es":"Contar algo que pasó antes de otro hecho del pasado con had + participio.","intro":{"explanation":"Had + participio (past perfect) va con lo que pasó primero: When I got to the station, the train had left. By the time (para cuando) introduce el segundo momento: By the time we arrived, the movie had started.","examples":[{"target":"When I arrived, the train had left.","base":"Cuando llegué, el tren se había ido."},{"target":"I realized I had forgotten my keys.","base":"Me di cuenta de que me había olvidado las llaves."}]},"takeaways":["Usas had + participio para lo que pasó antes.","Ordenas dos momentos con by the time y when."]},{"id":"b1-u03-l03","unit_id":"b1-u03","position":4,"title_es":"Antes, después y apenas","objective_es":"Ordenar los hechos con before, after, as soon as, afterwards y the day before.","intro":{"explanation":"Before y after pueden ir con -ing: before eating, after finishing. As soon as es «apenas, en cuanto»: As soon as I got home, I called you. Afterwards (después) y the day before (el día anterior) también ordenan una historia.","examples":[{"target":"As soon as I got home, I called you.","base":"Apenas llegué a casa, te llamé."},{"target":"We watched a movie, and afterwards we had dinner.","base":"Vimos una película y después cenamos."}]},"takeaways":["Ordenas hechos con before, after y as soon as.","Usas afterwards y the day before para avanzar o volver en la historia."]},{"id":"b1-u03-l04","unit_id":"b1-u03","position":5,"title_es":"Por suerte, por desgracia","objective_es":"Contar contratiempos: perderse, perder el tren, darse cuenta de algo.","intro":{"explanation":"Unfortunately (lamentablemente) presenta lo malo y luckily (por suerte), lo bueno. Miss es perder un transporte (I missed the bus); get lost es perderse. Realize es darse cuenta: I realized I had lost my keys.","examples":[{"target":"Unfortunately, we got lost.","base":"Lamentablemente, nos perdimos."},{"target":"Luckily, a woman showed us the way.","base":"Por suerte, una mujer nos indicó el camino."}]},"takeaways":["Cuentas contratiempos: I missed the bus, we got lost.","Presentas lo malo y lo bueno: unfortunately, luckily."]},{"id":"b1-u03-l05","unit_id":"b1-u03","position":7,"title_es":"Tu anécdota","objective_es":"Contar una anécdota completa, con escena, hechos ordenados y final.","intro":{"explanation":"Una buena anécdota tiene escena (was/were + -ing), hechos (past simple), lo que ya había pasado (had + participio) y un final (eventually, in the end). Recognize es reconocer a alguien.","examples":[{"target":"At first I didn't recognize him.","base":"Al principio no lo reconocí."},{"target":"Eventually, we found the hotel.","base":"Al fin encontramos el hotel."}]},"takeaways":["Cuentas una anécdota completa y ordenada.","Cierras la historia: eventually, in the end."]},{"id":"b1-u04-l01","unit_id":"b1-u04","position":1,"title_es":"Lo que ya arreglaste","objective_es":"Hablar de intenciones (going to) y de planes arreglados (present continuous).","intro":{"explanation":"Going to cuenta una intención: I am going to study more. El present continuous cuenta algo ya arreglado, casi siempre con día u hora: I am meeting my sister on Saturday. Appointment es un turno (con el médico, el dentista…).","examples":[{"target":"I'm meeting my sister on Saturday.","base":"El sábado me encuentro con mi hermana."},{"target":"I have a doctor’s appointment at ten.","base":"Tengo turno con el médico a las diez."}]},"takeaways":["Cuentas lo que ya arreglaste: I am meeting…, I have an appointment.","Cuentas intenciones con going to."]},{"id":"b1-u04-l02","unit_id":"b1-u04","position":2,"title_es":"Seguro, quizás","objective_es":"Decidir en el momento con will y hablar de lo posible con might.","intro":{"explanation":"Will sirve para una decisión que tomas en el momento (I'll call you) y para predicciones (It will be fine). Might dice que algo es posible, pero no seguro: I might go. Definitely (seguro) y probably (probablemente) dicen qué tan seguro estás.","examples":[{"target":"I might go to the concert.","base":"Puede que vaya al recital."},{"target":"I'll definitely call you tonight.","base":"Te llamo seguro esta noche."}]},"takeaways":["Decides en el momento con will.","Dices qué es posible (might) y qué es seguro (definitely)."]},{"id":"b1-u04-l03","unit_id":"b1-u04","position":4,"title_es":"Metas","objective_es":"Contar tus metas y cómo piensas lograrlas.","intro":{"explanation":"Para hablar de metas: My goal is to… (mi objetivo es…), achieve (lograr), the first step (el primer paso). Look forward to va con -ing o con un sustantivo: I look forward to seeing you.","examples":[{"target":"My goal is to speak English well.","base":"Mi objetivo es hablar bien inglés."},{"target":"I look forward to seeing you.","base":"Tengo ganas de verte."}]},"takeaways":["Cuentas una meta: My goal is to…","Dices qué esperas con ganas: I look forward to…"]},{"id":"b1-u04-l04","unit_id":"b1-u04","position":5,"title_es":"Proyectos de vida","objective_es":"Hablar de grandes proyectos: estudiar, ahorrar, montar un negocio, casarse, jubilarse.","intro":{"explanation":"Proyectos frecuentes: save money (ahorrar), apply for a course or a job (postularse), set up a business (montar un negocio), get married (casarse), retire (jubilarse). Se combinan con going to y con el present perfect continuous: I have been saving for two years.","examples":[{"target":"I'm going to set up my own business.","base":"Voy a montar mi propio negocio."},{"target":"They are getting married in June.","base":"Se casan en junio."}]},"takeaways":["Cuentas proyectos de vida con going to.","Usas apply for, set up, save, get married y retire."]},{"id":"b1-u04-l05","unit_id":"b1-u04","position":7,"title_es":"Cuando termine…","objective_es":"Hablar de lo que vas a hacer después de otra cosa: when, as soon as, until + presente.","intro":{"explanation":"Después de when, as soon as, before, after y until, el futuro va en PRESENTE: When I finish the course, I will look for a job (no «when I will finish»). Until es «hasta (que)».","examples":[{"target":"When I finish the course, I will look for a job.","base":"Cuando termine el curso, voy a buscar trabajo."},{"target":"I will wait until you arrive.","base":"Voy a esperar hasta que llegues."}]},"takeaways":["Usas el presente después de when, as soon as y until para hablar del futuro.","Escribes un pedido formal: I would like to apply for…"]},{"id":"b1-u05-l01","unit_id":"b1-u05","position":1,"title_es":"Tener que y no hace falta","objective_es":"Hablar de obligaciones y de lo que no es necesario: have to, must, don't have to.","intro":{"explanation":"Have to y must expresan obligación: I have to wear a uniform. Don't have to NO es una prohibición: dice que algo no hace falta (You don't have to come). En pasado: had to (tuve que).","examples":[{"target":"I have to wear a uniform at work.","base":"Tengo que usar uniforme en el trabajo."},{"target":"You don't have to pay. It's free.","base":"No hace falta pagar. Es gratis."}]},"takeaways":["Cuentas tus obligaciones con have to y must.","Dices que algo no hace falta con don't have to."]},{"id":"b1-u05-l02","unit_id":"b1-u05","position":2,"title_es":"Normas","objective_es":"Entender y explicar normas: must, mustn't, allowed to.","intro":{"explanation":"En normas escritas se usa must (obligación) y mustn't (prohibición). Para hablar de permisos: be allowed to (I am allowed to…, We aren't allowed to…). Are we allowed to…? pregunta si algo está permitido.","examples":[{"target":"You must wash your cup.","base":"Tienes que lavar tu taza."},{"target":"We are not allowed to use our phones in class.","base":"No nos dejan usar el teléfono en clase."}]},"takeaways":["Entiendes normas con must y mustn't.","Preguntas qué está permitido: Are we allowed to…?"]},{"id":"b1-u05-l03","unit_id":"b1-u05","position":4,"title_es":"Exámenes y materias","objective_es":"Hablar de estudios: materias, exámenes, aprobar y desaprobar.","intro":{"explanation":"Pass an exam es aprobar; fail an exam, desaprobar. Subject es una materia. Para dar ánimo: Don't worry, you'll pass. Para contar lo que tuviste que hacer: I had to study a lot.","examples":[{"target":"I hope I pass the exam.","base":"Espero aprobar el examen."},{"target":"My favorite subject is history.","base":"Mi materia favorita es historia."}]},"takeaways":["Hablas de exámenes y materias.","Cuentas si aprobaste o desaprobaste."]},{"id":"b1-u05-l04","unit_id":"b1-u05","position":5,"title_es":"Buscar trabajo","objective_es":"Entender un aviso de trabajo y explicar cómo postularse.","intro":{"explanation":"En un aviso: full-time / part-time (tiempo completo / medio tiempo), deadline (fecha límite), hire (contratar). Para postularte: fill in the form (completar el formulario) y send your CV. Find out es averiguar.","examples":[{"target":"Fill in the form and send your CV.","base":"Completa el formulario y manda tu currículum."},{"target":"They are hiring part-time employees.","base":"Están contratando empleados de medio tiempo."}]},"takeaways":["Entiendes un aviso de trabajo.","Explicas cómo postularse: fill in, send your CV, before the deadline."]},{"id":"b1-u05-l05","unit_id":"b1-u05","position":7,"title_es":"La entrevista","objective_es":"Responder en una entrevista: tu experiencia, tus tareas y por qué quieres el puesto.","intro":{"explanation":"En una entrevista cuentas tu experiencia (I worked in… for three years), tus tareas (I was responsible for…) y qué buscas (a full-time job). Make a decision es tomar una decisión.","examples":[{"target":"I was responsible for the orders.","base":"Estaba a cargo de los pedidos."},{"target":"We'll make a decision on Friday.","base":"Vamos a tomar una decisión el viernes."}]},"takeaways":["Cuentas tu experiencia y tus tareas en una entrevista.","Entiendes qué va a pasar después: We'll make a decision…"]},{"id":"b1-u06-l01","unit_id":"b1-u06","position":1,"title_es":"Si pasa esto…","objective_es":"Decir qué va a pasar si se cumple una condición: if + presente, will.","intro":{"explanation":"El primer condicional une una condición posible (if + presente) con su resultado (will + verbo): If it rains, we will stay at the hotel. El orden se puede invertir: We will stay at the hotel if it rains (sin coma).","examples":[{"target":"If it rains, we will stay at the hotel.","base":"Si llueve, nos quedamos en el hotel."},{"target":"You will miss the train if you don't hurry.","base":"Vas a perder el tren si no te apuras."}]},"takeaways":["Dices qué va a pasar si se cumple algo: If…, … will…","Usas el presente después de if."]},{"id":"b1-u06-l02","unit_id":"b1-u06","position":2,"title_es":"Problemas de viaje","objective_es":"Resolver demoras y cancelaciones; usar unless.","intro":{"explanation":"Delayed (demorado) y canceled (cancelado) son las malas noticias de un viaje. Unless es «a menos que» y equivale a if… not: We will miss the bus unless we take a taxi = if we don't take a taxi.","examples":[{"target":"Our flight is delayed.","base":"Nuestro vuelo está demorado."},{"target":"We'll miss the bus unless we take a taxi.","base":"Vamos a perder el autobús a menos que tomemos un taxi."}]},"takeaways":["Entiendes y cuentas demoras y cancelaciones.","Usas unless para decir «a menos que»."]},{"id":"b1-u06-l03","unit_id":"b1-u06","position":4,"title_es":"Recorrer la ciudad","objective_es":"Organizar un día de turismo: reservas, visitas guiadas y recuerdos.","intro":{"explanation":"Go sightseeing es salir a recorrer y conocer lugares. Una visita guiada tiene un guide (guía). Reservation es una reserva (de hotel, de mesa). Souvenir es un recuerdo que compras en el viaje.","examples":[{"target":"We went sightseeing all day.","base":"Recorrimos la ciudad todo el día."},{"target":"I bought a souvenir for my mother.","base":"Le compré un recuerdo a mi madre."}]},"takeaways":["Organizas un día de turismo.","Entiendes el programa de una visita guiada."]},{"id":"b1-u06-l04","unit_id":"b1-u06","position":5,"title_es":"Dinero y propinas","objective_es":"Cambiar dinero, preguntar por la moneda local y por las propinas.","intro":{"explanation":"Currency es la moneda de un país; exchange money es cambiar dinero. Tip es propina (y también «consejo»: travel tips). Local es «del lugar»: the local currency, a local restaurant.","examples":[{"target":"Where can I exchange money?","base":"¿Dónde puedo cambiar dinero?"},{"target":"Do people leave a tip here?","base":"¿Aquí se deja propina?"}]},"takeaways":["Preguntas por la moneda local y dónde cambiar dinero.","Preguntas si se deja propina."]},{"id":"b1-u06-l05","unit_id":"b1-u06","position":7,"title_es":"Otras costumbres","objective_es":"Explicar costumbres de un lugar: qué es de buena o mala educación.","intro":{"explanation":"Para explicar costumbres: It is polite to… (es de buena educación…), It is rude to… (es de mala educación…). Tradition es una tradición; culture, una cultura. Con el primer condicional das un consejo: If you go into a house, take off your shoes.","examples":[{"target":"It is polite to say thank you.","base":"Es de buena educación dar las gracias."},{"target":"It is rude to talk on the phone at dinner.","base":"Es de mala educación hablar por teléfono en la cena."}]},"takeaways":["Explicas qué es de buena y de mala educación en un lugar.","Das consejos de viaje con if."]},{"id":"b1-u07-l01","unit_id":"b1-u07","position":1,"title_es":"Síntomas","objective_es":"Explicar síntomas en una farmacia o con el médico.","intro":{"explanation":"Para contar cómo estás: I have a cold (tengo un resfrío), I have a bad cough (tengo mucha tos), I have a pain in my back. Con el present perfect dices desde cuándo: I've had a cough for three days.","examples":[{"target":"I've had a bad cough for three days.","base":"Hace tres días que tengo mucha tos."},{"target":"Is there a pharmacy near here?","base":"¿Hay una farmacia cerca?"}]},"takeaways":["Explicas tus síntomas y desde cuándo los tienes.","Te arreglas en una farmacia."]},{"id":"b1-u07-l02","unit_id":"b1-u07","position":2,"title_es":"Consejos","objective_es":"Dar consejos con should, ought to y had better.","intro":{"explanation":"Should y ought to dan un consejo: You should rest, You ought to rest. Had better ('d better) es más fuerte, avisa que si no, habrá un problema: You'd better see a doctor. En negativo: You'd better not go.","examples":[{"target":"You ought to rest for a few days.","base":"Tendrías que descansar unos días."},{"target":"You'd better not go to work today.","base":"Mejor que hoy no vayas a trabajar."}]},"takeaways":["Das consejos con should y ought to.","Adviertes con had better y had better not."]},{"id":"b1-u07-l03","unit_id":"b1-u07","position":4,"title_es":"Hábitos saludables","objective_es":"Hablar de alimentación, ejercicio y peso.","intro":{"explanation":"Healthy es saludable. Diet es la alimentación (no sólo «hacer dieta»). Exercise es hacer ejercicio; work out, entrenar. Lose weight es bajar de peso.","examples":[{"target":"I exercise three times a week.","base":"Hago ejercicio tres veces por semana."},{"target":"A healthy diet is very important.","base":"Una alimentación saludable es muy importante."}]},"takeaways":["Hablas de tus hábitos de alimentación y ejercicio.","Usas healthy, diet, work out y lose weight."]},{"id":"b1-u07-l04","unit_id":"b1-u07","position":5,"title_es":"Comparar hábitos","objective_es":"Comparar con as … as, not as … as, much / a bit + comparativo y the more…, the better…","intro":{"explanation":"As + adjetivo + as: tan … como (Walking is as good as running). Not as … as: no tan … como. Much / a bit delante del comparativo: much better (mucho mejor), a bit tired (un poco cansado). The more…, the better…: cuanto más…, mejor…","examples":[{"target":"Walking is not as hard as running.","base":"Caminar no es tan duro como correr."},{"target":"The more you sleep, the better you feel.","base":"Cuanto más duermes, mejor te sientes."}]},"takeaways":["Comparas con as … as y not as … as.","Matizas: much better, a bit healthier, the more…, the better…"]},{"id":"b1-u07-l05","unit_id":"b1-u07","position":7,"title_es":"Estrés y descanso","objective_es":"Hablar del estrés y de cómo descansar.","intro":{"explanation":"Stress es el estrés; stressed, estresado. Relax es relajarse. Take a few days off es tomarse unos días libres. Para aconsejar: You ought to relax, You need to take a break.","examples":[{"target":"I've been so stressed lately.","base":"Estuve muy estresado últimamente."},{"target":"I relax with music.","base":"Me relajo con música."}]},"takeaways":["Cuentas cómo te sientes cuando estás estresado.","Das consejos para relajarse."]},{"id":"b1-u08-l01","unit_id":"b1-u08","position":1,"title_es":"Aparatos","objective_es":"Hablar de aparatos y explicar para qué sirven con which y that.","intro":{"explanation":"Para explicar qué es una cosa: which o that + verbo (a device which/that you can carry). Turn on es prender; turn off, apagar. El objeto puede ir en el medio: turn it on, turn the light off.","examples":[{"target":"A charger is a thing which gives power to your phone.","base":"Un cargador es algo que le da energía al teléfono."},{"target":"Please turn off your phones.","base":"Por favor, apaguen los teléfonos."}]},"takeaways":["Explicas qué es algo con which y that.","Prendes y apagas aparatos: turn on, turn off."]},{"id":"b1-u08-l02","unit_id":"b1-u08","position":2,"title_es":"Gente y lugares","objective_es":"Describir personas con who y lugares con where; seguir en contacto.","intro":{"explanation":"Who explica quién es una persona: my friend who lives in Italy. Where explica un lugar: the cafe where we met. Para no perder el contacto: keep in touch, a video call (una videollamada).","examples":[{"target":"I have a friend who lives in Italy.","base":"Tengo un amigo que vive en Italia."},{"target":"That is the cafe where we met.","base":"Ese es el café donde nos conocimos."}]},"takeaways":["Describes personas con who y lugares con where.","Hablas de cómo sigues en contacto: a video call."]},{"id":"b1-u08-l03","unit_id":"b1-u08","position":4,"title_es":"Internet","objective_es":"Usar apps y resolver problemas con contraseñas y el inicio de sesión.","intro":{"explanation":"Download es descargar y upload, subir. Log in es entrar a una cuenta (log in to your account). Password es la contraseña. Para pedir ayuda: I can't log in. I have forgotten my password.","examples":[{"target":"You can download the app for free.","base":"Puedes descargar la app gratis."},{"target":"I have forgotten my password.","base":"Me olvidé la contraseña."}]},"takeaways":["Descargas y subes archivos: download, upload.","Explicas un problema: I can't log in, I have forgotten my password."]},{"id":"b1-u08-l04","unit_id":"b1-u08","position":5,"title_es":"Redes sociales","objective_es":"Hablar de cómo usas las redes: publicar, compartir, seguidores.","intro":{"explanation":"Social media son las redes sociales. Post es publicar (y una publicación); share, compartir; follower, seguidor. Online es «en línea» o «por internet»: I buy clothes online.","examples":[{"target":"She posts a photo every day.","base":"Publica una foto todos los días."},{"target":"I spend too much time on social media.","base":"Paso demasiado tiempo en las redes."}]},"takeaways":["Cuentas cómo usas las redes sociales.","Usas post, share, follower y online."]},{"id":"b1-u08-l05","unit_id":"b1-u08","position":7,"title_es":"Recomendar una app","objective_es":"Explicar qué hace una app y a quién se la recomiendas.","intro":{"explanation":"Para recomendar: It is an app which/that helps you… I recommend it to people who… Así combinas which/that (para la app) y who (para la gente).","examples":[{"target":"It is an app which helps you plan your meals.","base":"Es una app que te ayuda a planificar las comidas."},{"target":"I recommend it to people who travel a lot.","base":"Se la recomiendo a la gente que viaja mucho."}]},"takeaways":["Explicas qué hace una app con which o that.","Dices a quién se la recomiendas con who."]},{"id":"b1-u09-l01","unit_id":"b1-u09","position":1,"title_es":"El planeta","objective_es":"Hablar de problemas del medioambiente.","intro":{"explanation":"Palabras para hablar del planeta: the environment (el medioambiente), pollution (la contaminación), climate change (el cambio climático), forest (bosque). Con have to y must dices lo que hay que hacer: We have to protect the planet.","examples":[{"target":"There is a lot of pollution in big cities.","base":"Hay mucha contaminación en las ciudades grandes."},{"target":"Climate change is a big problem.","base":"El cambio climático es un gran problema."}]},"takeaways":["Nombras problemas del medioambiente.","Dices qué hay que hacer: We have to protect the planet."]},{"id":"b1-u09-l02","unit_id":"b1-u09","position":2,"title_es":"Se recicla…","objective_es":"Explicar cómo se hace algo con la pasiva en presente.","intro":{"explanation":"La pasiva en presente: is/are + participio. Paper is recycled (se recicla el papel). Plastic bottles are collected on Mondays (las botellas se recogen los lunes). Made of: hecho de (This bag is made of paper).","examples":[{"target":"Plastic bottles are recycled here.","base":"Aquí se reciclan las botellas de plástico."},{"target":"This bag is made of paper.","base":"Esta bolsa está hecha de papel."}]},"takeaways":["Explicas cómo se hace algo: is/are + participio.","Dices de qué está hecho algo: made of."]},{"id":"b1-u09-l03","unit_id":"b1-u09","position":4,"title_es":"Fue construido…","objective_es":"Contar la historia de algo con la pasiva en pasado y by.","intro":{"explanation":"La pasiva en pasado: was/were + participio. The bridge was built in 1890 (fue construido). Si importa quién lo hizo: by. It was designed by a famous engineer. Build: built; produce: produced.","examples":[{"target":"This house was built in 1950.","base":"Esta casa fue construida en 1950."},{"target":"The park was cleaned by volunteers.","base":"El parque fue limpiado por voluntarios."}]},"takeaways":["Cuentas la historia de un lugar: It was built in…","Dices quién lo hizo con by."]},{"id":"b1-u09-l04","unit_id":"b1-u09","position":5,"title_es":"¿Qué podemos hacer?","objective_es":"Proponer soluciones: reducir, proteger, ahorrar energía, usar transporte público.","intro":{"explanation":"Para proponer soluciones: reduce (reducir), protect (proteger), save energy (ahorrar energía), use public transport. Con el primer condicional muestras el resultado: If more people ride bikes, the air will be cleaner.","examples":[{"target":"We should save energy at home.","base":"Deberíamos ahorrar energía en casa."},{"target":"If we use public transport, there will be less pollution.","base":"Si usamos el transporte público, habrá menos contaminación."}]},"takeaways":["Propones soluciones con should y have to.","Muestras el resultado con if + will."]},{"id":"b1-u09-l05","unit_id":"b1-u09","position":7,"title_es":"En comunidad","objective_es":"Contar un proyecto de la comunidad con la pasiva y con voluntarios.","intro":{"explanation":"Community es la comunidad (los vecinos, el barrio). Volunteer es voluntario y también hacer voluntariado. Para contar un proyecto se usa mucho la pasiva: The park was cleaned, a hundred trees were planted.","examples":[{"target":"She works as a volunteer at the hospital.","base":"Trabaja de voluntaria en el hospital."},{"target":"Our community has a big garden.","base":"Nuestra comunidad tiene una huerta grande."}]},"takeaways":["Cuentas un proyecto de tu comunidad.","Usas la pasiva para contar qué se hizo."]},{"id":"b1-u10-l01","unit_id":"b1-u10","position":1,"title_es":"Titulares","objective_es":"Entender titulares y hablar de cómo te informas.","intro":{"explanation":"Los titulares (headlines) son cortos: usan el presente para hechos recientes (Local team wins the cup) y to o will para el futuro (New line will open). The news son las noticias o el noticiero; newspaper, el diario; article, una nota.","examples":[{"target":"I watch the news every night.","base":"Miro el noticiero todas las noches."},{"target":"I read an interesting article about food.","base":"Leí una nota interesante sobre comida."}]},"takeaways":["Entiendes titulares cortos.","Cuentas cómo te informas: the news, a newspaper, an article."]},{"id":"b1-u10-l02","unit_id":"b1-u10","position":2,"title_es":"Dijo que…","objective_es":"Contar lo que alguien dijo: said that, told me that.","intro":{"explanation":"Said va sin persona (He said that…) y told, con persona (He told me that…). El verbo va un tiempo atrás: «I am busy» → She said she was busy; «We will hire» → He said they would hire; «You can go» → He told us we could go. That se puede omitir.","examples":[{"target":"She said that she was busy.","base":"Dijo que estaba ocupada."},{"target":"He told us that we could work from home.","base":"Nos dijo que podíamos trabajar desde casa."}]},"takeaways":["Cuentas lo que alguien dijo con said y told.","Pasas el verbo un tiempo atrás: is → was, will → would, can → could."]},{"id":"b1-u10-l03","unit_id":"b1-u10","position":4,"title_es":"Preguntó si…","objective_es":"Contar lo que alguien preguntó: asked if, asked where.","intro":{"explanation":"Una pregunta de sí o no se cuenta con asked if: «Are you ready?» → She asked if we were ready. Con pregunta de información se repite la palabra y se ordena como afirmación: «Where do you live?» → He asked where I lived.","examples":[{"target":"She asked if we were ready.","base":"Preguntó si estábamos listos."},{"target":"He asked me where I lived.","base":"Me preguntó dónde vivía."}]},"takeaways":["Cuentas preguntas de sí o no con asked if.","Cuentas preguntas de información: asked where / what / when…"]},{"id":"b1-u10-l04","unit_id":"b1-u10","position":5,"title_es":"Sucesos","objective_es":"Entender noticias de sucesos: accidentes, incendios y rescates.","intro":{"explanation":"Las noticias de sucesos usan mucho la pasiva: ten people were rescued, nobody was injured. According to (según) dice de dónde viene la información: According to the police…","examples":[{"target":"There was a fire in the building.","base":"Hubo un incendio en el edificio."},{"target":"According to the police, nobody was injured.","base":"Según la policía, no hubo heridos."}]},"takeaways":["Entiendes noticias de accidentes e incendios.","Dices de dónde viene la información: according to."]},{"id":"b1-u10-l05","unit_id":"b1-u10","position":7,"title_es":"Fuentes confiables","objective_es":"Hablar de política, anuncios y noticias falsas; revisar la fuente.","intro":{"explanation":"Government (gobierno), president (presidente) y election (elecciones) son palabras frecuentes en las noticias. Announce es anunciar. Fake news son noticias falsas: antes de compartir, check the source (revisa la fuente).","examples":[{"target":"The government announced new rules.","base":"El gobierno anunció nuevas normas."},{"target":"Always check the source.","base":"Siempre revisa la fuente."}]},"takeaways":["Entiendes noticias sobre el gobierno y las elecciones.","Reconoces noticias falsas y revisas la fuente."]},{"id":"b1-u11-l01","unit_id":"b1-u11","position":1,"title_es":"¿Qué opinas?","objective_es":"Dar tu opinión y decir si estás de acuerdo.","intro":{"explanation":"Para opinar: In my opinion… / I think… Para acordar: I agree (with you). Para discrepar con cortesía: I don't agree o I disagree. Ojo: en inglés no se dice «I am agree».","examples":[{"target":"In my opinion, it is a good idea.","base":"En mi opinión, es una buena idea."},{"target":"I don't agree with you.","base":"No estoy de acuerdo contigo."}]},"takeaways":["Das tu opinión: In my opinion…, I think…","Acuerdas y discrepas: I agree, I disagree."]},{"id":"b1-u11-l02","unit_id":"b1-u11","position":2,"title_es":"Ventajas y desventajas","objective_es":"Comparar opciones con ventajas, desventajas y on the other hand.","intro":{"explanation":"Para comparar dos opciones: One advantage is… (una ventaja es…), The main disadvantage is… (la desventaja principal es…). On the other hand (por otro lado) presenta el otro punto de vista.","examples":[{"target":"One advantage of the city is the transport.","base":"Una ventaja de la ciudad es el transporte."},{"target":"It is cheap. On the other hand, it is far.","base":"Es barato. Por otro lado, queda lejos."}]},"takeaways":["Presentas ventajas y desventajas.","Muestras los dos lados con on the other hand."]},{"id":"b1-u11-rev1","unit_id":"b1-u11","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «¿Qué opinas?» y «Ventajas y desventajas».","intro":null,"takeaways":[]},{"id":"b1-u11-l03","unit_id":"b1-u11","position":4,"title_es":"Si fuera…","objective_es":"Imaginar situaciones y aconsejar con el segundo condicional e if I were you.","intro":{"explanation":"Para algo imaginario: If + pasado, would + verbo. If I had a million dollars, I would travel. If I were you (yo que tú) sirve para aconsejar: If I were you, I would talk to her. I would se contrae en I'd.","examples":[{"target":"If I had more time, I would travel more.","base":"Si tuviera más tiempo, viajaría más."},{"target":"If I were you, I'd talk to her.","base":"Yo que tú, hablaría con ella."}]},"takeaways":["Imaginas situaciones con if + pasado y would.","Aconsejas con If I were you, I would…"]},{"id":"b1-u11-l04","unit_id":"b1-u11","position":5,"title_es":"Relaciones","objective_es":"Hablar de amistades y relaciones: llevarse bien, discutir, confiar, pedir perdón.","intro":{"explanation":"Get on (well) with es llevarse bien con alguien. Argue es discutir. Trust es confiar (I trust you). Apologize es pedir perdón: I want to apologize for yesterday. Support es apoyar.","examples":[{"target":"I get on well with my sister.","base":"Me llevo bien con mi hermana."},{"target":"I want to apologize for yesterday.","base":"Quiero pedirte perdón por lo de ayer."}]},"takeaways":["Cuentas cómo te llevas con la gente.","Pides perdón y dices en quién confías."]},{"id":"b1-u11-l05","unit_id":"b1-u11","position":7,"title_es":"Deseos y preferencias","objective_es":"Expresar deseos (I wish) y preferencias (would rather).","intro":{"explanation":"I wish + pasado expresa un deseo sobre el presente que no es real: I wish I had more time (ojalá tuviera…). Would rather + verbo es «preferiría»: I would rather stay at home. Jealous es celoso o envidioso.","examples":[{"target":"I wish I had more free time.","base":"Ojalá tuviera más tiempo libre."},{"target":"I would rather live near the sea.","base":"Preferiría vivir cerca del mar."}]},"takeaways":["Expresas deseos con I wish + pasado.","Dices qué preferirías con would rather."]},{"id":"b1-u12-l01","unit_id":"b1-u12","position":1,"title_es":"Debe ser…","objective_es":"Sacar conclusiones con must be, might be y can't be.","intro":{"explanation":"Para deducir: must be (estás casi seguro de que sí), might be (es posible) y can't be (estás casi seguro de que no). You must be tired = seguro que estás cansado. That can't be true = eso no puede ser cierto.","examples":[{"target":"You must be tired after the trip.","base":"Debes estar cansado después del viaje."},{"target":"That can't be true!","base":"¡Eso no puede ser cierto!"}]},"takeaways":["Sacas conclusiones con must be y can't be.","Dices lo que es posible con might be."]},{"id":"b1-u12-l02","unit_id":"b1-u12","position":2,"title_es":"Se rompió","objective_es":"Explicar que algo se rompió o se acabó y pedir que lo arreglen.","intro":{"explanation":"Break down es romperse una máquina (un auto, un refrigerador): My car has broken down. Run out of es quedarse sin algo: We have run out of milk. Fix es arreglar y replace, reemplazar.","examples":[{"target":"My car has broken down.","base":"Se me rompió el auto."},{"target":"We have run out of milk.","base":"Nos quedamos sin leche."}]},"takeaways":["Explicas que algo se rompió o se acabó.","Pides que lo arreglen o lo cambien: fix, replace."]},{"id":"b1-u12-l03","unit_id":"b1-u12","position":4,"title_es":"Hacer un reclamo","objective_es":"Reclamar con cortesía y pedir un reembolso o un cambio.","intro":{"explanation":"Complain es quejarse y a complaint, un reclamo. Para reclamar con cortesía: I would like to make a complaint. Could you replace it? I would like a refund (que te devuelvan el dinero). The receipt es el ticket.","examples":[{"target":"I would like to make a complaint.","base":"Quisiera hacer un reclamo."},{"target":"Can I have a refund, please?","base":"¿Me pueden devolver el dinero, por favor?"}]},"takeaways":["Haces un reclamo con cortesía.","Pides un reembolso o un cambio y muestras el ticket."]},{"id":"b1-u12-l04","unit_id":"b1-u12","position":5,"title_es":"Causas y contrastes","objective_es":"Explicar causas, consecuencias y contrastes con conectores.","intro":{"explanation":"Because of va con un sustantivo (because of the storm); because, con una oración. Therefore (por lo tanto) da la consecuencia. Although (aunque) une dos ideas en una oración; however (sin embargo) empieza la oración siguiente.","examples":[{"target":"Because of the storm, the trains are canceled.","base":"Por la tormenta, los trenes están cancelados."},{"target":"The hotel was nice. However, it was expensive.","base":"El hotel era lindo. Sin embargo, era caro."}]},"takeaways":["Explicas causas con because of y consecuencias con therefore.","Muestras contrastes con although y however."]},{"id":"b1-u12-l05","unit_id":"b1-u12","position":7,"title_es":"Buscar soluciones","objective_es":"Proponer soluciones con los condicionales y sort out.","intro":{"explanation":"Sort out es resolver un problema: Don't worry, we'll sort it out. Para proponer soluciones usas los dos condicionales: If we call the mechanic, he will fix it (posible). If I had more money, I would buy a new car (imaginario).","examples":[{"target":"Don't worry, we'll sort it out.","base":"No te preocupes, lo vamos a resolver."},{"target":"There is a solution for every problem.","base":"Hay una solución para cada problema."}]},"takeaways":["Propones soluciones con if.","Tranquilizas a alguien: We'll sort it out."]},{"id":"b2-u01-l01","unit_id":"b2-u01","position":1,"title_es":"No quise decir eso","objective_es":"Aclarar un malentendido y explicar lo que quisiste decir.","intro":{"explanation":"Cuando algo se entiende mal, en inglés aclaras la intención con mean to: I didn’t mean to sound rude (no fue mi intención). Actually corrige una idea equivocada: Actually, I wasn’t angry (en realidad). Un misunderstanding es un malentendido y el tone, el tono de lo que dices.","examples":[{"target":"I didn't mean to sound rude.","base":"No fue mi intención sonar maleducado."},{"target":"It wasn't an argument, just a misunderstanding.","base":"No fue una pelea, sólo un malentendido."}]},"takeaways":["Aclaras tu intención con I didn’t mean to…","Corriges una idea equivocada con actually."]},{"id":"b2-u01-l02","unit_id":"b2-u01","position":2,"title_es":"Leer entre líneas","objective_es":"Entender indirectas, sarcasmo y lo que alguien da a entender.","intro":{"explanation":"No todo se dice de forma directa. Imply es dar a entender algo sin decirlo; to drop a hint es tirar una indirecta. Si alguien es sarcastic, dice lo contrario de lo que piensa. Apparently (al parecer) y seem (parecer) muestran que no estás del todo seguro.","examples":[{"target":"Are you implying that I am lazy?","base":"¿Estás insinuando que soy vago?"},{"target":"Apparently, she was talking about Tom.","base":"Al parecer, hablaba de Tom."}]},"takeaways":["Reconoces una indirecta y el sarcasmo.","Cuentas lo que no sabes seguro con apparently y seem."]},{"id":"b2-u01-l03","unit_id":"b2-u01","position":4,"title_es":"Recordar, dejar, intentar","objective_es":"Usar remember, forget, stop, try y regret con -ing o con infinitivo.","intro":{"explanation":"Con -ing hablas de algo que ya hiciste o de la actividad misma: I remember meeting her (me acuerdo de haberla conocido), I regret saying it (me arrepiento de haberlo dicho), We stopped talking (dejamos de hablar). Con to + verbo hablas de lo que hay que hacer o del propósito: Remember to call (acuérdate de llamar), We stopped to talk (paramos para hablar). Try + -ing es probar algo; try to, intentar.","examples":[{"target":"I remember meeting her, but I forgot to ask her name.","base":"Me acuerdo de haberla conocido, pero me olvidé de preguntarle el nombre."},{"target":"I regret saying those things to my brother.","base":"Me arrepiento de haberle dicho esas cosas a mi hermano."}]},"takeaways":["Distingues remember doing (ya pasó) de remember to do (hay que hacerlo).","Usas stop, try y regret con el sentido correcto."]},{"id":"b2-u01-l04","unit_id":"b2-u01","position":5,"title_es":"Directo, pero con tacto","objective_es":"Decir algo difícil de forma clara y amable.","intro":{"explanation":"Straightforward es claro y directo (algo bueno); blunt es tan directo que puede ofender; tactful es tener tacto. Para señalar un problema usas point out, y para sacar un tema, bring up. Tend to (soler) suaviza una crítica: You tend to interrupt people suena mejor que You always interrupt.","examples":[{"target":"She pointed out a mistake in my report.","base":"Señaló un error en mi informe."},{"target":"People tend to speak faster when they are nervous.","base":"La gente tiende a hablar más rápido cuando está nerviosa."}]},"takeaways":["Distingues straightforward, blunt y tactful.","Señalas un problema con point out y lo suavizas con tend to."]},{"id":"b2-u01-l05","unit_id":"b2-u01","position":7,"title_es":"Más allá de las palabras","objective_es":"Interpretar el lenguaje corporal y suavizar lo que dices.","intro":{"explanation":"El body language (lenguaje corporal) también comunica. Para hablar de lo que ves sin afirmarlo: He seems nervous, She tends to look away. Para suavizar una opinión: I’d say…, It seems to me that…, a bit. Y si no se entendió tu idea: I couldn’t get my point across.","examples":[{"target":"His body language showed that he was nervous.","base":"Su lenguaje corporal mostraba que estaba nervioso."},{"target":"It is hard to get your ideas across in a short message.","base":"Es difícil transmitir tus ideas en un mensaje corto."}]},"takeaways":["Describes el lenguaje corporal con seem y tend to.","Suavizas una opinión y explicas si una idea no se entendió."]},{"id":"b2-u02-l01","unit_id":"b2-u02","position":1,"title_es":"Sentarse a negociar","objective_es":"Presentar una propuesta, negociar un precio y cerrar un trato.","intro":{"explanation":"Para negociar: negotiate a price (negociar un precio), make a proposal (hacer una propuesta) y, al final, reach an agreement (llegar a un acuerdo). We have a deal significa trato hecho. Para sugerir algo con suavidad, What if we…? va con el pasado: What if we kept the price?","examples":[{"target":"We need to negotiate a better price.","base":"Tenemos que negociar un mejor precio."},{"target":"If you agree, we have a deal.","base":"Si estás de acuerdo, trato hecho."}]},"takeaways":["Presentas y discutes una propuesta.","Cierras una negociación: We have a deal, we reached an agreement."]},{"id":"b2-u02-l02","unit_id":"b2-u02","position":2,"title_es":"Ceder un poco","objective_es":"Buscar un término medio y decir qué es lo más importante para ti.","intro":{"explanation":"En una negociación nadie consigue todo: a compromise es un término medio. Let’s meet halfway propone que los dos cedan un poco. Para explicar qué te importa más: Our main priority is… Y si puedes adaptarte, eres flexible.","examples":[{"target":"You want ten, I want six. Let's meet halfway at eight.","base":"Tú quieres diez y yo seis. Cedamos los dos: ocho."},{"target":"Our main priority is the customer.","base":"Nuestra prioridad principal es el cliente."}]},"takeaways":["Propones un término medio: Let’s meet halfway.","Explicas tus prioridades y si puedes ser flexible."]},{"id":"b2-u02-l03","unit_id":"b2-u02","position":4,"title_es":"Con una condición","objective_es":"Poner condiciones y precauciones con as long as, provided that, otherwise e in case.","intro":{"explanation":"As long as y provided that ponen una condición y van con presente: I’ll sign, provided that the price stays the same. Otherwise dice qué pasa si no se cumple. In case es una precaución: llevas un paraguas in case it rains (por si llueve, aunque no sepas si va a llover).","examples":[{"target":"You can borrow my car as long as you drive carefully.","base":"Puedes usar mi auto siempre que manejes con cuidado."},{"target":"Take an umbrella in case it rains.","base":"Lleva un paraguas por si llueve."}]},"takeaways":["Pones condiciones con as long as y provided that.","Hablas de precauciones con in case y de consecuencias con otherwise."]},{"id":"b2-u02-l04","unit_id":"b2-u02","position":5,"title_es":"Liderar un equipo","objective_es":"Repartir tareas, hablar de la carga de trabajo y convencer.","intro":{"explanation":"A leader no hace todo: delegate es delegar tareas en otros. Si tienes demasiado trabajo, tu workload es demasiado grande. Take on es asumir una tarea nueva. Persuade someone to do something es convencer a alguien de hacer algo.","examples":[{"target":"You should delegate some tasks to your team.","base":"Deberías delegar algunas tareas en tu equipo."},{"target":"She took on a new project last week.","base":"La semana pasada asumió un proyecto nuevo."}]},"takeaways":["Hablas de la carga de trabajo y de asumir tareas nuevas.","Delegas y convences con persuade."]},{"id":"b2-u02-l05","unit_id":"b2-u02","position":7,"title_es":"Decir que no con cortesía","objective_es":"Rechazar una oferta o una tarea sin cerrar la puerta.","intro":{"explanation":"Turn down es rechazar (una oferta, una invitación, un trabajo). Para decir que no con cortesía, suavizas: I’m afraid I’ll have to turn it down (me temo que…), I’d love to, but… Y si quieres seguir negociando, ofreces una alternativa con as long as o provided that.","examples":[{"target":"He turned down the job because the salary was too low.","base":"Rechazó el trabajo porque el sueldo era muy bajo."},{"target":"I'm afraid I'll have to turn it down.","base":"Me temo que voy a tener que rechazarlo."}]},"takeaways":["Rechazas algo con cortesía: I’m afraid I’ll have to turn it down.","Ofreces una alternativa con una condición."]},{"id":"b2-u03-l01","unit_id":"b2-u03","position":1,"title_es":"Una sociedad que cambia","objective_es":"Hablar de cambios sociales, generaciones y costumbres.","intro":{"explanation":"Para hablar de cambios sociales: society (sociedad), generation (generación), trend (tendencia) y custom (costumbre). Ojo: custom no es «costume» (disfraz). Los cambios se cuentan con el present perfect: Technology has changed our society.","examples":[{"target":"Technology has changed our society.","base":"La tecnología cambió nuestra sociedad."},{"target":"Working from home is a growing trend.","base":"Trabajar desde casa es una tendencia en aumento."}]},"takeaways":["Hablas de la sociedad, las generaciones y sus costumbres.","Describes tendencias con el present perfect."]},{"id":"b2-u03-l02","unit_id":"b2-u03","position":2,"title_es":"Cifras y encuestas","objective_es":"Entender y contar datos: mayorías, promedios, aumentos y caídas.","intro":{"explanation":"Para dar cifras: the majority of (la mayoría de), a minority of (una minoría de), the average family (la familia promedio), one in four (uno de cada cuatro). Rise (rose, risen) es aumentar y decline, disminuir. Una survey es una encuesta.","examples":[{"target":"The population of the city has risen.","base":"La población de la ciudad aumentó."},{"target":"The majority of people voted for the plan.","base":"La mayoría de la gente votó a favor del plan."}]},"takeaways":["Entiendes datos de una encuesta: majority, minority, average.","Cuentas aumentos y caídas con rise y decline."]},{"id":"b2-u03-l03","unit_id":"b2-u03","position":4,"title_es":"Se dice que…","objective_es":"Contar lo que se dice, se cree o se espera con la pasiva impersonal.","intro":{"explanation":"Para contar lo que dice o piensa mucha gente, sin decir quién: It is said that… (se dice que), It is believed that… (se cree que). También con la persona o la cosa como sujeto: The homes are expected to be ready next year (se espera que estén listas). Algo widespread es muy extendido.","examples":[{"target":"It is said that the house is two hundred years old.","base":"Se dice que la casa tiene doscientos años."},{"target":"The new homes are expected to be ready next year.","base":"Se espera que las viviendas nuevas estén listas el año que viene."}]},"takeaways":["Cuentas lo que se dice o se cree: It is said that…","Cuentas lo que se espera: …is expected to…"]},{"id":"b2-u03-l04","unit_id":"b2-u03","position":5,"title_es":"Obras en marcha","objective_es":"Contar lo que se está haciendo y lo que ya se hizo con la pasiva.","intro":{"explanation":"Para algo que se está haciendo ahora: is / are being + participio (A new school is being built). Para algo que ya se hizo: has / have been + participio (The roof has been repaired). Take place es tener lugar, realizarse (un evento). Housing es la vivienda en general.","examples":[{"target":"A new school is being built near my house.","base":"Se está construyendo una escuela nueva cerca de mi casa."},{"target":"The festival will take place in the old market.","base":"El festival se va a realizar en el mercado viejo."}]},"takeaways":["Cuentas obras en marcha con is being + participio.","Cuentas lo que ya se hizo con has been + participio."]},{"id":"b2-u03-l05","unit_id":"b2-u03","position":7,"title_es":"Una ciudad diversa","objective_es":"Hablar de la diversidad y opinar sobre lo que se debería hacer.","intro":{"explanation":"Diversity es la diversidad (de culturas, de idiomas, de edades). Para opinar sobre lo que habría que hacer sin decir quién: should be + participio (More homes should be built). También can be + participio para posibilidades: Many languages can be heard in the market.","examples":[{"target":"The diversity of the city is its best quality.","base":"La diversidad de la ciudad es su mejor cualidad."},{"target":"More homes should be built for young people.","base":"Deberían construirse más viviendas para los jóvenes."}]},"takeaways":["Hablas de la diversidad de un lugar.","Opinas sobre lo que se debería hacer con should be + participio."]},{"id":"b2-u04-l01","unit_id":"b2-u04","position":1,"title_es":"En el laboratorio","objective_es":"Hablar de científicos, experimentos y pruebas.","intro":{"explanation":"A scientist hace research (investigación) y experiments. Evidence son las pruebas que demuestran algo: es incontable, así que se dice some evidence, no «an evidence». A discovery es un descubrimiento.","examples":[{"target":"The experiment failed, but we learned a lot.","base":"El experimento falló, pero aprendimos mucho."},{"target":"There is no evidence that it works.","base":"No hay pruebas de que funcione."}]},"takeaways":["Hablas de experimentos, pruebas y descubrimientos.","Usas evidence como incontable: some evidence, no evidence."]},{"id":"b2-u04-l02","unit_id":"b2-u04","position":2,"title_es":"Un gran avance","objective_es":"Contar un invento o una idea nueva y quién la tuvo.","intro":{"explanation":"Come up with es idear, tener una idea: Who came up with this? A breakthrough es un avance clave. Invention es un invento e innovation, la innovación. Whose (cuyo) une a una persona con algo suyo: the scientist whose team won the prize.","examples":[{"target":"Who came up with this idea?","base":"¿A quién se le ocurrió esta idea?"},{"target":"She is the scientist whose team won the prize.","base":"Es la científica cuyo equipo ganó el premio."}]},"takeaways":["Cuentas quién tuvo una idea con come up with.","Unes una persona con algo suyo con whose."]},{"id":"b2-u04-l03","unit_id":"b2-u04","position":4,"title_es":"Información extra entre comas","objective_es":"Agregar información con oraciones de relativo explicativas y which.","intro":{"explanation":"Las explicativas van entre comas y dan información extra: The telephone, which was invented in 1876, … No se usa that. Which también puede retomar toda una idea: One experiment failed, which was frustrating (lo cual). Most of which y many of whom: la mayoría de los cuales, muchos de los cuales.","examples":[{"target":"One of our experiments failed, which was very frustrating.","base":"Uno de nuestros experimentos falló, lo cual fue muy frustrante."},{"target":"I have many books, most of which I have never read.","base":"Tengo muchos libros, la mayoría de los cuales nunca leí."}]},"takeaways":["Agregas información extra entre comas con which y who.","Retomas toda una idea con which y hablas de partes con most of which."]},{"id":"b2-u04-l04","unit_id":"b2-u04","position":5,"title_es":"Máquinas que piensan","objective_es":"Opinar sobre la inteligencia artificial, los datos y la privacidad.","intro":{"explanation":"Artificial intelligence (AI) es la inteligencia artificial. Data (datos) se usa casi siempre como incontable: the data is / are. Privacy es la privacidad. Rely on es depender de algo o confiar en que funcione: We rely on our phones.","examples":[{"target":"We rely on our phones for everything.","base":"Dependemos del teléfono para todo."},{"target":"I worry about my privacy online.","base":"Me preocupa mi privacidad en internet."}]},"takeaways":["Hablas de la inteligencia artificial, los datos y la privacidad.","Dices de qué dependes con rely on."]},{"id":"b2-u04-l05","unit_id":"b2-u04","position":7,"title_es":"Ponerse al día","objective_es":"Hablar de tecnología nueva y vieja y de cómo seguirle el ritmo.","intro":{"explanation":"Keep up with es mantenerse al día, seguir el ritmo: It’s hard to keep up with technology. Algo outdated está anticuado; algo cutting-edge es de vanguardia. Con which puedes agregar un comentario: My phone, which I bought ten years ago, still works.","examples":[{"target":"It's hard to keep up with technology.","base":"Es difícil mantenerse al día con la tecnología."},{"target":"The lab uses cutting-edge technology.","base":"El laboratorio usa tecnología de vanguardia."}]},"takeaways":["Cuentas si te cuesta seguirle el ritmo a la tecnología.","Describes algo como outdated o cutting-edge."]},{"id":"b2-u05-l01","unit_id":"b2-u05","position":1,"title_es":"¿Me lo puedo permitir?","objective_es":"Hablar de ahorros, préstamos y deudas.","intro":{"explanation":"Afford es poder permitirse algo: I can’t afford it (no me alcanza). Savings son los ahorros; a loan, un préstamo (take out a loan = pedir un préstamo); debt, una deuda. The interest rate es la tasa de interés.","examples":[{"target":"I can't afford a new car right now.","base":"Ahora no me puedo permitir un auto nuevo."},{"target":"She took out a loan to buy a flat.","base":"Pidió un préstamo para comprarse un apartamento."}]},"takeaways":["Dices si puedes permitirte algo con afford.","Hablas de ahorros, préstamos, deudas e intereses."]},{"id":"b2-u05-l02","unit_id":"b2-u05","position":2,"title_es":"Gastar menos","objective_es":"Contar cómo ahorrar: recortar gastos, comprar usado y buscar ofertas.","intro":{"explanation":"Cut back on es gastar menos en algo: cut back on subscriptions. Second-hand es de segunda mano, usado. A bargain es una ganga. Para contar lo que hiciste para ahorrar usas el present perfect o el past simple, como siempre.","examples":[{"target":"We need to cut back on eating out.","base":"Tenemos que gastar menos en comer afuera."},{"target":"I bought a second-hand bike for fifty dollars.","base":"Compré una bici usada por cincuenta dólares."}]},"takeaways":["Cuentas en qué gastas menos con cut back on.","Hablas de compras usadas y de gangas."]},{"id":"b2-u05-l03","unit_id":"b2-u05","position":4,"title_es":"Mandar a hacer","objective_es":"Explicar que otra persona te hace o te arregla algo: have something done.","intro":{"explanation":"Have / get + objeto + participio: alguien hace algo por ti. I had my phone repaired (me arreglaron el teléfono, no lo arreglé yo). I’m going to get my hair cut (me voy a cortar el pelo, en la peluquería). Compara: I repaired my phone = lo arreglé yo.","examples":[{"target":"I had my phone repaired last week.","base":"La semana pasada me arreglaron el teléfono."},{"target":"I'd like to have the screen replaced.","base":"Quisiera que me cambiaran la pantalla."}]},"takeaways":["Cuentas lo que te hacen con have / get + objeto + participio.","Distingues I had it repaired de I repaired it."]},{"id":"b2-u05-l04","unit_id":"b2-u05","position":5,"title_es":"Comparar con matices","objective_es":"Comparar precios y calidad: by far, twice as, nowhere near.","intro":{"explanation":"By far refuerza un superlativo: by far the best (por lejos el mejor). Twice as … as es el doble: twice as expensive as. Nowhere near as … as es «ni de cerca tan… como». The …-er, the …-er: The older the phone, the less sense it makes (cuanto más viejo, menos sentido tiene). Value for money es la relación calidad-precio.","examples":[{"target":"This phone is twice as expensive as that one.","base":"Este teléfono es el doble de caro que ese."},{"target":"The cheap ones are nowhere near as good.","base":"Los baratos no son ni de cerca tan buenos."}]},"takeaways":["Comparas con by far, twice as… as y nowhere near as… as.","Hablas de la relación calidad-precio."]},{"id":"b2-u05-l05","unit_id":"b2-u05","position":7,"title_es":"Consumidores exigentes","objective_es":"Opinar sobre marcas y precios: ganga, robo, demasiado caro.","intro":{"explanation":"A consumer es un consumidor. A brand es una marca. Si algo es carísimo para lo que vale, es overpriced; si el precio es abusivo, a rip-off (¡qué robo!). Lo contrario: a bargain o good value for money.","examples":[{"target":"Ten dollars for a coffee? What a rip-off!","base":"¿Diez dólares por un café? ¡Qué robo!"},{"target":"The food was good, but overpriced.","base":"La comida era buena, pero demasiado cara."}]},"takeaways":["Opinas sobre marcas y precios como consumidor.","Dices si algo es una ganga, un robo o demasiado caro."]},{"id":"b2-u06-l01","unit_id":"b2-u06","position":1,"title_es":"Algo debe de haber pasado","objective_es":"Deducir qué pasó con must have, might have y can't have.","intro":{"explanation":"Para deducir algo del pasado: must have + participio (estás casi seguro: She must have lost her phone), might / could have (es posible: She might have been busy) y can’t have (estás casi seguro de que no: She can’t have forgotten). En la conversación suena «must’ve», «might’ve».","examples":[{"target":"You must have been very tired.","base":"Debes de haber estado muy cansado."},{"target":"He might have missed the bus.","base":"Puede que haya perdido el autobús."}]},"takeaways":["Deduces lo que pasó con must have y can’t have.","Dices lo que es posible con might have."]},{"id":"b2-u06-l02","unit_id":"b2-u06","position":2,"title_es":"Lo que debería haber hecho","objective_es":"Lamentar y criticar el pasado con should have y could have.","intro":{"explanation":"Should have + participio: algo que era lo correcto y no pasó (I should have called you = debería haberte llamado). Shouldn’t have: algo que pasó y no tendría que haber pasado. Could have: una posibilidad que no se aprovechó (You could have told me = me lo podrías haber dicho). Si te sientes mal por algo que hiciste, te sientes guilty.","examples":[{"target":"I should have called you yesterday.","base":"Debería haberte llamado ayer."},{"target":"You could have told me earlier!","base":"¡Me lo podrías haber dicho antes!"}]},"takeaways":["Lamentas lo que hiciste o no hiciste con should / shouldn’t have.","Reprochas con could have y dices que te sientes culpable."]},{"id":"b2-u06-l03","unit_id":"b2-u06","position":4,"title_es":"Peleas y reconciliaciones","objective_es":"Contar una pelea, reconocer que exageraste y hacer las paces.","intro":{"explanation":"Fall out (with someone) es pelearse; make up, reconciliarse. Overreact es exagerar, reaccionar de más. Don’t take it personally: no te lo tomes como algo personal. Si alguien está upset, está molesto o dolido (no «enojado» del todo).","examples":[{"target":"I fell out with my best friend last week.","base":"La semana pasada me peleé con mi mejor amiga."},{"target":"They argued, but they made up the next day.","base":"Discutieron, pero al día siguiente se reconciliaron."}]},"takeaways":["Cuentas una pelea con fall out y una reconciliación con make up.","Reconoces que exageraste y pides que no lo tomen como algo personal."]},{"id":"b2-u06-l04","unit_id":"b2-u06","position":5,"title_es":"Estados de ánimo","objective_es":"Hablar del humor, animar a alguien y contar que alguien te falló.","intro":{"explanation":"Mood es el humor: in a good / bad mood. Cheer up es animar (Cheer up! = ¡Arriba!) y cheer someone up, animar a alguien. Let someone down es fallarle, decepcionarlo. Grateful es agradecido; stubborn, terco.","examples":[{"target":"Don't talk to him now. He is in a bad mood.","base":"No le hables ahora. Está de mal humor."},{"target":"I trusted you, and you let me down.","base":"Confié en ti y me fallaste."}]},"takeaways":["Describes el humor de alguien y lo animas.","Dices que alguien te falló o que estás agradecido."]},{"id":"b2-u06-l05","unit_id":"b2-u06","position":7,"title_es":"Ponerse en el lugar del otro","objective_es":"Hablar de la empatía y de la confianza en uno mismo.","intro":{"explanation":"Empathy es entender cómo se siente otra persona: to put yourself in someone’s shoes (ponerse en su lugar). Self-confidence es la confianza en uno mismo. Para hablar de lo que alguien podría haber sentido: She might have felt alone.","examples":[{"target":"Empathy means understanding how others feel.","base":"Empatía significa entender cómo se sienten los demás."},{"target":"Learning a language gave me more self-confidence.","base":"Aprender un idioma me dio más confianza en mí mismo."}]},"takeaways":["Explicas qué es la empatía y cómo se practica.","Hablas de tu confianza en ti mismo."]},{"id":"b2-u07-l01","unit_id":"b2-u07","position":1,"title_es":"Un planeta más caliente","objective_es":"Hablar del calentamiento global, las emisiones y sus consecuencias.","intro":{"explanation":"Global warming es el calentamiento global, causado sobre todo por las emissions (emisiones) de CO2. Tu carbon footprint es tu huella de carbono: cuánto contaminas con lo que haces. Una consequence es una consecuencia: Floods are a consequence of global warming.","examples":[{"target":"Global warming is changing the weather.","base":"El calentamiento global está cambiando el clima."},{"target":"Eating less meat reduces your carbon footprint.","base":"Comer menos carne reduce tu huella de carbono."}]},"takeaways":["Hablas del calentamiento global y las emisiones.","Explicas tu huella de carbono y las consecuencias."]},{"id":"b2-u07-l02","unit_id":"b2-u07","position":2,"title_es":"Sequías e inundaciones","objective_es":"Entender una noticia sobre sequías, inundaciones y escasez.","intro":{"explanation":"A drought es una sequía; a flood, una inundación. A shortage es la escasez o la falta de algo: a water shortage. A threat es una amenaza. Las noticias suelen usar el present perfect: There hasn’t been any rain for eight months.","examples":[{"target":"It is the worst drought in fifty years.","base":"Es la peor sequía en cincuenta años."},{"target":"There is a water shortage in three towns.","base":"Hay escasez de agua en tres pueblos."}]},"takeaways":["Entiendes noticias sobre sequías, inundaciones y escasez.","Hablas de amenazas y consecuencias del clima extremo."]},{"id":"b2-u07-l03","unit_id":"b2-u07","position":4,"title_es":"A pesar de todo","objective_es":"Contrastar ideas con despite, in spite of, even though y even if.","intro":{"explanation":"Despite e in spite of van con un sustantivo o con -ing: Despite the rain… / In spite of feeling tired… Even though va con una oración completa y es más enfático que although: Even though I was tired, I finished. Even if es «aun si»: el resultado no cambia aunque se cumpla la condición.","examples":[{"target":"Despite the rain, we went for a walk.","base":"A pesar de la lluvia, salimos a caminar."},{"target":"Even if it rains, the game will go ahead.","base":"Aun si llueve, el partido se va a jugar."}]},"takeaways":["Usas despite / in spite of con un sustantivo o -ing.","Usas even though y even if con una oración."]},{"id":"b2-u07-l04","unit_id":"b2-u07","position":5,"title_es":"Energía y futuro","objective_es":"Hablar de soluciones: energía renovable, sostenibilidad y cómo enfrentar un problema.","intro":{"explanation":"Renewable energy es la energía renovable (solar, eólica). Sustainable es sostenible: que puede durar sin dañar el planeta. Tackle a problem es enfrentar o abordar un problema. Whereas (mientras que) compara dos cosas opuestas: Coal is cheap, whereas solar energy is clean.","examples":[{"target":"We need more renewable energy.","base":"Necesitamos más energía renovable."},{"target":"I love the city, whereas my brother prefers the country.","base":"A mí me encanta la ciudad, mientras que mi hermano prefiere el campo."}]},"takeaways":["Hablas de energía renovable y de un futuro sostenible.","Comparas dos ideas opuestas con whereas."]},{"id":"b2-u07-l05","unit_id":"b2-u07","position":7,"title_es":"Problemas globales","objective_es":"Hablar de la pobreza, las especies en peligro y por qué todo está conectado.","intro":{"explanation":"Poverty es la pobreza. An endangered animal está en peligro de extinción. Para relacionar problemas: X is connected to Y, X is a consequence of Y, X is a threat to Y. Y para no perder la esperanza: Despite these problems, there is good news.","examples":[{"target":"Poverty and the environment are connected.","base":"La pobreza y el medioambiente están relacionados."},{"target":"The panda is an endangered animal.","base":"El panda es un animal en peligro de extinción."}]},"takeaways":["Relacionas problemas globales: connected, consequence, threat.","Hablas de especies en peligro y de la pobreza."]},{"id":"b2-u08-l01","unit_id":"b2-u08","position":1,"title_es":"Se volvió viral","objective_es":"Hablar de rumores y publicaciones virales y de cómo se difunde la desinformación.","intro":{"explanation":"Algo que go viral (went viral) se comparte muchísimo en poco tiempo. A rumor es un rumor; misinformation, la desinformación. Spread (spread, spread) es difundirse. Clickbait es un título engañoso pensado para que hagas clic.","examples":[{"target":"The video went viral in one day.","base":"El video se volvió viral en un día."},{"target":"Fake news spreads faster than the truth.","base":"Las noticias falsas se difunden más rápido que la verdad."}]},"takeaways":["Cuentas que algo se volvió viral y se difundió.","Reconoces rumores, desinformación y clickbait."]},{"id":"b2-u08-l02","unit_id":"b2-u08","position":2,"title_es":"Lo que dijo, con precisión","objective_es":"Contar lo que alguien afirmó, sugirió o advirtió.","intro":{"explanation":"Claim that es afirmar algo que puede no ser cierto. Suggest va con -ing o con that: She suggested checking the website. Warn someone (not) to es advertir: He warned me not to touch it. Insist on + -ing o insist that: She insisted on paying.","examples":[{"target":"She suggested checking the official website.","base":"Sugirió consultar la página oficial."},{"target":"He warned me not to touch the cables.","base":"Me advirtió que no tocara los cables."}]},"takeaways":["Cuentas lo que alguien afirmó o sugirió con claim y suggest.","Cuentas advertencias e insistencias con warn e insist."]},{"id":"b2-u08-l03","unit_id":"b2-u08","position":4,"title_es":"Acusar, negar, admitir","objective_es":"Contar acusaciones, negaciones y confesiones con su forma correcta.","intro":{"explanation":"Accuse someone of + -ing: They accused him of lying. Deny + -ing es negar haber hecho algo: He denied taking the money. Admit + -ing es reconocerlo: She admitted making a mistake. Refuse to + verbo es negarse a hacer algo: He refused to answer.","examples":[{"target":"They accused him of lying.","base":"Lo acusaron de mentir."},{"target":"She admitted making a mistake.","base":"Reconoció haberse equivocado."}]},"takeaways":["Cuentas acusaciones con accuse someone of + -ing.","Usas deny y admit con -ing y refuse con to."]},{"id":"b2-u08-l04","unit_id":"b2-u08","position":5,"title_es":"Fuentes confiables","objective_es":"Distinguir fuentes confiables, parciales y engañosas.","intro":{"explanation":"A reliable source es una fuente confiable. Un artículo biased es parcial: muestra un solo lado. Misleading es engañoso (no siempre falso, pero lleva a una idea equivocada). Fact-check es verificar los datos.","examples":[{"target":"Is this a reliable source?","base":"¿Es una fuente confiable?"},{"target":"Always fact-check a story before you share it.","base":"Verifica siempre una noticia antes de compartirla."}]},"takeaways":["Evalúas si una fuente es confiable o parcial.","Detectas números y títulos engañosos y verificas antes de compartir."]},{"id":"b2-u08-l05","unit_id":"b2-u08","position":7,"title_es":"Los medios y su público","objective_es":"Opinar sobre los medios y contar una noticia con verbos de reporte.","intro":{"explanation":"The audience es el público de un programa, un medio o un espectáculo. Para contar una noticia con precisión, combinas los verbos de la unidad: The mayor denied the rumor, admitted that…, insisted that…, warned people not to…","examples":[{"target":"The program has a large audience.","base":"El programa tiene mucho público."},{"target":"The mayor denied the rumor about the park.","base":"La alcaldesa negó el rumor sobre el parque."}]},"takeaways":["Hablas del público de los medios.","Cuentas una noticia combinando claim, deny, admit, insist y warn."]},{"id":"b2-u09-l01","unit_id":"b2-u09","position":1,"title_es":"Si hubiera…","objective_es":"Imaginar un pasado distinto con el tercer condicional.","intro":{"explanation":"El tercer condicional habla de algo que no pasó y de su resultado imaginario: If + had + participio, would have + participio. If I had studied, I would have passed (si hubiera estudiado, habría aprobado; pero no estudié). En la conversación: If I’d studied, I’d have passed.","examples":[{"target":"If I had studied, I would have passed the exam.","base":"Si hubiera estudiado, habría aprobado el examen."},{"target":"If I hadn't left, I wouldn't have started my business.","base":"Si no me hubiera ido, no habría empezado mi negocio."}]},"takeaways":["Imaginas otro resultado para el pasado con if + had + participio.","Usas would have / wouldn’t have + participio en la otra parte."]},{"id":"b2-u09-l02","unit_id":"b2-u09","position":2,"title_es":"Ojalá hubiera…","objective_es":"Lamentar el pasado con if only y wish, y recordar una época.","intro":{"explanation":"Para lamentar algo del pasado: I wish / If only + past perfect. If only I had asked for help (ojalá hubiera pedido ayuda). I wish I hadn’t said that (ojalá no hubiera dicho eso). Look back on es recordar una época de tu vida. Struggle es tener dificultades con algo.","examples":[{"target":"If only I had asked for help.","base":"Ojalá hubiera pedido ayuda."},{"target":"I often look back on my school days.","base":"Muchas veces recuerdo mis años de colegio."}]},"takeaways":["Lamentas el pasado con if only / I wish + past perfect.","Recuerdas una época con look back on y cuentas qué te costaba."]},{"id":"b2-u09-l03","unit_id":"b2-u09","position":4,"title_es":"La forma de pensar","objective_es":"Hablar de la mentalidad, la motivación y el progreso.","intro":{"explanation":"Your mindset es tu forma de pensar. Potential es tu potencial: reach your potential (desarrollarlo al máximo). Motivation es la motivación. Make progress es progresar (progress es incontable: no se dice «a progress»).","examples":[{"target":"Your mindset is more important than your talent.","base":"Tu forma de pensar es más importante que tu talento."},{"target":"You are making great progress with your English.","base":"Estás progresando mucho con tu inglés."}]},"takeaways":["Hablas de la mentalidad y la motivación.","Cuentas tu progreso con make progress."]},{"id":"b2-u09-l04","unit_id":"b2-u09","position":5,"title_es":"Estudiar con método","objective_es":"Contar cómo organizas el estudio y cómo dejar de postergar.","intro":{"explanation":"Procrastinate es postergar, dejar todo para después. Self-discipline es la autodisciplina, la constancia. Keep track of es llevar la cuenta o el registro de algo. Catch up es ponerse al día: I need to catch up with the classes I missed.","examples":[{"target":"Learning a language takes self-discipline.","base":"Aprender un idioma requiere autodisciplina."},{"target":"I missed two classes, so I need to catch up.","base":"Falté a dos clases, así que tengo que ponerme al día."}]},"takeaways":["Cuentas cómo organizas tu estudio y llevas la cuenta.","Hablas de postergar, de la constancia y de ponerte al día."]},{"id":"b2-u09-l05","unit_id":"b2-u09","position":7,"title_es":"Salir de la zona de confort","objective_es":"Hablar de becas, inscripciones y de animarte a probar algo nuevo.","intro":{"explanation":"A scholarship es una beca. Enroll (in a course) es inscribirse. Your comfort zone es tu zona de confort, y step out of it, salir de ella. Give it a try es probarlo, animarse. Con el tercer condicional cuentas lo que habría pasado: If I’d known, I wouldn’t have…","examples":[{"target":"She won a scholarship to study abroad.","base":"Ganó una beca para estudiar en el exterior."},{"target":"You've never tried yoga? Give it a try!","base":"¿Nunca probaste yoga? ¡Pruébalo!"}]},"takeaways":["Hablas de becas e inscripciones.","Animas a alguien a probar algo fuera de su zona de confort."]},{"id":"b2-u10-l01","unit_id":"b2-u10","position":1,"title_es":"Sumar argumentos","objective_es":"Agregar razones y consecuencias en un debate.","intro":{"explanation":"En un debate o un texto formal, moreover y furthermore suman otra razón (además, asimismo); van al principio de la oración, seguidos de coma. As a result introduce la consecuencia. Son más formales que also y so.","examples":[{"target":"The plan is cheap. Moreover, it is easy to start.","base":"El plan es barato. Además, es fácil de empezar."},{"target":"It rained all week. As a result, the match was canceled.","base":"Llovió toda la semana. Como resultado, se canceló el partido."}]},"takeaways":["Sumas argumentos con moreover y furthermore.","Presentas consecuencias con as a result."]},{"id":"b2-u10-l02","unit_id":"b2-u10","position":2,"title_es":"Lo que importa es…","objective_es":"Enfatizar una idea con oraciones escindidas.","intro":{"explanation":"Para poner el foco en una idea: What + sujeto + verbo + is… (What matters is that you tried; What worries me is the cost). The reason why + oración + is that… También It is / was… that…: It is the cost of ignorance that should worry us. In other words reformula lo dicho (o sea, es decir).","examples":[{"target":"What matters is that you tried.","base":"Lo que importa es que lo intentaste."},{"target":"The reason why I called is that I need your help.","base":"La razón por la que llamé es que necesito tu ayuda."}]},"takeaways":["Enfatizas con What… is y The reason why… is that…","Reformulas una idea con in other words."]},{"id":"b2-u10-l03","unit_id":"b2-u10","position":4,"title_es":"Reconocer y rebatir","objective_es":"Reconocer el punto del otro y responder con tu postura.","intro":{"explanation":"Un buen argumento reconoce la otra postura antes de rebatirla. Admittedly (es cierto que…) concede un punto; nevertheless (aun así) vuelve a tu postura. On the contrary (al contrario) dice que es todo lo opuesto. Your point of view es tu punto de vista.","examples":[{"target":"Admittedly, it is expensive.","base":"Es cierto que es caro."},{"target":"I'm not tired. On the contrary, I feel great.","base":"No estoy cansado. Al contrario, me siento genial."}]},"takeaways":["Concedes un punto con admittedly y lo rebates con nevertheless.","Dices que es todo lo contrario con on the contrary."]},{"id":"b2-u10-l04","unit_id":"b2-u10","position":5,"title_es":"Argumentos sólidos","objective_es":"Evaluar si un argumento es válido y convincente.","intro":{"explanation":"A valid point es un argumento válido; convincing, convincente. An assumption es una suposición que no se demostró. Take into account es tener en cuenta: We need to take the costs into account (fíjate que el objeto puede ir en el medio).","examples":[{"target":"That's just an assumption. Where is the evidence?","base":"Eso es sólo una suposición. ¿Dónde están las pruebas?"},{"target":"We need to take the costs into account.","base":"Tenemos que tener en cuenta los costos."}]},"takeaways":["Evalúas argumentos: valid, convincing, assumption.","Pides que se tenga algo en cuenta con take into account."]},{"id":"b2-u10-l05","unit_id":"b2-u10","position":7,"title_es":"Sacar una conclusión","objective_es":"Cerrar un argumento: pesar pros y contras y resumir.","intro":{"explanation":"Outweigh es pesar más que algo: The benefits outweigh the costs. Para cerrar: To sum up (en resumen) o All things considered (en definitiva, considerando todo). Y una escindida da fuerza al final: It is the cost of ignorance that should worry us.","examples":[{"target":"The benefits outweigh the costs.","base":"Los beneficios superan a los costos."},{"target":"To sum up, I think the plan is a good idea.","base":"En resumen, creo que el plan es una buena idea."}]},"takeaways":["Comparas pros y contras con outweigh.","Concluyes con to sum up y all things considered."]},{"id":"b2-u11-l01","unit_id":"b2-u11","position":1,"title_es":"Comentar un libro","objective_es":"Hablar de una novela: la trama, los personajes y los capítulos.","intro":{"explanation":"A novel es una novela (no «una telenovela»). The plot es la trama; a character, un personaje (no el carácter de una persona); a chapter, un capítulo. Para opinar: The plot is clever, I couldn’t stop reading, My favorite character is…","examples":[{"target":"I could not stop reading the novel.","base":"No podía dejar de leer la novela."},{"target":"My favorite character is the old fisherman.","base":"Mi personaje favorito es el viejo pescador."}]},"takeaways":["Comentas una novela: trama, personajes y capítulos.","Das tu opinión sobre un libro."]},{"id":"b2-u11-l02","unit_id":"b2-u11","position":2,"title_es":"Giros inesperados","objective_es":"Hablar del narrador, de los giros de una historia y de cómo resultó todo.","intro":{"explanation":"The narrator es quien cuenta la historia. A twist es un giro inesperado. Turn out es resultar: It turns out that… (resulta que…). Set off es salir, ponerse en camino: She set off on foot.","examples":[{"target":"It turned out that we lived on the same street.","base":"Resultó que vivíamos en la misma calle."},{"target":"We set off early in the morning.","base":"Salimos temprano a la mañana."}]},"takeaways":["Hablas del narrador y de los giros de una historia.","Cuentas cómo resultó algo con turn out y cuándo salieron con set off."]},{"id":"b2-u11-l03","unit_id":"b2-u11","position":4,"title_es":"Contar con estilo","objective_es":"Contar una historia con oraciones con participio y expresiones vivas.","intro":{"explanation":"Con un participio resumes una acción del mismo sujeto: Walking past the lighthouse, she noticed a light (mientras pasaba…). Having + participio cuenta lo que pasó antes: Having missed the train, she walked. Expresiones que dan vida a un relato: out of the blue (de la nada), break the ice (romper el hielo), burst into tears (ponerse a llorar).","examples":[{"target":"Having missed the last train, Elena set off on foot.","base":"Como había perdido el último tren, Elena salió a pie."},{"target":"My old friend called me out of the blue.","base":"Mi viejo amigo me llamó de la nada."}]},"takeaways":["Unes acciones con un participio: Walking…, Having…","Cuentas con expresiones como out of the blue y burst into tears."]},{"id":"b2-u11-l04","unit_id":"b2-u11","position":5,"title_es":"Nunca había visto algo así","objective_es":"Dar dramatismo a un relato con la inversión.","intro":{"explanation":"En los relatos, si empiezas con never, hardly, no sooner o little, se invierten el auxiliar y el sujeto: Never had she felt so alone (= She had never felt so alone). Hardly had… when… y No sooner had… than…: una cosa pasó apenas terminó la otra. Little did I know…: poco me imaginaba.","examples":[{"target":"Never had she felt so alone.","base":"Nunca se había sentido tan sola."},{"target":"No sooner had we arrived than it started to rain.","base":"No bien llegamos, empezó a llover."}]},"takeaways":["Inviertes auxiliar y sujeto después de never, hardly y no sooner.","Anticipas un giro con Little did I know…"]},{"id":"b2-u11-l05","unit_id":"b2-u11","position":7,"title_es":"Expresiones de todos los días","objective_es":"Entender y usar expresiones idiomáticas frecuentes.","intro":{"explanation":"Las expresiones idiomáticas no se traducen palabra por palabra. A piece of cake es pan comido; once in a blue moon, muy de vez en cuando; the last straw, la gota que colmó el vaso. Úsalas en situaciones informales y con moderación.","examples":[{"target":"The exam was a piece of cake.","base":"El examen fue pan comido."},{"target":"I only go to the cinema once in a blue moon.","base":"Voy al cine muy de vez en cuando."}]},"takeaways":["Entiendes expresiones idiomáticas frecuentes.","Usas algunas en situaciones informales."]},{"id":"b2-u12-l01","unit_id":"b2-u12","position":1,"title_es":"Un dilema","objective_es":"Contar un dilema y pesar los pros y los contras.","intro":{"explanation":"A dilemma es un dilema: dos opciones difíciles. Weigh up es sopesar, evaluar: I’m weighing up the pros and cons (los pros y los contras). A trade-off es lo que pierdes a cambio de lo que ganas: More money, less free time.","examples":[{"target":"I am weighing up the pros and cons.","base":"Estoy sopesando los pros y los contras."},{"target":"More money, less free time: that is the trade-off.","base":"Más dinero, menos tiempo libre: ése es el costo."}]},"takeaways":["Cuentas un dilema y sopesas los pros y los contras.","Explicas lo que se pierde a cambio con trade-off."]},{"id":"b2-u12-l02","unit_id":"b2-u12","position":2,"title_es":"Si hubiera… ahora estaría…","objective_es":"Imaginar tu presente con otras decisiones: condicionales mixtos.","intro":{"explanation":"Condicional mixto 1: un pasado distinto cambia el presente. If + past perfect, would + verbo: If you had taken the job, you would be in Berlin now. Condicional mixto 2: un presente distinto habría cambiado el pasado. If + past simple, would have + participio: If I were braver, I would have said yes. Gut feeling es la intuición; have second thoughts, dudar.","examples":[{"target":"If you had taken the job, you'd be speaking German by now.","base":"Si hubieras aceptado el trabajo, ya estarías hablando alemán."},{"target":"If I were braver, I would have said yes.","base":"Si fuera más valiente, habría dicho que sí."}]},"takeaways":["Imaginas tu presente con un pasado distinto: If I had…, I would be…","Hablas de tu intuición y de tus dudas."]},{"id":"b2-u12-l03","unit_id":"b2-u12","position":4,"title_es":"Resolver un conflicto","objective_es":"Hablar de un conflicto, de no tomar partido y de buscar puntos en común.","intro":{"explanation":"A conflict es un conflicto; resolve, resolverlo. A mediator ayuda a las dos partes sin take sides (tomar partido). La idea es find common ground: encontrar puntos en común.","examples":[{"target":"We can help you resolve the conflict.","base":"Podemos ayudarte a resolver el conflicto."},{"target":"Try to find some common ground.","base":"Trata de encontrar puntos en común."}]},"takeaways":["Hablas de un conflicto y de cómo resolverlo.","Propones no tomar partido y buscar puntos en común."]},{"id":"b2-u12-l04","unit_id":"b2-u12","position":5,"title_es":"Defender lo tuyo","objective_es":"Defender a tu equipo o tu postura y decidir cuándo ceder.","intro":{"explanation":"Stand up for es defender a alguien o algo: I have to stand up for my team. Back down es ceder, echarse atrás. Something is at stake: está en juego. Neither side (ninguna de las dos partes) va con el verbo en afirmativo: Neither side wanted to back down.","examples":[{"target":"I have to stand up for my team.","base":"Tengo que defender a mi equipo."},{"target":"Neither side wanted to back down.","base":"Ninguna de las dos partes quería ceder."}]},"takeaways":["Defiendes a alguien con stand up for.","Hablas de lo que está en juego y de ceder con back down."]},{"id":"b2-u12-l05","unit_id":"b2-u12","position":7,"title_es":"Énfasis formal","objective_es":"Usar la inversión enfática en textos formales.","intro":{"explanation":"En avisos, correos formales y discursos: Not only + auxiliar + sujeto…, but (also)… (Not only is it free, but it is also confidential). Under no circumstances + auxiliar + sujeto (bajo ninguna circunstancia). Only then + auxiliar + sujeto (sólo entonces). Should you + verbo = If you + verbo, más formal: Should you need help, call reception.","examples":[{"target":"Not only is the service free, but it is also confidential.","base":"El servicio no sólo es gratuito, sino que también es confidencial."},{"target":"Should you need help, please call reception.","base":"Si necesita ayuda, llame a recepción."}]},"takeaways":["Enfatizas con Not only…, Under no circumstances… y Only then…","Escribes condiciones formales con Should you…"]},{"id":"pt-a1-u13-l01","unit_id":"pt-a1-u13","position":1,"title_es":"Nós, eles, vocês","objective_es":"Hablar de varias personas con ser.","intro":{"explanation":"Para hablar de varias personas: nós (nosotros), eles (ellos), elas (ellas) y vocês (ustedes). En Brasil vocês es «ustedes» también entre amigos. Ser: nós somos, eles são, vocês são.","examples":[{"target":"Nós somos estudantes.","base":"Somos estudiantes."},{"target":"Elas são brasileiras.","base":"Ellas son brasileñas."}]},"takeaways":["Usas nós, eles, elas y vocês.","Conjugas ser en plural: somos, são."]},{"id":"pt-a1-u13-l02","unit_id":"pt-a1-u13","position":2,"title_es":"Nós trabalhamos, a gente trabalha","objective_es":"Conjugar los verbos en -ar en plural y usar a gente.","intro":{"explanation":"En plural, los verbos en -ar terminan en -amos (nós) y en -am (eles, elas, vocês): nós trabalhamos, eles trabalham. En Brasil se dice mucho a gente en lugar de nós, con el verbo como ele: a gente trabalha.","examples":[{"target":"Nós trabalhamos de manhã.","base":"Trabajamos por la mañana."},{"target":"A gente trabalha em casa.","base":"Trabajamos en casa."}]},"takeaways":["Conjugas -ar en plural: trabalhamos, trabalham.","Dices «nosotros» como en Brasil: a gente + verbo en singular."]},{"id":"pt-a1-u13-l03","unit_id":"pt-a1-u13","position":4,"title_es":"O que você faz?","objective_es":"Preguntar y decir a qué se dedica alguien.","intro":{"explanation":"O que você faz? es «¿a qué te dedicas?». La profesión va sin artículo: sou médico, ela é enfermeira. Muchas tienen femenino en -a: o engenheiro, a engenheira.","examples":[{"target":"O que você faz? — Sou engenheira.","base":"¿A qué te dedicas? — Soy ingeniera."},{"target":"Meu pai é médico.","base":"Mi papá es médico."}]},"takeaways":["Preguntas la profesión con o que você faz?","Dices profesiones sin artículo y en femenino."]},{"id":"pt-a1-u13-l04","unit_id":"pt-a1-u13","position":5,"title_es":"No escritório, no restaurante","objective_es":"Decir dónde trabaja cada uno y evitar falsos amigos.","intro":{"explanation":"Falsos amigos: escritório es la «oficina» (el escritorio, el mueble, es mesa) y motorista es quien maneja un auto o un autobús. En el restaurante trabajan o garçom / a garçonete (el mesero, la mesera) y o cozinheiro.","examples":[{"target":"Eu trabalho em um escritório.","base":"Trabajo en una oficina."},{"target":"Ele é motorista de ônibus.","base":"Él es chofer de autobús."}]},"takeaways":["Sabes que escritório es «oficina».","Nombras trabajos del restaurante y del transporte."]},{"id":"pt-a1-u13-l05","unit_id":"pt-a1-u13","position":7,"title_es":"Nosso trabalho","objective_es":"Usar nosso y nossa y presentar a un grupo.","intro":{"explanation":"Nosso y nossa son «nuestro» y «nuestra»; en Brasil suelen llevar artículo: o nosso restaurante, a nossa casa. Concuerdan con la cosa, no con las personas.","examples":[{"target":"O nosso restaurante é pequeno.","base":"Nuestro restaurante es chico."},{"target":"A nossa família é grande.","base":"Nuestra familia es grande."}]},"takeaways":["Usas nosso y nossa según la cosa.","Entiendes una presentación de un grupo."]},{"id":"pt-a1-u14-l01","unit_id":"pt-a1-u14","position":1,"title_es":"Estou cansado","objective_es":"Decir cómo estás ahora con estar.","intro":{"explanation":"Estar dice cómo está alguien ahora: eu estou, você / ele / ela está. El adjetivo cambia con la persona: ele está cansado, ela está cansada.","examples":[{"target":"Hoje eu estou cansado.","base":"Hoy estoy cansado."},{"target":"Ela está muito feliz.","base":"Ella está muy feliz."}]},"takeaways":["Dices cómo estás con estou.","Haces concordar el adjetivo: cansado, cansada."]},{"id":"pt-a1-u14-l02","unit_id":"pt-a1-u14","position":2,"title_es":"Estou com fome","objective_es":"Decir que tienes hambre o sed.","intro":{"explanation":"«Tengo hambre» no se dice con ter: se dice estou com fome («estoy con hambre»). Igual con la sed: estou com sede.","examples":[{"target":"Estou com fome. Quero comer.","base":"Tengo hambre. Quiero comer."},{"target":"Você está com sede?","base":"¿Tienes sed?"}]},"takeaways":["Dices que tienes hambre: estou com fome.","Dices que tienes sed: estou com sede."]},{"id":"pt-a1-u14-l03","unit_id":"pt-a1-u14","position":4,"title_es":"Alto, baixo, simpático","objective_es":"Describir personas con ser.","intro":{"explanation":"Para describir cómo es una persona se usa ser: ele é alto, ela é baixa. Los adjetivos en -o hacen el femenino en -a y el plural con -s: alto, alta, altos, altas.","examples":[{"target":"O meu irmão é alto.","base":"Mi hermano es alto."},{"target":"As minhas irmãs são baixas.","base":"Mis hermanas son bajas."}]},"takeaways":["Describes personas con ser.","Haces concordar el adjetivo en género y número."]},{"id":"pt-a1-u14-l04","unit_id":"pt-a1-u14","position":5,"title_es":"Novo, velho, chato","objective_es":"Describir cosas y evitar el falso amigo chato.","intro":{"explanation":"Novo es «nuevo» (y también «joven») y velho, «viejo». Pequeno es «chico». Ojo: chato no es «plano», es «aburrido» o «pesado»: o filme é chato.","examples":[{"target":"O meu celular é novo.","base":"Mi celular es nuevo."},{"target":"Que filme chato!","base":"¡Qué película aburrida!"}]},"takeaways":["Describes cosas: novo, velho, pequeno, grande.","Sabes que chato es «aburrido»."]},{"id":"pt-a1-u14-l05","unit_id":"pt-a1-u14","position":7,"title_es":"Ser ou estar?","objective_es":"Elegir entre ser y estar y usar pouco y muito.","intro":{"explanation":"Ser: cómo es algo siempre (ele é simpático). Estar: cómo está ahora (hoje ele está triste). Pouco es «poco» y muito, «mucho» o «muy»: ele fala pouco; é muito legal.","examples":[{"target":"Ele é feliz, mas hoje está triste.","base":"Es feliz, pero hoy está triste."},{"target":"O Rafael fala pouco.","base":"Rafael habla poco."}]},"takeaways":["Eliges entre ser y estar.","Dices poco o mucho con pouco y muito."]},{"id":"pt-a1-u15-l01","unit_id":"pt-a1-u15","position":1,"title_es":"De janeiro a junho","objective_es":"Nombrar los primeros meses del año.","intro":{"explanation":"Los meses se parecen al español, pero cambian algunas letras: janeiro (enero), fevereiro (febrero), março (marzo). Se escriben con minúscula. Mês es «mes».","examples":[{"target":"O Carnaval é em fevereiro.","base":"El Carnaval es en febrero."},{"target":"O meu aniversário é em março.","base":"Mi cumpleaños es en marzo."}]},"takeaways":["Nombras los meses de enero a junio.","Usas em con los meses: em março."]},{"id":"pt-a1-u15-l02","unit_id":"pt-a1-u15","position":2,"title_es":"De julho a dezembro","objective_es":"Nombrar los meses del segundo semestre.","intro":{"explanation":"Julho es «julio» y junho, «junio»: cuidado, se parecen. Setembro, outubro, novembro y dezembro terminan en -bro, como en español.","examples":[{"target":"O Natal é em dezembro.","base":"La Navidad es en diciembre."},{"target":"Em julho eu trabalho muito.","base":"En julio trabajo mucho."}]},"takeaways":["Nombras los meses de julio a diciembre.","Distingues junho (junio) y julho (julio)."]},{"id":"pt-a1-u15-l03","unit_id":"pt-a1-u15","position":4,"title_es":"Que dia é hoje?","objective_es":"Decir la fecha y cuándo es tu cumpleaños.","intro":{"explanation":"La fecha: dia + número + de + mes: hoje é dia dez de maio. «El 10» de un mes es no dia dez. Aniversário es «cumpleaños» (también «aniversario»).","examples":[{"target":"Hoje é dia dez de maio.","base":"Hoy es 10 de mayo."},{"target":"O meu aniversário é no dia cinco de março.","base":"Mi cumpleaños es el 5 de marzo."}]},"takeaways":["Dices la fecha: dia dez de maio.","Preguntas y dices cuándo es el cumpleaños."]},{"id":"pt-a1-u15-l04","unit_id":"pt-a1-u15","position":5,"title_es":"Faz calor, faz frio","objective_es":"Decir qué tiempo hace.","intro":{"explanation":"El clima se dice con fazer, como en español con «hacer»: faz calor, faz frio. «Llueve» es chove. Las estaciones: o verão, o inverno; no verão = «en verano».","examples":[{"target":"Hoje faz muito calor.","base":"Hoy hace mucho calor."},{"target":"No inverno chove muito.","base":"En invierno llueve mucho."}]},"takeaways":["Dices qué tiempo hace: faz calor, faz frio, chove.","Hablas de verão e inverno."]},{"id":"pt-a1-u15-l05","unit_id":"pt-a1-u15","position":7,"title_es":"O ano no Brasil","objective_es":"Combinar fechas, meses y clima.","intro":{"explanation":"Brasil está en el hemisferio sur: em dezembro faz calor (o Natal é no verão) y em julho é inverno. En junio se hacen las festas juninas, con comida y música.","examples":[{"target":"O Natal é no verão.","base":"La Navidad es en verano."},{"target":"Em junho faz frio no sul.","base":"En junio hace frío en el sur."}]},"takeaways":["Hablas del año: meses, fiestas y clima.","Entiendes un aviso con fecha y hora."]},{"id":"pt-a1-u16-l01","unit_id":"pt-a1-u16","position":1,"title_es":"De ônibus, de carro, a pé","objective_es":"Decir cómo vas a un lugar.","intro":{"explanation":"En portugués el transporte va con de, no con «en»: vou de ônibus, de carro, de metrô, de bicicleta. Caminando se dice a pé.","examples":[{"target":"Eu vou para a escola de ônibus.","base":"Voy a la escuela en autobús."},{"target":"A padaria é perto: vou a pé.","base":"La panadería está cerca: voy caminando."}]},"takeaways":["Dices cómo vas: de ônibus, de carro, a pé.","Nombras medios de transporte."]},{"id":"pt-a1-u16-l02","unit_id":"pt-a1-u16","position":2,"title_es":"Vou ao cinema","objective_es":"Usar ao y à para decir adónde vas.","intro":{"explanation":"A + o se une en ao y a + a, en à (con acento grave): vou ao cinema, vou à praia. En Brasil también se dice vou para o / pra: vou pra praia.","examples":[{"target":"No sábado eu vou ao cinema.","base":"El sábado voy al cine."},{"target":"Você vai à praia amanhã?","base":"¿Vas a la playa mañana?"}]},"takeaways":["Usas ao con masculino y à con femenino.","Dices adónde vas el fin de semana."]},{"id":"pt-a1-u16-l03","unit_id":"pt-a1-u16","position":4,"title_es":"Pela praça, pelo centro","objective_es":"Decir por dónde pasa algo y pasear.","intro":{"explanation":"Por + o se une en pelo y por + a, en pela: o ônibus passa pela praça. Falso amigo: pelo no es el pelo (eso es cabelo). Passear es «pasear»: eu passeio pelo centro.","examples":[{"target":"O ônibus passa pela praça.","base":"El autobús pasa por la plaza."},{"target":"Eu gosto de passear pelo centro.","base":"Me gusta pasear por el centro."}]},"takeaways":["Usas pelo y pela para «por el» y «por la».","Dices dónde te gusta pasear."]},{"id":"pt-a1-u16-l04","unit_id":"pt-a1-u16","position":5,"title_es":"O que você faz no tempo livre?","objective_es":"Contar qué haces en tu tiempo libre con fazer.","intro":{"explanation":"Fazer es irregular: eu faço, você / ele / ela faz, nós fazemos. Tempo livre es «tiempo libre»: o que você faz no seu tempo livre?","examples":[{"target":"O que você faz no fim de semana?","base":"¿Qué haces el fin de semana?"},{"target":"Eu faço o almoço no domingo.","base":"Yo hago el almuerzo el domingo."}]},"takeaways":["Conjugas fazer: faço, faz, fazemos.","Cuentas qué haces en tu tiempo libre."]},{"id":"pt-a1-u16-l05","unit_id":"pt-a1-u16","position":7,"title_es":"Vamos?","objective_es":"Proponer planes con vamos y hablar de otros con vão.","intro":{"explanation":"Ir en plural: nós vamos, eles / vocês vão. Para proponer un plan alcanza con vamos…?: vamos ao cinema? Para aceptar: vamos!","examples":[{"target":"Vamos à praia no domingo?","base":"¿Vamos a la playa el domingo?"},{"target":"Eles vão de trem para São Paulo.","base":"Ellos van en tren a São Paulo."}]},"takeaways":["Propones un plan con vamos…?","Dices adónde van otros con vão."]},{"id":"pt-a2-u01-l01","unit_id":"pt-a2-u01","position":1,"title_es":"Ontem eu trabalhei","objective_es":"Contar qué hiciste ayer con verbos en -ar.","intro":{"explanation":"El pretérito perfeito cuenta acciones terminadas. Los verbos en -ar hacen eu -ei y você / ele -ou: falar → eu falei, ele falou; trabalhar → trabalhei, trabalhou. Ontem es «ayer».","examples":[{"target":"Ontem eu trabalhei até tarde.","base":"Ayer trabajé hasta tarde."},{"target":"Você falou com a professora?","base":"¿Hablaste con la profesora?"}]},"takeaways":["Cuentas qué hiciste con -ei: falei, trabalhei.","Preguntas con -ou: você falou?"]},{"id":"pt-a2-u01-l02","unit_id":"pt-a2-u01","position":2,"title_es":"Comi, bebi, saí","objective_es":"Contar qué hiciste con verbos en -er y en -ir.","intro":{"explanation":"En -er y en -ir, eu termina en -i: comi, bebi, saí, dormi. Con você / ele: comeu, bebeu, saiu, dormiu. Assistir a es «ver» una película o la tele: assisti a um filme.","examples":[{"target":"Ontem à noite eu saí com amigos.","base":"Anoche salí con amigos."},{"target":"Você comeu a pizza?","base":"¿Comiste la pizza?"}]},"takeaways":["Cuentas con -i: comi, saí, dormi.","Preguntas con -eu / -iu: você comeu? você saiu?"]},{"id":"pt-a2-u01-l03","unit_id":"pt-a2-u01","position":4,"title_es":"Como foi o fim de semana?","objective_es":"Preguntar y contar cómo fue el fin de semana.","intro":{"explanation":"Como foi o fim de semana? es la pregunta de cada lunes («¿cómo fue el fin de semana?»). Se responde con el perfeito: joguei futebol, dormi muito, a gente comeu uma pizza.","examples":[{"target":"Como foi o fim de semana? — Ótimo!","base":"¿Cómo fue el fin de semana? — ¡Buenísimo!"},{"target":"No sábado a gente comeu uma pizza.","base":"El sábado comimos una pizza."}]},"takeaways":["Preguntas cómo fue el fin de semana.","Cuentas varias cosas en orden."]},{"id":"pt-a2-u01-l04","unit_id":"pt-a2-u01","position":5,"title_es":"Já ou ainda não?","objective_es":"Decir lo que ya hiciste y lo que todavía no.","intro":{"explanation":"Já es «ya»: você já comeu? En la respuesta se repite el verbo: já, comi! «Todavía no» es ainda não: ainda não comi. En portugués no hace falta otro tiempo verbal: alcanza con el perfeito.","examples":[{"target":"Você já falou com a mamãe? — Já!","base":"¿Ya hablaste con mamá? — ¡Sí, ya!"},{"target":"Ainda não comi nada hoje.","base":"Todavía no comí nada hoy."}]},"takeaways":["Preguntas con já: você já comeu?","Respondes ainda não + perfeito."]},{"id":"pt-a2-u01-l05","unit_id":"pt-a2-u01","position":7,"title_es":"A semana passada","objective_es":"Contar qué hicieron varias personas y cuándo.","intro":{"explanation":"En plural: nós falamos, comemos, saímos; eles falaram, comeram, saíram. A semana passada es «la semana pasada»: na semana passada.","examples":[{"target":"Na semana passada nós trabalhamos muito.","base":"La semana pasada trabajamos mucho."},{"target":"Eles saíram tarde ontem.","base":"Ellos salieron tarde ayer."}]},"takeaways":["Cuentas en plural: falamos, falaram.","Ubicas en el tiempo: ontem, na semana passada."]},{"id":"pt-a2-u02-l01","unit_id":"pt-a2-u02","position":1,"title_es":"Fui para Salvador","objective_es":"Contar adónde fuiste y cómo fue con fui y foi.","intro":{"explanation":"Ir y ser comparten el pasado: eu fui, você / ele foi, nós fomos, eles foram. Fui para Salvador («fui a Salvador») y a viagem foi ótima («el viaje fue buenísimo»). Ojo: a viagem es femenino.","examples":[{"target":"Nas férias eu fui para Salvador.","base":"En las vacaciones fui a Salvador."},{"target":"Como foi a viagem?","base":"¿Cómo fue el viaje?"}]},"takeaways":["Cuentas adónde fuiste: fui para…","Dices cómo fue: foi ótimo."]},{"id":"pt-a2-u02-l02","unit_id":"pt-a2-u02","position":2,"title_es":"No aeroporto","objective_es":"Moverte en el aeropuerto.","intro":{"explanation":"En el aeropuerto: o voo (el vuelo), o passaporte, a mala. Falso amigo: mala es la «maleta», no algo malo. Pegar un transporte es «tomarlo»: peguei um táxi.","examples":[{"target":"A minha mala é azul.","base":"Mi maleta es azul."},{"target":"Peguei um táxi para o aeroporto.","base":"Tomé un taxi al aeropuerto."}]},"takeaways":["Nombras lo que llevas a un viaje.","Sabes que mala es «maleta»."]},{"id":"pt-a2-u02-l03","unit_id":"pt-a2-u02","position":4,"title_es":"O que você fez?","objective_es":"Contar qué hiciste con fiz y fez.","intro":{"explanation":"Fazer en pasado: eu fiz, você / ele fez, nós fizemos, eles fizeram. O que você fez? es «¿qué hiciste?». Fazer fotos (o tirar fotos) es «sacar fotos».","examples":[{"target":"O que você fez nas férias?","base":"¿Qué hiciste en las vacaciones?"},{"target":"Eu fiz muitas fotos.","base":"Saqué muchas fotos."}]},"takeaways":["Preguntas o que você fez?","Cuentas qué hiciste con fiz."]},{"id":"pt-a2-u02-l04","unit_id":"pt-a2-u02","position":5,"title_es":"Tive um problema","objective_es":"Contar un problema de viaje con tive y estive.","intro":{"explanation":"Ter en pasado: eu tive, ele teve («tuve un problema»). Estar en pasado: eu estive, ele esteve («estuve en Recife»). Estive sirve para decir en qué lugares estuviste.","examples":[{"target":"Eu tive um problema com a mala.","base":"Tuve un problema con la maleta."},{"target":"Já estive em Recife duas vezes.","base":"Ya estuve en Recife dos veces."}]},"takeaways":["Cuentas un problema con tive.","Dices dónde estuviste con estive."]},{"id":"pt-a2-u02-l05","unit_id":"pt-a2-u02","position":7,"title_es":"Conheci o Rio","objective_es":"Contar un viaje completo.","intro":{"explanation":"Conhecer un lugar es visitarlo por primera vez: conheci o Rio no ano passado. Viajar en pasado: eu viajei, ele viajou. Para ordenar el relato: primeiro… depois…","examples":[{"target":"No ano passado eu viajei para o Brasil.","base":"El año pasado viajé a Brasil."},{"target":"Lá eu conheci o Rio e Salvador.","base":"Allá conocí Río y Salvador."}]},"takeaways":["Cuentas un viaje: viajei, conheci, fui.","Ubicas el viaje: no ano passado."]},{"id":"pt-a2-u03-l01","unit_id":"pt-a2-u03","position":1,"title_es":"O cardápio","objective_es":"Entender una carta y evitar el falso amigo sobremesa.","intro":{"explanation":"En el restaurante: o cardápio (la carta), o prato (el plato), a garrafa (la botella). Falso amigo: sobremesa es el «postre». El prato do dia es el menú del día, muy común en Brasil.","examples":[{"target":"O prato do dia é feijoada.","base":"El plato del día es feijoada."},{"target":"De sobremesa, eu quero pudim.","base":"De postre quiero flan."}]},"takeaways":["Entiendes una carta: prato, sobremesa, garrafa.","Sabes que sobremesa es «postre»."]},{"id":"pt-a2-u03-l02","unit_id":"pt-a2-u03","position":2,"title_es":"Eu gostaria de…","objective_es":"Pedir con cortesía.","intro":{"explanation":"Eu gostaria de es «me gustaría» o «quisiera»: gostaria de um café; con o se une en do: gostaria do prato do dia. Poderia…? es «¿podría…?»: poderia me trazer o cardápio? Trazer es «traer».","examples":[{"target":"Eu gostaria de uma água, por favor.","base":"Quisiera un agua, por favor."},{"target":"Poderia me trazer a conta?","base":"¿Me podría traer la cuenta?"}]},"takeaways":["Pides con gostaria de.","Pides un favor con poderia…?"]},{"id":"pt-a2-u03-l03","unit_id":"pt-a2-u03","position":4,"title_es":"A conta e a gorjeta","objective_es":"Pagar y entender la propina en Brasil.","intro":{"explanation":"Para pagar: com cartão (con tarjeta) o em dinheiro (en efectivo). En Brasil la cuenta suele traer os 10% de serviço: es la gorjeta (propina) y es opcional. Muchos lugares aceptan Pix, el pago por el celular.","examples":[{"target":"Posso pagar com cartão?","base":"¿Puedo pagar con tarjeta?"},{"target":"A gorjeta está incluída na conta?","base":"¿La propina está incluida en la cuenta?"}]},"takeaways":["Dices cómo pagas: com cartão, em dinheiro.","Entiendes los 10% de serviço."]},{"id":"pt-a2-u03-l04","unit_id":"pt-a2-u03","position":5,"title_es":"Reservei um quarto","objective_es":"Reservar una habitación.","intro":{"explanation":"Una pousada es un hotel chico, típico de la costa. Quarto de casal es la habitación matrimonial. A diária es el precio por noche. Reservar en pasado: eu reservei.","examples":[{"target":"Eu gostaria de reservar um quarto de casal.","base":"Quisiera reservar una habitación matrimonial."},{"target":"Quanto é a diária?","base":"¿Cuánto cuesta la noche?"}]},"takeaways":["Reservas una habitación: quarto de casal.","Preguntas el precio: quanto é a diária?"]},{"id":"pt-a2-u03-l05","unit_id":"pt-a2-u03","position":7,"title_es":"O café da manhã está incluído?","objective_es":"Hacer el check-in y preguntar qué incluye.","intro":{"explanation":"Para saber qué entra en el precio: o café da manhã está incluído? En la recepción te van a pedir el nombre de la reserva y te dan a chave. Incluído concuerda: a gorjeta está incluída.","examples":[{"target":"O café da manhã está incluído?","base":"¿El desayuno está incluido?"},{"target":"Eu reservei um quarto. O meu nome é Teresa.","base":"Reservé una habitación. Me llamo Teresa."}]},"takeaways":["Preguntas qué está incluído.","Haces el check-in con tu reserva."]},{"id":"pt-a2-u04-l01","unit_id":"pt-a2-u04","position":1,"title_es":"Quando eu era criança","objective_es":"Describir cómo eras de niño con era y tinha.","intro":{"explanation":"Para describir el pasado se usa el imperfeito. Ser → era («era») y ter → tinha («tenía»): eu era tímido, eu tinha um cachorro. Quando eu era criança es «cuando era chico».","examples":[{"target":"Quando eu era criança, eu era muito tímido.","base":"Cuando era chico, era muy tímido."},{"target":"Eu tinha um cachorro preto.","base":"Tenía un perro negro."}]},"takeaways":["Describes el pasado con era y tinha.","Empiezas un recuerdo: quando eu era criança…"]},{"id":"pt-a2-u04-l02","unit_id":"pt-a2-u04","position":2,"title_es":"Eu morava, eu brincava","objective_es":"Contar qué hacías siempre con el imperfeito en -ava.","intro":{"explanation":"Los verbos en -ar hacen el imperfeito en -ava: morar → eu morava, brincar → eu brincava, gostar → eu gostava de. Falso amigo: brincar es «jugar» (los chicos); jogar es jugar a un deporte o un juego con reglas.","examples":[{"target":"Eu morava perto da praia.","base":"Vivía cerca de la playa."},{"target":"A gente brincava na rua.","base":"Jugábamos en la calle."}]},"takeaways":["Cuentas costumbres: morava, brincava, gostava de.","Distingues brincar (jugar de niño) y jogar."]},{"id":"pt-a2-u04-l03","unit_id":"pt-a2-u04","position":4,"title_es":"O meu bairro","objective_es":"Describir el barrio y los vecinos de antes.","intro":{"explanation":"Bairro es «barrio» y vizinho, «vecino». Naquela época es «en esa época»: naquela época todo mundo se conhecia. Lembro (de) es «me acuerdo (de)»: eu lembro de tudo.","examples":[{"target":"Naquela época os vizinhos conversavam na rua.","base":"En esa época los vecinos charlaban en la calle."},{"target":"Eu lembro do meu primeiro bairro.","base":"Me acuerdo de mi primer barrio."}]},"takeaways":["Describes un barrio y a sus vecinos.","Dices que te acuerdas de algo: eu lembro de…"]},{"id":"pt-a2-u04-l04","unit_id":"pt-a2-u04","position":5,"title_es":"Eu costumava…","objective_es":"Contar costumbres con costumava, ia y antigamente.","intro":{"explanation":"Costumava + verbo es «solía»: eu costumava ir a pé. Ir en imperfeito es ia: todo domingo a gente ia à praia. Antigamente es «antes», «en otros tiempos».","examples":[{"target":"Antigamente eu costumava ler muito.","base":"Antes solía leer mucho."},{"target":"Todo verão a gente ia para a fazenda.","base":"Todos los veranos íbamos al campo."}]},"takeaways":["Cuentas costumbres con costumava e ia.","Comparas con antigamente."]},{"id":"pt-a2-u04-l05","unit_id":"pt-a2-u04","position":7,"title_es":"A minha infância","objective_es":"Contar tu infancia combinando todo.","intro":{"explanation":"Para contar la infancia se combinan descripciones (eu era, eu tinha) y costumbres (eu brincava, a gente ia). El perfeito queda para algo que pasó una vez: um dia eu caí da bicicleta.","examples":[{"target":"Eu tive uma infância feliz.","base":"Tuve una infancia feliz."},{"target":"Eu morava numa fazenda e brincava com os animais.","base":"Vivía en el campo y jugaba con los animales."}]},"takeaways":["Cuentas tu infancia con el imperfeito.","Nombras juguetes, lugares y personas de antes."]},{"id":"pt-a2-u05-l01","unit_id":"pt-a2-u05","position":1,"title_es":"O que aconteceu?","objective_es":"Preguntar qué pasó y contar un hecho con el perfeito.","intro":{"explanation":"O que aconteceu? es «¿qué pasó?». Se responde con el perfeito: perdi o celular, caí na rua, encontrei a chave. Cair (caerse) en pasado: eu caí, ele caiu.","examples":[{"target":"O que aconteceu? — Perdi a chave.","base":"¿Qué pasó? — Perdí la llave."},{"target":"O celular caiu no chão.","base":"El celular se cayó al piso."}]},"takeaways":["Preguntas o que aconteceu?","Cuentas un hecho: perdi, caiu, encontrei."]},{"id":"pt-a2-u05-l02","unit_id":"pt-a2-u05","position":2,"title_es":"Eu estava andando quando…","objective_es":"Describir la escena con estava y estava + gerundio.","intro":{"explanation":"La escena va en imperfeito: eu estava no ônibus, estava chovendo. Estar + gerundio (-ando, -endo, -indo) dice qué estaba pasando: eu estava andando. Lo que interrumpe va en perfeito: quando eu vi…","examples":[{"target":"Eu estava andando quando vi o acidente.","base":"Estaba caminando cuando vi el accidente."},{"target":"Estava chovendo muito.","base":"Estaba lloviendo mucho."}]},"takeaways":["Describes la escena: estava + gerundio.","Interrumpes con el perfeito: quando vi…"]},{"id":"pt-a2-u05-l03","unit_id":"pt-a2-u05","position":4,"title_es":"Primeiro, depois, então","objective_es":"Ordenar un relato con conectores.","intro":{"explanation":"Para ordenar lo que pasó: primeiro (primero), depois (después), então (entonces, así que) y no final (al final). Então también da la consecuencia: estava chovendo, então peguei um táxi.","examples":[{"target":"Primeiro eu tomei café, depois saí.","base":"Primero desayuné, después salí."},{"target":"Estava tarde, então peguei um táxi.","base":"Era tarde, así que tomé un taxi."}]},"takeaways":["Ordenas un relato: primeiro, depois, no final.","Das una consecuencia con então."]},{"id":"pt-a2-u05-l04","unit_id":"pt-a2-u05","position":5,"title_es":"De repente…","objective_es":"Contar una sorpresa con de repente y enquanto.","intro":{"explanation":"De repente es igual que en español. Enquanto es «mientras»: enquanto eu cozinhava, ele lia. Ouvir en pasado: eu ouvi; ver: eu vi, ele viu.","examples":[{"target":"De repente, ouvi um barulho.","base":"De repente, oí un ruido."},{"target":"Enquanto eu dormia, o meu irmão chegou.","base":"Mientras yo dormía, llegó mi hermano."}]},"takeaways":["Cuentas una sorpresa con de repente.","Unes dos acciones con enquanto."]},{"id":"pt-a2-u05-l05","unit_id":"pt-a2-u05","position":7,"title_es":"Percebi que…","objective_es":"Contar un problema completo y disculparte.","intro":{"explanation":"Falso amigo: perceber es «darse cuenta»: percebi que estava sem a chave. Si hiciste algo sin intención: foi sem querer («fue sin querer»).","examples":[{"target":"Quando cheguei, percebi que estava sem a chave.","base":"Cuando llegué, me di cuenta de que no tenía la llave."},{"target":"Desculpa, foi sem querer!","base":"¡Perdón, fue sin querer!"}]},"takeaways":["Dices que te diste cuenta: percebi que…","Te disculpas: foi sem querer."]},{"id":"pt-a2-u06-l01","unit_id":"pt-a2-u06","position":1,"title_es":"Vou viajar","objective_es":"Contar tus planes con ir + infinitivo.","intro":{"explanation":"El futuro de todos los días es ir + infinitivo, sin «a»: eu vou viajar («voy a viajar»), ele vai sair, nós vamos jantar, eles vão chegar. Semana que vem es «la semana que viene».","examples":[{"target":"Na semana que vem eu vou viajar.","base":"La semana que viene voy a viajar."},{"target":"A gente vai jantar fora hoje.","base":"Hoy vamos a cenar afuera."}]},"takeaways":["Cuentas planes con vou + verbo.","Ubicas el plan: semana que vem, depois de amanhã."]},{"id":"pt-a2-u06-l02","unit_id":"pt-a2-u06","position":2,"title_es":"Topa?","objective_es":"Invitar a alguien.","intro":{"explanation":"Para invitar: você quer…?, vamos…? o, entre amigos, topa? («¿te apuntas?»). Convidar es «invitar» y o convite, «la invitación». El churrasco es el asado brasileño.","examples":[{"target":"Vou fazer um churrasco no sábado. Topa?","base":"El sábado hago un asado. ¿Te apuntas?"},{"target":"Eu quero convidar você para a minha festa.","base":"Te quiero invitar a mi fiesta."}]},"takeaways":["Invitas con topa? o você quer…?","Nombras planes: festa, churrasco."]},{"id":"pt-a2-u06-l03","unit_id":"pt-a2-u06","position":4,"title_es":"Bora! Com certeza!","objective_es":"Aceptar una invitación y cerrar el plan.","intro":{"explanation":"Para aceptar: com certeza! («¡seguro!»), bora! (de vamos embora, muy informal: «¡vamos!») o eu topo! Para cerrar día y hora: combinado! («¡quedamos así!»). Marcar es «arreglar un encuentro»: vamos marcar um café?","examples":[{"target":"Churrasco no sábado? Bora!","base":"¿Asado el sábado? ¡De acuerdo!"},{"target":"Sábado às oito? Combinado!","base":"¿Sábado a las ocho? ¡Quedamos así!"}]},"takeaways":["Aceptas: com certeza, bora, eu topo.","Cierras el plan: combinado, vamos marcar."]},{"id":"pt-a2-u06-l04","unit_id":"pt-a2-u06","position":5,"title_es":"Que pena, não posso","objective_es":"Rechazar una invitación con cortesía.","intro":{"explanation":"Para decir que no, con cortesía: que pena, não posso («qué lástima, no puedo») y una razón con vou + verbo: vou trabalhar. Se cierra con fica para outro dia («queda para otro día»). Ocupado es igual que en español.","examples":[{"target":"Que pena, não posso. Vou trabalhar.","base":"Qué lástima, no puedo. Voy a trabajar."},{"target":"Hoje estou ocupado. Fica para outro dia?","base":"Hoy estoy ocupado. ¿Lo dejamos para otro día?"}]},"takeaways":["Rechazas con que pena, não posso.","Propones otro día: fica para outro dia."]},{"id":"pt-a2-u06-l05","unit_id":"pt-a2-u06","position":7,"title_es":"Estou a fim de…","objective_es":"Decir que tienes ganas de algo y combinar todo.","intro":{"explanation":"A fim de es «con ganas de»: estou a fim de sair («tengo ganas de salir»); não estou a fim es una forma informal de decir que no. Con la invitación, la respuesta y el día, el plan está completo.","examples":[{"target":"Estou a fim de comer uma pizza.","base":"Tengo ganas de comer una pizza."},{"target":"Você está a fim de sair hoje?","base":"¿Tienes ganas de salir hoy?"}]},"takeaways":["Dices que tienes ganas: estou a fim de…","Armas un plan completo con día, hora y lugar."]},{"id":"pt-a2-u07-l01","unit_id":"pt-a2-u07","position":1,"title_es":"Na faculdade","objective_es":"Hablar de tus estudios.","intro":{"explanation":"Faculdade es la facultad o la universidad; o curso es la carrera. Falso amigo suave: prova es un «examen». «Aprobar» se dice passar na prova: eu passei na prova!","examples":[{"target":"Eu estudo economia na faculdade.","base":"Estudio economía en la facultad."},{"target":"Amanhã eu tenho prova. Espero passar!","base":"Mañana tengo examen. ¡Espero aprobar!"}]},"takeaways":["Hablas de la facultad y tu carrera.","Dices que aprobaste: passei na prova."]},{"id":"pt-a2-u07-l02","unit_id":"pt-a2-u07","position":2,"title_es":"No trabalho","objective_es":"Hablar de tu trabajo y de la gente con la que trabajas.","intro":{"explanation":"O chefe / a chefe (el jefe, la jefa), o colega (el compañero de trabajo), a reunião (la reunión). O salário es el sueldo. Uno va na reunião o à reunião.","examples":[{"target":"A reunião com a chefe é às três.","base":"La reunión con la jefa es a las tres."},{"target":"Os meus colegas são muito legais.","base":"Mis compañeros son muy simpáticos."}]},"takeaways":["Nombras a la gente del trabajo: chefe, colega.","Hablas de reuniones y del sueldo."]},{"id":"pt-a2-u07-l03","unit_id":"pt-a2-u07","position":4,"title_es":"Uma vaga de estágio","objective_es":"Entender un aviso de trabajo.","intro":{"explanation":"Falso amigo: vaga es una «vacante» o un «puesto»: tem uma vaga de estágio. Estágio es la pasantía. Para postularte mandas o currículo y después tienes a entrevista.","examples":[{"target":"Tem uma vaga de estágio na empresa.","base":"Hay una vacante de pasantía en la empresa."},{"target":"Mandei o meu currículo ontem.","base":"Ayer mandé mi currículum."}]},"takeaways":["Entiendes un aviso: vaga, estágio, salário.","Sabes que vaga es «vacante»."]},{"id":"pt-a2-u07-l04","unit_id":"pt-a2-u07","position":5,"title_es":"A entrevista será na segunda","objective_es":"Entender el futuro formal en un correo.","intro":{"explanation":"En un correo o un aviso aparece el futuro do presente: será (ser), terá (ter), falará (falar). Se forma con el infinitivo + -á: falar → falará. Al hablar, lo normal es vai ser, vai ter.","examples":[{"target":"A sua entrevista será na segunda-feira.","base":"Su entrevista será el lunes."},{"target":"A conversa terá duração de uma hora.","base":"La charla durará una hora."}]},"takeaways":["Entiendes el futuro formal: será, terá.","Sabes que al hablar se dice vai ser."]},{"id":"pt-a2-u07-l05","unit_id":"pt-a2-u07","position":7,"title_es":"O que você pretende fazer?","objective_es":"Contar tu formación y tus planes de trabajo.","intro":{"explanation":"Falso amigo: pretender es «tener pensado», «tener la intención»: pretendo fazer um mestrado. «Recibirse» es formar-se: eu me formei em engenharia (con el pronombre antes del verbo, como se habla en Brasil).","examples":[{"target":"Eu me formei no ano passado.","base":"Me recibí el año pasado."},{"target":"Pretendo trabalhar numa empresa grande.","base":"Tengo pensado trabajar en una empresa grande."}]},"takeaways":["Cuentas tu formación: me formei em…","Cuentas tus planes con pretendo."]},{"id":"pt-a2-u08-l01","unit_id":"pt-a2-u08","position":1,"title_es":"Estou com dor de cabeça","objective_es":"Decir qué te duele.","intro":{"explanation":"«Me duele…» se dice estou com dor de…: estou com dor de cabeça, de garganta, de dente. Con la espalda va nas: estou com dor nas costas. Falso amigo: costas es la «espalda».","examples":[{"target":"Estou com dor de cabeça.","base":"Me duele la cabeza."},{"target":"Ele está com dor nas costas.","base":"A él le duele la espalda."}]},"takeaways":["Dices qué te duele: estou com dor de…","Sabes que costas es «espalda»."]},{"id":"pt-a2-u08-l02","unit_id":"pt-a2-u08","position":2,"title_es":"Febre e resfriado","objective_es":"Contar tus síntomas.","intro":{"explanation":"Con estar com se dicen los síntomas: estou com febre (tengo fiebre), estou com um resfriado (estoy resfriado). En Brasil gripe es una gripe fuerte; un resfrío común es um resfriado.","examples":[{"target":"Estou com febre desde ontem.","base":"Tengo fiebre desde ayer."},{"target":"Acho que é um resfriado.","base":"Creo que es un resfrío."}]},"takeaways":["Cuentas síntomas con estou com…","Distingues resfriado y gripe."]},{"id":"pt-a2-u08-l03","unit_id":"pt-a2-u08","position":4,"title_es":"Tome o remédio","objective_es":"Entender y dar indicaciones con el imperativo.","intro":{"explanation":"El imperativo con você: los verbos en -ar terminan en -e (tomar → tome) y los en -er / -ir, en -a (beber → beba). Remédio es «remedio» o «medicamento». Se compra na farmácia.","examples":[{"target":"Tome um comprimido de oito em oito horas.","base":"Toma una pastilla cada ocho horas."},{"target":"Beba muita água.","base":"Toma mucha agua."}]},"takeaways":["Entiendes indicaciones: tome, beba.","Compras un remedio en la farmacia."]},{"id":"pt-a2-u08-l04","unit_id":"pt-a2-u08","position":5,"title_es":"Descanse e evite café","objective_es":"Dar consejos de salud (y en negativo).","intro":{"explanation":"Para aconsejar: descanse (descansa), evite (evita), coma frutas. En negativo se agrega não: não tome café, não coma doce. A alguien enfermo se le dice melhoras! («¡que te mejores!»).","examples":[{"target":"Descanse e evite café à noite.","base":"Descansa y evita el café por la noche."},{"target":"Não coma muito hoje. Melhoras!","base":"No comas mucho hoy. ¡Que te mejores!"}]},"takeaways":["Das consejos: descanse, evite.","Saludas a un enfermo: melhoras!"]},{"id":"pt-a2-u08-l05","unit_id":"pt-a2-u08","position":7,"title_es":"Marcar uma consulta","objective_es":"Pedir un turno y avisar que estás enfermo.","intro":{"explanation":"Una consulta es la «cita» con el médico; «pedir cita» es marcar uma consulta. Por teléfono: eu gostaria de marcar uma consulta. Para avisar: hoje não vou trabalhar, estou doente.","examples":[{"target":"Eu gostaria de marcar uma consulta.","base":"Quisiera pedir una cita."},{"target":"Já marquei uma consulta para as onze.","base":"Ya pedí cita para las once."}]},"takeaways":["Pides una cita: marcar uma consulta.","Avisas que no vas a trabajar."]},{"id":"pt-a2-u09-l01","unit_id":"pt-a2-u09","position":1,"title_es":"Mais barato do que…","objective_es":"Comparar con mais… do que y menos… do que.","intro":{"explanation":"Para comparar: mais + adjetivo + do que (o solo que): a azul é mais barata do que a preta. Al revés: menos… do que. El adjetivo concuerda: mais barato, mais barata.","examples":[{"target":"A camiseta azul é mais barata do que a preta.","base":"La camiseta azul es más barata que la negra."},{"target":"Esta loja é menos cara do que aquela.","base":"Esta tienda es menos cara que aquella."}]},"takeaways":["Comparas con mais… do que.","Comparas con menos… do que."]},{"id":"pt-a2-u09-l02","unit_id":"pt-a2-u09","position":2,"title_es":"Melhor, pior, maior, menor","objective_es":"Usar los comparativos irregulares.","intro":{"explanation":"Como en español, algunos son irregulares: melhor (mejor), pior (peor), maior (más grande, mayor) y menor (más chico, menor). No se dice mais bom: se dice melhor.","examples":[{"target":"Este restaurante é melhor do que aquele.","base":"Este restaurante es mejor que aquel."},{"target":"Você tem um tamanho maior?","base":"¿Tienes una talla más grande?"}]},"takeaways":["Usas melhor, pior, maior y menor.","Pides una talla más grande o más chica."]},{"id":"pt-a2-u09-l03","unit_id":"pt-a2-u09","position":4,"title_es":"Posso provar?","objective_es":"Probarte ropa y pedir otra talla.","intro":{"explanation":"Provar es «probarse» (y «probar» comida): posso provar esta calça? Falsos amigos: calça es el «pantalón» y tênis, las «zapatillas». O tamanho es el talle; en calzado se dice o número.","examples":[{"target":"Posso provar esta calça?","base":"¿Me puedo probar este pantalón?"},{"target":"Qual é o seu tamanho?","base":"¿Cuál es tu talla?"}]},"takeaways":["Pides probarte algo: posso provar…?","Sabes que calça es «pantalón»."]},{"id":"pt-a2-u09-l04","unit_id":"pt-a2-u09","position":5,"title_es":"Desconto e troca","objective_es":"Entender ofertas y cambiar un producto.","intro":{"explanation":"Desconto es «descuento» y liquidação, la «liquidación». Trocar es «cambiar» un producto: posso trocar? En Brasil es común pagar em três vezes sem juros (en tres cuotas sin interés).","examples":[{"target":"A loja está em liquidação.","base":"La tienda está de liquidación."},{"target":"Posso trocar por um tamanho maior?","base":"¿Lo puedo cambiar por una talla más grande?"}]},"takeaways":["Entiendes ofertas: desconto, liquidação.","Cambias un producto: posso trocar?"]},{"id":"pt-a2-u09-l05","unit_id":"pt-a2-u09","position":7,"title_es":"O melhor do ano","objective_es":"Elegir lo mejor: tão… quanto y el superlativo.","intro":{"explanation":"Igualdad: tão + adjetivo + quanto (tão boa quanto). Superlativo: o / a mais + adjetivo (o mais barato da loja) y los irregulares o melhor, o pior. «De» la tienda se dice da loja.","examples":[{"target":"A câmera é tão boa quanto a do outro.","base":"La cámara es tan buena como la del otro."},{"target":"Este é o tênis mais barato da loja.","base":"Estas son las zapatillas más baratas de la tienda."}]},"takeaways":["Dices que algo es igual: tão… quanto.","Eliges lo mejor: o melhor, o mais…"]},{"id":"pt-a2-u10-l01","unit_id":"pt-a2-u10","position":1,"title_es":"Te ligo depois","objective_es":"Llamar por teléfono y evitar el falso amigo ligar.","intro":{"explanation":"Falso amigo: ligar es «llamar por teléfono»: vou ligar para a minha mãe. Te va antes del verbo: te ligo depois («te llamo después»). Ligar también es «prender» un aparato, y desligar, «apagarlo».","examples":[{"target":"Te ligo depois do trabalho.","base":"Te llamo después del trabajo."},{"target":"Vou ligar para o meu pai.","base":"Voy a llamar a mi papá."}]},"takeaways":["Llamas a alguien: ligar para…","Pones te antes del verbo: te ligo."]},{"id":"pt-a2-u10-l02","unit_id":"pt-a2-u10","position":2,"title_es":"Me manda uma mensagem","objective_es":"Pedir y mandar mensajes con me y te.","intro":{"explanation":"Me y te van antes del verbo: me manda (mándame), te mando (te mando), vou te mandar. En Brasil todo el mundo usa WhatsApp: se le dice zap, y se mandan muchos áudios (mensajes de voz).","examples":[{"target":"Me manda o endereço no zap?","base":"¿Me mandas la dirección por WhatsApp?"},{"target":"Vou te mandar um áudio.","base":"Te voy a mandar un audio."}]},"takeaways":["Pides que te manden algo: me manda…","Ofreces mandar algo: te mando, vou te mandar."]},{"id":"pt-a2-u10-l03","unit_id":"pt-a2-u10","position":4,"title_es":"Senha e aplicativo","objective_es":"Usar apps y contraseñas.","intro":{"explanation":"Senha es la «contraseña»; aplicativo (o app), la aplicación. Baixar es «descargar»: baixe o aplicativo. Falso amigo: apagar es «borrar» (apague a foto).","examples":[{"target":"Esqueci a minha senha.","base":"Me olvidé la contraseña."},{"target":"Baixe o aplicativo e crie uma conta.","base":"Descarga la aplicación y crea una cuenta."}]},"takeaways":["Hablas de apps y contraseñas.","Sabes que apagar es «borrar»."]},{"id":"pt-a2-u10-l04","unit_id":"pt-a2-u10","position":5,"title_es":"A tela ficou preta","objective_es":"Resolver problemas con el celular y la computadora.","intro":{"explanation":"Falsos amigos: tela es la «pantalla» y desligar es «apagar» (desligue o computador). O carregador es el cargador. Cadê…? es una forma muy brasileña de preguntar «¿dónde está…?».","examples":[{"target":"A tela do celular ficou preta.","base":"La pantalla del celular se puso negra."},{"target":"Cadê o carregador?","base":"¿Dónde está el cargador?"}]},"takeaways":["Describes un problema: a tela, a bateria.","Sabes que desligar es «apagar»."]},{"id":"pt-a2-u10-l05","unit_id":"pt-a2-u10","position":7,"title_es":"Eu vi ele ontem","objective_es":"Usar «lo / la» como en Brasil (formal y coloquial).","intro":{"explanation":"Para «lo» y «la» hay dos registros. Formal o escrito: o / a antes del verbo (eu o conheço) o después (conheço-o, más raro en Brasil). En el habla: ele / ela después del verbo: eu vi ele ontem, chama ela!","examples":[{"target":"Eu o conheço do trabalho.","base":"Lo conozco del trabajo."},{"target":"Você viu a Nanda? — Vi ela ontem.","base":"¿Viste a Nanda? — La vi ayer."}]},"takeaways":["Reconoces o / a en lo formal.","Dices «lo vi» como en Brasil: eu vi ele."]},{"id":"pt-a2-u11-l01","unit_id":"pt-a2-u11","position":1,"title_es":"Eu me levanto cedo","objective_es":"Contar tu mañana con verbos reflexivos.","intro":{"explanation":"En Brasil el reflexivo va antes del verbo: eu me levanto, você se levanta. Cedo es «temprano». Ojo: acordar («despertarse») no lleva pronombre: eu acordo às seis e me levanto às seis e meia.","examples":[{"target":"Eu acordo cedo e me levanto às seis.","base":"Me despierto temprano y me levanto a las seis."},{"target":"Você se levanta tarde no domingo?","base":"¿Te levantas tarde el domingo?"}]},"takeaways":["Cuentas tu mañana: me levanto, me visto.","Pones el pronombre antes del verbo."]},{"id":"pt-a2-u11-l02","unit_id":"pt-a2-u11","position":2,"title_es":"Tomo banho e me deito","objective_es":"Contar tu noche y los verbos que cambian.","intro":{"explanation":"Algunos verbos no son reflexivos como en español: «bañarse» es tomar banho (eu tomo banho) y «despertarse», acordar. Deitar-se es «acostarse»: eu me deito às onze.","examples":[{"target":"À noite eu tomo banho e me deito.","base":"Por la noche me baño y me acuesto."},{"target":"Ela se deita muito tarde.","base":"Ella se acuesta muy tarde."}]},"takeaways":["Dices «bañarse»: tomar banho.","Dices a qué hora te acuestas: me deito."]},{"id":"pt-a2-u11-l03","unit_id":"pt-a2-u11","position":4,"title_es":"Às vezes, nunca, toda semana","objective_es":"Decir con qué frecuencia haces algo.","intro":{"explanation":"De más a menos: sempre (siempre), toda semana (todas las semanas), às vezes (a veces), de vez em quando (de vez en cuando), nunca. Para contar veces: uma vez por semana, duas vezes por semana.","examples":[{"target":"Às vezes eu almoço em casa.","base":"A veces almuerzo en casa."},{"target":"Eu jogo futebol duas vezes por semana.","base":"Juego al fútbol dos veces por semana."}]},"takeaways":["Dices la frecuencia: às vezes, nunca, toda semana.","Cuentas veces: duas vezes por semana."]},{"id":"pt-a2-u11-l04","unit_id":"pt-a2-u11","position":5,"title_es":"Há dois anos, desde março","objective_es":"Decir desde hace cuánto tiempo haces algo.","intro":{"explanation":"«Hace» + tiempo se dice há o faz: moro aqui há dois anos, faz dois anos que moro aqui. Para preguntar: há quanto tempo…? Desde es igual: desde março. Faz tempo que não… es «hace tiempo que no…».","examples":[{"target":"Eu estudo português há dois anos.","base":"Estudio portugués hace dos años."},{"target":"Faz tempo que eu não vejo você!","base":"¡Hace tiempo que no te veo!"}]},"takeaways":["Dices la duración: há dois anos, desde março.","Preguntas: há quanto tempo…?"]},{"id":"pt-a2-u11-l05","unit_id":"pt-a2-u11","position":7,"title_es":"Me sinto melhor","objective_es":"Contar cómo te sientes y tus hábitos de salud.","intro":{"explanation":"Sentir-se es «sentirse»: eu me sinto bem, ela se sente cansada. Falso amigo: academia es el «gimnasio» (la academia de idiomas es escola de idiomas).","examples":[{"target":"Depois da academia eu me sinto muito melhor.","base":"Después del gimnasio me siento mucho mejor."},{"target":"Você se sente cansado?","base":"¿Te sientes cansado?"}]},"takeaways":["Dices cómo te sientes: me sinto…","Sabes que academia es «gimnasio»."]},{"id":"pt-a2-u12-l01","unit_id":"pt-a2-u12","position":1,"title_es":"Acho que…","objective_es":"Dar tu opinión.","intro":{"explanation":"Achar es «encontrar», pero acho que es «creo que», «me parece que»: acho que é melhor. Na minha opinião es «en mi opinión». Para preguntar: o que você acha?","examples":[{"target":"Acho que morar no centro é melhor.","base":"Creo que vivir en el centro es mejor."},{"target":"O que você acha do filme?","base":"¿Qué te parece la película?"}]},"takeaways":["Das tu opinión: acho que…, na minha opinião…","Preguntas: o que você acha?"]},{"id":"pt-a2-u12-l02","unit_id":"pt-a2-u12","position":2,"title_es":"Concordo, discordo","objective_es":"Decir si estás de acuerdo.","intro":{"explanation":"«Estoy de acuerdo» es un solo verbo: concordo (com você). «No estoy de acuerdo»: discordo. Si te da igual: tanto faz. Si no sabes: sei lá (informal). Vale a pena es «vale la pena».","examples":[{"target":"Concordo com você.","base":"Estoy de acuerdo contigo."},{"target":"Pizza ou hambúrguer? Tanto faz.","base":"¿Pizza o hamburguesa? Me da igual."}]},"takeaways":["Acuerdas y discrepas: concordo, discordo.","Dices que te da igual: tanto faz."]},{"id":"pt-a2-u12-l03","unit_id":"pt-a2-u12","position":4,"title_es":"Se você quiser…","objective_es":"Plantear condiciones sencillas.","intro":{"explanation":"Una condición posible: se + presente y el resultado en presente o con vou + verbo: se você tem tempo, a gente vai. Hay expresiones fijas que vas a oír siempre: se você quiser («si quieres») y se der («si se puede»).","examples":[{"target":"Se você quiser, eu te ajudo.","base":"Si quieres, te ayudo."},{"target":"Se der, eu passo aí amanhã.","base":"Si puedo, paso mañana."}]},"takeaways":["Planteas una condición con se.","Usas se der y se você quiser."]},{"id":"pt-a2-u12-l04","unit_id":"pt-a2-u12","position":5,"title_es":"Quebrou, não funciona","objective_es":"Explicar que algo se rompió o no funciona.","intro":{"explanation":"Quebrar es «romper»: o celular quebrou («se rompió el celular»), sin pronombre. Para algo que anda mal: não funciona. Si se corta internet: a internet caiu. Consertar es «arreglar».","examples":[{"target":"O meu celular quebrou.","base":"Se me rompió el celular."},{"target":"A internet caiu de novo!","base":"¡Se cortó internet otra vez!"}]},"takeaways":["Explicas un problema: quebrou, não funciona.","Pides que lo arreglen: consertar."]},{"id":"pt-a2-u12-l05","unit_id":"pt-a2-u12","position":7,"title_es":"Uma reclamação","objective_es":"Hacer un reclamo y pedir una solución.","intro":{"explanation":"Fazer uma reclamação es «hacer un reclamo». Ainda es «todavía»: o problema ainda não foi resolvido («todavía no se resolvió»). Para cerrar con una condición: se vocês não resolverem, vou cancelar.","examples":[{"target":"Quero fazer uma reclamação.","base":"Quiero hacer un reclamo."},{"target":"Ainda estou sem internet.","base":"Todavía estoy sin internet."}]},"takeaways":["Haces un reclamo: fazer uma reclamação.","Explicas que todavía no se resolvió: ainda não…"]},{"id":"it-a1-u13-l01","unit_id":"it-a1-u13","position":1,"title_es":"Noi, voi, loro","objective_es":"Hablar de varias personas con essere.","intro":{"explanation":"Para hablar de varias personas: noi (nosotros), voi (ustedes) y loro (ellos, ellas). Essere: noi siamo, voi siete, loro sono. Ojo con siete: no es el número 7 (sette), es «ustedes son».","examples":[{"target":"Noi siamo amici.","base":"Somos amigos."},{"target":"Voi siete italiani?","base":"¿Ustedes son italianos?"}]},"takeaways":["Usas noi, voi y loro.","Conjugas essere en plural: siamo, siete, sono."]},{"id":"it-a1-u13-l02","unit_id":"it-a1-u13","position":2,"title_es":"Lavoriamo, lavorano","objective_es":"Conjugar los verbos en -are en plural.","intro":{"explanation":"En plural, los verbos en -are terminan en -iamo (noi), -ate (voi) y -ano (loro): lavoriamo, lavorate, lavorano. En lavorano el acento va atrás: la-vó-ra-no, nunca «lavoranó».","examples":[{"target":"Noi lavoriamo la mattina.","base":"Trabajamos a la mañana."},{"target":"Loro lavorano a casa.","base":"Ellos trabajan en casa."}]},"takeaways":["Conjugas -are en plural: lavoriamo, lavorate, lavorano.","Dices cuándo y dónde trabaja un grupo."]},{"id":"it-a1-u13-l03","unit_id":"it-a1-u13","position":4,"title_es":"Che lavoro fai?","objective_es":"Preguntar y decir de qué trabaja alguien.","intro":{"explanation":"Che lavoro fai? es «¿de qué trabajas?». Se responde con sono y la profesión sin artículo (sono medico) o con faccio y artículo (faccio il cuoco). En femenino, -o pasa a -a (cuoca) y -iere a -iera (infermiera); insegnante no cambia.","examples":[{"target":"Che lavoro fai? — Sono infermiera.","base":"¿De qué trabajas? — Soy enfermera."},{"target":"Faccio il cuoco.","base":"Soy cocinero."}]},"takeaways":["Preguntas la profesión con che lavoro fai?","Dices profesiones con sono o con faccio il / la."]},{"id":"it-a1-u13-l04","unit_id":"it-a1-u13","position":5,"title_es":"In ufficio, in negozio","objective_es":"Decir dónde trabaja cada uno.","intro":{"explanation":"Se dice lavoro in ufficio, in negozio, in ospedale (sin artículo). Ojo: negozio es la tienda, el local; el cameriere (el mesero) no tiene nada que ver con la camera (la habitación).","examples":[{"target":"Lavoro in ufficio.","base":"Trabajo en una oficina."},{"target":"Mio fratello è commesso in un negozio.","base":"Mi hermano es vendedor en una tienda."}]},"takeaways":["Dices dónde trabajas: in ufficio, in negozio.","Nombras trabajos de la tienda y del restaurante."]},{"id":"it-a1-u13-l05","unit_id":"it-a1-u13","position":7,"title_es":"Il nostro lavoro","objective_es":"Usar nostro y nostra y entender la presentación de un grupo.","intro":{"explanation":"Nostro y nostra son «nuestro» y «nuestra». En italiano llevan artículo: il nostro ristorante, la nostra casa. Concuerdan con la cosa, no con las personas que hablan.","examples":[{"target":"Il nostro ufficio è piccolo.","base":"Nuestra oficina es chica."},{"target":"La nostra famiglia è grande.","base":"Nuestra familia es grande."}]},"takeaways":["Usas il nostro y la nostra según la cosa.","Entiendes una presentación de un grupo."]},{"id":"it-a1-u14-l01","unit_id":"it-a1-u14","position":1,"title_es":"Sono stanco","objective_es":"Decir cómo estás con essere y con stare.","intro":{"explanation":"En italiano los estados van con essere: sono stanco es «estoy cansado» y sono felice, «estoy feliz». Stare se usa sobre todo para la salud y el saludo: sto bene, sto male. Por eso: come stai? — Sto male, sono malato.","examples":[{"target":"Oggi sono stanca.","base":"Hoy estoy cansada."},{"target":"Sto male, sono malato.","base":"Me siento mal, estoy enfermo."}]},"takeaways":["Dices cómo estás con sono: stanco, felice, malato.","Dices cómo te sientes con sto bene / sto male."]},{"id":"it-a1-u14-l02","unit_id":"it-a1-u14","position":2,"title_es":"Ho fame, ho sete","objective_es":"Decir si tienes hambre, sed, frío o calor.","intro":{"explanation":"Hambre, sed, frío y calor van con avere, como en español: ho fame, ho sete, ho freddo, ho caldo. Ojo: caldo no es el caldo de la sopa, es «calor» o «caliente»: ho caldo es «tengo calor».","examples":[{"target":"Ho fame e ho sete.","base":"Tengo hambre y tengo sed."},{"target":"Ho caldo, vorrei un gelato.","base":"Tengo calor, quisiera un helado."}]},"takeaways":["Dices ho fame, ho sete, ho freddo y ho caldo.","Sabes que caldo es «calor»."]},{"id":"it-a1-u14-l03","unit_id":"it-a1-u14","position":4,"title_es":"Com'è?","objective_es":"Describir cómo es una persona.","intro":{"explanation":"Com'è? es «¿cómo es?». Se responde con è: è alto, è bassa, è giovane. El pelo y los ojos van con avere y artículo: ha i capelli neri, ha gli occhi blu. El adjetivo concuerda: capelli lunghi, sorella bassa.","examples":[{"target":"Com'è tuo fratello? — È alto.","base":"¿Cómo es tu hermano? — Es alto."},{"target":"Ha i capelli lunghi.","base":"Tiene el pelo largo."}]},"takeaways":["Preguntas com'è? y describes con è y ha.","Haces concordar el adjetivo: basso, bassa, bassi."]},{"id":"it-a1-u14-l04","unit_id":"it-a1-u14","position":5,"title_es":"Simpatico, ma un po' timido","objective_es":"Describir el carácter y matizar con un po’ y ma.","intro":{"explanation":"Para el carácter: simpatico (buena onda) y carino (lindo, amable). Ojo: carino no es «cariño». Un po' es «un poco» y ma es «pero»: è carina ma un po' timida.","examples":[{"target":"Il mio amico è simpatico.","base":"Mi amigo es simpático."},{"target":"È carina ma un po' timida.","base":"Es linda pero un poco tímida."}]},"takeaways":["Describes el carácter con simpatico y carino.","Matizas con un po' y ma."]},{"id":"it-a1-u14-l05","unit_id":"it-a1-u14","position":7,"title_es":"Essere, stare, avere","objective_es":"Elegir el verbo justo para decir cómo estás y cómo eres.","intro":{"explanation":"Tres verbos donde el español dice «estar» o «tener»: essere para cómo eres y cómo estás (è alta, sono stanco), stare para la salud (sto male) y avere para hambre, sed, frío y calor (ho freddo).","examples":[{"target":"Paolo è malato e ha freddo.","base":"Paolo está enfermo y tiene frío."},{"target":"Sto bene, ma sono un po' stanca.","base":"Estoy bien, pero un poco cansada."}]},"takeaways":["Eliges entre essere, stare y avere.","Entiendes una llamada sobre cómo está alguien."]},{"id":"it-a1-u14-final","unit_id":"it-a1-u14","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Cómo eres? ¿Cómo estás?».","intro":null,"takeaways":[]},{"id":"it-a1-u15-l01","unit_id":"it-a1-u15","position":1,"title_es":"Trenta, cinquanta, cento","objective_es":"Contar de diez en diez hasta cien.","intro":{"explanation":"Las decenas: venti, trenta, quaranta, cinquanta… ottanta, cento. Con uno y otto la decena pierde la última vocal: ventuno, trentotto. Cien es cento, sin cambios: cento euro.","examples":[{"target":"Mio padre ha cinquanta anni.","base":"Mi papá tiene cincuenta años."},{"target":"Il biglietto costa cento euro.","base":"El boleto cuesta cien euros."}]},"takeaways":["Cuentas de diez en diez hasta cento.","Dices edades y precios más grandes."]},{"id":"it-a1-u15-l02","unit_id":"it-a1-u15","position":2,"title_es":"Il primo maggio","objective_es":"Decir la fecha y cuándo es tu cumpleaños.","intro":{"explanation":"Los meses van en minúscula: gennaio, maggio, luglio, agosto, dicembre. La fecha es il + número + mes: il 12 luglio. El día 1 usa el ordinal: il primo maggio. «En julio» es a luglio o in luglio.","examples":[{"target":"Il mio compleanno è il primo maggio.","base":"Mi cumpleaños es el 1 de mayo."},{"target":"Il mio compleanno è a luglio.","base":"Mi cumpleaños es en julio."}]},"takeaways":["Dices la fecha con il + número + mes (il primo para el 1).","Dices en qué mes es algo: a luglio, in luglio."]},{"id":"it-a1-u15-l03","unit_id":"it-a1-u15","position":4,"title_es":"Che tempo fa?","objective_es":"Preguntar y decir qué tiempo hace.","intro":{"explanation":"Che tempo fa? es «¿qué tiempo hace?». Con fare: fa caldo, fa freddo. Sin fare: piove (llueve), nevica (nieva), c’è il sole (hay sol). Ojo: fa caldo es «hace calor», no tiene que ver con el caldo.","examples":[{"target":"Che tempo fa? — Fa caldo.","base":"¿Qué tiempo hace? — Hace calor."},{"target":"Oggi piove e fa freddo.","base":"Hoy llueve y hace frío."}]},"takeaways":["Preguntas che tempo fa?","Dices fa caldo, fa freddo, piove, nevica y c’è il sole."]},{"id":"it-a1-u15-l04","unit_id":"it-a1-u15","position":5,"title_es":"L'estate e l'inverno","objective_es":"Hablar de las estaciones y del clima en cada una.","intro":{"explanation":"Las estaciones: la primavera, l'estate (el verano, femenino), l'autunno y l'inverno. «En verano» es d'estate o in estate. Y recuerda: en la Argentina diciembre es verano; en Italia, invierno.","examples":[{"target":"D'estate fa caldo.","base":"En verano hace calor."},{"target":"A dicembre in Italia è inverno.","base":"En diciembre en Italia es invierno."}]},"takeaways":["Nombras l'estate y l'inverno.","Comparas el clima de los dos hemisferios."]},{"id":"it-a1-u15-l05","unit_id":"it-a1-u15","position":7,"title_es":"Ferragosto","objective_es":"Entender fechas y avisos de días especiales en Italia.","intro":{"explanation":"Fechas que vas a ver en Italia: il primo maggio, Ferragosto (il 15 agosto, en pleno verano) y Natale (il 25 dicembre). Esos días muchos negocios están cerrados: chiuso.","examples":[{"target":"Il 15 agosto è Ferragosto.","base":"El 15 de agosto es Ferragosto."},{"target":"Il primo maggio è festa.","base":"El 1 de mayo es feriado."}]},"takeaways":["Entiendes un aviso de cierre por un feriado.","Dices fechas especiales del año."]},{"id":"it-a1-u16-l01","unit_id":"it-a1-u16","position":1,"title_es":"In treno, a piedi","objective_es":"Decir cómo vas a los lugares.","intro":{"explanation":"El transporte va con in y sin artículo: in treno, in autobus, in macchina, in bicicletta; caminando es a piedi. Ojo: macchina es el auto (no una máquina). «Tomar» el autobús es prendere: prendo l’autobus.","examples":[{"target":"Vado a scuola a piedi.","base":"Voy a la escuela a pie."},{"target":"Prendo l’autobus ogni giorno.","base":"Tomo el autobús todos los días."}]},"takeaways":["Dices cómo vas: in treno, in macchina, a piedi.","Sabes que macchina es «auto»."]},{"id":"it-a1-u16-l02","unit_id":"it-a1-u16","position":2,"title_es":"Al mare, alla stazione","objective_es":"Decir adónde vas con al y alla.","intro":{"explanation":"A + il = al y a + la = alla: vado al cinema, al mare, alla stazione. Con la montaña se usa in: vado in montagna. Andiamo es «vamos»: andiamo al mare!","examples":[{"target":"Sabato vado al mare.","base":"El sábado voy al mar."},{"target":"Andiamo alla stazione.","base":"Vamos a la estación."}]},"takeaways":["Usas al y alla para decir adónde vas.","Dices in montagna y al mare."]},{"id":"it-a1-u16-l03","unit_id":"it-a1-u16","position":4,"title_es":"Andiamo, andate, vanno","objective_es":"Conjugar andare en plural y entender cómo viaja un grupo.","intro":{"explanation":"Andare es irregular: vado, vai, va, andiamo, andate, vanno. Con noi y voi vuelve la raíz and-: andiamo, andate. Con loro: vanno.","examples":[{"target":"I miei genitori vanno in montagna.","base":"Mis papás van a la montaña."},{"target":"Voi andate al mare?","base":"¿Ustedes van al mar?"}]},"takeaways":["Conjugas andare: andiamo, andate, vanno.","Entiendes cómo viaja un grupo."]},{"id":"it-a1-u16-l04","unit_id":"it-a1-u16","position":5,"title_es":"Ieri ho mangiato…","objective_es":"Contar en pocas palabras qué hiciste ayer.","intro":{"explanation":"Para contar lo que hiciste se usa avere + participio: ho mangiato (comí), ho visto (vi). Ieri es «ayer». Para preguntar: cosa hai fatto? (¿qué hiciste?). En la U1 del A2 lo vas a ver completo.","examples":[{"target":"Ieri ho mangiato una pizza.","base":"Ayer comí una pizza."},{"target":"Cosa hai fatto ieri?","base":"¿Qué hiciste ayer?"}]},"takeaways":["Preguntas cosa hai fatto?","Cuentas algo de ayer con ho mangiato y ho visto."]},{"id":"it-a1-u16-l05","unit_id":"it-a1-u16","position":7,"title_es":"Sono andato al cinema","objective_es":"Contar adónde fuiste y entender planes de fin de semana.","intro":{"explanation":"Con andare el pasado va con essere, y el participio concuerda con quien habla: sono andato (varón), sono andata (mujer). Y ojo: guardare es «mirar», no «guardar»: guardo la TV, ho guardato un film.","examples":[{"target":"Ieri sono andata al mare.","base":"Ayer fui al mar."},{"target":"Mi piace guardare la TV.","base":"Me gusta mirar la tele."}]},"takeaways":["Dices adónde fuiste: sono andato / sono andata.","Sabes que guardare es «mirar»."]},{"id":"it-a2-u01-l01","unit_id":"it-a2-u01","position":1,"title_es":"Ho parlato, ho dormito","objective_es":"Contar lo que hiciste con los participios regulares.","intro":{"explanation":"El passato prossimo cuenta algo terminado: avere + participio. -are → -ato (parlato), -ere → -uto (bevuto), -ire → -ito (dormito). Donde decimos «hablé», en italiano se dice ho parlato.","examples":[{"target":"Ieri ho parlato con mia madre.","base":"Ayer hablé con mi mamá."},{"target":"Ho dormito molto.","base":"Dormí mucho."}]},"takeaways":["Formas el passato prossimo con ho + participio.","Conoces los participios en -ato, -uto, -ito."]},{"id":"it-a2-u01-l02","unit_id":"it-a2-u01","position":2,"title_es":"Ho fatto, ho preso","objective_es":"Usar los participios irregulares más frecuentes.","intro":{"explanation":"Algunos participios son irregulares: fare → fatto, leggere → letto, scrivere → scritto, prendere → preso (y vedere → visto). Ojo: fare la spesa es hacer las compras de comida, y la lettera es la carta que se escribe.","examples":[{"target":"Ho fatto la spesa al supermercato.","base":"Hice las compras en el súper."},{"target":"Ho preso il treno alle otto.","base":"Tomé el tren a las ocho."}]},"takeaways":["Usas fatto, letto, scritto y preso.","Dices que hiciste las compras: ho fatto la spesa."]},{"id":"it-a2-u01-l03","unit_id":"it-a2-u01","position":4,"title_es":"Abbiamo mangiato, hanno parlato","objective_es":"Contar lo que hizo un grupo.","intro":{"explanation":"Avere en plural: abbiamo (noi), avete (voi), hanno (loro). Con avere el participio no cambia aunque hablen varias personas: abbiamo mangiato, hanno parlato, Sara ha letto.","examples":[{"target":"Abbiamo mangiato in una trattoria.","base":"Comimos en una trattoria."},{"target":"I miei amici hanno parlato tutto il giorno.","base":"Mis amigos hablaron todo el día."}]},"takeaways":["Cuentas en plural: abbiamo, hanno + participio.","Sabes que con avere el participio no concuerda."]},{"id":"it-a2-u01-l04","unit_id":"it-a2-u01","position":5,"title_es":"Già, non… ancora","objective_es":"Decir lo que ya hiciste y lo que todavía no.","intro":{"explanation":"Già (ya) y ancora (todavía) van entre avere y el participio: ho già mangiato (ya comí), non ho ancora mangiato (todavía no comí). Non… ancora también sirve solo: non ancora!","examples":[{"target":"Ho già fatto la spesa.","base":"Ya hice las compras."},{"target":"Non ho ancora scritto alla nonna.","base":"Todavía no le escribí a la abuela."}]},"takeaways":["Dices ho già + participio.","Dices non ho ancora + participio."]},{"id":"it-a2-u01-l05","unit_id":"it-a2-u01","position":7,"title_es":"Sabato scorso","objective_es":"Ubicar en el tiempo lo que hiciste y entender un relato.","intro":{"explanation":"Para el pasado: stamattina (esta mañana), ieri sera (anoche), sabato scorso, la settimana scorsa (scorso concuerda). Ojo: la partita es el partido; la partida de un viaje es otra cosa.","examples":[{"target":"Ieri sera ho visto la partita.","base":"Anoche vi el partido."},{"target":"La settimana scorsa ho pulito la casa.","base":"La semana pasada limpié la casa."}]},"takeaways":["Dices cuándo: stamattina, ieri sera, sabato scorso.","Entiendes un relato de fin de semana."]},{"id":"it-a2-u02-l01","unit_id":"it-a2-u02","position":1,"title_es":"Sono partito, sono arrivato","objective_es":"Contar salidas y llegadas con essere.","intro":{"explanation":"Con los verbos de movimiento (andare, partire, arrivare, tornare) el passato prossimo va con essere, y el participio concuerda como un adjetivo: sono arrivato (él), sono arrivata (ella), siamo arrivati.","examples":[{"target":"Sono arrivata a Roma ieri.","base":"Llegué a Roma ayer."},{"target":"Siamo andati a Napoli in treno.","base":"Fuimos a Nápoles en tren."}]},"takeaways":["Usas essere con partire, arrivare, tornare y andare.","Haces concordar el participio: arrivato, arrivata, arrivati."]},{"id":"it-a2-u02-l02","unit_id":"it-a2-u02","position":2,"title_es":"Il viaggio, l'aeroporto","objective_es":"Usar el vocabulario del viaje y entender anuncios del aeropuerto.","intro":{"explanation":"Para viajar: il viaggio, la valigia (la maleta), l’aereo, l’aeroporto y il volo (el vuelo). En los anuncios vas a oír parte (sale) y in ritardo (demorado).","examples":[{"target":"Il volo parte alle undici.","base":"El vuelo sale a las once."},{"target":"La mia valigia è rossa.","base":"Mi maleta es roja."}]},"takeaways":["Nombras el aereo, la valigia y il volo.","Entiendes un anuncio de salida o de demora."]},{"id":"it-a2-u02-l03","unit_id":"it-a2-u02","position":4,"title_es":"Sono stato, sono rimasto","objective_es":"Decir dónde estuviste y cuánto te quedaste.","intro":{"explanation":"Essere y stare comparten participio: sono stato es «estuve» o «fui» (sono stato a Firenze). Rimanere (quedarse) da rimasto: sono rimasto a casa. Los dos van con essere.","examples":[{"target":"Siamo stati in vacanza in Sicilia.","base":"Estuvimos de vacaciones en Sicilia."},{"target":"Domenica sono rimasta a casa.","base":"El domingo me quedé en casa."}]},"takeaways":["Dices dónde estuviste: sono stato / stata.","Dices que te quedaste: sono rimasto / rimasta."]},{"id":"it-a2-u02-l04","unit_id":"it-a2-u02","position":5,"title_es":"Salire, scendere, uscire","objective_es":"No confundir salire con «salir».","intro":{"explanation":"Ojo con el falso amigo: salire es «subir» (sono salito sul treno) y scendere es «bajar» (sono sceso dall’autobus). «Salir» es uscire: sono uscito con gli amici. Todos van con essere.","examples":[{"target":"Sono salito sul treno a Milano.","base":"Subí al tren en Milán."},{"target":"Ieri sera sono uscita con Sara.","base":"Anoche salí con Sara."}]},"takeaways":["Sabes que salire es «subir».","Dices «salí» con sono uscito / uscita."]},{"id":"it-a2-u02-l05","unit_id":"it-a2-u02","position":7,"title_es":"Dieci anni fa","objective_es":"Decir hace cuánto pasó algo y entender el relato de un viaje.","intro":{"explanation":"Fa, después de una cantidad de tiempo, es «hace»: due anni fa (hace dos años), una settimana fa (hace una semana). Va al final: sono arrivato tre giorni fa.","examples":[{"target":"Sono andato in Italia dieci anni fa.","base":"Fui a Italia hace diez años."},{"target":"Siamo partiti due giorni fa.","base":"Partimos hace dos días."}]},"takeaways":["Dices hace cuánto con … fa.","Entiendes un relato de viaje en pasado."]},{"id":"it-a2-u03-l01","unit_id":"it-a2-u03","position":1,"title_es":"Vorrei prenotare","objective_es":"Reservar una habitación o una mesa.","intro":{"explanation":"Prenotare es «reservar»: vorrei prenotare una camera doppia (doble) o singola (simple). Si algo está incluido, es compreso y concuerda: la colazione è compresa.","examples":[{"target":"Vorrei prenotare una camera doppia.","base":"Quisiera reservar una habitación doble."},{"target":"La colazione è compresa?","base":"¿El desayuno está incluido?"}]},"takeaways":["Reservas con vorrei prenotare…","Preguntas qué está compreso."]},{"id":"it-a2-u03-l02","unit_id":"it-a2-u03","position":2,"title_es":"Il primo, il secondo","objective_es":"Entender el orden del menú italiano.","intro":{"explanation":"El menú italiano va en orden: antipasto, primo (pasta o risotto), secondo (carne o pescado), contorno (la guarnición, que se pide aparte) y dolce (el postre). Muchos comen sólo un primo o un secondo.","examples":[{"target":"Per secondo prendo il pollo.","base":"De segundo pido el pollo."},{"target":"Come contorno, patate.","base":"De guarnición, papas."}]},"takeaways":["Lees un menú: primi, secondi, contorni, dolci.","Pides un plato de cada parte."]},{"id":"it-a2-u03-l03","unit_id":"it-a2-u03","position":4,"title_es":"Mi porta…? Potrei…?","objective_es":"Pedir con cortesía tratando de usted.","intro":{"explanation":"Al mesero se le habla de Lei (usted), con el verbo en tercera persona: mi porta il conto? (¿me trae la cuenta?). Para pedir con cortesía: potrei avere…? o posso avere…? Y ojo: il burro es la mantequilla; el burro, el animal, es l’asino.","examples":[{"target":"Mi porta il conto, per favore?","base":"¿Me trae la cuenta, por favor?"},{"target":"Potrei avere un’acqua?","base":"¿Podría tomar un agua?"}]},"takeaways":["Pides con mi porta…?, potrei avere…? y posso avere…?","Sabes que burro es «mantequilla»."]},{"id":"it-a2-u03-l04","unit_id":"it-a2-u03","position":5,"title_es":"Il coperto e la mancia","objective_es":"Entender la cuenta y pagar.","intro":{"explanation":"En la cuenta italiana suele aparecer il coperto, un cargo fijo por persona (como el cubierto en la Argentina). La mancia (propina) no es obligatoria. Se paga in contanti (en efectivo) o con la carta (con tarjeta).","examples":[{"target":"Il coperto costa due euro.","base":"El cubierto cuesta dos euros."},{"target":"Posso pagare con la carta?","base":"¿Puedo pagar con tarjeta?"}]},"takeaways":["Entiendes il coperto y la mancia.","Dices cómo pagas: in contanti, con la carta."]},{"id":"it-a2-u03-l05","unit_id":"it-a2-u03","position":7,"title_es":"In albergo e al ristorante","objective_es":"Resolver una reserva y una comida de principio a fin.","intro":{"explanation":"Repasa todo el recorrido: reservar (ho prenotato un tavolo), pedir (per me un primo, mi porta…?), y pagar (il conto, con la carta). En el hotel: una camera singola o doppia, con la colazione compresa.","examples":[{"target":"Ho prenotato un tavolo per due.","base":"Reservé una mesa para dos."},{"target":"Vorrei una camera singola, per favore.","base":"Quisiera una habitación simple, por favor."}]},"takeaways":["Haces una reserva completa.","Entiendes una reseña de un restaurante."]},{"id":"it-a2-u04-l01","unit_id":"it-a2-u04","position":1,"title_es":"Ero, era, eravamo","objective_es":"Decir cómo eras con el imperfetto de essere.","intro":{"explanation":"Para describir cómo eran las cosas se usa el imperfetto, como nuestro pretérito imperfecto. Essere: ero (yo era), eri, era (él / ella era), eravamo (éramos). Da piccolo / da piccola es «de chico / de chica».","examples":[{"target":"Da piccola ero molto timida.","base":"De chica era muy tímida."},{"target":"Eravamo sette fratelli.","base":"Éramos siete hermanos."}]},"takeaways":["Usas ero, era y eravamo.","Dices da piccolo / da piccola."]},{"id":"it-a2-u04-l02","unit_id":"it-a2-u04","position":2,"title_es":"Abitavo, giocavo, andavo","objective_es":"Contar lo que hacías siempre.","intro":{"explanation":"Los verbos en -are hacen el imperfetto en -avo: abitavo (vivía), giocavo (jugaba), andavo (iba). Sirve para lo que hacías siempre, a menudo con di solito (por lo general). Ojo: giocare a calcio va sin artículo.","examples":[{"target":"Di solito andavo a scuola a piedi.","base":"Por lo general iba a la escuela a pie."},{"target":"Giocavo a calcio con mio fratello.","base":"Jugaba al fútbol con mi hermano."}]},"takeaways":["Cuentas hábitos con -avo: abitavo, giocavo, andavo.","Dices di solito y giocare a calcio."]},{"id":"it-a2-u04-l03","unit_id":"it-a2-u04","position":4,"title_es":"Avevo, facevo, c'era","objective_es":"Decir qué tenías, qué hacías y qué había.","intro":{"explanation":"Avere es regular: avevo (tenía), aveva. Fare usa la raíz fac-: facevo (hacía). Para lo que había: c’era (una cosa) y c’erano (varias). Y lo que te gustaba: mi piaceva.","examples":[{"target":"Da piccolo io avevo un gatto nero.","base":"De chico yo tenía un gato negro."},{"target":"Mi piaceva molto la scuola.","base":"Me gustaba mucho la escuela."}]},"takeaways":["Usas avevo, facevo y c'era.","Dices lo que te gustaba con mi piaceva."]},{"id":"it-a2-u04-l04","unit_id":"it-a2-u04","position":5,"title_es":"Il paese e la campagna","objective_es":"Hablar del lugar donde vivías y entender un recuerdo largo.","intro":{"explanation":"Paese es «país», pero también «pueblo»: abitavo in un piccolo paese. Ojo: la campagna es el campo (no una campaña). Vivir en el campo: abitare in campagna.","examples":[{"target":"Abitavo in un piccolo paese.","base":"Vivía en un pueblo chico."},{"target":"Mio nonno aveva una casa in campagna.","base":"Mi abuelo tenía una casa en el campo."}]},"takeaways":["Sabes que campagna es «campo» y paese, «pueblo».","Entiendes a alguien mayor que cuenta su infancia."]},{"id":"it-a2-u04-l05","unit_id":"it-a2-u04","position":7,"title_es":"Quando ero piccolo…","objective_es":"Contar un recuerdo de tu infancia.","intro":{"explanation":"Para contar recuerdos combinas todo: quando ero piccolo (cuando era chico) + lo que hacías (andavo, giocavo, facevo) + lo que había (c’era) + lo que te gustaba (mi piaceva).","examples":[{"target":"Quando ero piccola, abitavo a Roma.","base":"Cuando era chica, vivía en Roma."},{"target":"Di solito facevo i compiti in cucina.","base":"Por lo general hacía los deberes en la cocina."}]},"takeaways":["Cuentas un recuerdo con el imperfetto.","Combinas quando ero piccolo, di solito y mi piaceva."]},{"id":"it-a2-u05-l01","unit_id":"it-a2-u05","position":1,"title_es":"Cos'è successo?","objective_es":"Preguntar qué pasó y contar que perdiste o encontraste algo.","intro":{"explanation":"Cos’è successo? es «¿qué pasó?». Para contar: ho perso (perdí), ho trovato (encontré), ho chiamato (llamé). Ojo: subito es «enseguida», no «súbitamente».","examples":[{"target":"Ho perso le chiavi di casa!","base":"¡Perdí las llaves de casa!"},{"target":"Ho chiamato subito.","base":"Llamé enseguida."}]},"takeaways":["Preguntas cos'è successo?","Cuentas que perdiste, encontraste o llamaste."]},{"id":"it-a2-u05-l02","unit_id":"it-a2-u05","position":2,"title_es":"Stavo leggendo","objective_es":"Decir qué estabas haciendo cuando pasó algo.","intro":{"explanation":"Para «estaba haciendo» se usa stavo + gerundio: -are → -ando (camminando), -ere / -ire → -endo (leggendo, dormendo). Mentre (mientras) va con lo que estaba pasando: mentre stavo leggendo…","examples":[{"target":"Stavo camminando in centro.","base":"Estaba caminando por el centro."},{"target":"Mentre ero in autobus, ho visto Marco.","base":"Mientras estaba en el autobús, vi a Marco."}]},"takeaways":["Dices qué estabas haciendo: stavo + -ando / -endo.","Usas mentre para la escena."]},{"id":"it-a2-u05-l03","unit_id":"it-a2-u05","position":4,"title_es":"Pioveva e all'improvviso…","objective_es":"Separar la escena (imperfetto) del hecho (passato prossimo).","intro":{"explanation":"En un relato, el imperfetto pinta la escena: pioveva, faceva freddo, c’era tanta gente. El passato prossimo cuenta lo que pasó: all’improvviso è caduto un albero. Como en español: «llovía y de repente se cayó».","examples":[{"target":"Pioveva quando sono uscita.","base":"Llovía cuando salí."},{"target":"All'improvviso è caduto un albero.","base":"De repente se cayó un árbol."}]},"takeaways":["Usas el imperfetto para la escena y el passato prossimo para el hecho.","Usas all'improvviso para el momento clave."]},{"id":"it-a2-u05-l04","unit_id":"it-a2-u05","position":5,"title_es":"Che figura!","objective_es":"Contar un momento incómodo y sus consecuencias.","intro":{"explanation":"Ojo con el falso amigo: imbarazzato es «avergonzado» o «incómodo» (embarazada se dice incinta). Quindi es «así que, por eso». Y en italiano «hacer el ridículo» es fare una brutta figura: che figura!","examples":[{"target":"Ero così imbarazzata!","base":"¡Estaba tan avergonzada!"},{"target":"Pioveva, quindi sono rimasto a casa.","base":"Llovía, así que me quedé en casa."}]},"takeaways":["Sabes que imbarazzato es «avergonzado».","Unes causa y consecuencia con quindi."]},{"id":"it-a2-u05-l05","unit_id":"it-a2-u05","position":7,"title_es":"Raccontare un fatto","objective_es":"Contar de principio a fin algo que te pasó.","intro":{"explanation":"Un buen relato: la escena en imperfetto (pioveva, stavo leggendo), el hecho en passato prossimo (all’improvviso è successo…), y el final con un conector: per fortuna, quindi, poi.","examples":[{"target":"Mentre stavo leggendo, è arrivato Marco.","base":"Mientras estaba leyendo, llegó Marco."},{"target":"Per fortuna ho trovato le chiavi.","base":"Por suerte encontré las llaves."}]},"takeaways":["Cuentas un hecho con escena, momento clave y final.","Usas mentre, all’improvviso, quindi y per fortuna."]},{"id":"it-a2-u06-l01","unit_id":"it-a2-u06","position":1,"title_es":"Ti va di…?","objective_es":"Invitar a alguien y aceptar una invitación.","intro":{"explanation":"Para invitar: ti va di + infinitivo? (¿tienes ganas de…?) o che ne dici di…? (¿qué te parece…?). Para aceptar: volentieri! (¡con gusto!). Ojo: «invitar a Marco» es invitare Marco, sin a.","examples":[{"target":"Ti va di venire alla festa?","base":"¿Tienes ganas de venir a la fiesta?"},{"target":"Volentieri, grazie!","base":"¡Con gusto, gracias!"}]},"takeaways":["Invitas con ti va di…? y che ne dici di…?","Aceptas con volentieri."]},{"id":"it-a2-u06-l02","unit_id":"it-a2-u06","position":2,"title_es":"Volentieri! Mi dispiace…","objective_es":"Aceptar y rechazar con amabilidad.","intro":{"explanation":"Para aceptar: d’accordo (de acuerdo, vale). Para rechazar: mi dispiace (lo siento), non posso, devo lavorare (tengo que trabajar). Ojo: magari! es «¡ojalá!» (y magari solo, «quizás»).","examples":[{"target":"Mi dispiace, non posso: devo lavorare.","base":"Lo siento, no puedo: tengo que trabajar."},{"target":"Magari! Ma sono a Torino.","base":"¡Ojalá! Pero estoy en Turín."}]},"takeaways":["Rechazas con mi dispiace y devo…","Sabes que magari es «ojalá»."]},{"id":"it-a2-u06-l03","unit_id":"it-a2-u06","position":4,"title_es":"Sabato prossimo, tra due giorni","objective_es":"Arreglar día y hora para encontrarse.","intro":{"explanation":"Prossimo es «que viene»: sabato prossimo, la settimana prossima. Tra (o fra) + tiempo es «dentro de»: tra due giorni. Para despedirse con una cita: ci vediamo alle sette (nos vemos a las siete).","examples":[{"target":"Ci vediamo sabato prossimo.","base":"Nos vemos el sábado que viene."},{"target":"Parto tra due giorni.","base":"Me voy dentro de dos días."}]},"takeaways":["Dices sabato prossimo y tra due giorni.","Arreglas una cita con ci vediamo…"]},{"id":"it-a2-u06-l04","unit_id":"it-a2-u06","position":5,"title_es":"Andrò, farò, sarà","objective_es":"Contar planes con el futuro.","intro":{"explanation":"El futuro semplice: -are / -ere → -erò (parlerò), -ire → -irò (partirò); con noi, -emo (andremo, partiremo). Irregulares frecuentes: andrò, farò, sarò / sarà, verrò. Para planes cercanos también sirve el presente: domani vado al mare.","examples":[{"target":"L’estate prossima andrò in Puglia.","base":"El verano que viene voy a ir a Puglia."},{"target":"Sarà una bella festa.","base":"Va a ser una linda fiesta."}]},"takeaways":["Usas andrò, farò, sarà y verrò.","Cuentas planes de las vacaciones."]},{"id":"it-a2-u06-l05","unit_id":"it-a2-u06","position":7,"title_es":"Un aperitivo? D'accordo!","objective_es":"Organizar una salida de principio a fin.","intro":{"explanation":"En Italia, l’aperitivo es una costumbre: después del trabajo se toma algo con picoteo antes de cenar, como nuestra previa. Para organizar: propones (che ne dici…?), arreglas (ci vediamo alle…) y confirmas (d’accordo!).","examples":[{"target":"Che ne dici di un aperitivo?","base":"¿Qué te parece un aperitivo?"},{"target":"D'accordo, alle sette!","base":"¡De acuerdo, a las siete!"}]},"takeaways":["Organizas una salida: propones, arreglas y confirmas.","Conoces la costumbre del aperitivo."]},{"id":"it-a2-u07-l01","unit_id":"it-a2-u07","position":1,"title_es":"Sto studiando","objective_es":"Decir qué estás haciendo en este momento.","intro":{"explanation":"Para «estoy haciendo» se usa stare en presente + gerundio: sto studiando, sta lavorando. Es como en español, pero se usa un poco menos: muchas veces alcanza el presente (studio all’università).","examples":[{"target":"Sto studiando per un esame.","base":"Estoy estudiando para un examen."},{"target":"Mia sorella sta lavorando.","base":"Mi hermana está trabajando."}]},"takeaways":["Dices qué estás haciendo: sto + -ando / -endo.","Hablas de la universidad y los exámenes."]},{"id":"it-a2-u07-l02","unit_id":"it-a2-u07","position":2,"title_es":"Da due anni","objective_es":"Decir desde hace cuánto haces algo.","intro":{"explanation":"Para algo que empezó antes y sigue ahora: presente + da + tiempo. Lavoro qui da due anni = trabajo aquí desde hace dos años. Ojo: con algo terminado se usa fa (sono arrivato due anni fa). Attualmente es «actualmente, en este momento».","examples":[{"target":"Studio italiano da due anni.","base":"Estudio italiano desde hace dos años."},{"target":"Attualmente lavoro in un negozio.","base":"Actualmente trabajo en una tienda."}]},"takeaways":["Dices desde cuándo: presente + da.","Distingues da due anni de due anni fa."]},{"id":"it-a2-u07-l03","unit_id":"it-a2-u07","position":4,"title_es":"Il colloquio e lo stipendio","objective_es":"Entender un aviso y una entrevista de trabajo.","intro":{"explanation":"El vocabulario del trabajo: il colloquio es la entrevista (no un «coloquio»), lo stipendio es el sueldo, l’orario es el horario y il capo, el jefe o la jefa. En los avisos vas a leer cercasi (se busca).","examples":[{"target":"Domani ho un colloquio.","base":"Mañana tengo una entrevista."},{"target":"Lo stipendio è buono.","base":"El sueldo es bueno."}]},"takeaways":["Sabes que colloquio es «entrevista».","Entiendes un aviso de trabajo."]},{"id":"it-a2-u07-l04","unit_id":"it-a2-u07","position":5,"title_es":"Devi, dobbiamo, può","objective_es":"Decir lo que tienes que hacer y lo que se puede.","intro":{"explanation":"Dovere (tener que): devo, devi, deve, dobbiamo, dovete, devono. Potere: posso, puoi, può, possiamo, potete, possono. Van con infinitivo: dobbiamo finire, può venire.","examples":[{"target":"Dobbiamo finire oggi.","base":"Tenemos que terminar hoy."},{"target":"Il capo può venire domani?","base":"¿El jefe puede venir mañana?"}]},"takeaways":["Conjugas dovere y potere.","Hablas de tus compañeros y tu jefe."]},{"id":"it-a2-u07-l05","unit_id":"it-a2-u07","position":7,"title_es":"Mi sono laureato","objective_es":"Hablar de tus estudios y de lo que haces hoy.","intro":{"explanation":"La laurea es el título universitario; laurearsi es recibirse: mi sono laureato / laureata (me recibí). Para presentarte en lo profesional: mi sono laureato in…, attualmente lavoro…, da…","examples":[{"target":"Mi sono laureata due anni fa.","base":"Me recibí hace dos años."},{"target":"Ho una laurea in economia.","base":"Tengo un título en economía."}]},"takeaways":["Dices que te recibiste: mi sono laureato / laureata.","Te presentas en lo profesional."]},{"id":"it-a2-u08-l01","unit_id":"it-a2-u08","position":1,"title_es":"Mi fa male","objective_es":"Decir qué te duele.","intro":{"explanation":"Para decir qué te duele: mi fa male + la parte del cuerpo con artículo (mi fa male la schiena) o ho mal di + la parte sin artículo (ho mal di testa, ho mal di gola).","examples":[{"target":"Mi fa male la pancia.","base":"Me duele la panza."},{"target":"Ho mal di testa da ieri.","base":"Me duele la cabeza desde ayer."}]},"takeaways":["Dices mi fa male la… y ho mal di…","Nombras la gola, la pancia y la schiena."]},{"id":"it-a2-u08-l02","unit_id":"it-a2-u08","position":2,"title_es":"Dal medico","objective_es":"Contar tus síntomas en el consultorio.","intro":{"explanation":"Los síntomas van con avere y artículo: ho la febbre, ho la tosse, ho il raffreddore. Al médico se va con da (y no con a): vado dal medico, come vado da Marco.","examples":[{"target":"Ho la febbre e la tosse.","base":"Tengo fiebre y tos."},{"target":"Domani vado dal medico.","base":"Mañana voy al médico."}]},"takeaways":["Cuentas síntomas: ho la febbre, la tosse.","Dices vado dal medico."]},{"id":"it-a2-u08-l03","unit_id":"it-a2-u08","position":4,"title_es":"Prenda, beva","objective_es":"Entender las indicaciones del médico y de la farmacia.","intro":{"explanation":"El médico y el farmacéutico te tratan de Lei y dan indicaciones con el imperativo formal: con los verbos en -ere / -ire termina en -a (prenda, beva) y con los de -are, en -i (mangi). La ricetta es la receta del médico (y también la de cocina).","examples":[{"target":"Prenda questo sciroppo tre volte al giorno.","base":"Tome este jarabe tres veces por día."},{"target":"Ha la ricetta del medico?","base":"¿Tiene la receta del médico?"}]},"takeaways":["Entiendes prenda y beva.","Pides algo en la farmacia."]},{"id":"it-a2-u08-l04","unit_id":"it-a2-u08","position":5,"title_es":"Riposati! Non mangiare!","objective_es":"Dar consejos a un amigo con el imperativo.","intro":{"explanation":"Con tu: -are → -a (mangia), -ere / -ire → -i (prendi, bevi, dormi). En negativo: non + infinitivo (non mangiare!, non uscire!). Con un reflexivo, el pronombre va pegado al final: riposati! (descansa).","examples":[{"target":"Riposati e bevi tanto tè.","base":"Descansa y toma mucho té."},{"target":"Non mangiare troppo!","base":"¡No comas demasiado!"}]},"takeaways":["Aconsejas con prendi, bevi, riposati.","Prohíbes con non + infinitivo."]},{"id":"it-a2-u08-l05","unit_id":"it-a2-u08","position":7,"title_es":"Sto meglio","objective_es":"Decir que estás mejor y entender consejos para estar bien.","intro":{"explanation":"Cuando te recuperas: sto meglio (estoy mejor). Los carteles y las revistas dan consejos con el imperativo con tu: dormi, mangia, cammina, fai una pausa.","examples":[{"target":"Oggi sto meglio, grazie.","base":"Hoy estoy mejor, gracias."},{"target":"Bevi molta acqua e riposati.","base":"Toma mucha agua y descansa."}]},"takeaways":["Dices sto meglio.","Entiendes consejos de salud con el imperativo."]},{"id":"it-a2-u09-l01","unit_id":"it-a2-u09","position":1,"title_es":"Più caro, meno caro","objective_es":"Comparar con più y meno.","intro":{"explanation":"Para comparar: più (más) o meno (menos) + adjetivo + di: Roma è più grande di Firenze. Di se une al artículo: meno caro del supermercato (di + il).","examples":[{"target":"Roma è più grande di Firenze.","base":"Roma es más grande que Florencia."},{"target":"Il mercato è meno caro del supermercato.","base":"El mercado es menos caro que el súper."}]},"takeaways":["Comparas con più / meno … di.","Unes di con el artículo: del, della."]},{"id":"it-a2-u09-l02","unit_id":"it-a2-u09","position":2,"title_es":"Il migliore, bellissimo","objective_es":"Decir cuál es el mejor, el peor o el más.","intro":{"explanation":"Mejor y peor como adjetivo: migliore y peggiore (il caffè migliore della città). Para «el más»: il più / la più + adjetivo (la città più bella). Y para «muy, muy»: -issimo (bellissimo, carissimo).","examples":[{"target":"È il ristorante migliore della città.","base":"Es el mejor restaurante de la ciudad."},{"target":"La giacca è bellissima!","base":"¡La chaqueta es hermosísima!"}]},"takeaways":["Usas migliore y peggiore.","Dices il più… y -issimo."]},{"id":"it-a2-u09-l03","unit_id":"it-a2-u09","position":4,"title_es":"Posso provare?","objective_es":"Comprar ropa: talla y probador.","intro":{"explanation":"En una tienda de ropa: posso provare…? (¿puedo probarme…?), che taglia porta? (¿qué talla usa?) e il camerino (el probador). I pantaloni va en plural, como en español «los pantalones».","examples":[{"target":"Posso provare questi pantaloni?","base":"¿Puedo probarme este pantalón?"},{"target":"Il camerino è lì, a destra.","base":"El probador está ahí, a la derecha."}]},"takeaways":["Pides probarte algo con posso provare…?","Entiendes che taglia porta?"]},{"id":"it-a2-u09-l04","unit_id":"it-a2-u09","position":5,"title_es":"Sconti e saldi","objective_es":"Entender descuentos y liquidaciones.","intro":{"explanation":"Lo sconto es el descuento: lo sconto del venti per cento. I saldi son las liquidaciones de fin de temporada (en Italia, en enero y en julio). Ojo: no tienen nada que ver con el saldo de una cuenta.","examples":[{"target":"Oggi c’è lo sconto del venti per cento.","base":"Hoy hay un descuento del veinte por ciento."},{"target":"A luglio ci sono i saldi.","base":"En julio hay liquidaciones."}]},"takeaways":["Entiendes lo sconto y i saldi.","Lees un cartel de liquidación."]},{"id":"it-a2-u09-l05","unit_id":"it-a2-u09","position":7,"title_es":"Al mercato: ne prendo tre","objective_es":"Pedir cantidades en el mercado y usar ne.","intro":{"explanation":"En el mercado se pide un chilo (un kilo) o un etto (cien gramos): due etti di prosciutto. Ne reemplaza una cantidad de algo que ya se nombró: Quante mele vuole? — Ne prendo tre (llevo tres). También: Quanti anni hai? — Ne ho venti.","examples":[{"target":"Vorrei un chilo di pomodori.","base":"Quisiera un kilo de tomates."},{"target":"Quante mele vuole? — Ne prendo tre.","base":"¿Cuántas manzanas quiere? — Llevo tres."}]},"takeaways":["Pides por chilo y por etto.","Usas ne con una cantidad."]},{"id":"it-a2-u10-l01","unit_id":"it-a2-u10","position":1,"title_es":"Il cellulare","objective_es":"Nombrar el celular, la compu y la batería.","intro":{"explanation":"En Italia el celular es il cellulare (también il telefonino). La notebook es il portatile. Caricare es «cargar» (la batería) y la batteria scarica es la batería descargada.","examples":[{"target":"Il cellulare non ha batteria.","base":"El celular no tiene batería."},{"target":"Devo caricare il cellulare.","base":"Tengo que cargar el celular."}]},"takeaways":["Nombras il cellulare, il portatile y la batteria.","Dices que tienes que cargar el celular."]},{"id":"it-a2-u10-l02","unit_id":"it-a2-u10","position":2,"title_es":"Mandare, rispondere","objective_es":"Mandar y responder mensajes y llamadas.","intro":{"explanation":"Mandare un messaggio (mandar un mensaje), rispondere (responder), una chiamata (una llamada) y una videochiamata. Scaricare es «descargar»: scaricare un’app.","examples":[{"target":"Devo mandare una mail al capo.","base":"Tengo que mandarle un mail al jefe."},{"target":"Ho fatto una videochiamata con mia nonna.","base":"Hice una videollamada con mi abuela."}]},"takeaways":["Usas mandare, rispondere y scaricare.","Hablas de llamadas y videollamadas."]},{"id":"it-a2-u10-l03","unit_id":"it-a2-u10","position":4,"title_es":"Ti chiamo, ti scrivo","objective_es":"Usar mi y ti para quedar en contacto.","intro":{"explanation":"Los pronombres van antes del verbo: ti chiamo (te llamo), ti scrivo (te escribo), mi mandi un messaggio? (¿me mandas un mensaje?). Ojo: ti chiamo es «te llamo», no «te llamas» (ti chiami).","examples":[{"target":"Ti chiamo stasera, va bene?","base":"Te llamo esta noche, ¿está bien?"},{"target":"Mi mandi un messaggio?","base":"¿Me mandas un mensaje?"}]},"takeaways":["Dices ti chiamo y ti scrivo.","Pides mi mandi…?"]},{"id":"it-a2-u10-l04","unit_id":"it-a2-u10","position":5,"title_es":"Lo vedo, la chiamo","objective_es":"Reemplazar a una persona o una cosa con lo y la.","intro":{"explanation":"Para no repetir: lo (a él o algo masculino) y la (a ella o algo femenino), antes del verbo. Vedi Marco? — Sì, lo vedo. Chiami Anna? — La chiamo subito. Il portatile? Lo porto io.","examples":[{"target":"Vedi Marco oggi? — Sì, lo vedo alle cinque.","base":"¿Ves a Marco hoy? — Sí, lo veo a las cinco."},{"target":"Chiami Anna? — Sì, la chiamo subito.","base":"¿Llamas a Anna? — Sí, la llamo enseguida."}]},"takeaways":["Usas lo y la antes del verbo.","Entiendes indicaciones en la oficina."]},{"id":"it-a2-u10-l05","unit_id":"it-a2-u10","position":7,"title_es":"Gli scrivo, le telefono","objective_es":"Usar gli y le para decir a quién.","intro":{"explanation":"Para «a quién»: gli (a él) y le (a ella). Gli scrivo es «le escribo» a un hombre; le telefono, «le hablo por teléfono» a una mujer. Ojo: telefonare a va con gli / le (le telefono), pero chiamare va con lo / la (la chiamo).","examples":[{"target":"Scrivi a Marco? — Sì, gli scrivo stasera.","base":"¿Le escribes a Marco? — Sí, le escribo esta noche."},{"target":"Le telefono domani mattina.","base":"La llamo mañana a la mañana."}]},"takeaways":["Usas gli para él y le para ella.","Distingues la chiamo de le telefono."]},{"id":"it-a2-u11-l01","unit_id":"it-a2-u11","position":1,"title_es":"Ti alzi, si alza","objective_es":"Conjugar los reflexivos para contar la rutina de otros.","intro":{"explanation":"Los reflexivos cambian el pronombre con cada persona: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Igual con lavarsi y vestirsi: mi lavo, mi vesto.","examples":[{"target":"A che ora ti alzi?","base":"¿A qué hora te levantas?"},{"target":"Mio padre si alza alle sei.","base":"Mi papá se levanta a las seis."}]},"takeaways":["Conjugas los reflexivos: ti alzi, si alza, ci alziamo.","Cuentas la rutina de la mañana."]},{"id":"it-a2-u11-l02","unit_id":"it-a2-u11","position":2,"title_es":"Presto, tardi, spesso","objective_es":"Decir cuándo y cada cuánto haces algo.","intro":{"explanation":"Presto es «temprano» (y a presto, «hasta pronto»); tardi, «tarde». Para la frecuencia: sempre, spesso (seguido; no «espeso»), qualche volta (a veces), non… mai (nunca): non vado mai al cinema.","examples":[{"target":"Torno a casa tardi.","base":"Vuelvo tarde a casa."},{"target":"Qualche volta vado al mare.","base":"A veces voy al mar."}]},"takeaways":["Dices presto y tardi.","Dices cada cuánto: sempre, spesso, qualche volta, mai."]},{"id":"it-a2-u11-l03","unit_id":"it-a2-u11","position":4,"title_es":"Mi sono alzata tardi","objective_es":"Contar tu mañana con los reflexivos en pasado.","intro":{"explanation":"Los reflexivos forman el pasado con essere, y el participio concuerda: mi sono alzato (él), mi sono alzata (ella), ci siamo alzati. Mi sono vestito, si è lavata…","examples":[{"target":"Stamattina mi sono alzata tardi.","base":"Esta mañana me levanté tarde."},{"target":"Ci siamo alzati alle otto.","base":"Nos levantamos a las ocho."}]},"takeaways":["Cuentas tu mañana: mi sono alzato / alzata.","Haces concordar el participio."]},{"id":"it-a2-u11-l04","unit_id":"it-a2-u11","position":5,"title_es":"Ci siamo conosciuti","objective_es":"Contar cómo se conoció una pareja.","intro":{"explanation":"Con ci y si se dice lo que hacen dos personas entre sí: ci siamo conosciuti (nos conocimos), si sono sposati (se casaron). Il fidanzato / la fidanzata es el novio o la novia (también el prometido); il marito y la moglie, el marido y la esposa.","examples":[{"target":"Ci siamo conosciuti a una festa.","base":"Nos conocimos en una fiesta."},{"target":"I miei genitori si sono sposati a Roma.","base":"Mis papás se casaron en Roma."}]},"takeaways":["Cuentas cómo se conocieron: ci siamo conosciuti.","Nombras fidanzato, marito y moglie."]},{"id":"it-a2-u11-l05","unit_id":"it-a2-u11","position":7,"title_es":"Ci vado spesso","objective_es":"Usar ci para no repetir un lugar.","intro":{"explanation":"Ci reemplaza un lugar ya nombrado: Vai in palestra? — Sì, ci vado tre volte a settimana. Y con amigos: ci sentiamo (hablamos más tarde) y ci vediamo (nos vemos).","examples":[{"target":"Vai in palestra? — Sì, ci vado spesso.","base":"¿Vas al gimnasio? — Sí, voy seguido."},{"target":"Ci sentiamo stasera!","base":"¡Hablamos esta noche!"}]},"takeaways":["Usas ci en vez de repetir el lugar.","Te despides con ci sentiamo."]},{"id":"it-a2-u12-l01","unit_id":"it-a2-u12","position":1,"title_es":"Secondo me","objective_es":"Dar tu opinión y decir si estás de acuerdo.","intro":{"explanation":"Para opinar: secondo me (para mí), penso di sì / penso di no (creo que sí / que no). Para responder: sono d’accordo o non sono d’accordo. Invece es «en cambio».","examples":[{"target":"Non sono d'accordo con te.","base":"No estoy de acuerdo contigo."},{"target":"Secondo me è una bella idea.","base":"Para mí es una buena idea."}]},"takeaways":["Opinas con secondo me y penso di sì.","Dices sono d'accordo / non sono d'accordo."]},{"id":"it-a2-u12-l02","unit_id":"it-a2-u12","position":2,"title_es":"Mi piacerebbe, preferirei","objective_es":"Expresar deseos con el condizionale.","intro":{"explanation":"El condizionale expresa deseos de forma suave: mi piacerebbe (me gustaría), preferirei (preferiría), vorrei (quisiera), sarebbe (sería). Purtroppo (lamentablemente) es lo contrario de per fortuna.","examples":[{"target":"Mi piacerebbe vivere in Italia.","base":"Me gustaría vivir en Italia."},{"target":"Purtroppo adesso non posso.","base":"Lamentablemente ahora no puedo."}]},"takeaways":["Expresas deseos con mi piacerebbe y preferirei.","Usas purtroppo."]},{"id":"it-a2-u12-l03","unit_id":"it-a2-u12","position":4,"title_es":"Dovresti…","objective_es":"Dar consejos con dovresti y sarebbe meglio.","intro":{"explanation":"Para aconsejar con suavidad: dovresti + infinitivo (deberías) o sarebbe meglio + infinitivo (sería mejor). Comunque es «de todos modos, igual». Sensibile es como en español: una persona sensibile se ofende o se emociona fácil.","examples":[{"target":"Secondo me dovresti parlare con il capo.","base":"Para mí deberías hablar con el jefe."},{"target":"Comunque prova!","base":"¡Igual prueba!"}]},"takeaways":["Aconsejas con dovresti y sarebbe meglio.","Usas comunque."]},{"id":"it-a2-u12-l04","unit_id":"it-a2-u12","position":5,"title_es":"Non funziona!","objective_es":"Explicar un problema con algo que compraste.","intro":{"explanation":"Para un problema: non funziona (no anda), si è rotto / si è rotta (se rompió; el participio concuerda con la cosa). Para pedir una solución: vorrei cambiare… (quisiera cambiar…).","examples":[{"target":"Il mio cellulare si è rotto.","base":"Se me rompió el celular."},{"target":"Vorrei cambiare la giacca.","base":"Quisiera cambiar la chaqueta."}]},"takeaways":["Dices non funziona y si è rotto / rotta.","Pides cambiar algo."]},{"id":"it-a2-u12-l05","unit_id":"it-a2-u12","position":7,"title_es":"Lo scontrino e il rimborso","objective_es":"Resolver un reclamo y opinar sobre costumbres.","intro":{"explanation":"Lo scontrino es el ticket de compra (no un «descuento», que es lo sconto). Con el ticket puedes pedir il rimborso (que te devuelvan el dinero) o cambiare il prodotto. Para elegir con cortesía: preferirei…","examples":[{"target":"Ha lo scontrino?","base":"¿Tiene el ticket?"},{"target":"Preferirei il rimborso, grazie.","base":"Preferiría el reembolso, gracias."}]},"takeaways":["Pides il rimborso o cambiar algo.","Distingues lo scontrino de lo sconto."]},{"id":"zh-a1-u13-l01","unit_id":"zh-a1-u13","position":1,"title_es":"你们和他们","objective_es":"Hablar de varias personas con 们 y 都.","intro":{"explanation":"们 hace el plural de los pronombres: 我们 (nosotros), 你们 (ustedes), 他们 (ellos). 都 significa «todos» o «los dos» y va antes del verbo: 我们都是学生.","examples":[{"target":"你们是学生吗？","base":"¿Ustedes son estudiantes?"},{"target":"他们都是老师。","base":"Todos ellos son profesores."}]},"takeaways":["Usas 我们, 你们 y 他们.","Dices «todos» con 都, antes del verbo."]},{"id":"zh-a1-u13-l02","unit_id":"zh-a1-u13","position":2,"title_es":"你做什么工作？","objective_es":"Preguntar y decir de qué trabaja alguien.","intro":{"explanation":"做 es «hacer». Para preguntar el trabajo se dice 你做什么工作？ y se responde con 是 + profesión: 我是医生. Las profesiones no cambian en femenino: 医生 es médico y médica.","examples":[{"target":"你做什么工作？——我是护士。","base":"¿De qué trabajas? — Soy enfermera."},{"target":"我爸爸是司机。","base":"Mi papá es chofer."}]},"takeaways":["Preguntas el trabajo con 你做什么工作？","Dices profesiones con 是: 我是医生."]},{"id":"zh-a1-u13-l03","unit_id":"zh-a1-u13","position":4,"title_es":"在哪里工作？","objective_es":"Decir dónde trabaja o estudia alguien.","intro":{"explanation":"El lugar va con 在 y antes del verbo: 我在医院工作 («yo en el hospital trabajo»). 哪里 es «dónde», igual que 哪儿 (más común en el norte de China): 你在哪里工作？","examples":[{"target":"我在公司工作。","base":"Trabajo en una empresa."},{"target":"你在哪里工作？——我在大学工作。","base":"¿Dónde trabajas? — En la universidad."}]},"takeaways":["Dices dónde trabajas con 在 + lugar + 工作.","Preguntas «dónde» con 哪里."]},{"id":"zh-a1-u13-l04","unit_id":"zh-a1-u13","position":5,"title_es":"你会说英语吗？","objective_es":"Decir qué idiomas hablas y cuánto.","intro":{"explanation":"会 + 说 + idioma es «saber hablar un idioma». 语 significa «idioma»: 英语 (inglés), 西班牙语 (español). 一点儿 (un poco) va antes del idioma: 我会说一点儿中文.","examples":[{"target":"你会说英语吗？——会，我会说一点儿。","base":"¿Hablas inglés? — Sí, un poco."},{"target":"我会说西班牙语。","base":"Hablo español."}]},"takeaways":["Dices qué idiomas hablas con 会说.","Matizas con 一点儿 (un poco)."]},{"id":"zh-a1-u13-l05","unit_id":"zh-a1-u13","position":7,"title_es":"认识你很高兴","objective_es":"Presentarte y entender una presentación.","intro":{"explanation":"认识 es «conocer» a una persona. Al presentarte se dice 认识你很高兴 («conocerte me pone contento»). 同学 es el compañero o la compañera de clase.","examples":[{"target":"认识你很高兴！","base":"¡Encantado de conocerte!"},{"target":"他是我的同学。","base":"Él es mi compañero de clase."}]},"takeaways":["Te presentas con 认识你很高兴.","Entiendes de qué trabaja alguien en una charla."]},{"id":"zh-a1-u14-l01","unit_id":"zh-a1-u14","position":1,"title_es":"颜色","objective_es":"Nombrar colores y decir de qué color es algo.","intro":{"explanation":"Los colores terminan en 色 (color): 红色, 白色, 黑色, 蓝色. Para decir el color de algo: 是 + color + 的. Con 的 el color funciona como sustantivo: 我要红色的 (quiero el rojo).","examples":[{"target":"我的手机是黑色的。","base":"Mi celular es negro."},{"target":"我要红色的。","base":"Quiero el rojo."}]},"takeaways":["Nombras cuatro colores.","Dices de qué color es algo con 是…的."]},{"id":"zh-a1-u14-l02","unit_id":"zh-a1-u14","position":2,"title_es":"新、旧、长、短","objective_es":"Describir cosas y quejarte con 有点儿.","intro":{"explanation":"新 (nuevo) y 旧 (viejo, usado: sólo para cosas). 长 (largo) y 短 (corto). 有点儿 + adjetivo es «medio…» y suena a queja: 有点儿长 (medio largo, más de lo que quiero).","examples":[{"target":"我的手机很旧。","base":"Mi celular es muy viejo."},{"target":"这件衣服有点儿长。","base":"Esta ropa es medio larga."}]},"takeaways":["Describes cosas con 新, 旧, 长 y 短.","Te quejas con 有点儿 + adjetivo."]},{"id":"zh-a1-u14-l03","unit_id":"zh-a1-u14","position":4,"title_es":"高和矮","objective_es":"Describir cómo es una persona.","intro":{"explanation":"高 (alto) y 矮 (bajo, de estatura). Para el pelo y los ojos se dice persona + 头发 / 眼睛 + adjetivo: 她头发很长 («ella, el pelo muy largo»). 长 es para cosas largas como el pelo; para la estatura se usa 高.","examples":[{"target":"我哥哥很高。","base":"Mi hermano mayor es alto."},{"target":"她头发很长，眼睛很大。","base":"Tiene el pelo largo y los ojos grandes."}]},"takeaways":["Dices si alguien es alto o bajo.","Describes el pelo y los ojos."]},{"id":"zh-a1-u14-l04","unit_id":"zh-a1-u14","position":5,"title_es":"比","objective_es":"Comparar dos cosas o personas con 比.","intro":{"explanation":"Para comparar: A + 比 + B + adjetivo. 我比你高 es «soy más alto que tú». Con 比 el adjetivo va solo: 我比你很高 está mal.","examples":[{"target":"我比我哥哥高。","base":"Soy más alto que mi hermano mayor."},{"target":"白色的比红色的便宜。","base":"El blanco es más barato que el rojo."}]},"takeaways":["Comparas con A 比 B + adjetivo.","No usas 很 en una comparación con 比."]},{"id":"zh-a1-u14-l05","unit_id":"zh-a1-u14","position":7,"title_es":"跟…一样","objective_es":"Decir que dos cosas son iguales y entender una descripción.","intro":{"explanation":"A 跟 B 一样 es «A es igual a B». Con un adjetivo: 我跟你一样高 (soy tan alto como tú). 跟 también es «con»: 我跟朋友去超市.","examples":[{"target":"我的包跟你的一样。","base":"Mi bolso es igual al tuyo."},{"target":"我跟我哥哥一样高。","base":"Soy tan alto como mi hermano mayor."}]},"takeaways":["Dices que algo es igual con 跟…一样.","Entiendes cómo describen a una persona."]},{"id":"zh-a1-u15-l01","unit_id":"zh-a1-u15","position":1,"title_es":"年、月、号","objective_es":"Decir fechas completas y hablar de años.","intro":{"explanation":"La fecha va de lo grande a lo chico: año (年), mes (月), día (号). El año se lee cifra por cifra: 2026年 es «èr líng èr liù nián». 去年 es el año pasado y 明年, el año que viene.","examples":[{"target":"今天是十月五号。","base":"Hoy es 5 de octubre."},{"target":"我明年去北京。","base":"El año que viene voy a Pekín."}]},"takeaways":["Dices la fecha en orden: año, mes, día.","Usas 去年, 今年 y 明年."]},{"id":"zh-a1-u15-l02","unit_id":"zh-a1-u15","position":2,"title_es":"生日快乐！","objective_es":"Decir tu cumpleaños, saludar y contar un cambio con 了.","intro":{"explanation":"生日 es «cumpleaños» y se saluda con 生日快乐！ 了 al final de la oración marca un cambio de situación: 我二十岁了 (ya tengo veinte, antes no).","examples":[{"target":"生日快乐！","base":"¡Feliz cumpleaños!"},{"target":"我今天二十岁了。","base":"Hoy cumplo veinte años."}]},"takeaways":["Dices cuándo es tu cumpleaños.","Marcas un cambio con 了 al final."]},{"id":"zh-a1-u15-l03","unit_id":"zh-a1-u15","position":4,"title_es":"天气怎么样？","objective_es":"Preguntar y decir qué tiempo hace.","intro":{"explanation":"Para preguntar por el clima: 天气怎么样？ Se responde con un adjetivo: 很冷, 很热 (no hace falta un verbo «hacer»). 下雨 es llover y 下雨了, «se puso a llover». 晴天 es un día de sol.","examples":[{"target":"今天天气怎么样？——很热。","base":"¿Qué tiempo hace hoy? — Mucho calor."},{"target":"下雨了！","base":"¡Se puso a llover!"}]},"takeaways":["Preguntas por el clima con 天气怎么样？","Dices frío, calor, sol y lluvia."]},{"id":"zh-a1-u15-l04","unit_id":"zh-a1-u15","position":5,"title_es":"春夏秋冬","objective_es":"Hablar de las estaciones.","intro":{"explanation":"Las estaciones terminan en 天: 春天, 夏天, 秋天, 冬天. Ojo con el hemisferio: en Pekín el verano es en junio, julio y agosto, y en la Argentina, en diciembre, enero y febrero.","examples":[{"target":"北京的冬天很冷。","base":"El invierno en Pekín es muy frío."},{"target":"我喜欢秋天。","base":"Me gusta el otoño."}]},"takeaways":["Nombras las cuatro estaciones.","Cuentas cómo es el clima en cada una."]},{"id":"zh-a1-u15-l05","unit_id":"zh-a1-u15","position":7,"title_es":"中午","objective_es":"Ubicar actividades en el día y entender mensajes sobre el clima y un cumpleaños.","intro":{"explanation":"中午 es el mediodía. Las palabras de tiempo van antes del verbo, al principio o después de la persona: 中午我在家吃饭 o 我中午在家吃饭.","examples":[{"target":"中午我在家吃饭。","base":"Al mediodía como en casa."},{"target":"明天中午很热。","base":"Mañana al mediodía hace mucho calor."}]},"takeaways":["Usas 中午 y otras palabras de tiempo antes del verbo.","Entiendes un mensaje y una charla sobre el clima."]},{"id":"zh-a1-u16-l01","unit_id":"zh-a1-u16","position":1,"title_es":"在公园旁边","objective_es":"Decir dónde está un lugar.","intro":{"explanation":"左边 (izquierda), 右边 (derecha), 旁边 (al lado). Para ubicar algo: cosa + 在 + lugar + 旁边 / 左边: 银行在公园旁边 («el banco está al lado del parque»).","examples":[{"target":"银行在公园旁边。","base":"El banco está al lado del parque."},{"target":"超市在银行左边。","base":"El súper está a la izquierda del banco."}]},"takeaways":["Ubicas lugares con 左边, 右边 y 旁边.","Nombras el banco y el parque."]},{"id":"zh-a1-u16-l02","unit_id":"zh-a1-u16","position":2,"title_es":"一直走","objective_es":"Dar y entender indicaciones.","intro":{"explanation":"一直走 es «sigue derecho». 往 + dirección + 走 es «ve hacia»: 往左走 (dobla a la izquierda). 前面 es adelante y 后面, atrás: 火车站在前面.","examples":[{"target":"一直走，然后往右走。","base":"Sigue derecho y después dobla a la derecha."},{"target":"火车站在前面。","base":"La estación de tren está adelante."}]},"takeaways":["Indicas el camino con 一直走 y 往左 / 往右走.","Usas 前面 y 后面."]},{"id":"zh-a1-u16-l03","unit_id":"zh-a1-u16","position":4,"title_es":"我可以…吗？","objective_es":"Pedir y dar permiso; viajar en avión.","intro":{"explanation":"可以 es «poder» en el sentido de tener permiso: 我可以坐这儿吗？ (¿me puedo sentar aquí?). 不可以 es «no se puede». 能 (U11) es poder porque hay tiempo o capacidad.","examples":[{"target":"我可以坐这儿吗？——可以。","base":"¿Me puedo sentar aquí? — Sí."},{"target":"这儿不可以吃东西。","base":"Aquí no se puede comer."}]},"takeaways":["Pides permiso con 我可以…吗？","Dices que algo no se puede con 不可以."]},{"id":"zh-a1-u16-l04","unit_id":"zh-a1-u16","position":5,"title_es":"一起…吧！","objective_es":"Proponer un plan.","intro":{"explanation":"吧 al final convierte la frase en una propuesta: 我们走吧 (vamos). 一起 es «juntos» y va antes del verbo: 我们一起去吧！ Con 吗 sería una pregunta; con 吧, una invitación.","examples":[{"target":"我们一起去公园吧！","base":"¡Vamos juntos al parque!"},{"target":"我们走吧。","base":"Vamos."}]},"takeaways":["Propones planes con 吧.","Dices «juntos» con 一起, antes del verbo."]},{"id":"zh-a1-u16-l05","unit_id":"zh-a1-u16","position":7,"title_es":"我去了… / 我没去","objective_es":"Contar lo que hiciste y lo que no hiciste.","intro":{"explanation":"了 después del verbo cuenta una acción terminada: 我买了一件衣服 (compré una prenda). El pasado se niega con 没, sin 了: 我没去 (no fui). 不去 es «no voy» (presente o costumbre).","examples":[{"target":"我昨天去了超市。","base":"Ayer fui al súper."},{"target":"我没去银行。","base":"No fui al banco."}]},"takeaways":["Cuentas algo que hiciste con verbo + 了.","Lo niegas con 没, sin 了."]},{"id":"zh-a2-u01-l01","unit_id":"zh-a2-u01","position":1,"title_es":"周末做什么了？","objective_es":"Contar qué hiciste el fin de semana.","intro":{"explanation":"Para contar qué hiciste se pone 了 después del verbo o al final: 我休息了. Si el objeto lleva número, 了 va pegado al verbo: 我看了两个电影. 上个星期 es la semana pasada.","examples":[{"target":"周末你做什么了？——我休息了。","base":"¿Qué hiciste el fin de semana? — Descansé."},{"target":"上个星期我看了两个电影。","base":"La semana pasada vi dos películas."}]},"takeaways":["Cuentas lo que hiciste con 了.","Nombras actividades del tiempo libre."]},{"id":"zh-a2-u01-l02","unit_id":"zh-a2-u01","position":2,"title_es":"打扫和洗衣服","objective_es":"Contar tareas de la casa y de la escuela.","intro":{"explanation":"打扫 es limpiar (la casa, el cuarto) y 洗, lavar: 洗衣服. «Hacer la tarea» se dice 写作业 (escribir la tarea). El pasado se niega con 没: 我没写作业.","examples":[{"target":"我打扫了房间。","base":"Limpié el cuarto."},{"target":"我昨天没写作业。","base":"Ayer no hice la tarea."}]},"takeaways":["Cuentas tareas de la casa con 打扫 y 洗.","Dices «hacer la tarea» con 写作业."]},{"id":"zh-a2-u01-l03","unit_id":"zh-a2-u01","position":4,"title_es":"已经 y 还没","objective_es":"Decir qué ya hiciste y qué todavía no.","intro":{"explanation":"已经…了 es «ya»: 我已经吃饭了. «Todavía no» es 还没 + verbo, y se puede cerrar con 呢: 我还没写作业呢 (con 还没 nunca va 了). 刚才 es «hace un rato».","examples":[{"target":"我已经吃饭了。","base":"Ya comí."},{"target":"我还没写作业呢。","base":"Todavía no hice la tarea."}]},"takeaways":["Dices «ya» con 已经…了.","Dices «todavía no» con 还没…呢."]},{"id":"zh-a2-u01-l04","unit_id":"zh-a2-u01","position":5,"title_es":"早、晚、回、见面","objective_es":"Hablar de horarios y de encuentros.","intro":{"explanation":"回 es volver: 回家. 早 es temprano y 晚, tarde: 我很晚回家. 见面 es verse con alguien y no lleva objeto: se dice 跟朋友见面, no «见面朋友».","examples":[{"target":"我昨天很晚回家。","base":"Ayer volví tarde a casa."},{"target":"我们明天见面吧！","base":"¡Veámonos mañana!"}]},"takeaways":["Dices cuándo vuelves con 回家, 早 y 晚.","Quedas para verte con 见面."]},{"id":"zh-a2-u01-l05","unit_id":"zh-a2-u01","position":7,"title_es":"好玩吗？","objective_es":"Entender relatos y mensajes sobre lo que alguien hizo.","intro":{"explanation":"Repasa cómo se cuenta el pasado: verbo + 了, 没 + verbo, 已经…了 y 还没…呢. 好玩 es «divertido»: 爬山很好玩.","examples":[{"target":"爬山很好玩！","base":"¡Ir a la montaña es muy divertido!"},{"target":"作业还没写呢。","base":"La tarea todavía no la hice."}]},"takeaways":["Entiendes qué hizo alguien y qué le falta.","Cuentas tu semana con 了 y 还没."]},{"id":"zh-a2-u02-l01","unit_id":"zh-a2-u02","position":1,"title_es":"你去过…吗？","objective_es":"Contar experiencias con 过.","intro":{"explanation":"过 después del verbo cuenta una experiencia, algo que hiciste alguna vez: 我去过中国. Se niega con 没 (no con 不): 我没去过. Para preguntar: 你去过…吗？","examples":[{"target":"我去过中国。","base":"Estuve en China (alguna vez)."},{"target":"你吃过饺子吗？——没吃过。","base":"¿Probaste alguna vez jiaozi? — Nunca."}]},"takeaways":["Cuentas experiencias con 过.","Dices que nunca hiciste algo con 没…过."]},{"id":"zh-a2-u02-l02","unit_id":"zh-a2-u02","position":2,"title_es":"去过两次","objective_es":"Decir cuántas veces hiciste algo y hablar de viajes.","intro":{"explanation":"Cuántas veces: verbo + 过 + número + 次: 我去过两次. Si hay un lugar, va antes de las veces: 我去过长城两次. 旅游 es viajar de paseo, hacer turismo.","examples":[{"target":"我去过长城两次。","base":"Fui dos veces a la Gran Muralla."},{"target":"我想去中国旅游。","base":"Quiero ir de viaje a China."}]},"takeaways":["Dices cuántas veces con 次.","Hablas de viajes con 旅游."]},{"id":"zh-a2-u02-l03","unit_id":"zh-a2-u02","position":4,"title_es":"从北京到上海","objective_es":"Decir de dónde a dónde y cuánto tiempo lleva.","intro":{"explanation":"从 A 到 B es «de A a B»: 从北京到上海. 到 solo es «llegar»: 飞机三点到. La duración se cuenta con 个小时: 五个小时 (cinco horas).","examples":[{"target":"从北京到上海坐火车五个小时。","base":"De Pekín a Shanghái son cinco horas en tren."},{"target":"飞机几点到？","base":"¿A qué hora llega el avión?"}]},"takeaways":["Dices un recorrido con 从…到….","Dices cuántas horas dura con 个小时."]},{"id":"zh-a2-u02-l04","unit_id":"zh-a2-u02","position":5,"title_es":"是…的","objective_es":"Preguntar y decir cómo, cuándo y con quién pasó algo.","intro":{"explanation":"Si ya sabemos que algo pasó y queremos el detalle (cómo, cuándo, con quién), se usa 是 + detalle + verbo + 的: 你是怎么来的？——我是坐飞机来的. 你是什么时候到的？——我是昨天到的. El 是 se puede omitir; el 的, no.","examples":[{"target":"我是坐飞机来的。","base":"Vine en avión."},{"target":"你是什么时候到的？——我是昨天到的。","base":"¿Cuándo llegaste? — Llegué ayer."}]},"takeaways":["Preguntas detalles de algo pasado con 是…的.","Respondes cómo y cuándo llegaste."]},{"id":"zh-a2-u02-l05","unit_id":"zh-a2-u02","position":7,"title_es":"在机场","objective_es":"Resolver el aeropuerto: pasaporte, equipaje y boletos.","intro":{"explanation":"护照 es el pasaporte y 行李, el equipaje (se cuenta con 件: 两件行李). 票 es el boleto o la entrada, y se cuenta con 张: 两张票.","examples":[{"target":"你的护照呢？","base":"¿Y tu pasaporte?"},{"target":"我有两件行李。","base":"Tengo dos maletas."}]},"takeaways":["Te arreglas en el aeropuerto.","Cuentas boletos con 张 y equipaje con 件."]},{"id":"zh-a2-u03-l01","unit_id":"zh-a2-u03","position":1,"title_es":"菜单","objective_es":"Leer los platos básicos de un menú.","intro":{"explanation":"菜 es un plato de comida (y también la verdura); 菜单 es el menú. Algunos platos: 鱼 (pescado), 肉 (carne), 鸡蛋 (huevo).","examples":[{"target":"这是菜单。","base":"Este es el menú."},{"target":"我不吃肉，我吃鱼。","base":"No como carne, como pescado."}]},"takeaways":["Reconoces 鱼, 肉 y 鸡蛋 en un menú.","Dices qué comes y qué no."]},{"id":"zh-a2-u03-l02","unit_id":"zh-a2-u03","position":2,"title_es":"点菜","objective_es":"Pedir en un restaurante.","intro":{"explanation":"Para llamar al mesero y pedir: 服务员，我们点菜！ 请 + verbo es «por favor»: 请给我菜单. En un restaurante, 来 + cantidad es pedir algo: 来一碗米饭. 碗 es el tazón o plato hondo y se usa para contar arroz, fideos y sopa.","examples":[{"target":"服务员，我们点菜！","base":"¡Mesero, queremos pedir!"},{"target":"来两碗米饭。","base":"Dos platos de arroz, por favor."}]},"takeaways":["Pides con 来 + cantidad.","Usas 请 para pedir con cortesía."]},{"id":"zh-a2-u03-l03","unit_id":"zh-a2-u03","position":4,"title_es":"辣、甜、尝尝","objective_es":"Decir cómo es la comida y ofrecer probar.","intro":{"explanation":"辣 es picante y 甜, dulce. 尝 es probar comida; repetido (尝尝) suena más suave: «prueba un poquito». Muchos verbos se repiten así: 看看 (mira un poco).","examples":[{"target":"这个菜有点儿辣。","base":"Este plato es medio picante."},{"target":"你尝尝！","base":"¡Prueba un poco!"}]},"takeaways":["Dices si algo es picante o dulce.","Suavizas un verbo repitiéndolo: 尝尝."]},{"id":"zh-a2-u03-l04","unit_id":"zh-a2-u03","position":5,"title_es":"给我… · 买单！","objective_es":"Pedir cosas en la mesa y pedir la cuenta.","intro":{"explanation":"给 es «dar»; antes de una persona es «a / para»: 请给我一双筷子 (dame unos palitos), 妈妈给我做饭 (mamá cocina para mí). Para pedir la cuenta: 服务员，买单！ En China quien invita suele pagar todo: dividir la cuenta es menos común.","examples":[{"target":"请给我一双筷子。","base":"Por favor, dame unos palitos."},{"target":"服务员，买单！","base":"¡Mesero, la cuenta!"}]},"takeaways":["Pides cosas con 给我….","Pides la cuenta con 买单."]},{"id":"zh-a2-u03-l05","unit_id":"zh-a2-u03","position":7,"title_es":"在宾馆","objective_es":"Hacer el check-in y entender una charla en un restaurante.","intro":{"explanation":"宾馆 es el hotel. 预订 es reservar: 我预订了一个房间. En el mostrador te van a pedir el pasaporte: 请给我你的护照. Los números de habitación se leen cifra por cifra: 526 = 五二六.","examples":[{"target":"我预订了一个房间。","base":"Reservé una habitación."},{"target":"请给我你的护照。","base":"Su pasaporte, por favor."}]},"takeaways":["Haces el check-in en un hotel.","Entiendes un pedido en un restaurante."]},{"id":"zh-a2-u04-l01","unit_id":"zh-a2-u04","position":1,"title_es":"你在做什么呢？","objective_es":"Decir qué estás haciendo ahora.","intro":{"explanation":"Una acción en curso se dice con 在 + verbo, muchas veces con 呢 al final: 我在做饭呢 (estoy cocinando). 正在 subraya «justo ahora». Se niega con 没在: 我没在睡觉.","examples":[{"target":"你在做什么呢？——我在跑步。","base":"¿Qué estás haciendo? — Estoy corriendo."},{"target":"他正在玩游戏。","base":"Está jugando a un juego."}]},"takeaways":["Dices lo que haces ahora con 在 / 正在.","Lo niegas con 没在."]},{"id":"zh-a2-u04-l02","unit_id":"zh-a2-u04","position":2,"title_es":"喂，你找谁？","objective_es":"Hacer y atender una llamada.","intro":{"explanation":"打电话 es llamar por teléfono, y a quién se llama va con 给: 给妈妈打电话. Al atender se dice 喂 (wéi). 你找谁？ es «¿con quién quieres hablar?» (literalmente, «¿a quién buscas?»).","examples":[{"target":"喂，你好！","base":"¿Hola? ¡Buenas!"},{"target":"我给妈妈打电话。","base":"Llamo a mi mamá."}]},"takeaways":["Atiendes con 喂 y preguntas 你找谁？","Dices a quién llamas con 给…打电话."]},{"id":"zh-a2-u04-l03","unit_id":"zh-a2-u04","position":4,"title_es":"等一会儿","objective_es":"Pedir que te esperen y decir que ya vas.","intro":{"explanation":"等 es esperar: 等我！ 一会儿 es «un ratito»: 请等一会儿. 马上 es «enseguida»: 我马上来 (¡ya voy!).","examples":[{"target":"请等一会儿。","base":"Espera un ratito, por favor."},{"target":"我马上来！","base":"¡Ya voy!"}]},"takeaways":["Pides que te esperen con 等一会儿.","Dices «ya voy» con 马上."]},{"id":"zh-a2-u04-l04","unit_id":"zh-a2-u04","position":5,"title_es":"门口和楼","objective_es":"Decir dónde estás o dónde te espero.","intro":{"explanation":"门口 es la puerta de entrada: 我在门口等你. 楼 es el edificio y también el piso: 我家在三楼 (vivo en el tercer piso). 洗澡 es bañarse o ducharse.","examples":[{"target":"我在门口等你。","base":"Te espero en la puerta."},{"target":"我家在三楼。","base":"Vivo en el tercer piso."}]},"takeaways":["Dices dónde esperas con 在门口.","Dices el piso con número + 楼."]},{"id":"zh-a2-u04-l05","unit_id":"zh-a2-u04","position":7,"title_es":"你现在方便吗？","objective_es":"Preguntar si alguien puede hablar y entender llamadas.","intro":{"explanation":"方便 es «cómodo, conveniente»: 你现在方便吗？ (¿puedes hablar ahora?). 有事 es «tener algo que hacer o que decir»: 我有事. Para que el otro hable: 你说吧 (adelante, dime).","examples":[{"target":"你现在方便吗？","base":"¿Puedes hablar ahora?"},{"target":"对不起，我今天有事。","base":"Perdón, hoy tengo algo que hacer."}]},"takeaways":["Preguntas si es buen momento con 方便吗？","Entiendes quién hace qué en una llamada."]},{"id":"zh-a2-u05-l01","unit_id":"zh-a2-u05","position":1,"title_es":"我头疼","objective_es":"Decir qué te duele.","intro":{"explanation":"Para decir que algo duele: parte del cuerpo + 疼: 我头疼 («yo, la cabeza duele»). Con 有点儿 es «me duele un poco»: 我肚子有点儿疼.","examples":[{"target":"我头疼。","base":"Me duele la cabeza."},{"target":"我肚子有点儿疼。","base":"Me duele un poco la panza."}]},"takeaways":["Nombras la cabeza, la panza y la garganta.","Dices qué te duele con 疼."]},{"id":"zh-a2-u05-l02","unit_id":"zh-a2-u05","position":2,"title_es":"我感冒了","objective_es":"Contar que te enfermaste y cómo te sientes.","intro":{"explanation":"感冒 es el resfriado y 发烧, tener fiebre. Con 了 se cuenta el cambio: 我感冒了 (me resfrié), 我生病了 (me enfermé). 不舒服 es «sentirse mal».","examples":[{"target":"我感冒了。","base":"Me resfrié."},{"target":"我今天不舒服。","base":"Hoy me siento mal."}]},"takeaways":["Cuentas que te enfermaste con 了.","Dices que te sientes mal con 不舒服."]},{"id":"zh-a2-u05-l03","unit_id":"zh-a2-u05","position":4,"title_es":"看病和吃药","objective_es":"Ir al médico y hablar de remedios.","intro":{"explanation":"看病 es ir al médico (y, si lo dice el médico, atender). 药 es el remedio; «tomar un remedio» se dice 吃药 («comer remedio»). 身体 es el cuerpo y, en general, la salud: 你身体好吗？","examples":[{"target":"我去医院看病。","base":"Voy al hospital a que me vea un médico."},{"target":"你吃药了吗？","base":"¿Tomaste el remedio?"}]},"takeaways":["Dices que vas al médico con 看病.","Dices «tomar un remedio» con 吃药."]},{"id":"zh-a2-u05-l04","unit_id":"zh-a2-u05","position":5,"title_es":"应该 y 别","objective_es":"Dar consejos y pedir que no hagan algo.","intro":{"explanation":"应该 + verbo es un consejo, «deberías»: 你应该多休息. 别 + verbo pide que alguien no haga algo: 别去！ 多 + verbo es «haz más…»: 多喝水 (toma mucha agua).","examples":[{"target":"你应该多喝水。","base":"Deberías tomar mucha agua."},{"target":"别吃辣的！","base":"¡No comas picante!"}]},"takeaways":["Aconsejas con 应该 y 多 + verbo.","Pides que no hagan algo con 别."]},{"id":"zh-a2-u05-l05","unit_id":"zh-a2-u05","position":7,"title_es":"健康","objective_es":"Hablar de hábitos sanos y entender avisos y consejos.","intro":{"explanation":"运动 es hacer ejercicio o deporte, y 健康, sano o la salud: 他身体很健康. Hábitos sanos: 每天运动, 多喝水, 早睡觉.","examples":[{"target":"我每天运动半个小时。","base":"Hago ejercicio media hora por día."},{"target":"他身体很健康。","base":"Él es muy sano."}]},"takeaways":["Hablas de hábitos sanos.","Entiendes un aviso de enfermedad y consejos."]},{"id":"zh-a2-u06-l01","unit_id":"zh-a2-u06","position":1,"title_es":"你有没有空？","objective_es":"Preguntar si alguien tiene tiempo.","intro":{"explanation":"Una forma muy común de preguntar es repetir el verbo con 不 en el medio: 你去不去？ (¿vas o no?), 你想不想来？ Con 有 se usa 没: 你有没有空？ Estas preguntas no llevan 吗.","examples":[{"target":"你下个星期有没有空？","base":"¿La semana que viene tienes tiempo?"},{"target":"你想不想去？","base":"¿Quieres ir?"}]},"takeaways":["Preguntas con 去不去 y 有没有.","Hablas de tu tiempo libre con 有空."]},{"id":"zh-a2-u06-l02","unit_id":"zh-a2-u06","position":2,"title_es":"你打算做什么？","objective_es":"Contar planes y hablar de reuniones.","intro":{"explanation":"打算 + verbo es «tener pensado, planear»: 我打算去北京. 聚会 es una reunión o juntada, y 参加 es ir a algo organizado o participar: 参加聚会.","examples":[{"target":"周末你打算做什么？","base":"¿Qué tienes pensado hacer el fin de semana?"},{"target":"我想参加你的聚会。","base":"Quiero ir a tu reunión."}]},"takeaways":["Cuentas planes con 打算.","Dices que vas a una reunión con 参加."]},{"id":"zh-a2-u06-l03","unit_id":"zh-a2-u06","position":4,"title_es":"还是、当然、可惜","objective_es":"Elegir entre opciones, aceptar y rechazar.","intro":{"explanation":"还是 es «o» en una pregunta con dos opciones: 你喝茶还是喝咖啡？ Para aceptar: 当然！ (¡claro!). Para rechazar con amabilidad: 可惜我有事 (qué lástima, tengo algo que hacer).","examples":[{"target":"你喝茶还是喝咖啡？","base":"¿Tomas té o café?"},{"target":"可惜我星期六有事。","base":"Qué lástima, el sábado tengo algo que hacer."}]},"takeaways":["Ofreces opciones con 还是.","Aceptas con 当然 y rechazas con 可惜."]},{"id":"zh-a2-u06-l04","unit_id":"zh-a2-u06","position":5,"title_es":"进来、出去","objective_es":"Recibir visitas e indicar movimientos.","intro":{"explanation":"Después de un verbo de movimiento, 来 indica hacia quien habla y 去, hacia afuera o lejos: 进来 (pasa, entra aquí), 出去 (salir), 回来 (volver aquí), 上来 (sube). Al recibir a alguien: 欢迎！请进来！","examples":[{"target":"欢迎，欢迎！请进来！","base":"¡Bienvenido! ¡Pasa!"},{"target":"我们出去吃饭吧。","base":"Salgamos a comer."}]},"takeaways":["Recibes con 欢迎 y 请进来.","Usas 来 y 去 según la dirección."]},{"id":"zh-a2-u06-l05","unit_id":"zh-a2-u06","position":7,"title_es":"下次吧","objective_es":"Entender invitaciones y respuestas.","intro":{"explanation":"下次 es «la próxima vez»: 下次我们一起去吧. Para invitar: 你想不想来…？; para aceptar: 当然！; para rechazar sin cortar el plan: 可惜我有事，下次吧.","examples":[{"target":"下次我们一起去吧！","base":"¡La próxima vez vamos juntos!"},{"target":"可惜我有事，下次吧。","base":"Qué lástima, tengo algo que hacer; la próxima."}]},"takeaways":["Propones otra vez con 下次.","Entiendes si alguien acepta o rechaza."]},{"id":"zh-a2-u07-l01","unit_id":"zh-a2-u07","position":1,"title_es":"上班和下班","objective_es":"Hablar de tu horario y tu lugar de trabajo.","intro":{"explanation":"上班 es ir a trabajar (o estar trabajando) y 下班, salir del trabajo: 我九点上班，六点下班. 同事 es el compañero de trabajo, 经理 el gerente o jefe, y 开会, tener una reunión.","examples":[{"target":"我九点上班，六点下班。","base":"Entro a las nueve y salgo a las seis."},{"target":"经理在开会。","base":"La gerente está en una reunión."}]},"takeaways":["Dices tu horario con 上班 y 下班.","Hablas de tus compañeros y del gerente."]},{"id":"zh-a2-u07-l02","unit_id":"zh-a2-u07","position":2,"title_es":"考试","objective_es":"Hablar de exámenes y estudios.","intro":{"explanation":"考试 es el examen (y rendirlo). 准备 es preparar o prepararse: 准备考试. 教 es enseñar: 陈老师教中文. 毕业 es recibirse, terminar los estudios: 我明年毕业.","examples":[{"target":"我在准备考试。","base":"Estoy preparando el examen."},{"target":"陈老师教我们中文。","base":"El profesor Chen nos enseña chino."}]},"takeaways":["Hablas de exámenes con 考试 y 准备.","Dices quién enseña con 教."]},{"id":"zh-a2-u07-l03","unit_id":"zh-a2-u07","position":4,"title_es":"做完、听懂、写错","objective_es":"Decir el resultado de una acción.","intro":{"explanation":"Después del verbo, otro verbo o adjetivo dice el resultado: 做完 (terminar de hacer), 听懂 (escuchar y entender), 看懂 (leer y entender), 写错 (escribir mal). Se niega con 没: 我没听懂.","examples":[{"target":"我做完作业了。","base":"Terminé la tarea."},{"target":"老师说的我没听懂。","base":"No entendí lo que dijo el profesor."}]},"takeaways":["Dices el resultado con 完, 懂 y 错.","Lo niegas con 没."]},{"id":"zh-a2-u07-l04","unit_id":"zh-a2-u07","position":5,"title_es":"说得很好","objective_es":"Decir cómo se hace algo y pedir ayuda.","intro":{"explanation":"Para decir cómo se hace algo: verbo + 得 + adjetivo: 他跑得很快 (corre rápido). Si hay objeto, va antes: 你中文说得很好. 帮 es ayudar y 问题, pregunta o problema: 我有一个问题.","examples":[{"target":"你中文说得很好！","base":"¡Hablas muy bien chino!"},{"target":"我有一个问题，你能帮我吗？","base":"Tengo una pregunta, ¿me puedes ayudar?"}]},"takeaways":["Dices cómo se hace algo con 得.","Pides ayuda con 帮."]},{"id":"zh-a2-u07-l05","unit_id":"zh-a2-u07","position":7,"title_es":"学了两年","objective_es":"Contar cuánto tiempo hiciste algo y entender charlas de trabajo y estudio.","intro":{"explanation":"Para decir cuánto duró algo: verbo + 了 + tiempo: 我学了两年中文 (estudié chino dos años). La duración va antes del objeto.","examples":[{"target":"我学了两年中文。","base":"Estudié chino dos años."},{"target":"我在这个公司工作了三年。","base":"Trabajé tres años en esta empresa."}]},"takeaways":["Cuentas cuánto duró algo con verbo + 了 + tiempo.","Entiendes charlas sobre trabajo y estudio."]},{"id":"zh-a2-u08-l01","unit_id":"zh-a2-u08","position":1,"title_es":"裤子、裙子、帽子","objective_es":"Nombrar ropa y pedir probártela.","intro":{"explanation":"Ropa: 裤子 (pantalón), 裙子 (falda), 帽子 (gorro). Las prendas largas se cuentan con 条: 一条裤子. 试 es probar(se); repetido, 试试, suena amable: 我可以试试吗？","examples":[{"target":"我可以试试这条裤子吗？","base":"¿Me puedo probar este pantalón?"},{"target":"这个帽子很漂亮。","base":"Este gorro es muy lindo."}]},"takeaways":["Nombras pantalones, faldas y gorros.","Pides probarte algo con 试试."]},{"id":"zh-a2-u08-l02","unit_id":"zh-a2-u08","position":2,"title_es":"合适吗？","objective_es":"Decir si algo te queda bien, cambiarlo y elegir.","intro":{"explanation":"合适 es «quedar bien» (de talle o en general): 这条裤子很合适. 换 es cambiar una cosa por otra: 我想换一条. 选 es elegir: 你选哪个？","examples":[{"target":"这条裤子不合适，我想换一条。","base":"Este pantalón no me queda bien; quiero cambiarlo."},{"target":"你选哪个？","base":"¿Cuál eliges?"}]},"takeaways":["Dices si algo te queda bien con 合适.","Cambias y eliges con 换 y 选."]},{"id":"zh-a2-u08-l03","unit_id":"zh-a2-u08","position":4,"title_es":"更 y 最","objective_es":"Comparar con 比, 更 y 最.","intro":{"explanation":"Con 比 se puede decir cuánto: 比…一点儿 (un poco más), 比…多了 (mucho más): 这个比那个贵多了. 更 es «aún más» y va antes del adjetivo: 那个更好. 最 es «el más»: 这个最便宜.","examples":[{"target":"这个比那个便宜一点儿。","base":"Este es un poco más barato que aquel."},{"target":"这件最贵。","base":"Esta es la más cara."}]},"takeaways":["Comparas con 比…一点儿 y 比…多了.","Usas 更 (aún más) y 最 (el más)."]},{"id":"zh-a2-u08-l04","unit_id":"zh-a2-u08","position":5,"title_es":"没有…那么","objective_es":"Decir que algo no es tan… como otra cosa; comprar por internet.","intro":{"explanation":"A 没有 B 那么 + adjetivo es «A no es tan… como B»: 网上的没有商店的那么贵. 网上 es «por internet, en internet»: 我在网上买衣服.","examples":[{"target":"这件没有那件那么贵。","base":"Esta no es tan cara como aquella."},{"target":"我常常在网上买东西。","base":"Compro seguido por internet."}]},"takeaways":["Dices «no tan… como» con 没有…那么.","Hablas de compras por internet."]},{"id":"zh-a2-u08-l05","unit_id":"zh-a2-u08","position":7,"title_es":"打折和付钱","objective_es":"Entender descuentos y decir cómo pagas.","intro":{"explanation":"打折 es hacer descuento. Ojo: 打八折 no es 80 % de descuento: pagas el 80 % (o sea, 20 % menos); 打五折 es la mitad. 付 es pagar, con 现金 (efectivo) o con 卡 (tarjeta).","examples":[{"target":"今天打八折。","base":"Hoy pagas el 80 % (20 % de descuento)."},{"target":"我付现金。","base":"Pago en efectivo."}]},"takeaways":["Entiendes 打八折 y 打五折.","Dices si pagas en efectivo o con tarjeta."]},{"id":"zh-a2-u09-l01","unit_id":"zh-a2-u09","position":1,"title_es":"发消息","objective_es":"Mandar mensajes y pedir un número.","intro":{"explanation":"发 es mandar (un mensaje, una foto). Quien recibe va con 给, antes del verbo (给你发消息) o después (发给你). 号码 es el número de teléfono: 你的手机号码是多少？","examples":[{"target":"我晚上给你发消息。","base":"Por la noche te mando un mensaje."},{"target":"你的手机号码是多少？","base":"¿Cuál es tu número de celular?"}]},"takeaways":["Mandas mensajes con 发 y 给.","Pides un número con 号码是多少？"]},{"id":"zh-a2-u09-l02","unit_id":"zh-a2-u09","position":2,"title_es":"照片和视频","objective_es":"Hablar de fotos y videos.","intro":{"explanation":"照片 es la foto y 拍, sacar fotos o filmar: 拍照片. 视频 es un video y 下载, descargar. Las fotos se cuentan con 张: 一张照片.","examples":[{"target":"我拍了很多照片。","base":"Saqué muchas fotos."},{"target":"你看这个视频！","base":"¡Mira este video!"}]},"takeaways":["Sacas fotos con 拍.","Hablas de videos y descargas."]},{"id":"zh-a2-u09-l03","unit_id":"zh-a2-u09","position":4,"title_es":"上网和充电","objective_es":"Pedir internet, la contraseña y un lugar para cargar el celular.","intro":{"explanation":"上网 es conectarse a internet; 密码, la contraseña (también la del wifi); 充电, cargar la batería. 用 es usar, y 用 + cosa + verbo dice con qué haces algo: 我用手机上网.","examples":[{"target":"这儿可以上网吗？","base":"¿Aquí hay internet?"},{"target":"我用手机拍照片。","base":"Saco fotos con el celular."}]},"takeaways":["Pides el wifi y la contraseña.","Dices con qué haces algo con 用."]},{"id":"zh-a2-u09-l04","unit_id":"zh-a2-u09","position":5,"title_es":"开和关","objective_es":"Prender, apagar y escribir correos.","intro":{"explanation":"开 es abrir o prender y 关, cerrar o apagar: 开电脑, 关手机. 电子邮件 es el correo electrónico.","examples":[{"target":"我开电脑上网。","base":"Prendo la computadora y me conecto."},{"target":"晚上我关手机。","base":"Por la noche apago el celular."}]},"takeaways":["Prendes y apagas con 开 y 关.","Mandas un 电子邮件."]},{"id":"zh-a2-u09-l05","unit_id":"zh-a2-u09","position":7,"title_es":"把照片发给我","objective_es":"Decir qué haces con una cosa usando 把.","intro":{"explanation":"Con 把 la cosa va antes del verbo, cuando haces algo con ella (la mandas, la das, la apagas): 把照片发给我 (mándame la foto). Estructura: 把 + cosa + verbo + algo más (给我, 了…). El verbo nunca queda solo.","examples":[{"target":"请把手机给我。","base":"Dame el celular, por favor."},{"target":"我把照片发给你了。","base":"Te mandé las fotos."}]},"takeaways":["Usas 把 + cosa + verbo + algo más.","Entiendes mensajes y pedidos sobre tecnología."]},{"id":"zh-a2-u10-l01","unit_id":"zh-a2-u10","position":1,"title_es":"以前和现在","objective_es":"Contar cómo era antes y qué cambió.","intro":{"explanation":"以前 es «antes» y contrasta con 现在: 以前我不喝咖啡，现在喝了. 了 al final marca el cambio y 不…了 es «ya no»: 我不吃肉了. 变 es cambiar, volverse otra cosa; 习惯 es la costumbre y también acostumbrarse.","examples":[{"target":"以前我不喝咖啡，现在喝了。","base":"Antes no tomaba café; ahora sí."},{"target":"我不吃肉了。","base":"Ya no como carne."}]},"takeaways":["Contrastas 以前 y 现在.","Dices «ya no» con 不…了."]},{"id":"zh-a2-u10-l02","unit_id":"zh-a2-u10","position":2,"title_es":"越来越","objective_es":"Decir qué cambia cada vez más y qué empezaste.","intro":{"explanation":"越来越 + adjetivo es «cada vez más…»: 天气越来越冷. 开始 + verbo es «empezar a»: 我开始学游泳了. 以后 es «más adelante, en el futuro»: 以后我想去中国.","examples":[{"target":"我的中文越来越好。","base":"Mi chino está cada vez mejor."},{"target":"我上个星期开始学游泳。","base":"La semana pasada empecé a aprender a nadar."}]},"takeaways":["Dices «cada vez más» con 越来越.","Cuentas qué empezaste con 开始."]},{"id":"zh-a2-u10-l03","unit_id":"zh-a2-u10","position":4,"title_es":"男朋友和女朋友","objective_es":"Hablar de parejas, casamientos y vecinos.","intro":{"explanation":"男朋友 es el novio y 女朋友, la novia (男 hombre, 女 mujer). 结婚 es casarse; no lleva objeto: se dice 跟…结婚 (casarse con…). 邻居 es el vecino.","examples":[{"target":"我姐姐有男朋友。","base":"Mi hermana tiene novio."},{"target":"她下个月跟男朋友结婚。","base":"El mes que viene se casa con su novio."}]},"takeaways":["Nombras novio, novia y vecinos.","Dices con quién se casa alguien con 跟…结婚."]},{"id":"zh-a2-u10-l04","unit_id":"zh-a2-u10","position":5,"title_es":"小的时候","objective_es":"Contar cómo eras de chico y hablar de la edad.","intro":{"explanation":"…的时候 es «cuando…» y va al principio: 我小的时候 (cuando era chico), 吃饭的时候 (cuando como). 年轻 es joven y 老, mayor o viejo (personas): 我奶奶老了. 孩子 es el hijo o el chico.","examples":[{"target":"我小的时候很喜欢唱歌。","base":"De chico me gustaba mucho cantar."},{"target":"我奶奶年轻的时候是老师。","base":"Mi abuela, de joven, era profesora."}]},"takeaways":["Dices «cuando…» con …的时候.","Hablas de jóvenes, mayores e hijos."]},{"id":"zh-a2-u10-l05","unit_id":"zh-a2-u10","position":7,"title_es":"一边…一边","objective_es":"Decir qué haces a la vez y entender relatos de cambios.","intro":{"explanation":"一边 A 一边 B es hacer dos cosas a la vez: 我一边吃饭一边看电视 (como mientras miro la tele).","examples":[{"target":"她一边听音乐一边做饭。","base":"Cocina mientras escucha música."},{"target":"别一边走路一边看手机！","base":"¡No mires el celular mientras caminas!"}]},"takeaways":["Cuentas dos acciones a la vez con 一边…一边.","Entiendes relatos de cambios y de familia."]},{"id":"zh-a2-u11-l01","unit_id":"zh-a2-u11","position":1,"title_es":"春节","objective_es":"Contar cómo se festeja el Año Nuevo chino.","intro":{"explanation":"春节 es el Año Nuevo chino (en enero o febrero, según la luna) y 过年, festejarlo. Todos 放假 (tienen vacaciones) y muchos vuelven a su ciudad. A los chicos se les da un 红包: un sobre rojo con dinero.","examples":[{"target":"春节的时候我们放假。","base":"En Año Nuevo chino tenemos vacaciones."},{"target":"孩子过年的时候有红包。","base":"En Año Nuevo los chicos reciben sobres rojos."}]},"takeaways":["Hablas del 春节 y de 过年.","Sabes qué es un 红包."]},{"id":"zh-a2-u11-l02","unit_id":"zh-a2-u11","position":2,"title_es":"为什么？因为…","objective_es":"Preguntar y explicar por qué.","intro":{"explanation":"为什么 es «¿por qué?». Se responde con 因为 (porque), y 所以 es «por eso». En chino se usan juntos sin problema: 因为下雨了，所以我不去.","examples":[{"target":"你为什么不去？","base":"¿Por qué no vas?"},{"target":"因为下雨了，所以我不去。","base":"Como llueve, no voy."}]},"takeaways":["Preguntas con 为什么.","Explicas con 因为…所以…."]},{"id":"zh-a2-u11-l03","unit_id":"zh-a2-u11","position":4,"title_es":"中秋节","objective_es":"Hablar de la Fiesta de Medio Otoño y de las fiestas.","intro":{"explanation":"中秋节 es la Fiesta de Medio Otoño: la familia se junta, mira la luna llena y come 月饼 (pasteles de luna). 节日 es una fiesta o feriado. Algunos adjetivos se repiten para sonar más vivos: 甜甜的 (dulcecito).","examples":[{"target":"中秋节我们吃月饼。","base":"En la Fiesta de Medio Otoño comemos pasteles de luna."},{"target":"月饼甜甜的，很好吃。","base":"Los pasteles de luna son dulcecitos y muy ricos."}]},"takeaways":["Hablas del 中秋节 y los 月饼.","Reconoces adjetivos repetidos como 甜甜的."]},{"id":"zh-a2-u11-l04","unit_id":"zh-a2-u11","position":5,"title_es":"送礼物","objective_es":"Hablar de regalos y tradiciones.","intro":{"explanation":"送 es regalar o dar: 送礼物 (hacer un regalo). Quien recibe va enseguida: 送老师一个礼物. 传统 es la tradición. Ojo: en China no se regala un reloj de pared (钟), porque 送钟 suena igual que una expresión sobre la muerte.","examples":[{"target":"我想送妈妈一个礼物。","base":"Le quiero hacer un regalo a mamá."},{"target":"吃饺子是春节的传统。","base":"Comer jiaozi es una tradición del Año Nuevo."}]},"takeaways":["Dices a quién regalas algo con 送.","Conoces algunas tradiciones con los regalos."]},{"id":"zh-a2-u11-l05","unit_id":"zh-a2-u11","position":7,"title_es":"先…再…","objective_es":"Decir en qué orden se hacen las cosas y entender textos sobre fiestas.","intro":{"explanation":"先 A 再 B (o 然后 B) es «primero A y después B»: 我们先吃饭，再看电视. 再 también es «otra vez». 有意思 es «interesante, entretenido».","examples":[{"target":"我们先吃饭，再看电视。","base":"Primero comemos y después miramos la tele."},{"target":"中国的节日很有意思。","base":"Las fiestas chinas son muy interesantes."}]},"takeaways":["Ordenas acciones con 先…再….","Entiendes cómo se festejan las fiestas chinas."]},{"id":"zh-a2-u12-l01","unit_id":"zh-a2-u12","position":1,"title_es":"我觉得…","objective_es":"Dar tu opinión y decir si estás de acuerdo.","intro":{"explanation":"觉得 es «parecer, opinar»: 我觉得这个很好 (me parece que está muy bien). 但是 es «pero» (un poco más fuerte que 可是). 同意 es estar de acuerdo: 我同意 / 我不同意.","examples":[{"target":"我觉得中文很有意思。","base":"Me parece que el chino es muy interesante."},{"target":"我同意，但是有点儿贵。","base":"Estoy de acuerdo, pero es medio caro."}]},"takeaways":["Opinas con 我觉得….","Dices si estás de acuerdo con 同意 y matizas con 但是."]},{"id":"zh-a2-u12-l02","unit_id":"zh-a2-u12","position":2,"title_es":"你怎么了？","objective_es":"Preguntar qué pasó y contar un problema.","intro":{"explanation":"怎么了？ es «¿qué pasó?, ¿qué te pasa?». Los problemas se cuentan con 了 (cambio): 我的护照丢了 (perdí el pasaporte), 电脑坏了 (se rompió la computadora), 我忘了 (me olvidé).","examples":[{"target":"你怎么了？——我的护照丢了！","base":"¿Qué te pasa? — ¡Perdí el pasaporte!"},{"target":"我的电脑坏了。","base":"Se me rompió la computadora."}]},"takeaways":["Preguntas 怎么了？","Cuentas que algo se perdió, se rompió o te lo olvidaste."]},{"id":"zh-a2-u12-l03","unit_id":"zh-a2-u12","position":4,"title_es":"被偷了","objective_es":"Contar algo malo que te pasó con 被.","intro":{"explanation":"Con 被 la cosa sufre la acción, casi siempre algo malo: 我的手机被偷了 (me robaron el celular). Estructura: cosa + 被 (+ quién) + verbo + 了: 我的月饼被弟弟吃了.","examples":[{"target":"我的手机被偷了。","base":"Me robaron el celular."},{"target":"我的月饼被弟弟吃了。","base":"Mi hermano se comió mi pastel de luna."}]},"takeaways":["Cuentas algo que te hicieron con 被.","Usas 被 + (quién) + verbo + 了."]},{"id":"zh-a2-u12-l04","unit_id":"zh-a2-u12","position":5,"title_es":"怎么办？","objective_es":"Pedir y proponer una solución.","intro":{"explanation":"怎么办？ es «¿qué hago?, ¿qué hacemos?». 办法 es la solución o la manera: 我有一个办法. 修 es arreglar. 可能 es «tal vez, puede ser»: 可能是充电的问题.","examples":[{"target":"我的电脑坏了，怎么办？","base":"Se me rompió la computadora, ¿qué hago?"},{"target":"我有一个办法。","base":"Tengo una solución."}]},"takeaways":["Pides ayuda con 怎么办？","Propones una solución con 办法 y 修."]},{"id":"zh-a2-u12-l05","unit_id":"zh-a2-u12","position":7,"title_es":"如果…就…","objective_es":"Hablar de condiciones y tranquilizar a alguien.","intro":{"explanation":"如果…就… es «si…, (entonces)…»: 如果下雨，我就不去 (si llueve, no voy). 就 va después de la persona y antes del verbo. 担心 es preocuparse: 别担心 (no te preocupes).","examples":[{"target":"如果下雨，我就不去。","base":"Si llueve, no voy."},{"target":"别担心，我有办法。","base":"No te preocupes, tengo una solución."}]},"takeaways":["Dices condiciones con 如果…就….","Tranquilizas a alguien con 别担心."]},{"id":"fr-a1-u01-l01","unit_id":"fr-a1-u01","position":1,"title_es":"Bonjour, salut, au revoir","objective_es":"Saludar y despedirse según la hora y la persona.","intro":{"explanation":"Bonjour sirve todo el día (y se dice siempre al entrar a un negocio); bonsoir, desde la tarde-noche. Salut es informal: hola o adiós entre amigos. Para despedirse: au revoir o à bientôt. Con un desconocido se agrega madame o monsieur. Ojo: la t de salut no suena.","examples":[{"target":"Bonjour, madame.","base":"Buenos días, señora."},{"target":"Salut, Hugo!","base":"¡Hola, Hugo!"}]},"takeaways":["Saludas con bonjour, bonsoir o salut según la hora y la persona.","Te despides con au revoir y à bientôt."]},{"id":"fr-a1-u01-l02","unit_id":"fr-a1-u01","position":2,"title_es":"Merci, s'il vous plaît","objective_es":"Agradecer, pedir por favor y responder sí o no.","intro":{"explanation":"Merci es gracias y de rien, de nada. Por favor tiene dos formas: s'il vous plaît (con vous, formal) y s'il te plaît (con tu, entre amigos). En las dos, la t final de plaît no se pronuncia. Oui es sí y non, no.","examples":[{"target":"Merci, madame. — De rien.","base":"Gracias, señora. — De nada."},{"target":"Non, merci.","base":"No, gracias."}]},"takeaways":["Agradeces con merci y respondes de rien.","Eliges s'il vous plaît o s'il te plaît según la persona."]},{"id":"fr-a1-u01-l03","unit_id":"fr-a1-u01","position":4,"title_es":"Ça va?","objective_es":"Preguntar y responder cómo está alguien.","intro":{"explanation":"Ça va? (¿cómo va?) es la pregunta más común; se responde ça va bien o, más corto, ça va. Para devolver la pregunta: et toi? a un amigo y et vous? a alguien con quien usas vous. La ç con cedilla suena como una s: ça, nunca «ka».","examples":[{"target":"Ça va? — Ça va bien, merci.","base":"¿Cómo va? — Bien, gracias."},{"target":"Ça va bien. Et vous?","base":"Estoy bien. ¿Y usted?"}]},"takeaways":["Preguntas ça va? y respondes ça va bien.","Devuelves la pregunta con et toi? o et vous?"]},{"id":"fr-a1-u01-l04","unit_id":"fr-a1-u01","position":5,"title_es":"Je m'appelle…","objective_es":"Presentarse y preguntar el nombre.","intro":{"explanation":"Para decir tu nombre: je m'appelle + nombre. Me pierde la e delante de vocal (elisión): je m'appelle, nunca «je me appelle». Para preguntar: tu t'appelles comment? Al conocer a alguien se dice enchanté; una mujer escribe enchantée, pero suena igual.","examples":[{"target":"Je m'appelle Ana.","base":"Me llamo Ana."},{"target":"Tu t'appelles comment?","base":"¿Cómo te llamas?"}]},"takeaways":["Dices tu nombre con je m'appelle.","Preguntas el nombre y respondes enchanté o enchantée."]},{"id":"fr-a1-u01-l05","unit_id":"fr-a1-u01","position":7,"title_es":"Una conversación completa","objective_es":"Saludar, presentarse y despedirse en una conversación.","intro":{"explanation":"Una conversación corta en francés: saludo (bonjour / salut), pregunta (ça va?), presentación (je m'appelle…) y despedida (au revoir, à bientôt). Recuerda el registro: tu con amigos, vous con desconocidos. Y merci beaucoup es muchas gracias.","examples":[{"target":"Bonsoir, madame! Ça va?","base":"¡Buenas noches, señora! ¿Cómo va?"},{"target":"Merci beaucoup! À bientôt!","base":"¡Muchas gracias! ¡Hasta pronto!"}]},"takeaways":["Armas una conversación corta del saludo a la despedida.","Usas tu o vous según con quién hablas."]},{"id":"fr-a1-u02-l01","unit_id":"fr-a1-u02","position":1,"title_es":"Je suis, tu es","objective_es":"Decir quién eres y qué haces con el verbo être.","intro":{"explanation":"Être es ser: je suis, tu es, il est (él), elle est (ella). Tu es e il est suenan igual: la s y la t finales no se pronuncian. Con una profesión no va artículo: je suis étudiant (soy estudiante). En el femenino se agrega una e y la t final sí suena: étudiante. Para decir «yo también»: moi aussi.","examples":[{"target":"Je suis Ana.","base":"Soy Ana."},{"target":"Il est étudiant.","base":"Él es estudiante."}]},"takeaways":["Dices quién eres con je suis y hablas de otro con il est o elle est.","Sabes que en étudiante la t final suena y en étudiant no."]},{"id":"fr-a1-u02-l02","unit_id":"fr-a1-u02","position":2,"title_es":"Je suis argentin","objective_es":"Decir tu nacionalidad y preguntar la de otra persona con vous êtes.","intro":{"explanation":"Las nacionalidades concuerdan con la persona: argentin / argentine, français / française, italien / italienne, brésilien / brésilienne, espagnol / espagnole. En el femenino la consonante final suena: en argentin la n no suena (vocal nasal), en argentine sí; en français la s es muda, en française suena como z. Con vous êtes hay liaison: la s de vous se une a êtes con un sonido z. Ojo: en francés las nacionalidades van en minúscula.","examples":[{"target":"Je suis argentin.","base":"Soy argentino."},{"target":"Vous êtes française?","base":"¿Usted es francesa?"}]},"takeaways":["Dices tu nacionalidad en masculino o en femenino.","Preguntas con vous êtes y unes vous‿êtes con un sonido z."]},{"id":"fr-a1-u02-l03","unit_id":"fr-a1-u02","position":4,"title_es":"Tu es d'où?","objective_es":"Decir de dónde eres y en qué ciudad vives.","intro":{"explanation":"Para preguntar el origen: tu es d'où? (o vous êtes d'où?). Se responde je suis de + ciudad. Para la ciudad donde vives: j'habite à + ciudad (nunca «en» delante de una ciudad). La h de habite es muda: je se vuelve j' y se dice como si empezara con vocal. La ville es la ciudad y le pays, el país (la s final no suena).","examples":[{"target":"Tu es d'où? — Je suis de Rosario.","base":"¿De dónde eres? — Soy de Rosario."},{"target":"J'habite à Paris.","base":"Vivo en París."}]},"takeaways":["Dices de dónde eres con je suis de.","Dices dónde vives con j'habite à + ciudad."]},{"id":"fr-a1-u02-l04","unit_id":"fr-a1-u02","position":5,"title_es":"Je parle, je ne parle pas","objective_es":"Decir qué idiomas hablas y negar con ne… pas.","intro":{"explanation":"Je parle + idioma: je parle espagnol (la e final de parle no suena). El idioma es igual a la nacionalidad en masculino y va en minúscula: français, espagnol, italien, anglais. Para negar, ne… pas rodea al verbo: je ne parle pas italien, je ne suis pas française. Delante de vocal, ne se vuelve n': il n'est pas. Non sirve para responder solo; con un verbo, ne… pas.","examples":[{"target":"Je parle espagnol.","base":"Hablo español."},{"target":"Je ne suis pas italien.","base":"No soy italiano."}]},"takeaways":["Dices qué idiomas hablas con je parle.","Niegas con ne… pas alrededor del verbo (n' delante de vocal)."]},{"id":"fr-a1-u02-l05","unit_id":"fr-a1-u02","position":7,"title_es":"Me presento","objective_es":"Presentarte con nacionalidad, ciudad e idiomas, y entender una presentación.","intro":{"explanation":"Una presentación completa: je m'appelle…, je suis + nacionalidad, je suis de…, j'habite à…, je parle… Para preguntar a un amigo: tu es d'où? tu habites où? tu parles français? Con vous: vous êtes d'où? Recuerda: tu habites, tu parles llevan una s final que no suena.","examples":[{"target":"Je m'appelle Diego. Je suis argentin.","base":"Me llamo Diego. Soy argentino."},{"target":"Tu habites où?","base":"¿Dónde vives?"}]},"takeaways":["Te presentas con nombre, nacionalidad, ciudad e idiomas.","Entiendes una presentación corta escrita."]},{"id":"fr-a1-u03-l01","unit_id":"fr-a1-u03","position":1,"title_es":"Un, deux, trois","objective_es":"Contar del uno al cinco.","intro":{"explanation":"Un, deux, trois, quatre, cinq. Un es una vocal nasal (la n no suena); con una palabra femenina se dice une: une ville. En deux y trois la consonante final no suena, pero en cinq la q final sí se pronuncia cuando el número va solo. Para sumar, en el habla se usa et: deux et trois, cinq.","examples":[{"target":"Un, deux, trois.","base":"Uno, dos, tres."},{"target":"Rosario est une ville.","base":"Rosario es una ciudad."}]},"takeaways":["Cuentas del uno al cinco en francés.","Usas un o une según el género de la palabra."]},{"id":"fr-a1-u03-l02","unit_id":"fr-a1-u03","position":2,"title_es":"Six, sept, huit, neuf, dix","objective_es":"Contar del seis al diez y distinguir six de dix.","intro":{"explanation":"Six, sept, huit, neuf, dix. En sept la p no suena. La h de huit es muda y la t suena. Six y dix cambian según lo que sigue: solos, la x suena como s; delante de consonante no suena (six villes); delante de vocal se une con un sonido z (six‿ans, dix‿ans). Escucha bien la primera consonante: six empieza con s, dix con d.","examples":[{"target":"Six, sept, huit, neuf, dix.","base":"Seis, siete, ocho, nueve, diez."},{"target":"Cinq et cinq, dix.","base":"Cinco más cinco, diez."}]},"takeaways":["Cuentas del seis al diez.","Distingues six de dix y sabes que su x cambia según lo que sigue."]},{"id":"fr-a1-u03-l03","unit_id":"fr-a1-u03","position":4,"title_es":"J'ai vingt ans","objective_es":"Contar hasta el doce y el veinte, y decir tu edad con avoir.","intro":{"explanation":"Onze, douze y vingt. En vingt la g y la t no suenan (vocal nasal), pero en vingt ans la t se une a ans. La edad va con avoir: j'ai vingt ans (tengo veinte años), nunca «je suis vingt». Un an es un año; en plural, ans. Ojo con deux y douze: deux es corto; douze termina con un sonido z.","examples":[{"target":"J'ai vingt ans.","base":"Tengo veinte años."},{"target":"J'ai douze ans.","base":"Tengo doce años."}]},"takeaways":["Dices tu edad con j'ai + número + ans.","Distingues deux de douze al escuchar."]},{"id":"fr-a1-u03-l04","unit_id":"fr-a1-u03","position":5,"title_es":"Quel âge as-tu?","objective_es":"Preguntar la edad y decir la edad de otra persona.","intro":{"explanation":"Avoir en singular: j'ai, tu as, il a, elle a. En tu as la s final no suena.Para preguntar la edad: quel âge as-tu? (el verbo va antes del sujeto, unido con guion) o, entre amigos, tu as quel âge? Il a y elle a se distinguen solo por el pronombre: escúchalo bien.","examples":[{"target":"Quel âge as-tu?","base":"¿Cuántos años tienes?"},{"target":"Il a huit ans.","base":"Tiene ocho años."}]},"takeaways":["Preguntas la edad con quel âge as-tu? o tu as quel âge?","Dices la edad de otra persona con il a o elle a."]},{"id":"fr-a1-u03-l05","unit_id":"fr-a1-u03","position":7,"title_es":"Números y edades","objective_es":"Repasar los números y entender edades en un mensaje y en una conversación.","intro":{"explanation":"Ya puedes presentarte completo: je m'appelle…, j'ai… ans, je suis de…, j'habite à… Recuerda la liaison delante de ans: deux‿ans, trois‿ans, six‿ans y dix‿ans con sonido z, huit ans y vingt ans con t, neuf ans con v. Y para preguntar: tu as quel âge?","examples":[{"target":"Je m'appelle Clara. J'ai vingt ans.","base":"Me llamo Clara. Tengo veinte años."},{"target":"Il a trois ans.","base":"Tiene tres años."}]},"takeaways":["Entiendes edades en un texto y en un diálogo.","Pronuncias la liaison de los números delante de ans."]},{"id":"fr-a1-u04-l01","unit_id":"fr-a1-u04","position":1,"title_es":"Ma famille","objective_es":"Presentar a tus padres con mon, ma y mes.","intro":{"explanation":"Le père es el padre y la mère, la madre (la è es una e abierta). Les parents son los padres: es un falso amigo, no significa parientes. Mi se dice mon con palabras masculinas (mon père), ma con femeninas (ma mère) y mes en plural (mes parents). Para presentar: c'est mon père (es mi papá) o voici ma famille (esta es mi familia).","examples":[{"target":"C'est mon père.","base":"Es mi papá."},{"target":"Voici mes parents.","base":"Estos son mis padres."}]},"takeaways":["Presentas a tu familia con c'est y voici.","Eliges mon, ma o mes según la palabra que sigue."]},{"id":"fr-a1-u04-l02","unit_id":"fr-a1-u04","position":2,"title_es":"J'ai un frère","objective_es":"Hablar de hermanos e hijos con avoir.","intro":{"explanation":"Con avoir dices quién está en tu familia: j'ai un frère, j'ai une sœur. Le fils es el hijo: la l no suena y la s final sí (una excepción). La fille es la hija (también la chica): la ll suena como una y. En sœur, œ es una vocal que no existe en español: se dice con la boca redondeada. L'enfant es el niño o la niña; para preguntar si alguien tiene hijos: vous avez des enfants?","examples":[{"target":"J'ai un frère et une sœur.","base":"Tengo un hermano y una hermana."},{"target":"Vous avez des enfants?","base":"¿Tiene hijos?"}]},"takeaways":["Dices cuántos hermanos o hijos tienes con j'ai.","Pronuncias le fils con s y la fille con sonido y."]},{"id":"fr-a1-u04-l03","unit_id":"fr-a1-u04","position":4,"title_es":"Ton mari, ta grand-mère","objective_es":"Hablar de la pareja y los abuelos, y preguntar con ton, ta y tes.","intro":{"explanation":"Le mari es el marido y la femme, la mujer o la esposa (en femme la e suena como a). Los abuelos: le grand-père y la grand-mère; los dos juntos, les grands-parents. Para tu: ton con palabras masculinas (ton mari), ta con femeninas (ta grand-mère) y tes en plural (tes grands-parents). La d de grand no suena.","examples":[{"target":"C'est ton mari?","base":"¿Es tu marido?"},{"target":"Ma grand-mère est italienne.","base":"Mi abuela es italiana."}]},"takeaways":["Nombras a la pareja y a los abuelos.","Preguntas por la familia de otro con ton, ta y tes."]},{"id":"fr-a1-u04-l04","unit_id":"fr-a1-u04","position":5,"title_es":"Il s'appelle Marc","objective_es":"Decir cómo se llama alguien y usar son y sa.","intro":{"explanation":"Para decir el nombre de otra persona: il s'appelle Marc, elle s'appelle Chloé. Su se dice son, sa o ses según la palabra que sigue, no según quién la posee: son père es su papá (de Léa o de Hugo) y sa mère, su mamá. Delante de vocal se usa mon, ton, son aunque la palabra sea femenina: mon amie Inès, nunca «ma amie».","examples":[{"target":"Il s'appelle Marc.","base":"Se llama Marc."},{"target":"Hugo? Sa mère s'appelle Anne.","base":"¿Hugo? Su mamá se llama Anne."}]},"takeaways":["Dices cómo se llama alguien con il s'appelle o elle s'appelle.","Eliges son o sa por la palabra que sigue, no por el dueño."]},{"id":"fr-a1-u04-l05","unit_id":"fr-a1-u04","position":7,"title_es":"Mon chien et mon chat","objective_es":"Hablar de las mascotas y describir a tu familia.","intro":{"explanation":"Le chien es el perro y le chat, el gato: en chat la t final no suena. Las mascotas también entran en la familia: j'ai un chien, mon chat a trois ans. Con ses hablas de varias cosas de otra persona: Léa et ses parents (Léa y sus padres).","examples":[{"target":"J'ai un chien et deux chats.","base":"Tengo un perro y dos gatos."},{"target":"Mon chat a trois ans.","base":"Mi gato tiene tres años."}]},"takeaways":["Hablas de tus mascotas con le chien y le chat.","Entiendes una descripción corta de una familia."]},{"id":"fr-a1-u05-l01","unit_id":"fr-a1-u05","position":1,"title_es":"Qu'est-ce que c'est?","objective_es":"Nombrar objetos con c'est un / une y preguntar qué es algo.","intro":{"explanation":"Para nombrar un objeto: c'est + un / une + sustantivo. Un va con los masculinos y une con los femeninos, y el género no siempre coincide con el español: le stylo es masculino (el bolígrafo). Para preguntar: qu'est-ce que c'est? En qu'est-ce que c'est la s de est no suena: se dice todo en un solo bloque. Ojo: para presentar un objeto no se usa il est (nunca «il est un stylo»).","examples":[{"target":"Qu'est-ce que c'est? — C'est un sac.","base":"¿Qué es esto? — Es un bolso."},{"target":"C'est une clé.","base":"Es una llave."}]},"takeaways":["Nombras objetos con c'est un o c'est une.","Preguntas qué es algo con qu'est-ce que c'est?"]},{"id":"fr-a1-u05-l02","unit_id":"fr-a1-u05","position":2,"title_es":"Le, la, les · ce sont","objective_es":"Usar los artículos y hablar de varios objetos con ce sont.","intro":{"explanation":"Los artículos definidos son le (masculino), la (femenino), l' delante de vocal y les (plural). En plural, un / une pasa a des, que en español muchas veces no se dice: ce sont des chaises (son sillas). Con varios objetos se usa ce sont en lugar de c'est. La s del plural no suena: livre y livres se pronuncian igual, y lo que se oye es le / les.","examples":[{"target":"Ce sont des chaises.","base":"Son sillas."},{"target":"C'est la table de Claire.","base":"Es la mesa de Claire."}]},"takeaways":["Eliges le, la, les o des según el género y el número.","Usas c'est con un objeto y ce sont con varios."]},{"id":"fr-a1-u05-l03","unit_id":"fr-a1-u05","position":4,"title_es":"Les couleurs","objective_es":"Decir de qué color es un objeto.","intro":{"explanation":"El color va después del sustantivo: un sac rouge (nunca «un rouge sac»). Para preguntar: de quelle couleur est…? Couleur es femenino en francés (la couleur, el color), por eso se dice quelle y no quel; suenan igual. Rouge y jaune ya terminan en e: no cambian en femenino (une chaise rouge). En plural se agrega una s que no suena: des sacs rouges.","examples":[{"target":"C'est un sac rouge.","base":"Es un bolso rojo."},{"target":"De quelle couleur est ton téléphone?","base":"¿De qué color es tu teléfono?"}]},"takeaways":["Pones el color después del sustantivo.","Preguntas el color con de quelle couleur est…?"]},{"id":"fr-a1-u05-l04","unit_id":"fr-a1-u05","position":5,"title_es":"Vert, verte · petit, grand","objective_es":"Hacer concordar el color y el tamaño con el sustantivo.","intro":{"explanation":"Los adjetivos concuerdan: + e en femenino y + s en plural (un sac vert, une chaise verte, des chaises vertes). Blanc es irregular: blanche. Escucha la diferencia: en vert, petit y grand la consonante final no suena, pero en verte, petite y grande sí. En noir / noire y bleu / bleue no se oye ningún cambio. Petit y grand van antes del sustantivo: un petit livre, une grande table.","examples":[{"target":"La table est blanche.","base":"La mesa es blanca."},{"target":"C'est un petit livre vert.","base":"Es un libro verde chico."}]},"takeaways":["Haces concordar el adjetivo: vert, verte, verts, vertes.","Pones petit y grand antes del sustantivo y el color después."]},{"id":"fr-a1-u05-l05","unit_id":"fr-a1-u05","position":7,"title_es":"À vendre!","objective_es":"Entender y describir objetos con su color y su tamaño.","intro":{"explanation":"Ya puedes describir objetos completos: artículo + (petit / grand) + sustantivo + color, con concordancia. Una table blanche, des chaises noires, un grand sac rouge. Recuerda que la s del plural no suena: para saber si es uno o varios, escucha el artículo (le / les, un / des) y c'est / ce sont.","examples":[{"target":"Un grand sac rouge.","base":"Un bolso rojo grande."},{"target":"Ce sont des clés jaunes.","base":"Son llaves amarillas."}]},"takeaways":["Describes un objeto con su tamaño y su color.","Distingues singular y plural por el artículo, no por la s."]},{"id":"fr-a1-u06-l01","unit_id":"fr-a1-u06","position":1,"title_es":"La maison","objective_es":"Nombrar la casa, el apartamento y sus ambientes.","intro":{"explanation":"Las partes de la casa: la cuisine (la cocina), la salle de bains (el baño), le salon (la sala) y la chambre, que es un falso amigo: no es una cámara, es el dormitorio. Appartement empieza con vocal: l'appartement, un appartement. En bains, la s final no suena.","examples":[{"target":"C'est ma chambre.","base":"Es mi dormitorio."},{"target":"C'est un petit appartement.","base":"Es un apartamento chico."}]},"takeaways":["Nombras la casa y sus ambientes.","Recuerdas que la chambre es el dormitorio."]},{"id":"fr-a1-u06-l02","unit_id":"fr-a1-u06","position":2,"title_es":"Il y a, il n'y a pas de","objective_es":"Decir qué hay y qué no hay en una casa.","intro":{"explanation":"Il y a es hay, igual en singular y en plural: il y a un lit, il y a deux lits. Se dice en un solo bloque, casi como una palabra. En la negación, un / une / des pasan a de: il n'y a pas de porte (no hay puerta). Ojo con el género: le lit es masculino, aunque en español sea la cama.","examples":[{"target":"Il y a un lit et une table.","base":"Hay una cama y una mesa."},{"target":"Il n'y a pas de fenêtre.","base":"No hay ventana."}]},"takeaways":["Dices qué hay con il y a.","Dices qué no hay con il n'y a pas de, sin un / une."]},{"id":"fr-a1-u06-l03","unit_id":"fr-a1-u06","position":4,"title_es":"Où est…? Dans, sur, sous","objective_es":"Preguntar dónde está algo y responder con dans, sur y sous.","intro":{"explanation":"Para preguntar: où est…? (¿dónde está…?) y où sont…? en plural. Se responde con il / elle est + dans (adentro de), sur (sobre) o sous (debajo de). Escucha bien sur y sous: la u de sur se dice con los labios redondeados como para una u pero la lengua adelante, como para una i; la ou de sous es la u del español. Où lleva tilde para diferenciarse de ou (o), pero suenan igual.","examples":[{"target":"Où est le chat? — Il est sous le lit.","base":"¿Dónde está el gato? — Está debajo de la cama."},{"target":"Les clés sont sur la table.","base":"Las llaves están sobre la mesa."}]},"takeaways":["Preguntas dónde está algo con où est…?","Distingues sur y sous al escuchar y al hablar."]},{"id":"fr-a1-u06-l04","unit_id":"fr-a1-u06","position":5,"title_es":"À côté de, devant, derrière","objective_es":"Ubicar cosas y personas con à côté de, devant y derrière.","intro":{"explanation":"À côté de es al lado de. Ojo con la contracción: de + le se vuelve du (à côté du lit) y de + les, des; con la y l' no cambia (à côté de la porte, à côté de l'appartement). Devant (delante de) y derrière (detrás de) van directo, sin de: devant la maison, derrière la porte.","examples":[{"target":"La chaise est à côté du lit.","base":"La silla está al lado de la cama."},{"target":"Le chien est devant la porte.","base":"El perro está delante de la puerta."}]},"takeaways":["Ubicas algo con à côté de, devant y derrière.","Contraes de + le en du: à côté du lit."]},{"id":"fr-a1-u06-l05","unit_id":"fr-a1-u06","position":7,"title_es":"Chez moi","objective_es":"Describir una vivienda: qué ambientes tiene y dónde están las cosas.","intro":{"explanation":"Para describir dónde vives: j'habite dans un appartement / une maison, il y a… y il n'y a pas de… Después ubicas las cosas con las preposiciones: la cuisine est à côté du salon. Un dato cultural: en Francia muchos anuncios cuentan los ambientes sin el baño ni la cocina (un «trois pièces» tiene living y dos dormitorios).","examples":[{"target":"J'habite dans un petit appartement.","base":"Vivo en un apartamento chico."},{"target":"La cuisine est à côté du salon.","base":"La cocina está al lado de la sala."}]},"takeaways":["Describes tu casa con il y a y las preposiciones.","Entiendes un mensaje que describe una vivienda."]},{"id":"fr-a1-u07-l01","unit_id":"fr-a1-u07","position":1,"title_es":"Au café","objective_es":"Pedir algo en un café con je voudrais.","intro":{"explanation":"Para pedir con cortesía se usa je voudrais (quisiera) + un / une, y siempre s'il vous plaît. En Francia, un café es un espresso chico; le croissant es el cruasán. Pronunciación: en pain y en croissant la n no suena como n: la vocal sale por la nariz (es una vocal nasal).","examples":[{"target":"Je voudrais un café, s'il vous plaît.","base":"Quisiera un café, por favor."},{"target":"Un thé et un croissant, s'il vous plaît.","base":"Un té y un cruasán, por favor."}]},"takeaways":["Pides con je voudrais y s'il vous plaît.","Nombras el café, el té, el pan y el cruasán."]},{"id":"fr-a1-u07-l02","unit_id":"fr-a1-u07","position":2,"title_es":"Je mange, je bois","objective_es":"Decir qué comes y qué tomas con du, de la y de l'.","intro":{"explanation":"Para una cantidad que no se cuenta (pan, agua, queso) el francés usa el partitivo: du con masculinos, de la con femeninos y de l' delante de vocal. En español no se dice nada («como queso»), pero en francés hace falta: je mange du fromage. Con algo que se cuenta, un / une: je mange une pomme. Ojo con el género: l'eau es femenino y le lait, masculino (la leche). Eau suena como una o.","examples":[{"target":"Je bois de l'eau.","base":"Tomo agua."},{"target":"Je mange du fromage.","base":"Como queso."}]},"takeaways":["Usas du, de la o de l' con lo que no se cuenta.","Dices qué comes con je mange y qué tomas con je bois."]},{"id":"fr-a1-u07-l03","unit_id":"fr-a1-u07","position":4,"title_es":"Viande, poisson, légumes","objective_es":"Hablar de carne, pescado y verduras, y decir qué no comes.","intro":{"explanation":"En plural el partitivo es des: je mange des légumes. En la negación, du / de la / de l' / des pasan a de: je ne mange pas de viande, je ne bois pas de vin. Dos falsos amigos: le poisson es el pescado y les légumes son las verduras (no las legumbres). Vin, viande y pain tienen vocales nasales: la n no se pronuncia como n.","examples":[{"target":"Je mange des légumes.","base":"Como verduras."},{"target":"Je ne mange pas de viande.","base":"No como carne."}]},"takeaways":["Usas des con los plurales: des légumes.","Dices qué no comes con ne… pas de."]},{"id":"fr-a1-u07-l04","unit_id":"fr-a1-u07","position":5,"title_es":"Beaucoup, un peu","objective_es":"Pedir con je prends y hablar de cantidades.","intro":{"explanation":"Después de una cantidad el artículo desaparece y queda de (d' delante de vocal): beaucoup de légumes, un peu de lait, une bouteille d'eau. Je prends (tomo, pido) sirve para pedir en un café, igual que je voudrais pero más directo. La d de prends no suena.","examples":[{"target":"Je prends un thé avec un peu de lait.","base":"Tomo un té con un poco de leche."},{"target":"Une bouteille d'eau, s'il vous plaît.","base":"Una botella de agua, por favor."}]},"takeaways":["Usas beaucoup de y un peu de sin artículo.","Pides en un café con je prends o je voudrais."]},{"id":"fr-a1-u07-l05","unit_id":"fr-a1-u07","position":7,"title_es":"Le petit café","objective_es":"Leer una carta y pedir comida y bebida en un café.","intro":{"explanation":"En un café o un restaurante de Francia se pide con je voudrais o je prends, y siempre con s'il vous plaît. Un dato cultural: la carafe d'eau (una jarra de agua de la canilla) es gratis; si quieres agua mineral, pides une bouteille d'eau.","examples":[{"target":"Je prends du poisson et des légumes.","base":"Pido pescado y verduras."},{"target":"Une carafe d'eau, s'il vous plaît.","base":"Una jarra de agua, por favor."}]},"takeaways":["Entiendes una carta con precios.","Pides comida y bebida en un café."]},{"id":"fr-a1-u08-l01","unit_id":"fr-a1-u08","position":1,"title_es":"Le matin, le soir","objective_es":"Decir en qué momento del día te levantas y te acuestas.","intro":{"explanation":"Le matin es la mañana; l'après-midi, la tarde; le soir, la noche. Para decir «por la mañana» no hace falta preposición: le matin, je me lève. Se lever y se coucher son pronominales, como s'appeler: je me lève, tu te lèves, il / elle se lève. La s de tu te lèves no suena: lève y lèves se pronuncian igual.","examples":[{"target":"Le matin, je me lève.","base":"Por la mañana me levanto."},{"target":"Le soir, je me couche tard.","base":"Por la noche me acuesto tarde."}]},"takeaways":["Nombras los momentos del día: le matin, l'après-midi, le soir.","Dices je me lève y je me couche, con me como en je m'appelle."]},{"id":"fr-a1-u08-l02","unit_id":"fr-a1-u08","position":2,"title_es":"Je travaille, je regarde","objective_es":"Contar qué haces con verbos en -er (je, tu, il, elle).","intro":{"explanation":"Travailler, regarder y écouter son verbos en -er. En singular: je travaille, tu travailles, il / elle travaille. Las tres formas suenan igual, porque la -e y la -es finales no se pronuncian. Delante de vocal, je se vuelve j': j'écoute. Regarder es mirar (la télé, un livre).","examples":[{"target":"J'écoute la radio le matin.","base":"Escucho la radio por la mañana."},{"target":"Elle regarde la télé.","base":"Ella mira la tele."}]},"takeaways":["Conjugas un verbo en -er con je, tu, il y elle.","Sabes que travaille y travailles suenan igual y que je se vuelve j' delante de vocal."]},{"id":"fr-a1-u08-l03","unit_id":"fr-a1-u08","position":4,"title_es":"Nous, ils, on","objective_es":"Contar qué hacen otras personas con nous, vous, ils y on.","intro":{"explanation":"En plural: nous travaillons, vous travaillez, ils / elles travaillent. La -ent de ils travaillent no suena: se pronuncia igual que il travaille. On es muy común en lo oral y significa nosotros; va con el verbo como il: on regarde. Delante de vocal hay liaison con sonido z: nous‿écoutons, ils‿écoutent. Así se distingue ils écoutent de il écoute.","examples":[{"target":"Nous travaillons le matin.","base":"Trabajamos por la mañana."},{"target":"Ils écoutent la radio.","base":"Ellos escuchan la radio."}]},"takeaways":["Conjugas con nous (-ons), vous (-ez) e ils (-ent, que no suena).","Usas on como nosotros, con el verbo como il."]},{"id":"fr-a1-u08-l04","unit_id":"fr-a1-u08","position":5,"title_es":"D'abord, ensuite","objective_es":"Nombrar las comidas del día y contar las cosas en orden.","intro":{"explanation":"Ojo con el falso amigo: le petit-déjeuner es el desayuno, le déjeuner es el almuerzo (en Francia, cerca del mediodía) y le dîner es la cena (alrededor de las ocho). «En el desayuno» se dice au petit-déjeuner (à + le = au). Para ordenar: d'abord (primero), ensuite (después). Desayunar se puede decir je prends le petit-déjeuner.","examples":[{"target":"D'abord, je me lève. Ensuite, je prends le petit-déjeuner.","base":"Primero me levanto. Después desayuno."},{"target":"Au déjeuner, je mange du poisson.","base":"En el almuerzo como pescado."}]},"takeaways":["Distingues le petit-déjeuner, le déjeuner (el almuerzo) y le dîner.","Cuentas tu día en orden con d'abord y ensuite."]},{"id":"fr-a1-u08-l05","unit_id":"fr-a1-u08","position":7,"title_es":"Toujours, souvent","objective_es":"Decir con qué frecuencia haces las cosas.","intro":{"explanation":"Toujours (siempre) y souvent (seguido) van después del verbo: je bois toujours un café, il regarde souvent la télé. Tous les jours (todos los días) suele ir al final. En tous les jours, la s de tous no suena; no confundas tous les jours con toujours.","examples":[{"target":"Je bois toujours un café le matin.","base":"Siempre tomo un café por la mañana."},{"target":"Nous travaillons tous les jours.","base":"Trabajamos todos los días."}]},"takeaways":["Pones toujours y souvent después del verbo.","Distingues toujours (siempre) de tous les jours (todos los días)."]},{"id":"fr-a1-u09-l01","unit_id":"fr-a1-u09","position":1,"title_es":"Quelle heure est-il?","objective_es":"Preguntar y decir la hora en punto.","intro":{"explanation":"Para preguntar la hora: quelle heure est-il? (o, entre amigos, tu as l'heure?). Se responde con il est + número + heures: il est trois heures; a la una, il est une heure, en singular. Las doce del mediodía son midi y las de la noche, minuit, sin heures. Ojo con la liaison: deux‿heures y trois‿heures se unen con sonido z; en neuf heures la f suena como v.","examples":[{"target":"Quelle heure est-il? — Il est deux heures.","base":"¿Qué hora es? — Son las dos."},{"target":"Il est midi.","base":"Es mediodía."}]},"takeaways":["Preguntas quelle heure est-il? y respondes il est… heures.","Usas midi y minuit sin heures."]},{"id":"fr-a1-u09-l02","unit_id":"fr-a1-u09","position":2,"title_es":"Et quart, et demie","objective_es":"Decir la hora con cuartos y medias.","intro":{"explanation":"Después de la hora se agrega et quart (y cuarto), et demie (y media) o moins le quart (menos cuarto): il est huit heures et quart, il est dix heures moins le quart. Demie lleva e porque concuerda con heure, que es femenino; con midi y minuit se escribe et demi. En las dos formas suena igual.","examples":[{"target":"Il est sept heures et demie.","base":"Son las siete y media."},{"target":"Il est onze heures moins le quart.","base":"Son las once menos cuarto."}]},"takeaways":["Agregas et quart, et demie o moins le quart a la hora.","Escribes et demie con heures y et demi con midi y minuit."]},{"id":"fr-a1-u09-l03","unit_id":"fr-a1-u09","position":4,"title_es":"Lundi, mardi, mercredi","objective_es":"Nombrar los días de la semana.","intro":{"explanation":"Los días de la semana son masculinos y en francés se escriben con minúscula: lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche. Para un día concreto no se usa artículo: lundi, je travaille (el lunes trabajo). La semaine (la semana) es femenino.","examples":[{"target":"Lundi, je travaille.","base":"El lunes trabajo."},{"target":"Samedi et dimanche, je me lève tard.","base":"El sábado y el domingo me levanto tarde."}]},"takeaways":["Nombras los siete días, en minúscula.","Dices un día concreto sin artículo: lundi, je travaille."]},{"id":"fr-a1-u09-l04","unit_id":"fr-a1-u09","position":5,"title_es":"Aujourd'hui, demain, le week-end","objective_es":"Hablar de hoy, de mañana y de lo que haces cada semana.","intro":{"explanation":"Aujourd'hui es hoy y demain, mañana (el día siguiente; no lo confundas con le matin, la mañana). Con artículo, un día es una costumbre: le lundi, je travaille (todos los lunes). Lo mismo con le week-end. Para preguntar cuándo: quand? (la d final no suena): tu travailles quand?","examples":[{"target":"Aujourd'hui, c'est lundi.","base":"Hoy es lunes."},{"target":"Le dimanche, je ne travaille pas.","base":"Los domingos no trabajo."}]},"takeaways":["Dices aujourd'hui, demain y le week-end.","Usas le lundi para algo que haces todos los lunes y preguntas con quand?"]},{"id":"fr-a1-u09-l05","unit_id":"fr-a1-u09","position":7,"title_es":"À quelle heure?","objective_es":"Preguntar y decir a qué hora haces algo.","intro":{"explanation":"Para decir a qué hora pasa algo se usa à + hora: je me lève à sept heures, je mange à midi. La pregunta es à quelle heure? En lo oral suele ir al final: tu te lèves à quelle heure? Quelle va con e porque heure es femenino.","examples":[{"target":"Tu te lèves à quelle heure?","base":"¿A qué hora te levantas?"},{"target":"Je me couche à minuit.","base":"Me acuesto a medianoche."}]},"takeaways":["Preguntas à quelle heure? y respondes con à + hora.","Cuentas tu horario de la semana y del fin de semana."]},{"id":"fr-a1-u10-l01","unit_id":"fr-a1-u10","position":1,"title_es":"Je vais au cinéma","objective_es":"Decir adónde vas con je vais, tu vas, il va.","intro":{"explanation":"Aller (ir) es irregular: je vais, tu vas, il / elle va. Para decir adónde, se usa à: à la gare. Pero à + le se contrae en au: au cinéma, nunca «à le cinéma». La s de vas y la s de vais no suenan.","examples":[{"target":"Je vais au cinéma.","base":"Voy al cine."},{"target":"Tu vas à la gare?","base":"¿Vas a la estación?"}]},"takeaways":["Dices je vais, tu vas, il va.","Usas au con los masculinos (au cinéma) y à la con los femeninos (à la gare)."]},{"id":"fr-a1-u10-l02","unit_id":"fr-a1-u10","position":2,"title_es":"Nous allons, ils vont","objective_es":"Decir adónde van otras personas y nombrar negocios.","intro":{"explanation":"En plural: nous allons, vous allez, ils / elles vont. Hay liaison con sonido z: nous‿allons, vous‿allez. Ojo con ils vont (van) e ils sont (son, están): sólo cambia la primera consonante. Con un plural, à + les = aux: aux Galeries Lafayette. La boulangerie es la panadería, adonde en Francia se va casi todos los días.","examples":[{"target":"Nous allons à la boulangerie.","base":"Vamos a la panadería."},{"target":"Ils vont aux Galeries Lafayette.","base":"Van a las Galerías Lafayette."}]},"takeaways":["Conjugas nous allons, vous allez, ils vont.","Distingues ils vont de ils sont y usas aux con los plurales."]},{"id":"fr-a1-u10-l03","unit_id":"fr-a1-u10","position":4,"title_es":"Près de la gare","objective_es":"Decir dónde queda un lugar y si está cerca o lejos.","intro":{"explanation":"Ojo con el género: la banque (el banco) es femenino y le musée (el museo), masculino aunque termine en -ée. Para ubicar: près de (cerca de) y loin (lejos). De se contrae con le: de + le = du (près du musée); con la no cambia (près de la gare). Para preguntar: c'est loin?","examples":[{"target":"Le musée est près de la gare.","base":"El museo está cerca de la estación."},{"target":"C'est loin? — Non, c'est près.","base":"¿Queda lejos? — No, queda cerca."}]},"takeaways":["Dices la banque y le musée con el género correcto.","Ubicas un lugar con près de, du y loin."]},{"id":"fr-a1-u10-l04","unit_id":"fr-a1-u10","position":5,"title_es":"Tournez à gauche","objective_es":"Dar indicaciones simples con el imperativo.","intro":{"explanation":"Para indicar el camino a alguien que tratas de vous se usa el imperativo, que es el verbo sin el pronombre: tournez (doble), allez (vaya), prenez (tome). Con à gauche (a la izquierda), à droite (a la derecha) y tout droit (derecho). Ojo: en tout droit la t final no suena; en à droite, sí, porque va seguida de e.","examples":[{"target":"Allez tout droit.","base":"Vaya derecho."},{"target":"Tournez à droite après la banque.","base":"Doble a la derecha después del banco."}]},"takeaways":["Das indicaciones con tournez, allez y prenez.","Distingues tout droit (derecho) de à droite (a la derecha)."]},{"id":"fr-a1-u10-l05","unit_id":"fr-a1-u10","position":7,"title_es":"Où est la pharmacie?","objective_es":"Pedir y entender una indicación en la calle.","intro":{"explanation":"Para pedir una indicación, primero se saluda o se dice pardon: pardon, madame, où est la gare, s'il vous plaît? La respuesta encadena indicaciones con ensuite: allez tout droit, ensuite tournez à gauche. Y para saber si queda a mano: c'est loin?","examples":[{"target":"Pardon, monsieur. Où est la banque, s'il vous plaît?","base":"Disculpe, señor. ¿Dónde está el banco, por favor?"},{"target":"Allez tout droit, ensuite tournez à gauche.","base":"Vaya derecho y después doble a la izquierda."}]},"takeaways":["Pides una indicación con pardon y s'il vous plaît.","Entiendes y das un camino corto con ensuite."]},{"id":"fr-a1-u11-l01","unit_id":"fr-a1-u11","position":1,"title_es":"J'aime, je déteste","objective_es":"Decir qué te gusta, qué te encanta y qué odias.","intro":{"explanation":"Para los gustos: j'aime (me gusta), j'adore (me encanta), je déteste (odio). Para preguntar: tu aimes…? Van con el artículo definido, como en español: j'aime la musique, tu aimes le sport? Para negar, ne… pas alrededor del verbo (ne se vuelve n' delante de vocal): je n'aime pas. Y pas du tout es «para nada». Pronunciación: j'aime y tu aimes suenan igual, porque la es final no suena.","examples":[{"target":"J'aime la musique.","base":"Me gusta la música."},{"target":"Tu aimes le sport? — Non, pas du tout.","base":"¿Te gusta el deporte? — No, para nada."}]},"takeaways":["Dices tus gustos con j'aime, j'adore y je déteste + le / la.","Niegas con je n'aime pas y refuerzas con pas du tout."]},{"id":"fr-a1-u11-l02","unit_id":"fr-a1-u11","position":2,"title_es":"Lire, danser, voyager","objective_es":"Decir qué actividades te gustan y cuáles prefieres.","intro":{"explanation":"Después de aimer, adorer, détester y préférer puede ir un verbo en infinitivo, sin preposición: j'aime lire, j'adore danser. Muchos infinitivos terminan en -er, y la r final no suena: danser, voyager, cuisiner. Ojo con je préfère: la primera e lleva tilde aguda (é, cerrada) y la segunda, grave (è, abierta).","examples":[{"target":"J'aime lire.","base":"Me gusta leer."},{"target":"Je préfère voyager.","base":"Prefiero viajar."}]},"takeaways":["Usas aimer, adorer o préférer + infinitivo: j'aime lire.","Dices qué prefieres con je préfère."]},{"id":"fr-a1-u11-l03","unit_id":"fr-a1-u11","position":4,"title_es":"Je fais du sport","objective_es":"Preguntar y decir qué haces en tu tiempo libre.","intro":{"explanation":"Faire es hacer: je fais, tu fais, il fait. Las tres formas suenan igual: la s y la t finales no se pronuncian. Para preguntar: qu'est-ce que tu fais? Con actividades se usa du (de + le) o de la: je fais du sport. Con aimer, en cambio, va le: j'aime le sport. Avec es con: avec Hugo, avec mon frère.","examples":[{"target":"Qu'est-ce que tu fais le week-end?","base":"¿Qué haces el fin de semana?"},{"target":"Je fais du sport avec Hugo.","base":"Hago deporte con Hugo."}]},"takeaways":["Preguntas qu'est-ce que tu fais? y respondes je fais…","Dices je fais du sport, pero j'aime le sport."]},{"id":"fr-a1-u11-l04","unit_id":"fr-a1-u11","position":5,"title_es":"Jouer au foot, jouer de la guitare","objective_es":"Decir qué deporte juegas y qué instrumento tocas.","intro":{"explanation":"Jouer es jugar y también tocar un instrumento, pero cambia la preposición. Con deportes, jouer à: à + le = au (je joue au foot, au tennis). Con instrumentos, jouer de: de la guitare, du piano (de + le = du). El foot es el deporte más popular de Francia.","examples":[{"target":"Je joue au foot.","base":"Juego al fútbol."},{"target":"Elle joue de la guitare.","base":"Ella toca la guitarra."}]},"takeaways":["Dices jouer au + deporte: je joue au foot.","Dices jouer de la / du + instrumento: je joue de la guitare."]},{"id":"fr-a1-u11-l05","unit_id":"fr-a1-u11","position":7,"title_es":"Mi tiempo libre","objective_es":"Contar qué te gusta hacer y qué no, y preguntarle a otra persona.","intro":{"explanation":"Para hablar de tu tiempo libre combinas todo: j'aime + le / la o + infinitivo, je fais du sport, je joue au foot. En la negación el artículo no cambia: je n'aime pas le foot. Con ils y elles hay liaison: en ils aiment, la s se une a la vocal con un sonido z; en il aime no hay ningún sonido z.","examples":[{"target":"Ils aiment le foot.","base":"A ellos les gusta el fútbol."},{"target":"Je n'aime pas le foot, je préfère la musique.","base":"No me gusta el fútbol, prefiero la música."}]},"takeaways":["Cuentas qué te gusta y qué no con j'aime, je n'aime pas y je préfère.","Distingues il aime de ils aiment por la liaison con sonido z."]},{"id":"fr-a1-u12-l01","unit_id":"fr-a1-u12","position":1,"title_es":"Qui, qu'est-ce que, comment","objective_es":"Hacer preguntas de tres maneras y preguntar quién, qué y cómo.","intro":{"explanation":"Una pregunta de sí o no se hace de tres maneras: con la entonación (tu parles français?, lo más común al hablar), con est-ce que (est-ce que tu parles français?) o con inversión (parles-tu français?, más formal). Para pedir información: qui es quién, qu'est-ce que es qué y comment es cómo. En qui y en qu'est-ce que, qu suena como una k.","examples":[{"target":"Est-ce que tu parles français?","base":"¿Hablas francés?"},{"target":"Parles-tu français?","base":"¿Hablas francés? (formal)"},{"target":"Qui est-ce? — C'est ma sœur.","base":"¿Quién es? — Es mi hermana."}]},"takeaways":["Preguntas sí o no con la entonación, con est-ce que o con inversión.","Preguntas quién, qué y cómo con qui, qu'est-ce que y comment."]},{"id":"fr-a1-u12-l02","unit_id":"fr-a1-u12","position":2,"title_es":"Pourquoi? Parce que…","objective_es":"Preguntar y explicar por qué, y preguntar cuál con quel.","intro":{"explanation":"Pourquoi es por qué (una palabra) y se responde con parce que (dos palabras): es al revés que en español. Delante de vocal, parce que se vuelve parce qu': parce qu'il… Quel va delante de un sustantivo y concuerda con él: quel sac, quelle couleur (quels, quelles en plural). Las cuatro formas suenan igual.","examples":[{"target":"Pourquoi tu aimes Lyon? — Parce que c'est une grande ville.","base":"¿Por qué te gusta Lyon? — Porque es una ciudad grande."},{"target":"Quelle couleur tu préfères?","base":"¿Qué color prefieres?"}]},"takeaways":["Preguntas pourquoi? y respondes parce que…","Usas quel o quelle según el género del sustantivo."]},{"id":"fr-a1-u12-l03","unit_id":"fr-a1-u12","position":4,"title_es":"De treize à cent","objective_es":"Entender y decir números hasta 100.","intro":{"explanation":"Las decenas: trente, quarante, cinquante, soixante. Después, el francés de Francia suma y multiplica: 70 es soixante-dix (60 + 10), 80 es quatre-vingts (4 × 20) y 90, quatre-vingt-dix. Con 1 se dice et un: trente et un; con los demás, guion: trente-cinq. Cent es 100. En Bélgica y Suiza se dice septante (70) y nonante (90). Ojo al escuchar: treize, trente y trois se parecen, igual que quinze y cinq.","examples":[{"target":"J'ai quinze ans.","base":"Tengo quince años."},{"target":"Mon grand-père a soixante-dix ans.","base":"Mi abuelo tiene setenta años."}]},"takeaways":["Cuentas de diez en diez hasta cent.","Armas soixante-dix y quatre-vingts sumando y multiplicando."]},{"id":"fr-a1-u12-l04","unit_id":"fr-a1-u12","position":5,"title_es":"C'est combien?","objective_es":"Buscar algo en una tienda y preguntar el precio.","intro":{"explanation":"Al entrar a un magasin (falso amigo: es la tienda) se saluda con bonjour. Para pedir: je cherche + lo que buscas. Para el precio: c'est combien? Con euros hay liaison: deux euros y trois euros se unen con un sonido z; vingt euros y cent euros, con un sonido t. Y si es mucho: c'est cher!","examples":[{"target":"Bonjour! Je cherche un sac.","base":"¡Buenos días! Busco un bolso."},{"target":"C'est combien? — Trente euros.","base":"¿Cuánto cuesta? — Treinta euros."}]},"takeaways":["Pides lo que buscas con je cherche.","Preguntas el precio con c'est combien? y entiendes la respuesta en euros."]},{"id":"fr-a1-u12-l05","unit_id":"fr-a1-u12","position":7,"title_es":"De compras","objective_es":"Comprar, comparar precios y preguntar cuántos.","intro":{"explanation":"Combien sirve para el precio y para la cantidad: combien de + sustantivo, sin artículo (combien de livres?). Para comparar: c'est cher, ce n'est pas cher. Y para elegir: quel sac? quelle couleur? Recuerda que en un magasin se usa vous y se saluda al entrar y al salir.","examples":[{"target":"Tu as combien de livres?","base":"¿Cuántos libros tienes?"},{"target":"Le stylo? Ce n'est pas cher.","base":"¿El bolígrafo? No es caro."}]},"takeaways":["Preguntas cuántos con combien de + sustantivo.","Compras en una tienda: buscas, preguntas el precio y eliges."]},{"id":"fr-a1-u13-l01","unit_id":"fr-a1-u13","position":1,"title_es":"Qu'est-ce que tu fais dans la vie?","objective_es":"Preguntar y decir a qué se dedica alguien.","intro":{"explanation":"Para preguntar la profesión: qu'est-ce que tu fais dans la vie? (literalmente, «¿qué haces en la vida?»). Se responde con je suis + profesión, sin artículo: je suis médecin, nunca «je suis un médecin». Con c'est, en cambio, sí va el artículo: c'est un médecin. Médecin sirve también para una mujer: elle est médecin.","examples":[{"target":"Qu'est-ce que tu fais dans la vie? — Je suis professeur.","base":"¿A qué te dedicas? — Soy profesor."},{"target":"Ma sœur est médecin.","base":"Mi hermana es médica."}]},"takeaways":["Preguntas la profesión con qu'est-ce que tu fais dans la vie?","Dices je suis médecin sin artículo, pero c'est un médecin."]},{"id":"fr-a1-u13-l02","unit_id":"fr-a1-u13","position":2,"title_es":"Serveur, serveuse","objective_es":"Decir profesiones en masculino y femenino.","intro":{"explanation":"Muchas profesiones cambian en femenino: -eur pasa a -euse (serveur, serveuse; vendeur, vendeuse), -ier a -ière (infirmier, infirmière) y -er a -ère (boulanger, boulangère). En el femenino la r final suena: boulangère, infirmière; en boulanger e infirmier, no. Médecin no cambia.","examples":[{"target":"Il est serveur et elle est serveuse.","base":"Él es mesero y ella es mesera."},{"target":"Mon père est boulanger.","base":"Mi papá es panadero."}]},"takeaways":["Formas el femenino: serveuse, vendeuse, infirmière, boulangère.","Oyes la r final en el femenino: boulangère."]},{"id":"fr-a1-u13-l03","unit_id":"fr-a1-u13","position":4,"title_es":"Au bureau, à l'hôpital","objective_es":"Decir dónde trabaja alguien.","intro":{"explanation":"Para el lugar de trabajo: à l'hôpital, à l'école, au bureau (à + le = au) o dans une entreprise. Falso amigo: le bureau es la oficina (y también el escritorio). Delante de h muda hay elisión: l'hôpital. Le travail es el trabajo; je travaille, trabajo.","examples":[{"target":"Je travaille au bureau.","base":"Trabajo en la oficina."},{"target":"Il est infirmier à l'hôpital.","base":"Es enfermero en el hospital."}]},"takeaways":["Dices dónde trabajas: au bureau, à l'hôpital, dans une entreprise.","Recuerdas que le bureau es la oficina."]},{"id":"fr-a1-u13-l04","unit_id":"fr-a1-u13","position":5,"title_es":"Nous sommes, ils ont","objective_es":"Usar être y avoir en plural.","intro":{"explanation":"Être: je suis, tu es, il est, nous sommes, vous êtes, ils sont. Avoir: j'ai, tu as, il a, nous avons, vous avez, ils ont. Con elles es igual: elles sont, elles ont. Ojo con la liaison: en ils ont y en nous avons, la s se une a la vocal con un sonido z; en ils sont se oye una s. La profesión sigue sin artículo en plural: ils sont serveurs.","examples":[{"target":"Nous sommes étudiants.","base":"Somos estudiantes."},{"target":"Ils ont deux enfants.","base":"Tienen dos hijos."}]},"takeaways":["Conjugas être y avoir con nous, ils y elles.","Distingues ils ont (sonido z) de ils sont (sonido s)."]},{"id":"fr-a1-u13-l05","unit_id":"fr-a1-u13","position":7,"title_es":"Je commence, je finis","objective_es":"Decir a qué hora empiezas y terminas de trabajar.","intro":{"explanation":"Je commence es un verbo en -er, como je parle. Je finis es un verbo en -ir: je finis, tu finis, il finit; las tres formas suenan igual. Con la hora: je commence à neuf heures, je finis à cinq heures. En Francia, la jornada legal es de 35 horas por semana.","examples":[{"target":"Je commence à neuf heures.","base":"Empiezo a las nueve."},{"target":"Il finit à six heures.","base":"Él termina a las seis."}]},"takeaways":["Dices a qué hora empiezas con je commence à…","Conjugas je finis, tu finis, il finit."]},{"id":"fr-a1-u14-l01","unit_id":"fr-a1-u14","position":1,"title_es":"Comment est-il?","objective_es":"Preguntar cómo es alguien y describirlo como joven, viejo o lindo.","intro":{"explanation":"Para preguntar cómo es una persona: comment est-il? (él) o comment est-elle? (ella). El verbo va antes del pronombre y se une con un guion (inversión). Respondes con il est / elle est + adjetivo; muy es très. El adjetivo concuerda: beau → belle, vieux → vieille; jeune no cambia. Con personas, grand es alto y petit, bajo.","examples":[{"target":"Comment est-il? — Il est grand et beau.","base":"¿Cómo es? — Es alto y lindo."},{"target":"Elle est très jeune.","base":"Es muy joven."}]},"takeaways":["Preguntas comment est-il? o comment est-elle?","Describes con il est / elle est + jeune, vieux, beau y très."]},{"id":"fr-a1-u14-l02","unit_id":"fr-a1-u14","position":2,"title_es":"Les cheveux et les yeux","objective_es":"Describir el pelo, los ojos y la figura de una persona.","intro":{"explanation":"Para el pelo y los ojos se usa avoir + les: elle a les cheveux longs (tiene el pelo largo), il a les yeux bleus. Cheveux va siempre en plural, y el adjetivo también: longs, courts, blonds. Yeux es el plural irregular de œil; les se une a yeux con liaison, con un sonido z. Ojos marrones: les yeux marron (marron no cambia). Mince es delgado y assez, bastante.","examples":[{"target":"Elle a les cheveux longs et blonds.","base":"Tiene el pelo largo y rubio."},{"target":"Il a les yeux bleus.","base":"Tiene los ojos azules."}]},"takeaways":["Describes el pelo y los ojos con avoir les cheveux / les yeux.","Usas mince y assez para la figura."]},{"id":"fr-a1-u14-l03","unit_id":"fr-a1-u14","position":4,"title_es":"Gentil, drôle, timide","objective_es":"Describir el carácter de una persona.","intro":{"explanation":"Para el carácter: sympa (simpático, igual en femenino), gentil (¡falso amigo!: amable), drôle (gracioso, divertido), timide, sérieux y sportif. En femenino: gentille, sérieuse, sportive. En gentil la l final no suena; en gentille, -ille suena como una y (gentiy). En sportive, la f del masculino se vuelve v. Pero (para contrastar) es mais.","examples":[{"target":"Hugo est très drôle.","base":"Hugo es muy gracioso."},{"target":"Elle est gentille et un peu timide.","base":"Es amable y un poco tímida."}]},"takeaways":["Describes el carácter con sympa, gentil, drôle, timide, sérieux y sportif.","Recuerdas que gentil es amable y drôle, gracioso."]},{"id":"fr-a1-u14-l04","unit_id":"fr-a1-u14","position":5,"title_es":"Un beau garçon, une fille sportive","objective_es":"Ubicar el adjetivo antes o después del sustantivo y usar los femeninos irregulares.","intro":{"explanation":"Como en español, la mayoría de los adjetivos va después del sustantivo: un chat noir, une fille sportive. Pero beau, jeune, vieux, petit y grand van antes: un beau garçon, une jeune femme, un vieux chien. Y concuerdan: une belle maison, une vieille table.","examples":[{"target":"C'est un beau garçon.","base":"Es un chico lindo."},{"target":"C'est une jeune femme très sympa.","base":"Es una mujer joven muy simpática."}]},"takeaways":["Pones beau, jeune, vieux, petit y grand antes del sustantivo.","Usas belle, vieille, gentille, sportive y sérieuse con el femenino."]},{"id":"fr-a1-u14-l05","unit_id":"fr-a1-u14","position":7,"title_es":"Describir a alguien","objective_es":"Describir a una persona completa: físico y carácter.","intro":{"explanation":"Para describir a alguien, combinas todo: elle est grande et mince, elle a les cheveux blonds, elle est très gentille. Escucha el final del adjetivo: en el masculino la consonante final no suena (blond, brun, court) y en el femenino sí (blonde, courte); brune suena distinto de brun, que tiene vocal nasal.","examples":[{"target":"Elle est blonde et assez grande.","base":"Es rubia y bastante alta."},{"target":"Il est brun, il a les yeux marron.","base":"Es morocho, tiene los ojos marrones."}]},"takeaways":["Describes a una persona con su físico y su carácter.","Distingues al oído el masculino y el femenino: blond / blonde."]},{"id":"fr-a1-u15-l01","unit_id":"fr-a1-u15","position":1,"title_es":"De janvier à juin","objective_es":"Decir los meses de enero a junio y usar en + mes.","intro":{"explanation":"Los meses en francés son masculinos y se escriben con minúscula: janvier, février, mars, avril, mai, juin. «En mayo» es en mai, sin artículo. Pronunciación: en mars la s final sí suena (es una excepción), y en avril también suena la l. Juin termina en vocal nasal. Le mois es el mes.","examples":[{"target":"Je vais à Paris en avril.","base":"Voy a París en abril."},{"target":"Mai est un beau mois.","base":"Mayo es un mes lindo."}]},"takeaways":["Dices los meses de janvier a juin, con minúscula.","Usas en + mes: en mai, en juin."]},{"id":"fr-a1-u15-l02","unit_id":"fr-a1-u15","position":2,"title_es":"De juillet à décembre","objective_es":"Decir los meses de julio a diciembre y hablar del año.","intro":{"explanation":"Los otros seis meses: juillet, août, septembre, octobre, novembre, décembre. En août no suenan la a ni, casi siempre, la t final: sólo se oye la vocal ou. En juillet la t final no suena. L'année es el año (femenino: une année); con números se usa an: vingt ans. En Francia las vacaciones de verano son en julio y agosto, y las clases empiezan en septiembre.","examples":[{"target":"En août, nous allons à Marseille.","base":"En agosto vamos a Marsella."},{"target":"Il y a douze mois dans une année.","base":"Un año tiene doce meses."}]},"takeaways":["Dices los meses de juillet a décembre.","Usas le mois y l'année."]},{"id":"fr-a1-u15-l03","unit_id":"fr-a1-u15","position":4,"title_es":"Quelle est la date?","objective_es":"Preguntar y decir la fecha.","intro":{"explanation":"Para preguntar la fecha: quelle est la date? Se responde nous sommes le + número + mes, o c'est le…: nous sommes le 10 mars. No va «de» entre el número y el mes. Sólo el día 1 es distinto: le premier (el primero): le premier mai. Ojo con deux y douze: en douze la vocal es como una u y la z final suena.","examples":[{"target":"Quelle est la date? — Nous sommes le 3 mars.","base":"¿Qué fecha es? — Es 3 de marzo."},{"target":"C'est le premier mai.","base":"Es primero de mayo."}]},"takeaways":["Preguntas quelle est la date? y respondes nous sommes le…","Dices le premier para el día 1 y el número para los demás."]},{"id":"fr-a1-u15-l04","unit_id":"fr-a1-u15","position":5,"title_es":"Joyeux anniversaire!","objective_es":"Preguntar y decir cuándo es un cumpleaños y saludar.","intro":{"explanation":"Falso amigo: l'anniversaire es el cumpleaños (masculino, con elisión: l'anniversaire; mi cumpleaños es mon anniversaire). Para preguntar: c'est quand, ton anniversaire? Se responde c'est le 3 mars o c'est en mars. Para saludar a quien cumple años: joyeux anniversaire!","examples":[{"target":"C'est quand, ton anniversaire? — C'est le deux juin.","base":"¿Cuándo es tu cumpleaños? — Es el 2 de junio."},{"target":"Joyeux anniversaire, Léa!","base":"¡Feliz cumpleaños, Léa!"}]},"takeaways":["Preguntas c'est quand, ton anniversaire? y respondes con la fecha.","Saludas con joyeux anniversaire!"]},{"id":"fr-a1-u15-l05","unit_id":"fr-a1-u15","position":7,"title_es":"Fechas francesas","objective_es":"Entender y decir fechas importantes del año en Francia.","intro":{"explanation":"Dos fechas muy francesas: le 14 juillet, la fiesta nacional, con desfile y fuegos artificiales, y le 21 juin, la Fête de la musique, con música gratis en las calles de todo el país. Repaso: en + mes (en juin), le + número + mes (le 21 juin) y le premier para el día 1.","examples":[{"target":"Le 14 juillet, nous sommes à Paris.","base":"El 14 de julio estamos en París."},{"target":"Le 21 juin, c'est la Fête de la musique.","base":"El 21 de junio es la Fiesta de la Música."}]},"takeaways":["Conoces el 14 de julio y la Fête de la musique.","Lees y escribes fechas con le, en y le premier."]},{"id":"fr-a1-u16-l01","unit_id":"fr-a1-u16","position":1,"title_es":"Quel temps fait-il?","objective_es":"Preguntar qué tiempo hace y responder con il fait.","intro":{"explanation":"Para el clima, el francés usa il fait + adjetivo, como el «hace» del español pero con un adjetivo: il fait beau (hace buen tiempo), il fait mauvais (hace mal tiempo), il fait froid, il fait chaud. Para preguntar: quel temps fait-il?, con inversión como en comment est-il? La t de fait no suena, ni la d final de froid y chaud.","examples":[{"target":"Quel temps fait-il? — Il fait beau.","base":"¿Qué tiempo hace? — Hace buen tiempo."},{"target":"Aujourd'hui, il fait très chaud.","base":"Hoy hace mucho calor."}]},"takeaways":["Preguntas quel temps fait-il?","Respondes con il fait beau, mauvais, froid o chaud."]},{"id":"fr-a1-u16-l02","unit_id":"fr-a1-u16","position":2,"title_es":"Il pleut, il neige","objective_es":"Hablar de la lluvia, la nieve, el sol y el viento.","intro":{"explanation":"La lluvia y la nieve tienen verbo propio: il pleut (llueve) e il neige (nieva). Con el sol y el viento se usa il y a du: il y a du soleil (hay sol), il y a du vent (hay viento). La pluie es la lluvia. Ojo al oído: vent tiene la vocal nasal de blanc y vin, la de pain: il y a du vent no es il y a du vin.","examples":[{"target":"Il pleut à Paris.","base":"Llueve en París."},{"target":"Il y a du soleil et du vent.","base":"Hay sol y viento."}]},"takeaways":["Dices il pleut e il neige.","Usas il y a du soleil e il y a du vent."]},{"id":"fr-a1-u16-l03","unit_id":"fr-a1-u16","position":4,"title_es":"Les saisons","objective_es":"Nombrar las estaciones y decir qué tiempo hace en cada una.","intro":{"explanation":"Las cuatro estaciones son masculinas: le printemps (la primavera, ¡masculino!), l'été, l'automne, l'hiver. «En verano» es en été, y lo mismo en automne, en hiver: la n de en se une a la vocal siguiente (liaison). Pero printemps empieza con consonante: au printemps. En automne, la m no suena.","examples":[{"target":"En hiver, il neige.","base":"En invierno nieva."},{"target":"Au printemps, il fait beau.","base":"En primavera hace buen tiempo."}]},"takeaways":["Nombras le printemps, l'été, l'automne y l'hiver.","Dices en été, en automne, en hiver, pero au printemps."]},{"id":"fr-a1-u16-l04","unit_id":"fr-a1-u16","position":5,"title_es":"La mer ou la montagne?","objective_es":"Hablar de la playa, el mar y la montaña, y decir qué prefieres.","intro":{"explanation":"Ojo con el género: la mer (el mar) es femenino en francés. Mer y mère (madre) suenan igual. La montagne es la montaña y la plage, la playa. Para decir adónde vas: je vais à la mer, à la montagne, à la plage. Para elegir: tu préfères la mer ou la montagne?","examples":[{"target":"En été, je vais à la mer.","base":"En verano voy al mar."},{"target":"Nous allons à la montagne en hiver.","base":"En invierno vamos a la montaña."}]},"takeaways":["Dices la mer, la montagne y la plage, todas femeninas.","Cuentas adónde vas con je vais à la…"]},{"id":"fr-a1-u16-l05","unit_id":"fr-a1-u16","position":7,"title_es":"Julio: ¿verano o invierno?","objective_es":"Describir el clima de un lugar y entender la diferencia de hemisferios.","intro":{"explanation":"Francia está en el hemisferio norte: allí julio y agosto son verano y hace calor, mientras que en la Argentina es invierno. Por eso un francés dice en juillet, il fait chaud, y tú, en juillet, il fait froid. Recuerda: il fait + adjetivo, il pleut, il neige, il y a du soleil / du vent.","examples":[{"target":"En France, il fait chaud en juillet.","base":"En Francia hace calor en julio."},{"target":"En Argentine, en juillet, c'est l'hiver.","base":"En la Argentina, en julio, es invierno."}]},"takeaways":["Describes el clima de un lugar y de una estación.","Sabes que en julio es verano en Francia e invierno en la Argentina."]},{"id":"fr-a1-u17-l01","unit_id":"fr-a1-u17","position":1,"title_es":"En bus, en train, à pied","objective_es":"Nombrar los medios de transporte y decir cómo vas a un lugar.","intro":{"explanation":"Para decir cómo viajas, con los transportes con motor se usa en: en bus, en train, en voiture, en avion, en métro. Pero se dice à pied y à vélo. Ojo con la pronunciación: en bus la s final sí suena (es una excepción), y en en avion hay liaison: la n de en se une con la a de avion.","examples":[{"target":"Je vais à la gare en bus.","base":"Voy a la estación en autobús."},{"target":"Je vais au travail à pied.","base":"Voy al trabajo a pie."}]},"takeaways":["Dices en bus, en train, en voiture, en avion y en métro.","Pero dices à pied y à vélo."]},{"id":"fr-a1-u17-l02","unit_id":"fr-a1-u17","position":2,"title_es":"Je prends le train","objective_es":"Conjugar prendre y comprar un pasaje.","intro":{"explanation":"Prendre (tomar) es irregular. Je prends, tu prends e il prend suenan igual: la s y la d finales no se pronuncian y termina en una vocal nasal. En plural cambia: nous prenons, vous prenez, ils prennent (en ils prennent suena la doble n). Le billet es el pasaje o la entrada (y también el billete de dinero). Maintenant es ahora.","examples":[{"target":"Nous prenons le train.","base":"Tomamos el tren."},{"target":"Ils prennent le métro maintenant.","base":"Ahora ellos toman el metro."}]},"takeaways":["Conjugas prendre: je prends, nous prenons, ils prennent.","Pides un billet pour Lyon, s'il vous plaît."]},{"id":"fr-a1-u17-l03","unit_id":"fr-a1-u17","position":4,"title_es":"Je vais partir","objective_es":"Contar planes con aller + infinitivo.","intro":{"explanation":"Para hablar de un plan cercano se usa aller en presente + infinitivo, igual que «ir a» en español: je vais partir, tu vas rester, il va visiter. Entre amigos, on va + infinitivo es la forma más común de decir «vamos a»: on va prendre le train. En la negación, ne… pas rodea a aller: je ne vais pas partir. Ojo: rester es quedarse, no «restar».","examples":[{"target":"Je vais partir demain.","base":"Me voy a ir mañana."},{"target":"On va visiter le musée.","base":"Vamos a visitar el museo."}]},"takeaways":["Cuentas un plan con aller + infinitivo: je vais partir.","Dices «vamos a…» con on va: on va rester."]},{"id":"fr-a1-u17-l04","unit_id":"fr-a1-u17","position":5,"title_es":"Ce soir, ce week-end","objective_es":"Ubicar los planes en el tiempo.","intro":{"explanation":"Ce soir es esta noche; ce week-end, este fin de semana; la semaine prochaine, la semana que viene (prochaine va después de semaine). No confundas ce soir (esta noche) con le soir (por la noche, todos los días). Con estos marcadores se usa el futuro próximo: ce soir, je vais rester à la maison.","examples":[{"target":"Ce soir, on va au cinéma.","base":"Esta noche vamos al cine."},{"target":"La semaine prochaine, je vais partir.","base":"La semana que viene me voy a ir."}]},"takeaways":["Ubicas un plan con ce soir, ce week-end o la semaine prochaine.","Distingues ce soir (esta noche) de le soir (todas las noches)."]},{"id":"fr-a1-u17-l05","unit_id":"fr-a1-u17","position":7,"title_es":"Les vacances","objective_es":"Hablar de un viaje y de las vacaciones.","intro":{"explanation":"Les vacances va siempre en plural (la s final no suena): partir en vacances es irse de vacaciones. Le voyage es el viaje y voyager, el verbo. Para despedir a alguien que viaja: bon voyage! En Francia muchas familias se van de vacaciones en julio o en agosto.","examples":[{"target":"Bon voyage!","base":"¡Buen viaje!"},{"target":"En août, on va partir en vacances.","base":"En agosto nos vamos a ir de vacaciones."}]},"takeaways":["Dices les vacances siempre en plural: partir en vacances.","Despides a un viajero con bon voyage!"]},{"id":"fr-a2-u01-l01","unit_id":"fr-a2-u01","position":1,"title_es":"Hier, j'ai mangé","objective_es":"Contar qué hiciste ayer con verbos en -er.","intro":{"explanation":"El passé composé cuenta acciones terminadas: avoir en presente + participio. Los verbos en -er hacen el participio en -é: manger → mangé, parler → parlé, regarder → regardé. Hier es ayer; le week-end dernier, el fin de semana pasado (dernier va después). Escucha la diferencia: je parle termina en l; j'ai parlé termina en é y empieza con j'ai.","examples":[{"target":"Hier, j'ai mangé avec Léa.","base":"Ayer comí con Léa."},{"target":"Le week-end dernier, j'ai parlé avec ma mère.","base":"El fin de semana pasado hablé con mi mamá."}]},"takeaways":["Cuentas el pasado con j'ai + participio: j'ai mangé.","Distingues je parle (presente) de j'ai parlé (pasado)."]},{"id":"fr-a2-u01-l02","unit_id":"fr-a2-u01","position":2,"title_es":"J'ai fini, j'ai lu","objective_es":"Contar el pasado con participios en -i y en -u.","intro":{"explanation":"Los verbos en -ir hacen el participio en -i: finir → fini, dormir → dormi. Varios verbos irregulares terminan en -u: boire → bu, lire → lu, voir → vu. Cuidado con j'ai bu y j'ai vu: la b se hace con los dos labios y la v, con los dientes sobre el labio de abajo. Y la u de vu no es la ou de vous: se dice con los labios redondeados, como para silbar.","examples":[{"target":"J'ai lu un livre.","base":"Leí un libro."},{"target":"J'ai bu un café.","base":"Tomé un café."}]},"takeaways":["Usas los participios fini, dormi, bu, lu y vu.","Distingues j'ai bu de j'ai vu."]},{"id":"fr-a2-u01-l03","unit_id":"fr-a2-u01","position":4,"title_es":"Faire les courses, faire le ménage","objective_es":"Contar las tareas de la casa con fait y pris.","intro":{"explanation":"Faire y prendre tienen participios irregulares: faire → fait, prendre → pris. Faire les courses es hacer las compras (de la comida): falso amigo, no tiene nada que ver con carreras. Faire le ménage es limpiar la casa y ranger, ordenar (j'ai rangé ma chambre). Escucha la diferencia: je fais les courses (presente) y j'ai fait les courses (pasado).","examples":[{"target":"Samedi, j'ai fait les courses.","base":"El sábado hice las compras."},{"target":"Hier, j'ai pris le métro.","base":"Ayer tomé el metro."}]},"takeaways":["Cuentas lo que hiciste con j'ai fait y j'ai pris.","Dices faire les courses (compras) y faire le ménage (limpieza)."]},{"id":"fr-a2-u01-l04","unit_id":"fr-a2-u01","position":5,"title_es":"Déjà ou pas encore?","objective_es":"Decir lo que no hiciste y preguntar si alguien ya hizo algo.","intro":{"explanation":"En la negación del passé composé, ne… pas rodea al auxiliar, no al participio: je n'ai pas mangé (ne se vuelve n' delante de vocal). Déjà (ya) va entre el auxiliar y el participio: tu as déjà mangé? Para responder «todavía no»: non, pas encore, o completo: je n'ai pas encore mangé.","examples":[{"target":"Je n'ai pas mangé.","base":"No comí."},{"target":"Tu as déjà fini? — Non, pas encore.","base":"¿Ya terminaste? — No, todavía no."}]},"takeaways":["Niegas el pasado con ne… pas alrededor de avoir: je n'ai pas fini.","Preguntas con déjà y respondes pas encore."]},{"id":"fr-a2-u01-l05","unit_id":"fr-a2-u01","position":7,"title_es":"Mon week-end","objective_es":"Contar el fin de semana de otras personas.","intro":{"explanation":"Con las otras personas sólo cambia avoir; el participio queda igual: tu as mangé, il a lu, nous avons vu, vous avez fini, ils ont pris. Ojo con la liaison: en nous avons, vous avez e ils ont la s final se une a la vocal con un sonido z. Así se distingue ils ont (tienen / pasado) de ils sont (son), que suena con s.","examples":[{"target":"Nous avons visité Paris.","base":"Visitamos París."},{"target":"Ils ont pris le train.","base":"Ellos tomaron el tren."}]},"takeaways":["Conjugas avoir para cada persona: nous avons vu, ils ont pris.","Escuchas la liaison de ils‿ont frente a ils sont."]},{"id":"fr-a2-u02-l01","unit_id":"fr-a2-u02","position":1,"title_es":"Je suis allé, je suis parti","objective_es":"Contar adónde fuiste y cuándo llegaste con être.","intro":{"explanation":"Los verbos de movimiento como aller, partir y arriver forman el passé composé con être, no con avoir: je suis allé, je suis parti, je suis arrivé (nunca «j'ai allé»). El participio concuerda con el sujeto como un adjetivo: elle est allée, ils sont partis, elles sont arrivées. La e y la s que se agregan no suenan.","examples":[{"target":"Je suis allé à Paris.","base":"Fui a París."},{"target":"Elle est arrivée à l'aéroport.","base":"Ella llegó al aeropuerto."}]},"takeaways":["Usas être con aller, partir y arriver: je suis allé.","Haces concordar el participio: elle est partie, ils sont arrivés."]},{"id":"fr-a2-u02-l02","unit_id":"fr-a2-u02","position":2,"title_es":"Je suis resté à l'hôtel","objective_es":"Contar cuánto te quedaste y cuándo volviste.","intro":{"explanation":"Más verbos con être: rester → resté (quedarse, no «restar»), rentrer → rentré (volver, sobre todo a casa), venir → venu, tomber → tombé. Con nous, vous, ils y elles el participio va en plural: nous sommes restés. En l'hôtel la h no suena, por eso hay elisión: l'hôtel. Le séjour es la estadía.","examples":[{"target":"Je suis resté à l'hôtel.","base":"Me quedé en el hotel."},{"target":"Nous sommes rentrés dimanche.","base":"Volvimos el domingo."}]},"takeaways":["Cuentas tu estadía con je suis resté y je suis rentré.","Pones el participio en plural con nous y ils: nous sommes restés."]},{"id":"fr-a2-u02-l03","unit_id":"fr-a2-u02","position":4,"title_es":"Il y a deux ans","objective_es":"Decir hace cuánto pasó algo y hablar del equipaje.","intro":{"explanation":"Il y a + tiempo significa «hace»: il y a deux ans (hace dos años), il y a une semaine. Ya conoces il y a como «hay»: con una cantidad de tiempo y un verbo en pasado, es «hace». À l'étranger es en el exterior o al exterior: partir à l'étranger. Para viajar llevas la valise (la maleta) y le passeport.","examples":[{"target":"Il y a deux ans, je suis parti à l'étranger.","base":"Hace dos años me fui al exterior."},{"target":"Mon passeport est dans la valise.","base":"Mi pasaporte está en la maleta."}]},"takeaways":["Dices hace cuánto con il y a: il y a deux ans.","Nombras la valise, le passeport y l'étranger."]},{"id":"fr-a2-u02-l04","unit_id":"fr-a2-u02","position":5,"title_es":"En retard ou à l'heure?","objective_es":"Decir si un vuelo o un tren llegó a tiempo o atrasado.","intro":{"explanation":"En retard es atrasado o tarde: le vol est en retard, je suis arrivé en retard. À l'heure es a tiempo, puntual: le train est arrivé à l'heure. En Francia, el tren de alta velocidad es el TGV, de la compañía SNCF. En los trenes regionales todavía hay que composter (validar) el pasaje en una máquina antes de subir.","examples":[{"target":"Le train est en retard.","base":"El tren está atrasado."},{"target":"Le vol est arrivé à l'heure.","base":"El vuelo llegó a tiempo."}]},"takeaways":["Dices si algo está en retard o llegó à l'heure.","Entiendes una conversación sobre un viaje con demoras."]},{"id":"fr-a2-u02-l05","unit_id":"fr-a2-u02","position":7,"title_es":"Un séjour à l'étranger","objective_es":"Contar un viaje completo con être y avoir.","intro":{"explanation":"Para contar un viaje se mezclan los dos auxiliares: être con los verbos de movimiento (je suis allé, nous sommes rentrés) y avoir con los demás (j'ai pris le train, nous avons visité Rome). Sólo con être el participio concuerda: Léa est partie; Paul et Léa sont partis (con un varón en el grupo, masculino plural).","examples":[{"target":"Nous sommes allés à Rome il y a deux ans.","base":"Fuimos a Roma hace dos años."},{"target":"Léa est partie avec sa valise.","base":"Léa se fue con su maleta."}]},"takeaways":["Eliges être o avoir según el verbo: je suis allé, j'ai visité.","Haces concordar el participio sólo con être."]},{"id":"fr-a2-u03-l01","unit_id":"fr-a2-u03","position":1,"title_es":"Reservar","objective_es":"Reservar una mesa o una habitación con cortesía.","intro":{"explanation":"Para reservar con amabilidad: j'aimerais (me gustaría) + réserver o + lo que quieres. Es más suave que je veux y tan cortés como je voudrais. En el hotel: une chambre double (habitación doble) y la nuit (la noche que duermes allí; para la hora del día ya conoces le soir). Ojo con el número: deux (dos) y douze (doce) se distinguen por la vocal y por la z de douze.","examples":[{"target":"J'aimerais réserver une table pour deux.","base":"Me gustaría reservar una mesa para dos."},{"target":"J'aimerais une chambre double pour deux nuits.","base":"Me gustaría una habitación doble para dos noches."}]},"takeaways":["Reservas con j'aimerais réserver…","Pides una chambre double y dices cuántas nuits."]},{"id":"fr-a2-u03-l02","unit_id":"fr-a2-u03","position":2,"title_es":"En el hotel","objective_es":"Pedir cosas en la recepción y ubicarse en el hotel.","intro":{"explanation":"Para pedir algo con cortesía: pourriez-vous…? (¿podría usted…?) + infinitivo, o je pourrais…? (¿yo podría…?). L'étage es el piso de un edificio: le premier étage, le deuxième étage, le troisième étage. Como en Argentina, el premier étage está arriba de la planta baja. Ascenseur y étage empiezan con vocal: l'ascenseur, l'étage.","examples":[{"target":"La chambre est au deuxième étage.","base":"La habitación está en el segundo piso."},{"target":"Pourriez-vous me donner la clé?","base":"¿Podría darme la llave?"}]},"takeaways":["Pides algo con pourriez-vous…? o je pourrais…?","Ubicas la habitación con l'étage y l'ascenseur."]},{"id":"fr-a2-u03-l03","unit_id":"fr-a2-u03","position":4,"title_es":"La carta","objective_es":"Leer la carta y entender cómo se ordena una comida francesa.","intro":{"explanation":"Dos falsos amigos: la carte es la carta completa del restaurante, y le menu es el menú del día a precio fijo (entrée + plat + dessert). Y l'entrée no es la entrada al local: es el primer plato. Después viene le plat (el plato principal) y le dessert (el postre). En dessert, la doble s suena como una s.","examples":[{"target":"Le menu à vingt euros: entrée, plat et dessert.","base":"El menú de veinte euros: entrada, plato principal y postre."},{"target":"Je pourrais avoir la carte, s'il vous plaît?","base":"¿Me podría traer la carta, por favor?"}]},"takeaways":["Distingues la carte (la carta) de le menu (el menú del día).","Ordenas la comida: l'entrée, le plat, le dessert."]},{"id":"fr-a2-u03-l04","unit_id":"fr-a2-u03","position":5,"title_es":"Pedir la comida","objective_es":"Pedir los platos y decir cómo quieres la carne.","intro":{"explanation":"El mesero pregunta vous avez choisi? (¿ya eligieron?). Para la carne hay tres puntos: saignant (jugoso, rojo por dentro), à point (a punto) y bien cuit (bien cocido). En Francia la carne se sirve más cruda que en Argentina: un steak à point es bastante rosado. La gn de saignant suena como la ñ. Saignant concuerda: la viande saignante, y en el femenino la t final sí suena.","examples":[{"target":"Un steak saignant, s'il vous plaît.","base":"Un bife jugoso, por favor."},{"target":"Vous avez choisi? — Oui, j'aimerais le poisson.","base":"¿Ya eligieron? — Sí, me gustaría el pescado."}]},"takeaways":["Pides la carne saignant, à point o bien cuit.","Pides con je voudrais, j'aimerais o pourriez-vous…?"]},{"id":"fr-a2-u03-l05","unit_id":"fr-a2-u03","position":7,"title_es":"La cuenta","objective_es":"Pedir la cuenta y entender el servicio y la propina.","intro":{"explanation":"Para pagar: l'addition, s'il vous plaît, o pourriez-vous m'apporter l'addition? En Francia el servicio ya está en el precio (service compris), así que le pourboire es opcional: se dejan unas monedas si te gustó. Pronunciación: en compris la s final no suena; en el femenino comprise sí suena, como una z.","examples":[{"target":"Pourriez-vous m'apporter l'addition?","base":"¿Me podría traer la cuenta?"},{"target":"Le service est compris.","base":"El servicio está incluido."}]},"takeaways":["Pides l'addition con cortesía.","Sabes que el service está compris y le pourboire es opcional."]},{"id":"fr-a2-u04-l01","unit_id":"fr-a2-u04","position":1,"title_es":"Quand j'étais petit","objective_es":"Decir cómo eras y qué tenías de chico.","intro":{"explanation":"Para describir tu infancia usas el imparfait: j'étais (yo era) y j'avais (tenía). Quand j'étais petit es «cuando era chico»; una mujer dice quand j'étais petite, y en el femenino la t sí suena. La edad va con avoir: quand j'avais dix ans (cuando tenía diez años). En j'étais y j'avais la s final no suena: terminan en una e abierta.","examples":[{"target":"Quand j'étais petit, j'étais timide.","base":"Cuando era chico, era tímido."},{"target":"Quand j'avais dix ans, j'avais un chien.","base":"Cuando tenía diez años, tenía un perro."}]},"takeaways":["Describes cómo eras con j'étais.","Dices qué tenías y tu edad con j'avais."]},{"id":"fr-a2-u04-l02","unit_id":"fr-a2-u04","position":2,"title_es":"Dónde vivía","objective_es":"Contar dónde vivías y cómo era el lugar.","intro":{"explanation":"El imparfait se arma con la raíz de nous: nous habitons → habit- + -ais: j'habitais, il habitait, nous habitions, ils habitaient. -ais, -ait y -aient suenan igual. Il y a (hay) pasa a il y avait (había). Avant es antes. Falso amigo: la campagne es el campo, no una campaña.","examples":[{"target":"Avant, j'habitais à la campagne.","base":"Antes vivía en el campo."},{"target":"Dans le village, il y avait une boulangerie.","base":"En el pueblo había una panadería."}]},"takeaways":["Cuentas dónde vivías con j'habitais.","Describes el lugar con il y avait."]},{"id":"fr-a2-u04-l03","unit_id":"fr-a2-u04","position":4,"title_es":"Juegos y costumbres","objective_es":"Contar qué hacías normalmente de chico.","intro":{"explanation":"El imparfait también cuenta lo habitual, lo que hacías siempre: je jouais (jugaba), on allait (íbamos). Va con d'habitude (normalmente), chaque (cada: chaque été, chaque dimanche), tous les jours y souvent. Escucha la diferencia: je joue (presente), je jouais (imparfait, termina en e abierta) y j'ai joué (passé composé).","examples":[{"target":"D'habitude, je jouais avec mon frère.","base":"Normalmente jugaba con mi hermano."},{"target":"Chaque été, on allait à la plage.","base":"Cada verano íbamos a la playa."}]},"takeaways":["Cuentas costumbres con el imparfait: je jouais, on allait.","Usas d'habitude y chaque para lo que se repetía."]},{"id":"fr-a2-u04-l04","unit_id":"fr-a2-u04","position":5,"title_es":"La escuela y los recuerdos","objective_es":"Describir lugares del pasado y hablar de tus recuerdos.","intro":{"explanation":"C'était (era, estaba) describe en pasado: c'était loin, c'était beau. Escucha la diferencia con c'est (presente). Le souvenir es el recuerdo (también el souvenir de un viaje). Grandir es crecer; para decir dónde creciste: j'ai grandi à… En Francia, l'école primaire va de los 6 a los 11 años.","examples":[{"target":"L'école primaire, c'était à côté de la maison.","base":"La primaria estaba al lado de casa."},{"target":"J'ai grandi dans un petit village.","base":"Crecí en un pueblito."}]},"takeaways":["Describes el pasado con c'était.","Cuentas tus souvenirs y dónde creciste: j'ai grandi à…"]},{"id":"fr-a2-u04-l05","unit_id":"fr-a2-u04","position":7,"title_es":"Antes y ahora","objective_es":"Comparar tu infancia con tu vida de hoy.","intro":{"explanation":"Para comparar: avant + imparfait (avant, j'habitais…) y maintenant o aujourd'hui + presente (maintenant, j'habite…). Con nous, el imparfait termina en -ions: nous allions, nous habitions. Y con on, en -ait: on allait, on jouait.","examples":[{"target":"Avant, j'habitais à la campagne. Maintenant, j'habite à Paris.","base":"Antes vivía en el campo. Ahora vivo en París."},{"target":"Quand j'étais petite, j'avais un chat.","base":"Cuando era chica, tenía un gato."}]},"takeaways":["Contrastas avant (imparfait) con maintenant (presente).","Cuentas un recuerdo de infancia completo."]},{"id":"fr-a2-u05-l01","unit_id":"fr-a2-u05","position":1,"title_es":"¿Qué pasó?","objective_es":"Preguntar qué pasó y contar una pérdida o un robo.","intro":{"explanation":"Para preguntar qué pasó: qu'est-ce qui s'est passé? El hecho se cuenta en passé composé: j'ai perdu (perdre, perder) y on m'a volé (me robaron; on sirve para alguien que no conoces). Falso amigo: voler es robar, y también volar. Le portefeuille es la billetera, y la police, la policía.","examples":[{"target":"Qu'est-ce qui s'est passé? — J'ai perdu mon portefeuille.","base":"¿Qué pasó? — Perdí la billetera."},{"target":"On m'a volé mon téléphone!","base":"¡Me robaron el teléfono!"}]},"takeaways":["Preguntas qu'est-ce qui s'est passé?","Cuentas una pérdida con j'ai perdu y un robo con on m'a volé."]},{"id":"fr-a2-u05-l02","unit_id":"fr-a2-u05","position":2,"title_es":"La escena","objective_es":"Describir qué estaba pasando cuando ocurrió algo.","intro":{"explanation":"La escena de un relato va en imparfait: il pleuvait (llovía; en presente, il pleut), il faisait froid. Para una acción en curso: être en train de + infinitivo (j'étais en train de lire, estaba leyendo). Pendant que es mientras: pendant que je dormais. Quelqu'un es alguien.","examples":[{"target":"Il pleuvait et il faisait froid.","base":"Llovía y hacía frío."},{"target":"J'étais en train de lire quand quelqu'un est arrivé.","base":"Estaba leyendo cuando llegó alguien."}]},"takeaways":["Describes la escena con el imparfait: il pleuvait.","Dices qué estabas haciendo con être en train de."]},{"id":"fr-a2-u05-l03","unit_id":"fr-a2-u05","position":4,"title_es":"De repente","objective_es":"Contar el hecho que interrumpe la escena y su consecuencia.","intro":{"explanation":"Después de la escena, el hecho en passé composé, con soudain o tout à coup (de repente, de golpe). Alors (entonces) da la consecuencia. Avoir peur es tener miedo, con avoir como en español; en pasado, j'ai eu peur. Soudain termina en vocal nasal, como vin: la n no se pronuncia.","examples":[{"target":"Il pleuvait. Soudain, j'ai vu un accident.","base":"Llovía. De repente, vi un accidente."},{"target":"J'ai eu peur, alors j'ai appelé la police.","base":"Tuve miedo, entonces llamé a la policía."}]},"takeaways":["Marcas el hecho con soudain o tout à coup.","Cuentas la consecuencia con alors y dices j'ai eu peur."]},{"id":"fr-a2-u05-l04","unit_id":"fr-a2-u05","position":5,"title_es":"Por suerte","objective_es":"Comentar lo que pasó y entender un relato oral.","intro":{"explanation":"Heureusement (por suerte) y malheureusement (lamentablemente) comentan lo que pasó; la h no suena y eu se pronuncia con los labios redondeados. Le voisin es el vecino; la voisine, la vecina. En voisin la n no suena (vocal nasal); en voisine sí se pronuncia.","examples":[{"target":"Heureusement, mon téléphone était dans mon sac.","base":"Por suerte, mi teléfono estaba en el bolso."},{"target":"Malheureusement, il pleuvait.","base":"Lamentablemente, llovía."}]},"takeaways":["Comentas con heureusement o malheureusement.","Hablas de le voisin y la voisine."]},{"id":"fr-a2-u05-l05","unit_id":"fr-a2-u05","position":7,"title_es":"Contar un hecho","objective_es":"Contar un hecho completo, de la escena al final.","intro":{"explanation":"Un relato completo tiene cuatro partes: la escena en imparfait (il pleuvait, pendant que je rentrais…), el hecho en passé composé (soudain, j'ai vu…), la consecuencia (alors, j'ai appelé…) y tu comentario (heureusement…). Escucha bien: je rentrais (imparfait) y je suis rentré (passé composé) no suenan igual.","examples":[{"target":"Pendant que je rentrais à la maison, il pleuvait.","base":"Mientras volvía a casa, llovía."},{"target":"Tout à coup, quelqu'un a volé mon sac.","base":"De golpe, alguien me robó el bolso."}]},"takeaways":["Ordenas un relato: escena, hecho, consecuencia y comentario.","Eliges imparfait para la escena y passé composé para el hecho."]},{"id":"fr-a2-u06-l01","unit_id":"fr-a2-u06","position":1,"title_es":"Ça te dit?","objective_es":"Invitar a un amigo y aceptar una invitación.","intro":{"explanation":"Para invitar a un amigo: ça te dit de + infinitivo (¿tienes ganas de…?, ¿te gustaría…?). Delante de vocal, de se vuelve d': ça te dit d'aller au cinéma? Para aceptar: avec plaisir (con mucho gusto) o d'accord (de acuerdo, dale). En d'accord, la d final no suena. Inviter es invitar: je voudrais inviter Julien.","examples":[{"target":"Ça te dit d'aller au cinéma? — Avec plaisir!","base":"¿Tienes ganas de ir al cine? — ¡Con mucho gusto!"},{"target":"Ça te dit de danser? — D'accord!","base":"¿Quieres bailar? — ¡De acuerdo!"}]},"takeaways":["Invitas con ça te dit de + infinitivo.","Aceptas con avec plaisir o d'accord."]},{"id":"fr-a2-u06-l02","unit_id":"fr-a2-u06","position":2,"title_es":"Désolé, je ne peux pas","objective_es":"Rechazar una invitación con cortesía y proponer otro día.","intro":{"explanation":"Para decir que no con cortesía: désolé (désolée si eres mujer: se escribe con otra e, pero suena igual) + je ne peux pas y una razón. Para proponer otro día: je suis libre samedi. Prochain va después del día o del mes: samedi prochain, le mois prochain; con un sustantivo femenino, prochaine: la semaine prochaine. En peux, la x final no suena.","examples":[{"target":"Désolée, je ne peux pas. Je travaille.","base":"Perdón, no puedo. Trabajo."},{"target":"Je suis libre samedi prochain.","base":"Estoy libre el sábado que viene."}]},"takeaways":["Rechazas con désolé, je ne peux pas y una razón.","Propones otro día con je suis libre y prochain."]},{"id":"fr-a2-u06-l03","unit_id":"fr-a2-u06","position":4,"title_es":"J'irai, je ferai","objective_es":"Contar planes con el futur simple de aller, faire, être y venir.","intro":{"explanation":"El futur simple sirve para planes y predicciones. Cuatro verbos muy usados son irregulares: j'irai (aller), je ferai (faire), je serai (être) y je viendrai (venir). En la persona je terminan en -ai, que suena como una é cerrada. Ojo con el oído: je ferai (futuro) y je fais (presente) se parecen; en ferai hay una sílaba más. El futuro próximo (je vais + infinitivo) también sirve, sobre todo para algo inmediato.","examples":[{"target":"Samedi, j'irai à la fête.","base":"El sábado voy a ir a la fiesta."},{"target":"Je viendrai avec ma sœur.","base":"Voy a ir con mi hermana."}]},"takeaways":["Usas j'irai, je ferai, je serai y je viendrai para tus planes.","Distingues je ferai (futuro) de je fais (presente)."]},{"id":"fr-a2-u06-l04","unit_id":"fr-a2-u06","position":5,"title_es":"Il y aura de la musique","objective_es":"Anunciar lo que va a haber y decir cuándo pasa algo.","intro":{"explanation":"Il y aura es el futuro de il y a (habrá, va a haber) y ce sera, el de c'est (será, va a ser). Dans + tiempo dice cuándo pasa algo a partir de ahora: dans deux jours, dentro de dos días. No lo confundas con il y a deux ans (hace dos años), que mira al pasado. Le rendez-vous es una cita con un amigo, pero también el turno con el médico. En rendez-vous, la z final no suena y ren es una vocal nasal, como en vent.","examples":[{"target":"Il y aura de la musique.","base":"Va a haber música."},{"target":"La fête est dans deux jours.","base":"La fiesta es dentro de dos días."}]},"takeaways":["Anuncias con il y aura y ce sera.","Dices cuándo pasa algo con dans + tiempo."]},{"id":"fr-a2-u06-l05","unit_id":"fr-a2-u06","position":7,"title_es":"On se retrouve où?","objective_es":"Quedar en un lugar y una hora, y cerrar un plan.","intro":{"explanation":"Para fijar lugar y hora: on se retrouve (nos encontramos): on se retrouve où?, on se retrouve à quelle heure? Cultura: el apéro (el aperitivo, algo para tomar y picar antes de cenar) es un plan muy común entre amigos. Y si te invitan a cenar a una casa, en Francia se acostumbra llegar unos minutos después de la hora, nunca antes.","examples":[{"target":"On se retrouve devant le cinéma?","base":"¿Nos encontramos delante del cine?"},{"target":"On se retrouve à huit heures pour l'apéro.","base":"Nos encontramos a las ocho para el aperitivo."}]},"takeaways":["Fijas lugar y hora con on se retrouve.","Armas un plan completo: invitación, respuesta, lugar y hora."]},{"id":"fr-a2-u07-l01","unit_id":"fr-a2-u07","position":1,"title_es":"Je dois, je peux, je veux","objective_es":"Decir lo que tienes que hacer, lo que puedes y lo que quieres.","intro":{"explanation":"Je dois (tengo que), je peux (puedo) y je veux (quiero) van seguidos de un infinitivo: je dois travailler, je peux venir, je veux partir. Con tu, las formas son iguales: tu dois, tu peux, tu veux. En la negación, ne… pas rodea al verbo conjugado: je ne peux pas venir. Pronunciación: peux y veux sólo se distinguen por la primera consonante (p / v), y la x final no suena.","examples":[{"target":"Je dois travailler samedi.","base":"Tengo que trabajar el sábado."},{"target":"Tu peux venir à la réunion?","base":"¿Puedes venir a la reunión?"}]},"takeaways":["Usas je dois, je peux y je veux + infinitivo.","Distingues peux y veux al oído."]},{"id":"fr-a2-u07-l02","unit_id":"fr-a2-u07","position":2,"title_es":"Il faut un CV","objective_es":"Hablar de lo que hace falta para conseguir un empleo.","intro":{"explanation":"Il faut + infinitivo es la obligación general, sin persona (hay que): il faut envoyer un CV. Con un sustantivo dice lo que hace falta: il faut un diplôme. Nunca cambia de forma. Ojo al oído: il faut y il fait se distinguen por la vocal, y en los dos la t final no suena. Falso amigo: l'entretien es la entrevista de trabajo, no el entretenimiento.","examples":[{"target":"Il faut envoyer ton CV.","base":"Hay que mandar tu currículum."},{"target":"Pour l'emploi, il faut un entretien.","base":"Para el puesto hace falta una entrevista."}]},"takeaways":["Dices lo que hay que hacer con il faut + infinitivo.","Hablas de l'emploi, le CV, l'entretien y le salaire."]},{"id":"fr-a2-u07-l03","unit_id":"fr-a2-u07","position":4,"title_es":"Depuis deux ans","objective_es":"Decir desde cuándo haces algo y cuánto duró.","intro":{"explanation":"Para algo que empezó en el pasado y sigue hoy, el francés usa el presente con depuis: je travaille ici depuis deux ans (trabajo aquí desde hace dos años). Para algo terminado, passé composé con pendant (durante): j'ai fait un stage pendant six mois. Falso amigo: le stage es la pasantía, y le collègue (la collègue), el compañero o la compañera de trabajo.","examples":[{"target":"Je travaille ici depuis deux ans.","base":"Trabajo aquí desde hace dos años."},{"target":"J'ai fait un stage pendant six mois.","base":"Hice una pasantía durante seis meses."}]},"takeaways":["Usas depuis + presente para algo que sigue.","Usas pendant para una duración cerrada."]},{"id":"fr-a2-u07-l04","unit_id":"fr-a2-u07","position":5,"title_es":"Réussir l'examen","objective_es":"Hablar de la universidad, los exámenes y el título.","intro":{"explanation":"Falso amigo: réussir un examen es aprobarlo (passer un examen es rendirlo, no aprobarlo). Le diplôme es el título, y l'université es femenino: à l'université. Pronunciación: en examen, la x suena como gz y el final -en es una vocal nasal, como la de vin.","examples":[{"target":"Je veux réussir l'examen.","base":"Quiero aprobar el examen."},{"target":"Ma sœur étudie à l'université.","base":"Mi hermana estudia en la universidad."}]},"takeaways":["Dices aprobar con réussir.","Hablas de l'université, l'examen y le diplôme."]},{"id":"fr-a2-u07-l05","unit_id":"fr-a2-u07","position":7,"title_es":"D'abord, ensuite, enfin","objective_es":"Contar los pasos de una búsqueda de empleo y dar razones.","intro":{"explanation":"Para ordenar los pasos: d'abord (primero), ensuite (después) y enfin (por último). Para dar una razón: parce que (porque); delante de vocal, parce qu': parce qu'il faut travailler. En enfin hay dos nasales distintas: en- suena como la preposición en (en France) y -fin, como vin.","examples":[{"target":"D'abord, j'ai un entretien. Ensuite, une réunion.","base":"Primero tengo una entrevista. Después, una reunión."},{"target":"Je ne peux pas venir parce que je dois travailler.","base":"No puedo ir porque tengo que trabajar."}]},"takeaways":["Ordenas los pasos con d'abord, ensuite y enfin.","Das razones con parce que."]},{"id":"fr-a2-u08-l01","unit_id":"fr-a2-u08","position":1,"title_es":"J'ai mal à la tête","objective_es":"Decir qué te duele: la cabeza, la espalda, la panza, la garganta.","intro":{"explanation":"Para decir qué te duele: j'ai mal à + la parte del cuerpo con artículo. À + le se contrae en au (j'ai mal au dos, au ventre); à la no cambia (à la tête, à la gorge). Ojo: le dos (la espalda) es masculino. Con otra persona: il a mal, elle a mal. Pronunciación: en dos, la s final no suena, e il y elle se distinguen por la vocal y la l final de elle.","examples":[{"target":"J'ai mal à la tête.","base":"Me duele la cabeza."},{"target":"Mon père a mal au dos.","base":"A mi papá le duele la espalda."}]},"takeaways":["Dices qué te duele con j'ai mal à.","Usas au con masculinos y à la con femeninos."]},{"id":"fr-a2-u08-l02","unit_id":"fr-a2-u08","position":2,"title_es":"Un rhume et de la fièvre","objective_es":"Hablar de los dientes, la pierna y el brazo, y decir que tienes fiebre o un resfrío.","intro":{"explanation":"À + les se contrae en aux: j'ai mal aux dents. Delante de vocal hay liaison: aux yeux se une con un sonido z. La dent (el diente) es femenino. Para la fiebre y el resfrío se usa avoir: j'ai de la fièvre (tengo fiebre), j'ai un rhume (estoy resfriado). En bras, la s final no suena.","examples":[{"target":"J'ai mal aux dents.","base":"Me duelen los dientes."},{"target":"J'ai un rhume et de la fièvre.","base":"Estoy resfriado y tengo fiebre."}]},"takeaways":["Usas aux con los plurales: aux dents, aux yeux.","Dices j'ai de la fièvre y j'ai un rhume."]},{"id":"fr-a2-u08-l03","unit_id":"fr-a2-u08","position":4,"title_es":"Je me sens fatigué","objective_es":"Decir cómo te sientes: bien, mal, cansado, enfermo o en forma.","intro":{"explanation":"Je me sens + adjetivo es me siento: je me sens bien, je me sens mal, je me sens fatigué. Malade es enfermo (je suis malade) y en forme, en forma o con energía. Fatigué concuerda: una mujer dice fatiguée, que suena igual.","examples":[{"target":"Je me sens très fatigué.","base":"Me siento muy cansado."},{"target":"Aujourd'hui, je suis en forme!","base":"¡Hoy estoy con todas las pilas!"}]},"takeaways":["Dices cómo te sientes con je me sens.","Usas malade, fatigué y en forme."]},{"id":"fr-a2-u08-l04","unit_id":"fr-a2-u08","position":5,"title_es":"Chez le médecin","objective_es":"Explicarle al médico qué te pasa y desde cuándo.","intro":{"explanation":"En la consulta se usa vous: vous avez mal où? (¿dónde le duele?), depuis quand? (¿desde cuándo?). Se responde con depuis + presente: j'ai mal à la tête depuis hier. Cultura: en Francia, el médico te da l'ordonnance (la receta) y en la pharmacie, la de la cruz verde, te dan le médicament. Falso amigo: l'ordonnance no es una ordenanza.","examples":[{"target":"Vous avez mal où?","base":"¿Dónde le duele?"},{"target":"Voici votre ordonnance.","base":"Aquí tiene su receta."}]},"takeaways":["Explicas qué te duele y desde cuándo con depuis.","Entiendes l'ordonnance y le médicament."]},{"id":"fr-a2-u08-l05","unit_id":"fr-a2-u08","position":7,"title_es":"Reposez-vous!","objective_es":"Entender y dar consejos de salud con el imperativo de vous.","intro":{"explanation":"Para aconsejar con vous se usa el imperativo: es la forma de vous sin el pronombre (vous prenez → prenez, vous buvez → buvez). En negativo, ne… pas rodea al verbo: ne mangez pas trop. Con un verbo pronominal, el pronombre va después, con guion: reposez-vous (descanse). Il faut + infinitivo también sirve para aconsejar.","examples":[{"target":"Reposez-vous et buvez de l'eau.","base":"Descanse y tome agua."},{"target":"Ne mangez pas trop.","base":"No coma demasiado."}]},"takeaways":["Entiendes los consejos del médico en imperativo.","Aconsejas con reposez-vous, buvez, prenez y ne mangez pas."]},{"id":"fr-a2-u09-l01","unit_id":"fr-a2-u09","position":1,"title_es":"La ropa y les soldes","objective_es":"Nombrar la ropa y los zapatos y decir de qué color son.","intro":{"explanation":"La chemise es la camisa, le pantalon el pantalón, la veste la chaqueta y les chaussures los zapatos. Ojo con dos falsos amigos: la robe es el vestido (la ropa en general es les vêtements) y les soldes son las rebajas (el sueldo es le salaire). El color va después y concuerda: une veste noire, des chaussures noires. La ch de chemise y de chaussures suena como la sh de show. En Francia hay soldes dos veces por año: en enero y en verano, entre fines de junio y julio.","examples":[{"target":"Je cherche une robe rouge.","base":"Busco un vestido rojo."},{"target":"Les soldes commencent en janvier.","base":"Las rebajas empiezan en enero."}]},"takeaways":["Nombras la ropa: la chemise, le pantalon, la robe, la veste, les chaussures.","Sabes que la robe es el vestido y les soldes, las rebajas."]},{"id":"fr-a2-u09-l02","unit_id":"fr-a2-u09","position":2,"title_es":"La cabine d'essayage","objective_es":"Pedir tu talle o tu número y probarte ropa.","intro":{"explanation":"Para probarte algo: je peux essayer…? (después de je peux va el infinitivo). La taille es el talle de la ropa y la pointure, el número de los zapatos; las dos se preguntan con vous faites quelle…? y se responden con je fais du + número: je fais du 38. Te pruebas la ropa en la cabine d'essayage. Pronunciación: una s sola entre vocales suena como z (chemise), pero la ss de essayer suena s.","examples":[{"target":"Je peux essayer cette robe?","base":"¿Puedo probarme este vestido?"},{"target":"Vous faites quelle pointure?","base":"¿Qué número calza?"}]},"takeaways":["Pides probarte algo con je peux essayer…?","Dices tu talle y tu número con je fais du…"]},{"id":"fr-a2-u09-l03","unit_id":"fr-a2-u09","position":4,"title_es":"Más caro, más barato","objective_es":"Comparar precios y cosas con plus, moins y aussi… que.","intro":{"explanation":"Para comparar: plus + adjetivo + que (más… que), moins + adjetivo + que (menos… que) y aussi + adjetivo + que (tan… como). Siempre que, nunca «comme»; delante de vocal, qu': aussi cher qu'à Paris. El adjetivo concuerda con el primer sustantivo: la veste est plus chère. Bon marché (barato) no cambia: des chaussures bon marché. La s final de plus y de moins no suena delante de consonante: plus cher, moins cher.","examples":[{"target":"La veste est plus chère que la chemise.","base":"La chaqueta es más cara que la camisa."},{"target":"Le vélo est moins cher que la voiture.","base":"La bici es más barata que el auto."}]},"takeaways":["Comparas con plus, moins y aussi + adjetivo + que.","Dices que algo es barato con bon marché, que no cambia."]},{"id":"fr-a2-u09-l04","unit_id":"fr-a2-u09","position":5,"title_es":"Lo mejor y lo más","objective_es":"Decir qué es mejor y qué es lo más caro o lo más lindo.","intro":{"explanation":"Bon (bueno) tiene un comparativo propio: meilleur, meilleure en femenino. Nunca «plus bon». El superlativo lleva el artículo: le plus, la plus, les plus + adjetivo, y de para el grupo: la veste la plus chère du magasin. Con adjetivos que van antes del sustantivo (beau, petit, grand) el superlativo también va antes: la plus belle robe. Le meilleur, la meilleure: lo mejor de todo.","examples":[{"target":"C'est la meilleure boulangerie de la ville.","base":"Es la mejor panadería de la ciudad."},{"target":"C'est la veste la plus chère du magasin.","base":"Es la chaqueta más cara de la tienda."}]},"takeaways":["Usas meilleur o meilleure, nunca «plus bon».","Armas el superlativo con le plus o la plus."]},{"id":"fr-a2-u09-l05","unit_id":"fr-a2-u09","position":7,"title_es":"En la caja","objective_es":"Decir cuántos te llevas con en y pagar.","intro":{"explanation":"Para no repetir el sustantivo con una cantidad, el francés usa en delante del verbo: des chemises? J'en prends deux (me llevo dos). En con je se apostrofa: j'en. Para pagar: payer par carte (con tarjeta: en francés par, no «avec») o en espèces (en efectivo). Escucha bien: j'en prends tiene la vocal nasal de en, como en vent; je prends no la tiene.","examples":[{"target":"Des chemises? J'en prends deux.","base":"¿Camisas? Me llevo dos."},{"target":"Je peux payer par carte?","base":"¿Puedo pagar con tarjeta?"}]},"takeaways":["Dices cuántos te llevas con j'en prends…","Pagas par carte o en espèces."]},{"id":"fr-a2-u10-l01","unit_id":"fr-a2-u10","position":1,"title_es":"L'ordinateur et le portable","objective_es":"Nombrar la computadora, el celular, la pantalla y las apps, y decir si funcionan.","intro":{"explanation":"L'ordinateur es la computadora, le portable el celular, l'écran la pantalla y l'appli (de application) la app. Falso amigo: marcher es caminar, pero también funcionar: mon portable ne marche pas (mi celular no anda). Appli es femenino, pero delante de vocal ma se vuelve mon: mon appli. Pronunciación: con liaison, mon‿ordinateur se une con un sonido n y deux‿écrans, con un sonido z.","examples":[{"target":"Mon ordinateur ne marche pas.","base":"Mi computadora no funciona."},{"target":"L'écran de mon portable est très petit.","base":"La pantalla de mi celular es muy chica."}]},"takeaways":["Nombras l'ordinateur, le portable, l'écran y l'appli.","Dices que algo no funciona con ne marche pas."]},{"id":"fr-a2-u10-l02","unit_id":"fr-a2-u10","position":2,"title_es":"Messages et mails","objective_es":"Mandar y recibir mensajes y mails.","intro":{"explanation":"Envoyer (mandar) cambia la y por i delante de una e muda: j'envoie, tu envoies, il envoie, pero vous envoyez. Recevoir (recibir) es irregular: je reçois, il reçoit, vous recevez. La ç (con cedilla) suena s delante de o y u: reçois, reçu. En pasado: j'ai envoyé, j'ai reçu. Se manda algo à quelqu'un: j'envoie un message à Paul.","examples":[{"target":"J'envoie un message à Claire.","base":"Le mando un mensaje a Claire."},{"target":"Tu as reçu mon mail?","base":"¿Recibiste mi mail?"}]},"takeaways":["Conjugas envoyer (j'envoie) y recevoir (je reçois).","Cuentas lo que mandaste o recibiste con j'ai envoyé y j'ai reçu."]},{"id":"fr-a2-u10-l03","unit_id":"fr-a2-u10","position":4,"title_es":"Appeler et télécharger","objective_es":"Llamar, descargar apps y hablar de contraseñas y de estar en línea.","intro":{"explanation":"Appeler (llamar) duplica la l cuando la terminación no suena: j'appelle, tu appelles, il appelle, ils appellent; pero nous appelons, vous appelez. En j'appelle la e suena abierta; en appeler y appelez casi no suena. Télécharger es descargar: je télécharge une appli. Le mot de passe es la contraseña y en ligne, en línea. Y un dato: ça marche! también quiere decir ¡dale!","examples":[{"target":"J'appelle ma mère ce soir.","base":"Llamo a mi mamá esta noche."},{"target":"Je fais les courses en ligne.","base":"Hago las compras en línea."}]},"takeaways":["Conjugas appeler: j'appelle con ll, vous appelez con una sola l.","Hablas de descargar, de contraseñas y de estar en línea."]},{"id":"fr-a2-u10-l04","unit_id":"fr-a2-u10","position":5,"title_es":"Je l'appelle, je les vois","objective_es":"Reemplazar a una persona o una cosa con le, la, l' y les.","intro":{"explanation":"Con verbos sin à, como appeler o voir, la persona o la cosa se reemplaza con le (masculino), la (femenino), l' (delante de vocal) o les (plural), y el pronombre va delante del verbo: Paul? Je l'appelle. En la negación queda pegado al verbo: je ne l'appelle pas. Con un infinitivo va delante del infinitivo: je vais l'appeler (voy a llamarlo). Escucha la diferencia: je le vois (e muda) y je les vois (e cerrada, como en el español «mes»).","examples":[{"target":"Paul? Je l'appelle demain.","base":"¿Paul? Lo llamo mañana."},{"target":"Mes parents? Je les vois le dimanche.","base":"¿Mis padres? Los veo los domingos."}]},"takeaways":["Pones le, la, l' o les delante del verbo.","Dices je ne l'appelle pas y je vais l'appeler."]},{"id":"fr-a2-u10-l05","unit_id":"fr-a2-u10","position":7,"title_es":"Je lui écris, je leur parle","objective_es":"Reemplazar a una persona con lui y leur.","intro":{"explanation":"Con verbos que llevan à (parler à, écrire à, envoyer à, téléphoner à), la persona se reemplaza con lui (a él o a ella) o leur (a ellos o a ellas), delante del verbo: ma sœur? Je lui écris. Leur nunca lleva s. Ojo con la diferencia con el español: appeler va sin à (je l'appelle), pero téléphoner lleva à (je lui téléphone), aunque en español los dos sean «la llamo». Escucha: lui y leur se distinguen por la vocal.","examples":[{"target":"Ma sœur? Je lui écris souvent.","base":"¿Mi hermana? Le escribo seguido."},{"target":"Mes grands-parents? Je leur parle tous les jours.","base":"¿Mis abuelos? Les hablo todos los días."}]},"takeaways":["Usas lui y leur con parler à, écrire à y envoyer à.","Distingues je l'appelle de je lui téléphone."]},{"id":"fr-a2-u11-l01","unit_id":"fr-a2-u11","position":1,"title_es":"Je me suis levée tard","objective_es":"Contar la rutina y lo que hiciste con verbos pronominales.","intro":{"explanation":"Los verbos pronominales (se lever, se réveiller, se coucher) llevan me, te, se, nous, vous delante del verbo: je me réveille, tu te réveilles. En el passé composé van con être, no con avoir: je me suis levé. Con être, el participio concuerda con el sujeto: una mujer escribe je me suis levée y en plural nous nous sommes levés, pero levé y levée suenan igual. Para la frecuencia: toujours, souvent, parfois (a veces) y rarement (casi nunca).","examples":[{"target":"Je me réveille à sept heures.","base":"Me despierto a las siete."},{"target":"Hier, je me suis levée tard.","base":"Ayer me levanté tarde."}]},"takeaways":["Cuentas tu mañana con je me réveille y je me suis levé o levée.","Dices con qué frecuencia haces algo con parfois y rarement."]},{"id":"fr-a2-u11-l02","unit_id":"fr-a2-u11","position":2,"title_es":"On s'est rencontrés à Lyon","objective_es":"Contar cómo se conoció una pareja y si viven juntos.","intro":{"explanation":"Para contar una historia de pareja: on s'est rencontrés (nos conocimos), ils se sont mariés (se casaron). Son verbos pronominales, así que van con être y concuerdan: elles se sont rencontrées. Ojo con ils sont mariés (están casados) y ils se sont mariés (se casaron): la diferencia es el se. Le couple es masculino aunque en español digamos la pareja, y ensemble es juntos. Falso amigo: le copain o la copine es amigo o amiga, pero mon copain también puede ser mi novio.","examples":[{"target":"Claire et Paul se sont mariés en juin.","base":"Claire y Paul se casaron en junio."},{"target":"On s'est rencontrés à Paris.","base":"Nos conocimos en París."}]},"takeaways":["Cuentas cómo se conocieron con on s'est rencontrés y ils se sont mariés.","Hablas de tu copain o tu copine y de lo que hacen ensemble."]},{"id":"fr-a2-u11-l03","unit_id":"fr-a2-u11","position":4,"title_es":"On s'entend bien","objective_es":"Decir cómo te llevas con alguien y hablar de lo que hacen juntos.","intro":{"explanation":"Con los verbos recíprocos, se significa el uno al otro: on se voit le samedi (nos vemos), ils se parlent (se hablan), on s'entend bien (nos llevamos bien), ils se disputent (se pelean). Entendre es oír, pero s'entendre bien es llevarse bien: je m'entends, on s'entend, ils s'entendent. En il s'entend la d no suena; en ils s'entendent sí se oye la d (la terminación -ent es muda). En pasado: on s'est disputés.","examples":[{"target":"On s'entend très bien.","base":"Nos llevamos muy bien."},{"target":"Ils se disputent souvent.","base":"Se pelean seguido."}]},"takeaways":["Dices cómo te llevas con alguien con s'entendre bien y se disputer.","Usas se para hablar de lo que dos personas hacen el uno con el otro."]},{"id":"fr-a2-u11-l04","unit_id":"fr-a2-u11","position":5,"title_es":"J'y vais · qui et que","objective_es":"Reemplazar un lugar con y y unir frases con qui y que.","intro":{"explanation":"Y reemplaza un lugar que ya se nombró (à la plage, au cinéma, chez mes parents) y va antes del verbo: Tu vas au cinéma? — Oui, j'y vais. También on y va, ils y vont. Liaison: en ils‿y vont la s se une a la y con un sonido z. Para unir frases: qui es el sujeto del verbo que sigue (le copain qui habite à Nice) y que, el objeto (le film que j'ai vu); que se vuelve qu' delante de vocal: le film qu'on aime.","examples":[{"target":"Tu vas à la plage? — Oui, j'y vais demain.","base":"¿Vas a la playa? — Sí, voy mañana."},{"target":"C'est le copain qui habite à Lyon.","base":"Es el amigo que vive en Lyon."}]},"takeaways":["Evitas repetir el lugar con y: j'y vais, on y va.","Unes dos frases con qui (sujeto) y que (objeto)."]},{"id":"fr-a2-u11-l05","unit_id":"fr-a2-u11","position":7,"title_es":"Je ne fais rien","objective_es":"Negar con nunca, ya no, nada y nadie, y ofrecer algo.","intro":{"explanation":"Como ne… pas, estas negaciones rodean al verbo: je ne bois jamais de café (nunca), je n'habite plus à Paris (ya no), je ne fais rien (nada), je ne vois personne (nadie). En el passé composé, rien va antes del participio (je n'ai rien mangé) y personne, después (je n'ai vu personne). Lo contrario de ne… rien es quelque chose (algo). Ne se vuelve n' delante de vocal: en je n'ai rien vu, esa n es lo único que se oye de la negación. En lo oral el ne a veces se cae, pero se escribe siempre.","examples":[{"target":"Je ne bois jamais de café le soir.","base":"Nunca tomo café por la noche."},{"target":"Il n'y a personne dans la cuisine.","base":"No hay nadie en la cocina."}]},"takeaways":["Niegas con ne… jamais, ne… plus, ne… rien y ne… personne alrededor del verbo.","Ofreces o preguntas por quelque chose y respondes ne… rien."]},{"id":"fr-a2-u12-l01","unit_id":"fr-a2-u12","position":1,"title_es":"À mon avis…","objective_es":"Dar tu opinión, decir si estás de acuerdo y hablar de ventajas y desventajas.","intro":{"explanation":"Para dar tu opinión: à mon avis (en mi opinión) o je pense que + frase (creo que). Para responder: je suis d'accord o je ne suis pas d'accord, y con alguien, avec: je suis d'accord avec toi. Tener razón es avoir raison: tu as raison, nunca «tu es raison». L'avantage y l'inconvénient son masculinos: un avantage. Liaison: en mon‿avis la n de mon se une a avis.","examples":[{"target":"À mon avis, le train est meilleur que l'avion.","base":"En mi opinión, el tren es mejor que el avión."},{"target":"Je pense que tu as raison.","base":"Creo que tienes razón."}]},"takeaways":["Das tu opinión con à mon avis y je pense que.","Dices je suis d'accord o je ne suis pas d'accord y nombras ventajas y desventajas."]},{"id":"fr-a2-u12-l02","unit_id":"fr-a2-u12","position":2,"title_es":"Tu devrais…","objective_es":"Aconsejar y proponer soluciones con el condicional.","intro":{"explanation":"Para aconsejar se usa el condicional: tu devrais + infinitivo (deberías) y, con vous, vous devriez. Para proponer algo: on pourrait + infinitivo (podríamos). Tu devrais es un consejo; tu dois, una obligación (tienes que). El condicional termina en -ais / -ait (devrais, pourrait, aimerais) y esa terminación suena como la è de mère: on pourrait no suena igual que on peut. Le problème es masculino, como en español, y la solution, femenino.","examples":[{"target":"Tu es fatigué? Tu devrais dormir.","base":"¿Estás cansado? Deberías dormir."},{"target":"On pourrait aller au cinéma ce soir.","base":"Podríamos ir al cine esta noche."}]},"takeaways":["Aconsejas con tu devrais o vous devriez + infinitivo.","Propones una solución con on pourrait + infinitivo."]},{"id":"fr-a2-u12-l03","unit_id":"fr-a2-u12","position":4,"title_es":"S'il pleut…","objective_es":"Decir qué vas a hacer según lo que pase, con si + presente y futuro.","intro":{"explanation":"Para una hipótesis sobre el futuro: si + presente y después futuro: S'il pleut, on restera à la maison. Después de si nunca va futuro: «si il pleuvra» está mal. Si pierde la i sólo delante de il e ils (s'il, s'ils), pero si elle. Ya viste algunos futuros: j'irai, je ferai, ce sera. Donc es así que o por lo tanto: une consecuencia: Il fait froid, donc je reste à la maison.","examples":[{"target":"S'il pleut, on restera à la maison.","base":"Si llueve, nos vamos a quedar en casa."},{"target":"S'il fait beau demain, j'irai à la plage.","base":"Si mañana hace buen tiempo, voy a ir a la playa."}]},"takeaways":["Haces planes condicionados con si + presente y futuro: s'il pleut, on restera…","Unes una causa y su consecuencia con donc."]},{"id":"fr-a2-u12-l04","unit_id":"fr-a2-u12","position":5,"title_es":"Ça ne marche pas","objective_es":"Reclamar en un negocio cuando algo no funciona y pedir que te devuelvan el dinero.","intro":{"explanation":"Marcher es caminar, pero con un aparato es funcionar: ça ne marche pas (no funciona), mon portable ne marche pas. Para reclamar, con vous y cortesía: Bonjour, monsieur. Pourriez-vous me rembourser? (¿podría devolverme el dinero?). Enfin es por fin (Enfin une bonne nouvelle!) o finalmente al terminar una lista: d'abord…, ensuite…, enfin…","examples":[{"target":"Bonjour, monsieur. Mon portable ne marche pas.","base":"Buenos días, señor. Mi celular no funciona."},{"target":"Pourriez-vous me rembourser, s'il vous plaît?","base":"¿Podría devolverme el dinero, por favor?"}]},"takeaways":["Explicas el problema con ça ne marche pas.","Pides con cortesía que te devuelvan el dinero con pourriez-vous me rembourser?"]},{"id":"fr-a2-u12-l05","unit_id":"fr-a2-u12","position":7,"title_es":"Il dit que…","objective_es":"Contar lo que dijo otra persona y marcar un contraste con pourtant.","intro":{"explanation":"Para contar lo que dice otro: il dit que / elle dit que + frase; que se vuelve qu' delante de vocal: Hugo dit qu'il est malade. En pasado, elle m'a dit que (me dijo que) y el presente pasa a imperfecto: «C'est fermé» → Elle m'a dit que c'était fermé. En il dit la t no suena; en ils disent se oye una z. Pourtant es sin embargo o aun así: marca algo que no esperabas.","examples":[{"target":"Hugo dit qu'il est malade.","base":"Hugo dice que está enfermo."},{"target":"Elle m'a dit que c'était fermé.","base":"Me dijo que estaba cerrado."}]},"takeaways":["Cuentas lo que dice o dijo otra persona con il dit que y elle m'a dit que.","Marcas un contraste con pourtant."]},{"id":"fr-a2-u13-l01","unit_id":"fr-a2-u13","position":1,"title_es":"Moi, je suis de Buenos Aires","objective_es":"Remarcar de quién hablas con moi, toi, lui y elle, y responder con c'est moi.","intro":{"explanation":"En francés el sujeto (je, tu, il, elle) nunca va solo ni separado del verbo. Para remarcarlo, como cuando en español decimos «yo» con énfasis, se agrega el pronombre tónico adelante, con coma: moi, je suis argentine; toi, tu travailles où? Para responder a «¿quién es?» también se usa el tónico: c'est moi (soy yo), c'est lui (es él). Moi y toi ya los usabas en et toi?: son los mismos. Lui (él) y elle (ella) sirven tanto de tónicos como en lui, il… / elle, elle…","examples":[{"target":"Moi, je suis argentine. Et toi?","base":"Yo soy argentina. ¿Y tú?"},{"target":"Qui est-ce? — C'est moi, Paul.","base":"¿Quién es? — Soy yo, Paul."}]},"takeaways":["Remarcas el sujeto con moi, je… o toi, tu…","Respondes a qui est-ce? con c'est moi, c'est lui o c'est elle."]},{"id":"fr-a2-u13-l02","unit_id":"fr-a2-u13","position":2,"title_es":"Chez moi, avec toi, sans eux","objective_es":"Usar los pronombres tónicos después de avec, pour, sans y chez.","intro":{"explanation":"Después de una preposición va siempre el pronombre tónico: avec moi (conmigo), avec toi (contigo), pour lui (para él), sans elle (sin ella). En francés no hay una palabra como «conmigo»: se dice avec moi. Chez + pronombre es «en la casa de»: chez moi (en mi casa o a mi casa), chez toi, chez eux. En plural, eux es «ellos» (también para un grupo mixto) y elles, «ellas»; nous y vous no cambian. Ojo: ils es sujeto (ils travaillent), pero después de avec se dice avec eux.","examples":[{"target":"Tu viens au cinéma avec moi?","base":"¿Vienes al cine conmigo?"},{"target":"Mes frères? Je vais au marché avec eux.","base":"¿Mis hermanos? Voy al mercado con ellos."}]},"takeaways":["Después de avec, pour, sans y chez usas moi, toi, lui, elle, nous, vous, eux, elles.","Invitas con tu viens chez moi? y dices con quién vas con avec eux o avec elles."]},{"id":"fr-a2-u13-l03","unit_id":"fr-a2-u13","position":4,"title_es":"Moi aussi, moi non plus","objective_es":"Estar de acuerdo o no con moi aussi, moi non plus y pas moi.","intro":{"explanation":"Para estar de acuerdo con una frase afirmativa se dice moi aussi (yo también): j'aime le chocolat. — Moi aussi! Con una frase negativa, el acuerdo es moi non plus (yo tampoco): je n'aime pas le café. — Moi non plus. Para no estar de acuerdo: pas moi (yo no) después de una afirmativa. Funciona con todos los tónicos: lui aussi, eux non plus, nous aussi. El tónico también va primero cuando comparas a dos personas: moi, je préfère le cinéma; Julie, elle, préfère le marché.","examples":[{"target":"J'aime le chocolat. — Moi aussi!","base":"Me gusta el chocolate. — ¡A mí también!"},{"target":"Je n'aime pas le café. — Moi non plus.","base":"No me gusta el café. — A mí tampoco."}]},"takeaways":["Respondes moi aussi a una afirmativa y moi non plus a una negativa.","Comparas gustos con moi, je… y lui, il…"]},{"id":"fr-a2-u13-l04","unit_id":"fr-a2-u13","position":5,"title_es":"Regarde! Allons-y!","objective_es":"Dar indicaciones a un amigo con el imperativo de tu y proponer con el de nous.","intro":{"explanation":"El imperativo de tu y de nous es el presente sin el sujeto: tu prends → prends (toma), tu attends → attends (espera), nous allons → allons (vamos). En los verbos en -er la s de tu se cae: tu regardes → regarde, tu manges → mange; también en aller: va! Delante de y vuelve la s, que se oye como z: vas-y (dale), y con nous, allons-y (vamos). Regarde y regardes suenan igual: la diferencia es sólo escrita. Être y avoir son irregulares: sois sage (pórtate bien), n'aie pas peur (no tengas miedo). En negativo se usa ne… pas como siempre: n'oublie pas, ne regarde pas.","examples":[{"target":"Regarde, il neige!","base":"¡Mira, está nevando!"},{"target":"Le film commence à huit heures: allons-y!","base":"La película empieza a las ocho: ¡vamos!"}]},"takeaways":["Das una indicación a un amigo con regarde, prends o attends (sin tu y sin la s de -er).","Propones con allons-y y avisas con n'oublie pas."]},{"id":"fr-a2-u13-l05","unit_id":"fr-a2-u13","position":7,"title_es":"Dépêche-toi! Ne t'inquiète pas","objective_es":"Usar el imperativo con pronombres en afirmativo y en negativo.","intro":{"explanation":"En el imperativo afirmativo el pronombre va después del verbo, con guion, y me y te pasan a moi y toi: aide-moi (ayúdame), attends-moi (espérame), dépêche-toi (apúrate), assieds-toi (siéntate). En negativo el pronombre vuelve adelante, como en el presente, y otra vez es me o te: ne te dépêche pas (no te apures), ne m'attends pas. Por eso no te preocupes es ne t'inquiète pas, con la elisión de te. Con vous es igual: dépêchez-vous, ne vous dépêchez pas.","examples":[{"target":"Dépêche-toi, on est en retard!","base":"¡Apúrate, llegamos tarde!"},{"target":"Ne t'inquiète pas, tout va bien.","base":"No te preocupes, todo está bien."}]},"takeaways":["En afirmativo dices dépêche-toi o aide-moi, con el pronombre después.","En negativo dices ne te dépêche pas o ne t'inquiète pas, con el pronombre adelante."]}],"words":[{"id":"en-bye","language_code":"en","unit_id":"a1-u01","text":"bye","translation_es":"chao","accepted_translations":["adiós","chau"],"ipa":"/baɪ/","romanization":null,"emoji":null,"example_en":"Bye, Mom!","example_es":"¡Chao, mamá!","difficulty":1,"tags":["greetings"]},{"id":"en-excuse-me","language_code":"en","unit_id":"a1-u01","text":"excuse me","translation_es":"disculpe","accepted_translations":["permiso","disculpa","disculpá"],"ipa":"/ɪkˈskjuz mi/","romanization":null,"emoji":null,"example_en":"Excuse me, where is the bank?","example_es":"Disculpe, ¿dónde está el banco?","difficulty":1,"tags":["courtesy"]},{"id":"en-and","language_code":"en","unit_id":"a1-u01","text":"and","translation_es":"y","accepted_translations":[],"ipa":"/ænd/","romanization":null,"emoji":null,"example_en":"I'm fine. And you?","example_es":"Estoy bien. ¿Y tú?","difficulty":1,"tags":["grammar"]},{"id":"en-you","language_code":"en","unit_id":"a1-u02","text":"you","translation_es":"tú / usted","accepted_translations":["tú","vos","usted","ustedes","tú / vos / usted"],"ipa":"/ju/","romanization":null,"emoji":null,"example_en":"You are my friend.","example_es":"Eres mi amigo.","difficulty":1,"tags":["pronouns"]},{"id":"en-are","language_code":"en","unit_id":"a1-u02","text":"are","translation_es":"eres / son / están (con you, we, they)","accepted_translations":["sos / son / están (con you, we, they)"],"ipa":"/ɑr/","romanization":null,"emoji":null,"example_en":"We are happy.","example_es":"Estamos felices.","difficulty":1,"tags":["to-be"]},{"id":"en-how-old","language_code":"en","unit_id":"a1-u03","text":"how old","translation_es":"¿cuántos años…?","accepted_translations":[],"ipa":"/haʊ oʊld/","romanization":null,"emoji":null,"example_en":"How old are you?","example_es":"¿Cuántos años tienes?","difficulty":1,"tags":["age","questions"]},{"id":"en-where","language_code":"en","unit_id":"a1-u03","text":"where","translation_es":"dónde","accepted_translations":[],"ipa":"/wɛr/","romanization":null,"emoji":null,"example_en":"Where are you from?","example_es":"¿De dónde eres?","difficulty":1,"tags":["questions"]},{"id":"en-apartment","language_code":"en","unit_id":"a1-u06","text":"apartment","translation_es":"apartamento","accepted_translations":["piso","departamento"],"ipa":"/əˈpɑrtmənt/","romanization":null,"emoji":"🏢","example_en":"We live in an apartment.","example_es":"Vivimos en un apartamento.","difficulty":1,"tags":["home"]},{"id":"en-living-room","language_code":"en","unit_id":"a1-u06","text":"living room","translation_es":"sala de estar","accepted_translations":["living / sala de estar","living","sala","salón"],"ipa":"/ˈlɪvɪŋ ˌrum/","romanization":null,"emoji":"🛋️","example_en":"The sofa is in the living room.","example_es":"El sillón está en la sala.","difficulty":1,"tags":["home"]},{"id":"en-thirsty","language_code":"en","unit_id":"a1-u07","text":"thirsty","trans