":1,"tags":["verbs"]},{"id":"en-t-shirt","language_code":"en","unit_id":"a2-u06","text":"T-shirt","translation_es":"camiseta","accepted_translations":["camiseta","playera","remera"],"ipa":"/ˈtiˌʃɜrt/","romanization":null,"emoji":"👕","example_en":"I bought a cheap T-shirt.","example_es":"Me compré una camiseta barata.","difficulty":1,"tags":["clothes"]},{"id":"en-skirt","language_code":"en","unit_id":"a2-u06","text":"skirt","translation_es":"falda","accepted_translations":["falda","pollera","pollera / falda"],"ipa":"/skɜrt/","romanization":null,"emoji":null,"example_en":"She is wearing a green skirt.","example_es":"Tiene puesta una falda verde.","difficulty":1,"tags":["clothes"]},{"id":"en-jacket","language_code":"en","unit_id":"a2-u06","text":"jacket","translation_es":"chaqueta","accepted_translations":["chaqueta","chamarra","campera"],"ipa":"/ˈdʒækɪt/","romanization":null,"emoji":"🧥","example_en":"I am wearing my new jacket.","example_es":"Tengo puesta mi chaqueta nueva.","difficulty":1,"tags":["clothes"]},{"id":"en-wear","language_code":"en","unit_id":"a2-u06","text":"wear","translation_es":"tener puesto / usar (ropa)","accepted_translations":["usar","llevar puesto","tener puesto","vestir"],"ipa":"/wɛr/","romanization":null,"emoji":null,"example_en":"I am wearing a red jacket.","example_es":"Tengo puesta una chaqueta roja.","difficulty":1,"tags":["clothes","verbs"]},{"id":"en-size","language_code":"en","unit_id":"a2-u06","text":"size","translation_es":"talla / tamaño","accepted_translations":["talle","tamaño","talla","talle / tamaño"],"ipa":"/saɪz/","romanization":null,"emoji":"📏","example_en":"What size are you?","example_es":"¿Qué talla eres?","difficulty":1,"tags":["shopping"]},{"id":"en-cheap","language_code":"en","unit_id":"a2-u06","text":"cheap","translation_es":"barato / barata","accepted_translations":["barato","barata"],"ipa":"/tʃip/","romanization":null,"emoji":null,"example_en":"This T-shirt is very cheap.","example_es":"Esta camiseta es muy barata.","d