ado","accepted_answers":[],"explanation_es":"«Sam is not happy. He is tired»: está cansado.","difficulty":2,"recommended_seconds":60,"words":[]},{"id":"a1-u02-context-e03","lesson_id":"a1-u02-context","position":3,"type":"context_choice","skill":"reading","prompt_es":"Lee el texto y responde.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u02-class-card","document":"description","setting":"Una ficha sobre dos personas de una clase.","title":"Our class","lines":["Sam is a teacher.","Mia is a student. She is happy.","Sam is not happy. He is tired.","Mia and Sam are friends."]},"question":"¿Qué relación hay entre Mia y Sam?","options":["Son amigos","Son hermanos","No se conocen"]},"answer":"Son amigos","accepted_answers":[],"explanation_es":"«Mia and Sam are friends».","difficulty":2,"recommended_seconds":60,"words":[]},{"id":"a1-u02-context-e04","lesson_id":"a1-u02-context","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u02-teacher-questions","setting":"Primer día de clase: la profesora te habla a ti.","speakers":[{"name":"Kate","voice":"a"}],"rate":0.85,"lines":[{"speaker":"Kate","text":"Hello! My name is Kate. I am your teacher."},{"speaker":"Kate","text":"Are you a student?"},{"speaker":"Kate","text":"And are you tired?"}]},"question":"¿Quién te habla?","options":["Una estudiante nueva","Tu profesora","Una amiga tuya"]},"answer":"Tu profesora","accepted_answers":[],"explanation_es":"Dice «I am your teacher»: es tu profesora.","difficulty":2,"recommended_seconds":75,"words":[]},{"id":"a1-u02-context-e05","lesson_id":"a1-u02-context","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u02-teacher-questions","setting":"Primer día de clase: la profesora te habla a ti.","speakers":[{"name":"