context-e03","lesson_id":"a1-u04-context","position":3,"type":"context_choice","skill":"reading","prompt_es":"Lee el texto y responde.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u04-ana-family","document":"post","setting":"Ana publica un texto sobre su familia.","from":"Ana","lines":["My family is big.","My mother is Rosa and my father is Carlos.","I have two brothers and a sister.","My sister has a baby. Her baby is a girl.","Our grandmother is Elena."]},"question":"¿Quién es Elena?","options":["La madre de Ana","La hermana de Ana","La abuela de Ana"]},"answer":"La abuela de Ana","accepted_answers":[],"explanation_es":"«Our grandmother is Elena»; la madre se llama Rosa.","difficulty":2,"recommended_seconds":60,"words":[]},{"id":"a1-u04-context-e04","lesson_id":"a1-u04-context","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u04-family-photo","setting":"Tom mira una foto de la familia de Ana y le pregunta.","speakers":[{"name":"Tom","voice":"a"},{"name":"Ana","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Tom","text":"Who is he?"},{"speaker":"Ana","text":"He is my grandfather."},{"speaker":"Tom","text":"And who is she?"},{"speaker":"Ana","text":"She is my sister, Julia. She has a baby girl."},{"speaker":"Tom","text":"Is Julia a teacher?"},{"speaker":"Ana","text":"Yes, she is."}]},"question":"¿Quién es el hombre de la foto?","options":["El padre de Ana","El hermano de Ana","El abuelo de Ana"]},"answer":"El abuelo de Ana","accepted_answers":[],"explanation_es":"Ana responde «He is my grandfather».","difficulty":2,"recommended_seconds":75,"words":[]},{"id":"a1-u04-context-e05","lesson_id":"a1-u04-context","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u04-family-photo","setting":"To