.85,"lines":[{"speaker":"Leo","text":"Kim, is that your phone?"},{"speaker":"Kim","text":"No, my phone is white. That phone is black."},{"speaker":"Leo","text":"And this cup?"},{"speaker":"Kim","text":"Yes, it is my cup. Thank you!"}]},"question":"¿Cómo termina la conversación?","options":["Kim le agradece a Leo","Kim le pide perdón a Leo","Leo se despide de Kim"]},"answer":"Kim le agradece a Leo","accepted_answers":[],"explanation_es":"Kim termina con «Thank you!».","difficulty":2,"recommended_seconds":75,"words":[]},{"id":"a1-u06-context-e01","lesson_id":"a1-u06-context","position":1,"type":"context_choice","skill":"reading","prompt_es":"Lee el texto y responde.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u06-rental-ad","document":"ad","setting":"Un aviso de un apartamento en alquiler.","title":"Apartment","lines":["Small apartment.","There are two bedrooms and one bathroom.","There is a big kitchen.","There is a sofa in the living room.","There is no garden."]},"question":"¿Cuántos dormitorios tiene el apartamento?","options":["Dos","Uno","Tres"]},"answer":"Dos","accepted_answers":[],"explanation_es":"«There are two bedrooms».","difficulty":2,"recommended_seconds":60,"words":[]},{"id":"a1-u06-context-e02","lesson_id":"a1-u06-context","position":2,"type":"context_choice","skill":"reading","prompt_es":"Lee el texto y responde.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u06-rental-ad","document":"ad","setting":"Un aviso de un apartamento en alquiler.","title":"Apartment","lines":["Small apartment.","There are two bedrooms and one bathroom.","There is a big kitchen.","There is a sofa in the living room.","There is no garden."]},"question":"¿Qué mueble hay en la sala?","options":["Una cama","Una mesa","Un sofá"]},"answer":"Un sofá","accepted_answers":[],"explanation_es":"«There is a sofa in the living room».","difficulty":2,"recommended_seconds":60,"words":[]},{"id":"a1-u06-context-e03","less