":"Nora","voice":"a"},{"name":"Sara","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Nora","text":"This is the living room. The kitchen is next to the living room."},{"speaker":"Sara","text":"Where is the bathroom?"},{"speaker":"Nora","text":"The bathroom is next to the bedroom."},{"speaker":"Sara","text":"And the keys?"},{"speaker":"Nora","text":"They are on the table, in the kitchen."}]},"question":"¿Qué quiere saber Sara primero?","options":["Dónde está el baño","Cuántos dormitorios hay","Dónde está el jardín"]},"answer":"Dónde está el baño","accepted_answers":[],"explanation_es":"Su primera pregunta es «Where is the bathroom?».","difficulty":2,"recommended_seconds":75,"words":[]},{"id":"a1-u06-context-e06","lesson_id":"a1-u06-context","position":6,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u06-house-tour","setting":"Nora le muestra el apartamento a Sara.","speakers":[{"name":"Nora","voice":"a"},{"name":"Sara","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Nora","text":"This is the living room. The kitchen is next to the living room."},{"speaker":"Sara","text":"Where is the bathroom?"},{"speaker":"Nora","text":"The bathroom is next to the bedroom."},{"speaker":"Sara","text":"And the keys?"},{"speaker":"Nora","text":"They are on the table, in the kitchen."}]},"question":"¿Dónde están las llaves?","options":["Sobre la mesa de la cocina","Debajo de la mesa","En el dormitorio"]},"answer":"Sobre la mesa de la cocina","accepted_answers":[],"explanation_es":"«They are on the table, in the kitchen».","difficulty":2,"recommended_seconds":75,"words":[]},{"id":"a1-u07-context-e01","lesson_id":"a1-u07-context","position":1,"type":"context_choice","skill":"reading","prompt_es":"Lee el texto y responde.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u07-cafe-menu","document":"menu","setting":"El menú de un café.","title":"Menu"