 Kim"]},"question":"¿Qué tono tiene el correo de Laura?","options":["Amable y abierto a negociar","Enojado y exigente","Triste y resignado","Informal y gracioso"]},"answer":"Amable y abierto a negociar","accepted_answers":[],"explanation_es":"Laura agradece la oferta, explica su condición y termina con «I hope we can reach an agreement».","difficulty":1,"recommended_seconds":60,"words":[]},{"id":"b2-u02-l05-e06","lesson_id":"b2-u02-l05","position":6,"type":"listen_choice","skill":"listening","prompt_es":"Escucha y elige lo que oyes","payload":{"type":"listen_choice","audioText":"I'm afraid I'll have to turn it down.","options":["I'm afraid I'll have to turn it down.","I'm afraid I'll have to take it on.","I'm sure I'll have to turn it down.","I'm afraid I had to turn it down."]},"answer":"I'm afraid I'll have to turn it down.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-turn-down"]},{"id":"b2-u02-l05-e07","lesson_id":"b2-u02-l05","position":7,"type":"order_words","skill":"sentence_building","prompt_es":"Ordena las palabras","payload":{"type":"order_words","tokens":["She","turned","down","the","offer","because","of","the","hours"],"translation":"Rechazó la oferta por los horarios."},"answer":"She turned down the offer because of the hours.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":25,"words":["en-turn-down"]},{"id":"b2-u02-l05-e08","lesson_id":"b2-u02-l05","position":8,"type":"short_answer","skill":"sentence_building","prompt_es":"Responde en inglés","payload":{"type":"short_answer","question":"Did you accept the job? (no, lo rechazaste porque el sueldo era bajo)","translation":"¿Aceptaste el trabajo?"},"answer":"No, I turned it down because the salary was low.","accepted_answers":["No, I turned it down.","No, I turned it down because the salary was too low.","I turned it down because the salary was low."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":