onds":30,"words":["en-priority"]},{"id":"b2-u02-final-e09","lesson_id":"b2-u02-final","position":9,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"She took ___ a new project last week.","translation":"La semana pasada asumió un proyecto nuevo.","options":["on","up","off","down"]},"answer":"on","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-take-on"]},{"id":"b2-u02-final-e10","lesson_id":"b2-u02-final","position":10,"type":"listen_choice","skill":"listening","prompt_es":"Escucha y elige lo que oyes","payload":{"type":"listen_choice","audioText":"flexible","options":["flexible","leader","deal","otherwise"]},"answer":"flexible","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-flexible"]},{"id":"b2-u03-l01-e01","lesson_id":"b2-u03-l01","position":1,"type":"match_pairs","skill":"vocabulary","prompt_es":"Une cada palabra con su significado","payload":{"type":"match_pairs","pairs":[{"left":"society","right":"sociedad"},{"left":"generation","right":"generación"},{"left":"trend","right":"tendencia"},{"left":"custom","right":"costumbre"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["en-society","en-generation","en-trend","en-custom"]},{"id":"b2-u03-l01-e02","lesson_id":"b2-u03-l01","position":2,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Working from home is a growing ___.","translation":"Trabajar desde casa es una tendencia en aumento.","options":["trend","custom","society","generation"]},"answer":"trend","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-trend"]},{"id":"b2-u03-l01-e03","lesson_id":"b2-u03-l01","position":3,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"In some countries it is a ___ to take off your shoes at home.","translation":"En algunos países es costumbre sacarse los zapatos en casa.","options":["custom","trend","society","habit"]},"answer":"custom","accepted_answers":[],"explanation_es":"Custom: costumbre de una sociedad. Habit: hábito de una persona.","difficulty":1,"recommended_seconds":15,"words":["en-custom"]},{"id":"b2-u03-l01-e04","lesson_id":"b2-u03-l01","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u3-podcast","setting":"Un pódcast entrevista a una socióloga sobre las generaciones.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Reyes","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"People often complain that young people have no respect for old customs. Is that true?"},{"speaker":"Dr. Reyes","text":"Every generation has said that about the next one. It is said that even the ancient Greeks complained about their teenagers."},{"speaker":"Host","text":"So nothing has really changed?"},{"speaker":"Dr. Reyes","text":"Customs change, of course. Fewer people get married in church, for example, and family dinners are less common. But the values behind them haven't disappeared."},{"speaker":"Host","text":"What do you mean?"},{"speaker":"Dr. Reyes","text":"Young people still care about their families. They just show it in different ways: a video call instead of a Sunday lunch."},{"speaker":"Host","text":"And is the gap between generations getting bigger?"},{"speaker":"Dr. Reyes","text":"Honestly, I don't think so. Many people believe that, but my research shows that parents and children agree about most things."}]},"question":"Según la socióloga, ¿qué dice cada generación de la siguiente?","options":["Que no respeta las costumbres de antes","Que es más trabajadora","Que vive mejor","Que es más feliz"]},"answer":"Que no respeta las costumbres de antes","accepted_answers":[],"explanation_es":"El conductor pregunta si los jóvenes no respetan las costumbres y ella responde: «Every generation has said that about the next one».","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"b2-u03-l01-e05","lesson_id":"b2-u03-l01","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u3-podcast","setting":"Un pódcast entrevista a una socióloga sobre las generaciones.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Reyes","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"People often complain that young people have no respect for old customs. Is that true?"},{"speaker":"Dr. Reyes","text":"Every generation has said that about the next one. It is said that even the ancient Greeks complained about their teenagers."},{"speaker":"Host","text":"So nothing has really changed?"},{"speaker":"Dr. Reyes","text":"Customs change, of course. Fewer people get married in church, for example, and family dinners are less common. But the values behind them haven't disappeared."},{"speaker":"Host","text":"What do you mean?"},{"speaker":"Dr. Reyes","text":"Young people still care about their families. They just show it in different ways: a video call instead of a Sunday lunch."},{"speaker":"Host","text":"And is the gap between generations getting bigger?"},{"speaker":"Dr. Reyes","text":"Honestly, I don't think so. Many people believe that, but my research shows that parents and children agree about most things."}]},"question":"¿Qué cambió y qué no, según la socióloga?","options":["Cambiaron las costumbres, pero no los valores","Cambiaron los valores, pero no las costumbres","No cambió nada","Cambió todo"]},"answer":"Cambiaron las costumbres, pero no los valores","accepted_answers":[],"explanation_es":"Dice: «Customs change, of course… But the values behind them haven’t disappeared».","difficulty":1,"recommended_seconds":75,"word