masked":"f_l_ o_t","hint":"pelearse / enojarse (con alguien)"},"answer":"fall out","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":20,"words":["en-fall-out"]},{"id":"b2-u06-rev2-e09","lesson_id":"b2-u06-rev2","position":9,"type":"order_words","skill":"sentence_building","prompt_es":"Ordena las palabras","payload":{"type":"order_words","tokens":["I","am","sorry","I","overreacted","yesterday"],"translation":"Perdón por exagerar ayer."},"answer":"I am sorry I overreacted yesterday.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":25,"words":["en-overreact"]},{"id":"b2-u06-rev2-e10","lesson_id":"b2-u06-rev2","position":10,"type":"translate_write","skill":"translation","prompt_es":"Traduce al inglés","payload":{"type":"translate_write","source":"Te estoy muy agradecido por tu ayuda."},"answer":"I am very grateful for your help.","accepted_answers":["I'm very grateful for your help.","I am really grateful for your help.","I'm really grateful for your help."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["en-grateful"]},{"id":"b2-u06-l05-e02","lesson_id":"b2-u06-l05","position":2,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"___ means understanding how others feel.","translation":"Empatía significa entender cómo se sienten los demás.","options":["Empathy","Mood","Self-confidence","Diversity"]},"answer":"Empathy","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-empathy"]},{"id":"b2-u06-l05-e03","lesson_id":"b2-u06-l05","position":3,"type":"fill_blank","skill":"vocabulary","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Learning a language gave me more ___.","translation":"Aprender un idioma me dio más confianza en mí mismo.","options":["self-confidence","empathy","mood","evidence"]},"answer":"self-confidence","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-self-confidence"]},{"id":"b2-u06-l05-e04","lesson_id":"b2-u06-l05","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u6-podcast","setting":"Un pódcast sobre psicología entrevista a un psicólogo.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Moss","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"Today we are talking about empathy. What exactly is it?"},{"speaker":"Dr. Moss","text":"It is the ability to understand how another person feels, to put yourself in their shoes. It's not the same as agreeing with them."},{"speaker":"Host","text":"Can empathy be learned?"},{"speaker":"Dr. Moss","text":"Yes. The first step is to listen without judging. Most of us listen only to answer."},{"speaker":"Host","text":"Some listeners say their mood changes very quickly. Is that normal?"},{"speaker":"Dr. Moss","text":"Everybody has good and bad days. But if you are often in a bad mood, it might be stress, or a lack of sleep."},{"speaker":"Host","text":"And what about self-confidence?"},{"speaker":"Dr. Moss","text":"People with low self-confidence tend to think that others are judging them. Usually, others are too busy thinking about themselves!"}]},"question":"Según el psicólogo, ¿la empatía es lo mismo que estar de acuerdo?","options":["No: es entender cómo se siente otro, aunque no estés de acuerdo","Sí, es lo mismo","Sí, pero sólo con amigos","No: es dar consejos"]},"answer":"No: es entender cómo se siente otro, aunque no estés de acuerdo","accepted_answers":[],"explanation_es":"Dice: «It is the ability to understand how another person feels… It’s not the same as agreeing with them».","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"b2-u06-l05-e05","lesson_id":"b2-u06-l05","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u6-podcast","setting":"Un pódcast sobre psicología entrevista a un psicólogo.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Moss","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"Today we are talking about empathy. What exactly is it?"},{"speaker":"Dr. Moss","text":"It is the ability to understand how another person feels, to put yourself in their shoes. It's not the same as agreeing with them."},{"speaker":"Host","text":"Can empathy be learned?"},{"speaker":"Dr. Moss","text":"Yes. The first step is to listen without judging. Most of us listen only to answer."},{"speaker":"Host","text":"Some listeners say their mood changes very quickly. Is that normal?"},{"speaker":"Dr. Moss","text":"Everybody has good and bad days. But if you are often in a bad mood, it might be stress, or a lack of sleep."},{"speaker":"Host","text":"And what about self-confidence?"},{"speaker":"Dr. Moss","text":"People with low self-confidence tend to think that others are judging them. Usually, others are too busy thinking about themselves!"}]},"question":"¿Qué puede haber detrás de estar seguido de mal humor?","options":["Estrés o falta de sueño","Una mala dieta","Demasiado trabajo en equipo","El clima"]},"answer":"Estrés o falta de sueño","accepted_answers":[],"explanation_es":"Dice: «if you are often in a bad mood, it might be stress, or a lack of sleep».","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"b2-u06-l05-e06","lesson_id":"b2-u06-l05","position":6,"type":"context_choice","skill":"listening","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u6-podcast","setting":"Un pódcast sobre psicología entrevista a un psicólogo.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Moss","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"Today we are talking about empathy. What exactly is it?"},{"speaker":"Dr. Moss","text":"It is the ability to understand how another person feels, to put yourself in their shoes. It's not the same as agreeing with them."},{"speaker":"Host","text":"Can empathy be learned?"},{"speaker":"Dr. Moss","text":"Yes. The first step is to listen without judging. Most of us listen only to answer."},{"speaker":"Host","text":"Some listeners say their mood changes very quickly. Is that normal?"},{"speaker":"Dr. Moss","text":"Everybody has good and bad days. But if you are often in a bad mood, it might be stress, or a lack of sleep."},{"speaker":"Host","text":"And what about self-confidence?"},{"speaker":"Dr. Moss","text":"People with low self-confidence tend to think that others are judging them. Usually, others are too busy thinking about themselves!"}]},"question":"¿Qué dice con humor sobre las personas con poca confianza en sí mismas?","options":["Creen que los demás las juzgan, pero los demás están pensando en sí mismos","Que nunca cambian","Que tienen razón","Que deberían hablar más"]},"answer":"Creen que los demás las juzgan, pero los demás están pensando en sí mismos","accepted_answers":[],"explanation_es":"Dice: «People with low self-confidence tend to think that others are judging them. Usually, others are too busy thinking about themselves!».","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"b2-u06-l05-e07","lesson_id":"b2-u06-l05","position":7,"type":"listen_choice","skill":"listening","prompt_es":"Escucha y elige lo que oyes","payload":{"type":"listen_choice","audioText":"Empathy means understanding how others feel.","options":["Empathy means understanding how others feel.","Empathy means understanding how you feel.","Empathy means telling others how you feel.","Empathy means knowing what others think."]},"answer":"Empathy means understanding how others feel.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["en-empathy"]},{"id":"b2-u06-l05-e08","lesson_id":"b2-u06-l05","position":8,"type":"order_words",