r-a2-u13-l01","position":6,"type":"fill_blank","skill":"grammar","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Lui, il travaille à Lyon. ___, elle étudie à Paris.","translation":"Él trabaja en Lyon. Ella estudia en París.","options":["Elle","Lui","La","Sa"]},"answer":"Elle","accepted_answers":[],"explanation_es":"Para remarcar a una mujer: elle, elle étudie. Lui es para un hombre; la y sa no son pronombres tónicos.","difficulty":1,"recommended_seconds":15,"words":["fr-moi"]},{"id":"fr-a2-u13-l01-e07","lesson_id":"fr-a2-u13-l01","position":7,"type":"translation_choice","skill":"vocabulary","prompt_es":"¿Qué significa «c'est moi»?","payload":{"type":"translation_choice","word":"c'est moi","options":["soy yo","es mío","eres tú","es él"]},"answer":"soy yo","accepted_answers":[],"explanation_es":"C'est moi es «soy yo». «Es mío» se dice c'est à moi.","difficulty":1,"recommended_seconds":12,"words":["fr-c-est-moi"]},{"id":"fr-a2-u13-l01-e08","lesson_id":"fr-a2-u13-l01","position":8,"type":"order_words","skill":"sentence_building","prompt_es":"Ordena las palabras","payload":{"type":"order_words","tokens":["C'est","toi","sur","la","photo"],"translation":"¿Eres tú el de la foto?"},"answer":"C'est toi sur la photo?","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":25,"words":["fr-toi"]},{"id":"fr-a2-u13-l01-e09","lesson_id":"fr-a2-u13-l01","position":9,"type":"translate_write","skill":"translation","prompt_es":"Traduce al francés","payload":{"type":"translate_write","source":"Yo soy de Buenos Aires. ¿Y tú?"},"answer":"Moi, je suis de Buenos Aires. Et toi?","accepted_answers":["Moi je suis de Buenos Aires. Et toi?","Je suis de Buenos Aires. Et toi?"],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["fr-moi","fr-toi"]},{"id":"fr-a2-u13-l01-e10","lesson_id":"fr-a2-u13-l01","position":10,"type":"short_answer","skill":"sentence_building","prompt_es":"Responde en francés","payload":{"type":"short_answer","question":"Qui est-ce sur la photo? C'est toi?","translation":"¿Quién es el de la foto? ¿Eres tú? (Responde que sí, que eres tú.)"},"answer":"Oui, c'est moi.","accepted_answers":["Oui, c'est moi!","C'est moi."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["fr-c-est-moi"]},{"id":"fr-a2-u13-l02-e02","lesson_id":"fr-a2-u13-l02","position":2,"type":"fill_blank","skill":"grammar","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Tu viens au cinéma avec ___?","translation":"¿Vienes al cine conmigo?","options":["moi","me","je","mon"]},"answer":"moi","accepted_answers":[],"explanation_es":"Después de una preposición va el tónico: avec moi, nunca «avec me» ni «avec je».","difficulty":1,"recommended_seconds":15,"words":["fr-avec-moi"]},{"id":"fr-a2-u13-l02-e03","lesson_id":"fr-a2-u13-l02","position":3,"type":"fill_blank","skill":"grammar","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Ce livre est pour ___, Hugo.","translation":"Este libro es para ti, Hugo.","options":["toi","tu","te","ton"]},"answer":"toi","accepted_answers":[],"explanation_es":"Pour + pronombre tónico: pour toi. Tu es sujeto y te va antes del verbo.","difficulty":1,"recommended_seconds":15,"words":["fr-toi"]},{"id":"fr-a2-u13-l02-e04","lesson_id":"fr-a2-u13-l02","position":4,"type":"fill_blank","skill":"grammar","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Mes frères? Je mange avec ___ ce soir.","translation":"¿Mis hermanos? Ceno con ellos esta noche.","options":["eux","ils","les","leur"]},"answer":"eux","accepted_answers":[],"explanation_es":"Ils es sujeto (ils mangent); después de avec va eux. Les y leur son complementos que van antes del verbo.","difficulty":1,"recommended_seconds":15,"words":["fr-eux"]},{"id":"fr-a2-u13-l02-e05","lesson_id":"fr-a2-u13-l02","position":5,"type":"fill_blank","skill":"grammar","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"Léa et Juli