nerator":null,"generator_version":null},{"item_id":"en.ex.xg9u1c5qnbqknm","content_hash":"v1:d76dcc9309addd203a5e7446a9231ae68f81908e8756ca5cb5d86f344e7daa46","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"In some countries it is a ___ to take off your shoes at home.","translation":"En algunos países es costumbre sacarse los zapatos en casa.","options":["custom","trend","society","habit"]},"answer":"custom","accepted_answers":[],"explanation_es":"Custom: costumbre de una sociedad. Habit: hábito de una persona.","difficulty":1,"recommended_seconds":15,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.prded338kpjnjp","content_hash":"v1:c50b346b642f69d4a3e07c61b8e7643ec91ba048a0db7f6d7fcff06a93eacd3b","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u3-podcast","setting":"Un pódcast entrevista a una socióloga sobre las generaciones.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Reyes","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"People often complain that young people have no respect for old customs. Is that true?"},{"speaker":"Dr. Reyes","text":"Every generation has said that about the next one. It is said that even the ancient Greeks complained about their teenagers."},{"speaker":"Host","text":"So nothing has really changed?"},{"speaker":"Dr. Reyes","text":"Customs change, of course. Fewer people get married in church, for example, and family dinners are less common. But the values behind them haven't disappeared."},{"speaker":"Host","text":"What do you mean?"},{"speaker":"Dr. Reyes","text":"Young people still care about their families. They just show it in different ways: a video call instead of a Sunday lunch."},{"speaker":"Host","text":"And is the gap between generations getting bigger?"},{"speaker":"Dr. Reyes","text":"Honestly, I don't think so. Many people believe that, but my research shows that parents and children agree about most things."}]},"question":"Según la socióloga, ¿qué dice cada generación de la siguiente?","options":["Que no respeta las costumbres de antes","Que es más trabajadora","Que vive mejor","Que es más feliz"]},"answer":"Que no respeta las costumbres de antes","accepted_answers":[],"explanation_es":"El conductor pregunta si los jóvenes no respetan las costumbres y ella responde: «Every generation has said that about the next one».","difficulty":1,"recommended_seconds":75,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.fefv2t4th4598p","content_hash":"v1:b59e11701cb132d6ff8fa019af841e976efa6512f2ef0f30a74e9fe80a7a72df","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u3-podcast","setting":"Un pódcast entrevista a una socióloga sobre las generaciones.","speakers":[{"name":"Host","voice":"a"},{"name":"Dr. Reyes","voice":"b"}],"rate":1,"lines":[{"speaker":"Host","text":"People often complain that young people have no respect for old customs. Is that true?"},{"speaker":"Dr. Reyes","text":"Every generation has said that about the next one. It is said that even the ancient Greeks complained about their teenagers."},{"speaker":"Host","text":"So nothing has really changed?"},{"speaker":"Dr. Reyes","text":"Customs change, of course. Fewer people get married in church, for example, and family dinners are less common. But the values behind them haven't disappeared."},{"speaker":"Host","text":"What do you mean?"},{"speaker":"Dr. Reyes","text":"Young people still care about their families. They just show it in different ways: a video call instead of a Sunday lunch."},{"speaker":"Host","text":"And is the gap between generations getting bigger?"},{"speaker":"Dr. Reyes","text":"Honestly, I don't think so. Many people believe that, but my research shows that parents and children agree about most things."}]}