he rain we went for a walk.","We went for a walk despite the rain."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"normalized_text","mode_version":1,"normalizer":"polygo.answers.v1","typo_tolerance":true},"generator":null,"generator_version":null},{"item_id":"en.ex.gfi0yvqun35i3n","content_hash":"v1:c676da690a27de9ecc5549c41cff2702cac136c8a0749b1f548d7f2fbbb69c8e","prompt_es":"Une cada palabra con su significado","payload":{"type":"match_pairs","pairs":[{"left":"renewable","right":"renovable"},{"left":"sustainable","right":"sostenible / sustentable"},{"left":"tackle","right":"abordar / enfrentar (un problema)"},{"left":"whereas","right":"mientras que"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"pair_set","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.1hwtgyl2b1d9zn","content_hash":"v1:840f72bb28e32b87412ad6edbfbdfd113902c1b39b888e35930f9e876d29ebeb","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"I love the city, ___ my brother prefers the country.","translation":"A mí me encanta la ciudad, mientras que mi hermano prefiere el campo.","options":["whereas","despite","even if","in spite of"]},"answer":"whereas","accepted_answers":[],"explanation_es":"Whereas une dos hechos opuestos.","difficulty":1,"recommended_seconds":15,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.n0yrvfcvdxwsdf","content_hash":"v1:2f8dd5471e413b720cb9fc31185da13d13ae09fb8d1f1d1b46d3cc2e3ce80d12","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"We need to ___ the real causes of the problem.","translation":"Tenemos que enfrentar las verdaderas causas del problema.","options":["tackle","reduce","produce","protect"]},"answer":"tackle","accepted_answers":[],"explanation_es":"Collocation: tackle a problem (enfrentar un problema).","d