ulty":1,"recommended_seconds":25,"grading_spec":{"mode":"normalized_text","mode_version":1,"normalizer":"polygo.answers.v1","typo_tolerance":false},"generator":null,"generator_version":null},{"item_id":"en.ex.ube7bkjzsll67v","content_hash":"v1:e41e3a03addd33506973b906edd2b4fa8eca632696b2cc2d76d06c2fb361e037","prompt_es":"Responde en inglés","payload":{"type":"short_answer","question":"You don't agree with me, do you? (entiendes su punto de vista, pero no estás de acuerdo)","translation":"No estás de acuerdo conmigo, ¿no?"},"answer":"I understand your point of view, but I disagree.","accepted_answers":["I understand your point of view, but I don't agree.","I understand your point of view but I disagree.","No. I understand your point of view, but I don't agree."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"normalized_text","mode_version":1,"normalizer":"polygo.answers.v1","typo_tolerance":true},"generator":null,"generator_version":null},{"item_id":"en.ex.w72ehycn26aqw7","content_hash":"v1:f8cda8ffaab6828c1c67420253d0d2080dd668562e174ffc34385d7a48136bc1","prompt_es":"Traduce al inglés","payload":{"type":"translate_write","source":"Fue difícil. Aun así, terminamos a tiempo."},"answer":"It was difficult. Nevertheless, we finished on time.","accepted_answers":["It was hard. Nevertheless, we finished on time.","It was difficult. Nevertheless we finished on time."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"normalized_text","mode_version":1,"normalizer":"polygo.answers.v1","typo_tolerance":true},"generator":null,"generator_version":null},{"item_id":"en.ex.3h8z0auyeaso5j","content_hash":"v1:dd148ea19bbda17b272d8e4407279232ea334bb969093bb90bf711d657811c3f","prompt_es":"Une cada palabra con su significado","payload":{"type":"match_pairs","pairs":[{"left":"valid","right":"válido"},{"left":"convincing","right":"convincente"},{"left":"assumption","right":"suposición / supuesto"},{"left":"take into account","right":"tener en cuenta"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"pair_set","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.zo67chnfp18nfy","content_hash":"v1:c1a1eedc26e409021b43fbc7aeefdd3ae506ee9ed83187607c8492212f5c0823","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"We need to take the costs ___ account.","translation":"Tenemos que tener en cuenta los costos.","options":["into","in","on","to"]},"answer":"into","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.jm2yh0ygpq7yms","content_hash":"v1:577da6353f2dbad26ae74d0a857c60a2e48edb32f63ed81d759d59b27e42884c","prompt_es":"Completa la frase","payload":{"type":"fill_blank","sentence":"That's just an ___. Where is the evidence?","translation":"Eso es sólo una suposición. ¿Dónde están las pruebas?","options":["assumption","argument","opinion","answer"]},"answer":"assumption","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.v2lps8utaiswyw","content_hash":"v1:c819ed7a7e1d723b0bc800887331ba48b29c8a3e2230abe852245ebf79735d93","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u10-school-debate","setting":"Un debate en un colegio: ¿hay que prohibir los teléfonos en clase?","speakers":[{"name":"Moderator","voice":"a"},{"name":"Lucas","voice":"b"},{"name":"Hannah","voice":"a"}],"rate":1,"lines":[{"speaker":"Moderator","text":"Today's debate: should phones be banned in schools? Lucas, you're first."},{"speaker":"Lucas","text":"Yes, they should. Phones distract students. Moreover, they make bullying easier, because it continues after school. As a result, many students feel anxious all day."},{"speaker":"Moderator","text":"Hannah, your answer?"},{"speaker":"Hannah","text":"Admittedly, phones can be a distraction. Nevertheless, banning them is not the answer. On the contrary, schools should teach students how to use them responsibly."},{"speaker":"Lucas","text":"But that's an assumption. Where is the evidence that teaching works better?"},{"speaker":"Hannah","text":"Fair question. What I'm saying is that a ban doesn't teach anything. In other words, students will just use their phones more at home."}]},"question":"¿Qué le reprocha Lucas a Hannah?","options":["Que lo que dice es una suposición sin pruebas","Que habla demasiado","Que cambió de opinión","Que no respondió la pregunta"]},"answer":"Que lo que dice es una suposición sin pruebas","accepted_answers":[],"explanation_es":"Lucas dice: «But that’s an assumption. Where is the evidence that teaching works better?».","difficulty":1,"recommended_seconds":75,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.w2o877vgdgebxl","content_hash":"v1:28143b7f88850c1652b386f4a7eb65437113a914ce417eff54c6e1d15b07c1f5","prompt_es":"Escucha y responde","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.b2-u10-four-days","setting":"Unos colegas discuten la propuesta de trabajar cuatro días por semana.","speakers":[{"name":"Olivia","voice":"a"},{"name":"Ken","voice":"b"}],"rate":1,"lines":[{"speaker":"Olivia","text":"So, the four-day week. What worries me is the customers. Who answers the phone on Fridays?"},{"speaker":"Ken","text":"We'd take turns. The reason why other companies have done it is that people work better when they're rested."},{"speaker":"Olivia","text":"That may be true for some jobs. But we need to take into account that our clients expect us every day."},{"speaker":"Ken","text":"That's a valid point. So let's try it for three months and measure the results."},{"speaker":"Olivia","text":"OK, I find that convincing. All things considered, a trial is a good compromise."}]},"question":"¿Qué pide Olivia que se tenga en cuenta y cómo responde Ken?","options":["Que los clientes los esperan todos los días; Ken lo acepta y propone una prueba de tres meses","Que es caro; Ken lo niega","Que nadie quiere trabajar los viernes; Ken se enoja","Que es ilegal; Ken lo duda"]},"answer":"Que los clientes los esperan todos los días; Ken lo acepta y propone una prueba de tres meses","accepted_answers":[],"explanation_es":"Olivia: «we need to take into account that our clients expect us every day». Ken: «That’s a valid point. So let’s try it for three months».","difficulty":1,"recommended_seconds":75,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.tnm0kutubwjvsm","content_hash":"v1:57f943ba4f9c645cc52ad2f36dc635ae2d91d8c28e7c3d796c21fca2132b6700","prompt_es":"Lee y responde","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.b2-u10-tips","document":"post","setting":"Consejos para escribir un buen argumento.","title":"Writing tips","lines":["How to write a convincing argument","Give reasons, not only opinions. \"I think it is bad\" is a point of view; \"it increases traffic by 30%\" is an argument.","Question your assumptions. If you assume that everyone agrees with you, your argument will be weak.","Take the other side into account. Mention the strongest counterargument and explain why your position is still valid.","Finish clearly. What readers remember is usually the last thing they read."]},"question":"Según los consejos, ¿qué diferencia hay entre un punto de vista y un argumento?","options":["Un argumento da una razón concreta, no sólo una opinión","No hay diferencia","El argumento es más corto","El punto de vista usa números"]},"answer":"Un argumento da una razón concreta, no sólo una opinión","accepted_answers":[],"explanation_es":"El texto dice: «\"I think it is bad\" is a point of view; \"it increases traffic by 30%\" is an argument».","difficulty":1,"recommended_seconds":60,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.yqkoxvr2c12538","content_hash":"v1:4cc08945bbf01fa08b51841b1aa70c8237a4751d6eee108d772dc584befb765c","prompt_es":"Escucha y elige lo que oyes","payload":{"type":"listen_choice","audioText":"Her argument was very convincing.","options":["Her argument was very convincing.","Her argument was not very convincing.","His argument was very convincing.","Her answer was very convincing."]},"answer":"Her argument was very convincing.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"grading_spec":{"mode":"exact_option","mode_version":1},"generator":null,"generator_version":null},{"item_id":"en.ex.cqtgqlotu4x0vs","content_hash":"v1:a0fa627fc1828dbd39b81c49cc2c40fd6790f5c3830820978854bc4c4d767969","prompt_es":"Ordena las palabras","payload":{"type":"order_words","tokens":["That","is","a","valid","point"],"translation":"Es un argumento válido."},"answer":"That is a valid point.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":25,"grading_spec":{"mode":"normalized_text","mode_version":1,"normalizer":"polygo.answers.v1","typo_tolerance":false},"generator":null,"generator_version":null},{"item_id":"en.ex.45hl7wi0asppek","content_hash":"v1:0c5a19a1a97d74a2e06d53a69e5bec86ec8c3bee52e21d89140988ceb7426949","prompt_es":"Responde en inglés","payload":{"type":"short_answer","question":"Did his presentation persuade you? (sí, fue muy convincente)","translation":"¿Te convenció su presentación?"},"answer":"Yes, it was very convincing.","accepted_answers":["Yes, it was really convincing.","Yes. It was very convincing.","It was very convincing."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"grading_spec":{"mode":"normalized_text"